window.BOOK={"key":"akhsar","app":"mutoon","lsk":"mutoon_akhsar_v1","title":"أخصر المختصرات","unitWord":"فقرة","sub":"الفقه الحنبلي: على مذهب الإمام أحمد · ابن بلبان الدمشقي (ت ١٠٨٣هـ) · ٢٦ بابًا","source":"أخصر المختصرات: اللفظ المتداول لطبعة محمد ناصر العجمي (دار البشائر ١٤١٦هـ) = https://shamela.ws/book/6084، والشكل من طبعة ركائز المشكولة (ت. العيدان واليتامى ١٤٣٨هـ) = https://shamela.ws/book/147656 · قوبل بـ: قوبلت الطبعتان كلمةً كلمةً بسكربت؛ أُخذ لفظ العجمي في ١٣٠ موضعًا وشُكلت كلماته الجديدة (١٠٨ كلمات) — انظر akhsar-sources.md","note":"اللفظ المتداول لطبعة العجمي، قوبل كلمةً كلمةً بسكربت بطبعة ركائز المشكولة المحققة. الشكل منقول من ركائز حيث اتفق اللفظ، وشُكلت ١٠٨ كلمات من لفظ العجمي ليس لها مقابل مشكول، وكل ذلك في تقرير المصادر.","chapters":[{"id":"ak1","title":"مُقَدِّمَةُ الْمُصَنِّفِ","units":[{"id":"ak1_1","label":"مُقَدِّمَةُ الْمُصَنِّفِ · ١","segs":[["matn","الْحَمْدُ لِلَّهِ الْمُفَقِّهِ مَنْ شَاءَ مِنْ خَلْقِهِ فِي الدِّينِ، وَالصَّلَاةُ وَالسَّلَامُ عَلَى نَبِيِّنَا مُحَمَّدٍ الْأَمِينِ، الْمُؤَيَّدِ بِكِتَابِهِ الْمُبِينِ، الْمُتَمَسِّكِ بِحَبْلِهِ الْمَتِينِ، وَعَلَى آلِهِ وَصَحْبِهِ أَجْمَعِينَ."]]},{"id":"ak1_2","label":"مُقَدِّمَةُ الْمُصَنِّفِ · ٢","segs":[["matn","وَبَعْدُ: فَقَدْ سَنَحَ بِخَلَدِي أَنْ أَخْتَصِرَ كِتَابِيَ الْمُسَمَّى بِكَافِي الْمُبْتَدِي، الْكَائِنَ فِي فِقْهِ الْإِمَامِ أَحْمَدَ بْنِ حَنْبَلٍ الصَّابِرِ لِحُكْمِ الْمَلِكِ الْمُبْدِي؛"]]},{"id":"ak1_3","label":"مُقَدِّمَةُ الْمُصَنِّفِ · ٣","segs":[["matn","لِيَقْرُبَ تَنَاوُلُهُ عَلَى الْمُبْتَدِئِينَ، وَيَسْهُلَ حِفْظُهُ عَلَى الرَّاغِبِينَ، وَيَقِلَّ حَجْمُهُ عَلَى الطَّالِبِينَ، وَسَمَّيْتُهُ أَخْصَرَ الْمُخْتَصَرَاتِ؛ لِأَنِّي لَمْ أَقِفْ عَلَى أَخْصَرَ مِنْهُ جَامِعٍ لِمَسَائِلِهِ فِي فِقْهِنَا مِنَ الْمُؤَلَّفَاتِ."]]},{"id":"ak1_4","label":"مُقَدِّمَةُ الْمُصَنِّفِ · ٤","segs":[["matn","وَاللَّهَ أَسْأَلُ أَنْ يَنْفَعَ بِهِ قَارِئِيهِ، وَحَافِظِيهِ، وَنَاظِرِيهِ، إِنَّهُ جَدِيرٌ بِإِجَابَةِ الدَّعَوَاتِ، وَأَنْ يَجْعَلَهُ خَالِصاً لِوَجْهِهِ الْكَرِيمِ، مُقَرِّباً إِلَيْهِ فِي جَنَّاتِ النَّعِيمِ، وَمَا تَوْفِيقِي وَاعْتِصَامِي إِلَّا بِاللَّهِ، عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ أُنِيبُ."]]}],"group":"مُقَدِّمَةُ الْمُصَنِّفِ"},{"id":"ak2","title":"كِتَابُ الطَّهَارَةِ","units":[{"id":"ak2_1","label":"كِتَابُ الطَّهَارَةِ · ١","segs":[["matn","الْمِيَاهُ ثَلَاثَةٌ: الْأَوَّلُ: طَهُورٌ، وَهُوَ الْبَاقِي عَلَى خِلْقَتِهِ، وَمِنْهُ: مَكْرُوهٌ؛ كَمُتَغَيِّرٍ بِغَيْرِ مُمَازِجٍ. وَمُحَرَّمٌ، لَا يَرْفَعُ الْحَدَثَ وَيُزِيلُ الْخَبَثَ، وَهُوَ: الْمَغْصُوبُ. وَغَيْرُ بِئْرِ النَّاقَةِ مِنْ ثَمُودَ."]]},{"id":"ak2_2","label":"كِتَابُ الطَّهَارَةِ · ٢","segs":[["matn","الثَّانِي: طَاهِرٌ، لَا يَرْفَعُ الْحَدَثَ وَلَا يُزِيلُ الْخَبَثَ، وَهُوَ: الْمُتَغَيِّرُ بِمُمَازِجٍ طَاهِرٍ. وَمِنْهُ: يَسِيرٌ مُسْتَعْمَلٌ فِي رَفْعِ حَدَثٍ."]]},{"id":"ak2_3","label":"كِتَابُ الطَّهَارَةِ · ٣","segs":[["matn","الثَّالِثُ: نَجِسٌ، يَحْرُمُ اسْتِعْمَالُهُ مُطْلَقاً، وَهُوَ: مَا تَغَيَّرَ بِنَجَاسَةٍ فِي غَيْرِ مَحَلِّ تَطْهِيرٍ. أَوْ لَاقَاهَا فِي غَيْرِهِ وَهُوَ يَسِيرٌ. وَالْجَارِي كَالرَّاكِدِ."]]},{"id":"ak2_4","label":"كِتَابُ الطَّهَارَةِ · ٤","segs":[["matn","وَالْكَثِيرُ: قُلَّتَانِ، وَهُمَا: مِائَةُ رِطْلٍ وَسَبْعَةُ أَرْطَالٍ وَسُبُعُ رِطْلٍ بِالدِّمَشْقِيِّ، وَالْيَسِيرُ: مَا دُونَهُمَا."]]},{"id":"ak2_5","label":"كِتَابُ الطَّهَارَةِ · ٥","segs":[["matn","فَصْلٌ: كُلُّ إِنَاءٍ طَاهِرٍ يُبَاحُ: اتِّخَاذُهُ، وَاسْتِعْمَالُهُ. إِلَّا أَنْ يَكُونَ: ذَهَباً. أَوْ فِضَّةً. أَوْ مُضَبَّباً بِأَحَدِهِمَا. لَكِنْ تُبَاحُ: ضَبَّةٌ، يَسِيرَةٌ، مِنْ فِضَّةٍ، لِحَاجَةٍ."]]},{"id":"ak2_6","label":"كِتَابُ الطَّهَارَةِ · ٦","segs":[["matn","وَمَا لَمْ تُعْلَمْ نَجَاسَتُهُ مِنْ آنِيَةِ كُفَّارٍ، وَثِيَابِهِمْ: طَاهِرَةٌ. وَلَا يَطْهُرُ جِلْدُ مَيْتَةٍ بِدِبَاغٍ. وَكُلُّ أَجْزَائِهَا نَجِسَةٌ، إِلَّا شَعْراً وَنَحْوَهُ. وَالْمُنْفَصِلُ مِنْ حَيٍّ كَمَيْتَتِهِ."]]},{"id":"ak2_7","label":"كِتَابُ الطَّهَارَةِ · ٧","segs":[["matn","فَصْلٌ: الِاسْتِنْجَاءُ وَاجِبٌ مِنْ كُلِّ خَارِجٍ إِلَّا: الرِّيحَ. وَالطَّاهِرَ. وَغَيْرَ الْمُلَوَّثِ. وَسُنَّ: عِنْدَ دُخُولِ خَلَاءٍ قَوْلُ: «بِاسْمِ اللَّهِ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْخُبُثِ وَالْخَبَائِثِ»."]]},{"id":"ak2_8","label":"كِتَابُ الطَّهَارَةِ · ٨","segs":[["matn","وَبَعْدَ خُرُوجٍ مِنْهُ: «غُفْرَانَكَ»، «الْحَمْدُ لِلَّهِ الَّذِي أَذْهَبَ عَنِّي الْأَذَى وَعَافَانِي». وَتَغْطِيَةُ رَأْسٍ. وَانْتِعَالٌ. وَتَقْدِيمُ رِجْلِهِ الْيُسْرَى دُخُولاً. وَاعْتِمَادُهُ عَلَيْهَا جَالِساً. وَالْيُمْنَى خُرُوجاً، عَكْسُ مَسْجِدٍ، وَنَعْلٍ، وَنَحْوِهِمَا. وَبُعْدٌ فِي فَضَاءٍ."]]},{"id":"ak2_9","label":"كِتَابُ الطَّهَارَةِ · ٩","segs":[["matn","وَطَلَبُ مَكَانٍ رِخْوٍ لِبَوْلٍ. وَمَسْحُ الذَّكَرِ بِالْيَدِ الْيُسْرَى إِذَا انْقَطَعَ الْبَوْلُ، مِنْ أَصْلِهِ إِلَى رَأْسِهِ ثَلَاثاً. وَنَتْرُهُ ثَلَاثاً. وَكُرِهَ: دُخُولُ خَلَاءٍ بِمَا فِيهِ ذِكْرُ اللَّهِ تَعَالَى. وَكَلَامٌ فِيهِ بِلَا حَاجَةٍ."]]},{"id":"ak2_10","label":"كِتَابُ الطَّهَارَةِ · ١٠","segs":[["matn","وَرَفْعُ ثَوْبٍ قَبْلَ دُنُوٍّ مِنَ الْأَرْضِ. وَبَوْلٌ فِي شَقٍّ وَنَحْوِهِ. وَمَسُّ فَرْجٍ بِيَمِينٍ بِلَا حَاجَةٍ. وَاسْتِقْبَالُ النَّيِّرَيْنِ. وَحَرُمَ: اسْتِقْبَالُ قِبْلَةٍ وَاسْتِدْبَارُهَا فِي غَيْرِ بُنْيَانٍ. وَلُبْثٌ فَوْقَ الْحَاجَةِ."]]},{"id":"ak2_11","label":"كِتَابُ الطَّهَارَةِ · ١١","segs":[["matn","وَبَوْلٌ فِي طَرِيقٍ مَسْلُوكٍ وَنَحْوِهِ، وَتَحْتَ شَجَرَةٍ مُثْمِرَةٍ ثَمَراً مَقْصُوداً. وَسُنَّ: اسْتِجْمَارٌ ثُمَّ اسْتِنْجَاءٌ بِمَاءٍ. وَيَجُوزُ الِاقْتِصَارُ عَلَى أَحَدِهِمَا، لَكِنِ الْمَاءُ أَفْضَلُ حِينَئِذٍ. وَلَا يَصِحُّ اسْتِجْمَارٌ إِلَّا: بِطَاهِرٍ. مُبَاحٍ. يَابِسٍ."]]},{"id":"ak2_12","label":"كِتَابُ الطَّهَارَةِ · ١٢","segs":[["matn","مُنْقٍ. وَحَرُمَ: بِرَوْثٍ. وَعَظْمٍ. وَطَعَامٍ. وَذِي حُرْمَةٍ. وَمُتَّصِلٍ بِحَيَوَانٍ. وَشُرِطَ لَهُ: عَدَمُ تَعَدِّي خَارِجٍ مَوْضِعَ الْعَادَةِ. وَثَلَاثُ مَسَحَاتٍ مُنْقِيَةٍ فَأَكْثَرُ."]]},{"id":"ak2_13","label":"كِتَابُ الطَّهَارَةِ · ١٣","segs":[["matn","فَصْلٌ: يُسَنُّ السِّوَاكُ بِالْعُودِ: كُلَّ وَقْتٍ. إِلَّا لِصَائِمٍ بَعْدَ الزَّوَالِ؛ فَيُكْرَهُ. وَيَتَأَكَّدُ عِنْدَ: صَلَاةٍ وَنَحْوِهَا، وَتَغَيُّرِ فَمٍ وَنَحْوِهِ. وَسُنَّ: بَدَاءَةٌ بِالْأَيْمَنِ: فِيهِ، وَفِي طُهْرٍ، وَشَأْنِهِ كُلِّهِ. وَادِّهَانٌ غِبًّا."]]},{"id":"ak2_14","label":"كِتَابُ الطَّهَارَةِ · ١٤","segs":[["matn","وَاكْتِحَالٌ فِي كُلِّ عَيْنٍ ثَلَاثاً. وَنَظَرٌ فِي مِرْآةٍ. وَتَطَيُّبٌ. وَاسْتِحْدَادٌ. وَحَفُّ شَارِبٍ. وَتَقْلِيمُ ظُفُرٍ. وَنَتْفُ إِبْطٍ. وَكُرِهَ: قَزَعٌ. وَنَتْفُ شَيْبٍ. وَثَقْبُ أُذُنِ صَبِيٍّ."]]},{"id":"ak2_15","label":"كِتَابُ الطَّهَارَةِ · ١٥","segs":[["matn","وَيَجِبُ خِتَانُ ذَكَرٍ وَأُنْثَى بُعَيْدَ بُلُوغٍ مَعَ أَمْنِ الضَّرَرِ. وَيُسَنُّ: قَبْلَهُ. وَيُكْرَهُ: سَابِعَ وِلَادَتِهِ، وَمِنْهَا إِلَيْهِ."]]},{"id":"ak2_16","label":"كِتَابُ الطَّهَارَةِ · ١٦","segs":[["matn","فَصْلٌ: فُرُوضُ الْوُضُوءِ سِتَّةٌ: غَسْلُ الْوَجْهِ، مَعَ مَضْمَضَةٍ وَاسْتِنْشَاقٍ. وَغَسْلُ الْيَدَيْنِ. وَالرِّجْلَيْنِ. وَمَسْحُ جَمِيعِ الرَّأْسِ، مَعَ الْأُذُنَيْنِ. وَتَرْتِيبٌ. وَمُوَالَاةٌ. وَالنِّيَّةُ شَرْطٌ لِكُلِّ طَهَارَةٍ شَرْعِيَّةٍ، غَيْرِ: إِزَالَةِ خَبَثٍ."]]},{"id":"ak2_17","label":"كِتَابُ الطَّهَارَةِ · ١٧","segs":[["matn","وَغُسْلِ كِتَابِيَّةٍ لِحِلِّ وَطْءٍ. وَمُسْلِمَةٍ مُمْتَنِعَةٍ. وَالتَّسْمِيَةُ وَاجِبَةٌ فِي: وُضُوءٍ. وَغُسْلٍ. وَتَيَمُّمٍ. وَغَسْلِ يَدَيْ قَائِمٍ مِنْ نَوْمِ لَيْلٍ نَاقِضٍ لِوُضُوءٍ. وَتَسْقُطُ سَهْواً وَجَهْلاً. وَمِنْ سُنَنِهِ: اسْتِقْبَالُ قِبْلَةٍ. وَسِوَاكٌ."]]},{"id":"ak2_18","label":"كِتَابُ الطَّهَارَةِ · ١٨","segs":[["matn","وَبَدَاءَةٌ بِغَسْلِ يَدَيْ غَيْرِ قَائِمٍ مِنْ نَوْمِ لَيْلٍ، وَيَجِبُ لَهُ ثَلَاثاً تَعَبُّداً. وَبِمَضْمَضَةٍ فَاسْتِنْشَاقٍ. وَمُبَالَغَةٌ فِيهِمَا لِغَيْرِ صَائِمٍ. وَتَخْلِيلُ شَعْرٍ كَثِيفٍ، وَالْأَصَابِعِ. وَغَسْلَةٌ ثَانِيَةٌ وَثَالِثَةٌ، وَكُرِهَ أَكْثَرُ."]]},{"id":"ak2_19","label":"كِتَابُ الطَّهَارَةِ · ١٩","segs":[["matn","وَسُنَّ بَعْدَ فَرَاغِهِ: رَفْعُ بَصَرِهِ إِلَى السَّمَاءِ. وَقَوْلُ مَا وَرَدَ. وَاللَّهُ أَعْلَمُ."]]},{"id":"ak2_20","label":"كِتَابُ الطَّهَارَةِ · ٢٠","segs":[["matn","فَصْلٌ: يَجُوزُ الْمَسْحُ عَلَى: خُفٍّ وَنَحْوِهِ. وَعِمَامَةِ ذَكَرٍ، مُحَنَّكَةٍ، أَوْ ذَاتِ ذُؤَابَةٍ. وَخُمُرِ نِسَاءٍ مُدَارَةٍ تَحْتَ حُلُوقِهِنَّ. وَعَلَى جَبِيرَةٍ لَمْ تُجَاوِزْ قَدْرَ الْحَاجَةِ إِلَى حَلِّهَا."]]},{"id":"ak2_21","label":"كِتَابُ الطَّهَارَةِ · ٢١","segs":[["matn","وَإِنْ جَاوَزَتْهُ، أَوْ وَضَعَهَا عَلَى غَيْرِ طَهَارَةٍ: لَزِمَ نَزْعُهَا. فَإِنْ خَافَ الضَّرَرَ: تَيَمَّمَ، مَعَ مَسْحِ مَوْضُوعَةٍ عَلَى طَهَارَةٍ. وَيَمْسَحُ: مُقِيمٌ، وَعَاصٍ بِسَفَرِهِ، مِنْ حَدَثٍ بَعْدَ لُبْسٍ: يَوْماً وَلَيْلَةً."]]},{"id":"ak2_22","label":"كِتَابُ الطَّهَارَةِ · ٢٢","segs":[["matn","وَمُسَافِرٌ سَفَرَ قَصْرٍ: ثَلَاثَةً بِلَيَالِيهَا. فَإِنْ مَسَحَ فِي سَفَرٍ ثُمَّ أَقَامَ، أَوْ عَكَسَ: فَكَمُقِيمٍ. وَشُرِطَ: تَقَدُّمُ كَمَالِ طَهَارَةٍ. وَسَتْرُ مَمْسُوحٍ مَحَلَّ فَرْضٍ. وَثُبُوتُهُ بِنَفْسِهِ. وَإِمْكَانُ مَشْيٍ بِهِ عُرْفاً. وَطَهَارَتُهُ. وَإِبَاحَتُهُ."]]},{"id":"ak2_23","label":"كِتَابُ الطَّهَارَةِ · ٢٣","segs":[["matn","وَيَجِبُ مَسْحُ: أَكْثَرِ دَوَائِرِ عِمَامَةٍ. وَأَكْثَرِ ظَاهِرِ قَدَمِ خُفٍّ. وَجَمِيعِ جَبِيرَةٍ. وَإِنْ ظَهَرَ بَعْضُ مَحَلِّ فَرْضٍ، أَوْ تَمَّتِ الْمُدَّةُ: اسْتَأْنَفَ الطَّهَارَةَ."]]},{"id":"ak2_24","label":"كِتَابُ الطَّهَارَةِ · ٢٤","segs":[["matn","فَصْلٌ: نَوَاقِضُ الْوُضُوءِ ثَمَانِيَةٌ: خَارِجٌ مِنْ سَبِيلٍ مُطْلَقاً. وَخَارِجٌ مِنْ بَقِيَّةِ الْبَدَنِ مِنْ بَوْلٍ، وَغَائِطٍ، وَكَثِيرٍ نَجِسٍ غَيْرِهِمَا. وَزَوَالُ عَقْلٍ، إِلَّا يَسِيرَ نَوْمٍ مِنْ قَائِمٍ أَوْ قَاعِدٍ. وَغُسْلُ مَيِّتٍ."]]},{"id":"ak2_25","label":"كِتَابُ الطَّهَارَةِ · ٢٥","segs":[["matn","وَأَكْلُ لَحْمِ إِبِلٍ. وَالرِّدَّةُ. وَكُلُّ مَا أَوْجَبَ غُسْلاً غَيْرَ مَوْتٍ. وَمَسُّ فَرْجِ آدَمِيٍّ مُتَّصِلٍ، أَوْ حَلْقَةِ دُبُرِهِ، بِيَدٍ. وَلَمْسُ ذَكَرٍ أَوْ أُنْثَى الْآخَرَ لِشَهْوَةٍ. بِلَا حَائِلٍ فِيهِمَا. لَا: لِشَعْرٍ. وَسِنٍّ."]]},{"id":"ak2_26","label":"كِتَابُ الطَّهَارَةِ · ٢٦","segs":[["matn","وَظُفُرٍ. وَلَا بِهَا. وَلَا مَنْ دُونَ سَبْعٍ. وَلَا يَنْتَقِضُ وُضُوءُ مَلْمُوسٍ مُطْلَقاً. وَمَنْ شَكَّ فِي طَهَارَةٍ أَوْ حَدَثٍ: بَنَى عَلَى يَقِينِهِ. وَحَرُمَ عَلَى مُحْدِثٍ: مَسُّ مُصْحَفٍ. وَصَلَاةٌ. وَطَوَافٌ."]]},{"id":"ak2_27","label":"كِتَابُ الطَّهَارَةِ · ٢٧","segs":[["matn","وَعَلَى جُنُبٍ وَنَحْوِهِ: ذَلِكَ. وَقِرَاءَةُ آيَةِ قُرْآنٍ. وَلُبْثٌ فِي مَسْجِدٍ بِغَيْرِ وُضُوءٍ."]]},{"id":"ak2_28","label":"كِتَابُ الطَّهَارَةِ · ٢٨","segs":[["matn","فَصْلٌ: مُوجِبَاتُ الْغُسْلِ سَبْعَةٌ: خُرُوجُ الْمَنِيِّ مِنْ مَخْرَجِهِ بِلَذَّةٍ. وَانْتِقَالُهُ. وَتَغْيِيبُ حَشَفَةٍ فِي فَرْجٍ أَوْ دُبُرٍ، وَلَوْ لِبَهِيمَةٍ أَوْ مَيِّتٍ، بِلَا حَائِلٍ. وَإِسْلَامُ كَافِرٍ. وَمَوْتٌ. وَحَيْضٌ. وَنِفَاسٌ. وَسُنَّ: لِجُمُعَةٍ. وَعِيدٍ."]]},{"id":"ak2_29","label":"كِتَابُ الطَّهَارَةِ · ٢٩","segs":[["matn","وَكُسُوفٍ. وَاسْتِسْقَاءٍ. وَجُنُونٍ، وَإِغْمَاءٍ، لَا احْتِلَامَ فِيهِمَا. وَاسْتِحَاضَةٍ لِكُلِّ صَلَاةٍ. وَإِحْرَامٍ. وَدُخُولِ مَكَّةَ. وَحَرَمِهَا. وَوُقُوفٍ بِعَرَفَةَ. وَطَوَافِ زِيَارَةٍ. وَوَدَاعٍ. وَمَبِيتٍ بِمُزْدَلِفَةَ. وَرَمْيِ جِمَارٍ. وَتَنْقُضُ الْمَرْأَةُ شَعْرَهَا لِحَيْضٍ وَنِفَاسٍ."]]},{"id":"ak2_30","label":"كِتَابُ الطَّهَارَةِ · ٣٠","segs":[["matn","لَا جَنَابَةٍ إِذَا رَوَّتْ أُصُولَهُ. وَسُنَّ: تَوَضُّؤٌ بِمُدٍّ. وَاغْتِسَالٌ بِصَاعٍ. وَكُرِهَ إِسْرَافٌ. وَإِنْ نَوَى بِالْغُسْلِ رَفْعَ الْحَدَثَيْنِ، أَوِ الْحَدَثِ وَأَطْلَقَ: ارْتَفَعَا. وَسُنَّ لِجُنُبٍ: غَسْلُ فَرْجِهِ. وَالْوُضُوءُ: لَأَكْلٍ وَشُرْبٍ. وَنَوْمٍ."]]},{"id":"ak2_31","label":"كِتَابُ الطَّهَارَةِ · ٣١","segs":[["matn","وَمُعَاوَدَةِ وَطْءٍ. وَالْغُسْلُ لَهَا أَفْضَلُ. وَكُرِهَ نَوْمُ جُنُبٍ بِلَا وُضُوءٍ."]]},{"id":"ak2_32","label":"كِتَابُ الطَّهَارَةِ · ٣٢","segs":[["matn","فَصْلٌ: يَصِحُّ التَّيَمُّمُ: بِتُرَابٍ. طَهُورٍ. مُبَاحٍ. لَهُ غُبَارٌ. إِذَا عَدِمَ الْمَاءَ لِحَبْسٍ أَوْ غَيْرِهِ، أَوْ خِيفَ بِاسْتِعْمَالِهِ أَوْ طَلَبِهِ: ضَرَرٌ بِبَدَنٍ، أَوْ مَالٍ، أَوْ غَيْرِهِمَا."]]},{"id":"ak2_33","label":"كِتَابُ الطَّهَارَةِ · ٣٣","segs":[["matn","وَيُفْعَلُ عَنْ كُلِّ مَا يُفْعَلُ بِالْمَاءِ، سِوَى نَجَاسَةٍ عَلَى غَيْرِ بَدَنٍ. إِذَا دَخَلَ وَقْتُ فَرْضٍ، وَأُبِيحَ غَيْرُهُ. وَإِنْ وَجَدَ مَاءً لَا يَكْفِي طَهَارَتَهُ: اسْتَعْمَلَهُ ثُمَّ تَيَمَّمَ."]]},{"id":"ak2_34","label":"كِتَابُ الطَّهَارَةِ · ٣٤","segs":[["matn","وَيَتَيَمَّمُ لِلْجُرْحِ عِنْدَ غَسْلِهِ إِنْ لَمْ يُمْكِنْ مَسْحُهُ بِالْمَاءِ، وَيَغْسِلُ الصَّحِيحَ. وَطَلَبُ الْمَاءِ شَرْطٌ. فَإِنْ نَسِيَ قُدْرَتَهُ عَلَيْهِ وَتَيَمَّمَ: أَعَادَ. وَفُرُوضُهُ: مَسْحُ وَجْهِهِ. وَيَدَيْهِ إِلَى كُوعَيْهِ. وَفِي أَصْغَرَ: تَرْتِيبٌ."]]},{"id":"ak2_35","label":"كِتَابُ الطَّهَارَةِ · ٣٥","segs":[["matn","وَمُوَالَاةٌ أَيْضاً. وَنِيَّةُ الِاسْتِبَاحَةِ شَرْطٌ لِمَا يَتَيَمَّمُ لَهُ. وَلَا يُصَلِّي بِهِ فَرْضاً إِنْ نَوَى نَفْلاً، أَوْ أَطْلَقَ. وَيَبْطُلُ: بِخُرُوجِ الْوَقْتِ. وَمُبْطِلَاتِ الْوُضُوءِ. وَبِوُجُودِ مَاءٍ إِنْ تَيَمَّمَ لِفَقْدِهِ."]]},{"id":"ak2_36","label":"كِتَابُ الطَّهَارَةِ · ٣٦","segs":[["matn","وَسُنَّ لِرَاجِيهِ تَأْخِيرٌ لِآخِرِ وَقْتٍ مُخْتَارٍ. وَمَنْ عَدِمَ الْمَاءَ وَالتُّرَابَ، أَوْ لَمْ يُمْكِنْهُ اسْتِعْمَالُهُمَا: صَلَّى الْفَرْضَ فَقَطْ عَلَى حَسَبِ حَالِهِ، وَلَا إِعَادَةَ. وَيَقْتَصِرُ عَلَى مُجْزِئٍ."]]},{"id":"ak2_37","label":"كِتَابُ الطَّهَارَةِ · ٣٧","segs":[["matn","وَلَا يَقْرَأُ فِي غَيْرِ صَلَاةٍ إِنْ كَانَ جُنُباً."]]},{"id":"ak2_38","label":"كِتَابُ الطَّهَارَةِ · ٣٨","segs":[["matn","فَصْلٌ: تَطْهُرُ: أَرْضٌ وَنَحْوُهَا: بِإِزَالَةِ عَيْنِ النَّجَاسَةِ وَأَثَرِهَا بِالْمَاءِ. وَبَوْلُ غُلَامٍ لَمْ يَأْكُلْ طَعَاماً بِشَهْوَةٍ، وَقَيْئُهُ: بِغَمْرِهِ بِهِ."]]},{"id":"ak2_39","label":"كِتَابُ الطَّهَارَةِ · ٣٩","segs":[["matn","وَغَيْرُهُمَا: بِسَبْعِ غَسَلَاتٍ، أَحَدُهَا بِتُرَابٍ وَنَحْوِهِ فِي نَجَاسَةِ كَلْبٍ وَخِنْزِيرٍ فَقَطْ، مَعَ زَوَالِهَا. وَلَا يَضُرُّ بَقَاءُ لَوْنٍ، أَوْ رِيحٍ، أَوْ هُمَا عَجْزاً. وَتَطْهُرُ خَمْرَةٌ انْقَلَبَتْ بِنَفْسِهَا خَلّاً، وَكَذَا دَنُّهَا."]]},{"id":"ak2_40","label":"كِتَابُ الطَّهَارَةِ · ٤٠","segs":[["matn","لَا دُهْنٌ، وَمُتَشَرِّبٌ نَجَاسَةً. وَعُفِيَ فِي غَيْرِ مَائِعٍ وَمَطْعُومٍ، عَنْ يَسِيرِ دَمٍ نَجِسٍ وَنَحْوِهِ، مِنْ حَيَوَانٍ طَاهِرٍ. لَا دَمِ سَبِيلٍ، إِلَّا مِنْ حَيْضٍ."]]},{"id":"ak2_41","label":"كِتَابُ الطَّهَارَةِ · ٤١","segs":[["matn","وَمَا لَا نَفْسَ لَهُ سَائِلَةٌ، وَقَمْلٌ، وَبَرَاغِيثُ، وَبَعُوضٌ، وَنَحْوُهَا: طَاهِرَةٌ مُطْلَقاً. وَمَائِعٌ مُسْكِرٌ. وَمَا لَا يُؤْكَلُ مِنْ طَيْرٍ وَبَهَائِمَ مِمَّا فَوْقَ الْهِرِّ خِلْقَةً. وَلَبَنٌ وَمَنِيٌّ مِنْ غَيْرِ آدَمِيٍّ."]]},{"id":"ak2_42","label":"كِتَابُ الطَّهَارَةِ · ٤٢","segs":[["matn","وَبَوْلٌ، وَرَوْثٌ وَنَحْوُهَا مِنْ غَيْرِ مَأْكُولِ اللَّحْمِ. نَجِسَةٌ، وَمِنْهُ: طَاهِرَةٌ، كَمِمَّا لَا دَمَ لَهُ سَائِلٌ. وَيُعْفَى عَنْ يَسِيرِ طِينِ شَارِعٍ عُرْفاً إِنْ عُلِمَتْ نَجَاسَتُهُ، وَإِلَّا فَطَاهِرٌ."]]},{"id":"ak2_43","label":"كِتَابُ الطَّهَارَةِ · ٤٣","segs":[["matn","فَصْلٌ فِي الْحَيْضِ: لَا حَيْضَ: مَعَ حَمْلٍ. وَلَا بَعْدَ خَمْسِينَ سَنَةً. وَلَا قَبْلَ تَمَامِ تِسْعِ سِنِينَ. وَأَقَلُّهُ: يَوْمٌ وَلَيْلَةٌ. وَأَكْثَرُهُ: خَمْسَةَ عَشَرَ. وَغَالِبُهُ: سِتٌّ أَوْ سَبْعٌ. وَأَقَلُّ طُهْرٍ بَيْنَ حَيْضَتَيْنِ: ثَلَاثَةَ عَشَرَ."]]},{"id":"ak2_44","label":"كِتَابُ الطَّهَارَةِ · ٤٤","segs":[["matn","وَلَا حَدَّ لِأَكْثَرِهِ. وَحَرُمَ عَلَيْهَا فِعْلُ: صَلَاةٍ، وَصَوْمٍ، وَيَلْزَمُهَا قَضَاؤُهُ. وَيَجِبُ بِوَطْئِهَا فِي الْفَرْجِ: دِينَارٌ أَوْ نِصْفُهُ كَفَّارَةً. وَتُبَاحُ الْمُبَاشَرَةُ فِيمَا دُونَهُ. وَالْمُبْتَدَأَةُ: تَجْلِسُ أَقَلَّهُ. ثُمَّ تَغْتَسِلُ وَتُصَلِّي."]]},{"id":"ak2_45","label":"كِتَابُ الطَّهَارَةِ · ٤٥","segs":[["matn","فَإِنْ لَمْ يُجَاوِزْ دَمُهَا أَكْثَرَهُ: اغْتَسَلَتْ أَيْضاً إِذَا انْقَطَعَ. فَإِنْ تَكَرَّرَ ثَلَاثاً: فَهُوَ حَيْضٌ، تَقْضِي مَا وَجَبَ فِيهِ. وَإِنْ أَيِسَتْ قَبْلَهُ، أَوْ لَمْ يَعُدْ: فَلَا."]]},{"id":"ak2_46","label":"كِتَابُ الطَّهَارَةِ · ٤٦","segs":[["matn","وَإِنْ جَاوَزَهُ: فَمُسْتَحَاضَةٌ، تَجْلِسُ الْمُتَمَيِّزَ إِنْ كَانَ وَصَلُحَ فِي الشَّهْرِ الثَّانِي. وَإِلَّا أَقَلَّ الْحَيْضِ حَتَّى تَتَكَرَّرَ اسْتِحَاضَتُهَا، ثُمَّ غَالِبَهُ. وَمُسْتَحَاضَةٌ مُعْتَادَةٌ: تُقَدِّمُ عَادَتَهَا. وَيَلْزَمُهَا وَنَحْوَهَا: غَسْلُ الْمَحَلِّ. وَعَصْبُهُ."]]},{"id":"ak2_47","label":"كِتَابُ الطَّهَارَةِ · ٤٧","segs":[["matn","وَالْوُضُوءُ لِكُلِّ صَلَاةٍ إِنْ خَرَجَ شَيْءٌ. وَنِيَّةُ الِاسْتِبَاحَةِ. وَحَرُمَ وَطْؤُهَا، إِلَّا مَعَ خَوْفِ زِنًى. وَأَكْثَرُ مُدَّةِ النِّفَاسِ: أَرْبَعُونَ يَوْماً. وَالنَّقَاءُ زَمَنَهُ: طُهْرٌ، يُكْرَهُ الْوَطْءُ فِيهِ. وَهُوَ كَحَيْضٍ فِي أَحْكَامِهِ، غَيْرَ: عِدَّةٍ. وَبُلُوغٍ."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"ak3","title":"كِتَابُ الصَّلَاةِ","units":[{"id":"ak3_1","label":"كِتَابُ الصَّلَاةِ · ١","segs":[["matn","تَجِبُ الْخَمْسُ عَلَى كُلِّ: مُسْلِمٍ. مُكَلَّفٍ. إِلَّا حَائِضاً وَنُفَسَاءَ. وَلَا تَصِحُّ مِنْ مَجْنُونٍ، وَلَا صَغِيرٍ غَيْرِ مُمَيِّزٍ. وَعَلَى وَلِيِّهِ أَمْرُهُ بِهَا لِسَبْعٍ، وَضَرْبُهُ عَلَى تَرْكِهَا لِعَشْرٍ."]]},{"id":"ak3_2","label":"كِتَابُ الصَّلَاةِ · ٢","segs":[["matn","وَيَحْرُمُ تَأْخِيرُهَا إِلَى وَقْتِ الضَّرُورَةِ إِلَّا: مِمَّنْ لَهُ الْجَمْعُ بِنِيَّتِهِ. وَمُشْتَغِلٍ بِشَرْطٍ لَهَا يَحْصُلُ قَرِيباً. وَجَاحِدُهَا كَافِرٌ."]]},{"id":"ak3_3","label":"كِتَابُ الصَّلَاةِ · ٣","segs":[["matn","فَصْلٌ: الْأَذَانُ وَالْإِقَامَةُ فَرْضَا كِفَايَةٍ عَلَى: الرِّجَالِ. الْأَحْرَارِ. الْمُقِيمِينَ. لِلْخَمْسِ الْمُؤَدَّاةِ، وَالْجُمُعَةِ. وَلَا يَصِحُّ إِلَّا: مُرَتَّباً. مُتَوَالِياً. مَنْوِيًّا. مِنْ ذَكَرٍ. مُمَيِّزٍ. عَدْلٍ وَلَوْ ظَاهِراً. وَبَعْدَ الْوَقْتِ لِغَيْرِ فَجْرٍ."]]},{"id":"ak3_4","label":"كِتَابُ الصَّلَاةِ · ٤","segs":[["matn","وَسُنَّ كَوْنُهُ: صَيِّتاً. أَمِيناً. عَالِماً بِالْوَقْتِ. وَمَنْ جَمَعَ أَوْ قَضَى فَوَائِتَ: أَذَّنَ لِلْأُولَى، وَأَقَامَ لِكُلِّ صَلَاةٍ."]]},{"id":"ak3_5","label":"كِتَابُ الصَّلَاةِ · ٥","segs":[["matn","وَسُنَّ لِمُؤَذِّنٍ وَسَامِعِهِ: مُتَابَعَةُ قَوْلِهِ سِرًّا، إِلَّا فِي الْحَيْعَلَةِ، فَيَقُولُ: الْحَوْقَلَةَ، وَفِي التَّثْوِيبِ: صَدَقْتَ وَبَرِرْتَ. وَالصَّلَاةُ عَلَى النَّبِيِّ عَلَيْهِ السَّلَامُ بَعْدَ فَرَاغِهِ. وَقَوْلُ مَا وَرَدَ. وَالدُّعَاءُ."]]},{"id":"ak3_6","label":"كِتَابُ الصَّلَاةِ · ٦","segs":[["matn","وَحَرُمَ خُرُوجٌ مِنْ مَسْجِدٍ بَعْدَهُ بِلَا عُذْرٍ، أَوْ نِيَّةِ رُجُوعٍ."]]},{"id":"ak3_7","label":"كِتَابُ الصَّلَاةِ · ٧","segs":[["matn","فَصْلٌ: شُرُوطُ صِحَّةِ الصَّلَاةِ سِتَّةٌ: طَهَارَةُ الْحَدَثِ، وَتَقَدَّمَتْ. وَدُخُولُ الْوَقْتِ. فَوَقْتُ الظُّهْرِ: مِنَ الزَّوَالِ حَتَّى يَتَسَاوَى مُنْتَصِبٌ وَفَيْئُهُ سِوَى ظِلِّ الزَّوَالِ."]]},{"id":"ak3_8","label":"كِتَابُ الصَّلَاةِ · ٨","segs":[["matn","وَيَلِيهِ: الْمُخْتَارُ لِلْعَصْرِ حَتَّى يَصِيرَ ظِلُّ كُلِّ شَيْءٍ مِثْلَيْهِ سِوَى ظِلِّ الزَّوَالِ. وَالضَّرُورَةُ: إِلَى الْغُرُوبِ. وَيَلِيهِ: الْمَغْرِبُ حَتَّى يَغِيبَ الشَّفَقُ الْأَحْمَرُ. وَيَلِيهِ: الْمُخْتَارُ لِلْعِشَاءِ إِلَى ثُلُثِ اللَّيْلِ الْأَوَّلِ."]]},{"id":"ak3_9","label":"كِتَابُ الصَّلَاةِ · ٩","segs":[["matn","وَالضَّرُورَةُ: إِلَى طُلُوعِ فَجْرٍ ثَانٍ. وَيَلِيهِ: الْفَجْرُ إِلَى الشُّرُوقِ. وَتُدْرَكُ مَكْتُوبَةٌ بِإِحْرَامٍ فِي وَقْتِهَا. لَكِنْ يَحْرُمُ تَأْخِيرُهَا إِلَى وَقْتٍ لَا يَسَعُهَا. وَلَا يُصَلِّي حَتَّى: يَتَيَقَّنَهُ."]]},{"id":"ak3_10","label":"كِتَابُ الصَّلَاةِ · ١٠","segs":[["matn","أَوْ يَغْلِبَ عَلَى ظَنِّهِ دُخُولُهُ إِنْ عَجَزَ عَنِ الْيَقِينِ، وَيُعِيدُ إِنْ أَخْطَأَ. وَمَنْ صَارَ أَهْلاً لِوُجُوبِهَا قَبْلَ خُرُوجِ وَقْتِهَا بِتَكْبِيرَةٍ: لَزِمَتْهُ، وَمَا يُجْمَعُ إِلَيْهَا قَبْلَهَا."]]},{"id":"ak3_11","label":"كِتَابُ الصَّلَاةِ · ١١","segs":[["matn","وَيَجِبُ فَوْراً قَضَاءُ فَوَائِتَ مُرَتَّباً، مَا لَمْ: يَتَضَرَّرْ. أَوْ يَنْسَ. أَوْ يَخْشَ فَوْتَ حَاضِرَةٍ، أَوِ اخْتِيَارِهَا. الثَّالِثُ: سَتْرُ الْعَوْرَةِ. وَيَجِبُ حَتَّى خَارِجَهَا، وَفِي خَلْوَةٍ وَظُلْمَةٍ. بِمَا لَا يَصِفُ الْبَشَرَةَ."]]},{"id":"ak3_12","label":"كِتَابُ الصَّلَاةِ · ١٢","segs":[["matn","وَعَوْرَةُ: رَجُلٍ، وَحُرَّةٍ مُرَاهِقَةٍ، وَأَمَةٍ: مَا بَيْنَ سُرَّةٍ وَرُكْبَةٍ. وَابْنِ سَبْعٍ إِلَى عَشْرٍ: الْفَرْجَانِ. وَكُلُّ الْحُرَّةِ عَوْرَةٌ إِلَّا وَجْهَهَا فِي الصَّلَاةِ. وَمَنِ: انْكَشَفَ بَعْضُ عَوْرَتِهِ وَفَحُشَ."]]},{"id":"ak3_13","label":"كِتَابُ الصَّلَاةِ · ١٣","segs":[["matn","أَوْ صَلَّى فِي نَجِسٍ، أَوْ غَصْبٍ، ثَوْباً أَوْ بُقْعَةً: أَعَادَ. لَا مَنْ حُبِسَ فِي مَحَلٍّ نَجِسٍ أَوْ غَصْبٍ لَا يُمْكِنُهُ الْخُرُوجُ مِنْهُ."]]},{"id":"ak3_14","label":"كِتَابُ الصَّلَاةِ · ١٤","segs":[["matn","الرَّابِعُ: اجْتِنَابُ نَجَاسَةٍ غَيْرِ مَعْفُوٍّ عَنْهَا فِي بَدَنٍ، وَثَوْبٍ، وَبُقْعَةٍ مَعَ الْقُدْرَةِ. وَمَنْ جَبَرَ عَظْمَهُ، أَوْ خَاطَهُ بِنَجِسٍ، وَتَضَرَّرَ بِقَلْعِهِ: لَمْ يَجِبْ، وَيَتَيَمَّمُ إِنْ لَمْ يُغَطِّهِ اللَّحْمُ."]]},{"id":"ak3_15","label":"كِتَابُ الصَّلَاةِ · ١٥","segs":[["matn","وَلَا تَصِحُّ -بِلَا عُذْرٍ- فِي: مَقْبَرَةٍ. وَخَلَاءٍ. وَحَمَّامٍ. وَأَعْطَانِ إِبِلٍ. وَمَجْزَرَةٍ. وَمَزْبَلَةٍ. وَقَارِعَةِ طَرِيقٍ. وَلَا فِي أَسْطِحَتِهَا. الْخَامِسُ: اسْتِقْبَالُ الْقِبْلَةِ. وَلَا تَصِحُّ بِدُونِهِ، إِلَّا: لِعَاجِزٍ. وَمُتَنَفِّلٍ فِي سَفَرٍ مُبَاحٍ."]]},{"id":"ak3_16","label":"كِتَابُ الصَّلَاةِ · ١٦","segs":[["matn","وَفَرْضُ قَرِيبٍ مِنْهَا: إِصَابَةُ عَيْنِهَا. وَبَعِيدٍ: جِهَتُهَا. وَيَعْمَلُ وُجُوباً: بِخَبَرِ ثِقَةٍ بِيَقِينٍ. وَبِمَحَارِيبِ الْمُسْلِمِينَ. وَإِنِ اشْتَبَهَتْ فِي السَّفَرِ: اجْتَهَدَ عَارِفٌ بِأَدِلَّتِهَا. وَقَلَّدَ غَيْرُهُ."]]},{"id":"ak3_17","label":"كِتَابُ الصَّلَاةِ · ١٧","segs":[["matn","وَإِنْ صَلَّى بِلَا أَحَدِهِمَا مَعَ الْقُدْرَةِ: قَضَى مُطْلَقاً. السَّادِسُ: النِّيَّةُ. فَيَجِبُ تَعْيِينُ مُعَيَّنَةٍ. وَسُنَّ مُقَارَنَتُهَا لِتَكْبِيرَةِ إِحْرَامٍ. وَلَا يَضُرُّ تَقْدِيمُهَا عَلَيْهَا بِيَسِيرٍ. وَشُرِطَ: نِيَّةُ إِمَامَةٍ وَائْتِمَامٍ. وَلِمُؤْتَمٍّ انْفِرَادٌ لِعُذْرٍ."]]},{"id":"ak3_18","label":"كِتَابُ الصَّلَاةِ · ١٨","segs":[["matn","وَتَبْطُلُ صَلَاتُهُ بِبُطْلَانِ صَلَاةِ إِمَامِهِ. لَا عَكْسُهُ إِنْ نَوَى إِمَامٌ الِانْفِرَادَ. وَاللَّهُ أَعْلَمُ."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"ak4","title":"بَابُ صِفَةِ الصَّلَاةِ","units":[{"id":"ak4_1","label":"بَابُ صِفَةِ الصَّلَاةِ · ١","segs":[["matn","يُسَنُّ: خُرُوجُهُ إِلَيْهَا مُتَطَهِّراً. بِسَكِينَةٍ وَوَقَارٍ. مَعَ قَوْلِ مَا وَرَدَ. وَقِيَامُ إِمَامٍ فَغَيْرِ مُقِيمٍ إِلَيْهَا عِنْدَ قَوْلِ مُقِيمٍ: «قَدْ قَامَتِ الصَّلَاةُ». فَيَقُولُ: «اللَّهُ أَكْبَرُ»، وَهُوَ قَائِمٌ فِي فَرْضٍ."]]},{"id":"ak4_2","label":"بَابُ صِفَةِ الصَّلَاةِ · ٢","segs":[["matn","رَافِعاً يَدَيْهِ إِلَى حَذْوِ مَنْكِبَيْهِ. ثُمَّ يَقْبِضُ بِيُمْنَاهُ كُوعَ يُسْرَاهُ. وَيَجْعَلُهُمَا تَحْتَ سُرَّتِهِ. وَيَنْظُرُ مَسْجِدَهُ فِي كُلِّ صَلَاتِهِ. ثُمَّ يَقُولُ: «سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، وَتَبَارَكَ اسْمُكَ، وَتَعَالَى جَدُّكَ، وَلَا إِلَهَ غَيْرُكَ»."]]},{"id":"ak4_3","label":"بَابُ صِفَةِ الصَّلَاةِ · ٣","segs":[["matn","ثُمَّ يَسْتَعِيذُ. ثُمَّ يُبَسْمِلُ سِرًّا. ثُمَّ يَقْرَأُ الْفَاتِحَةَ مُرَتَّبَةً، مُتَوَالِيَةً. وَفِيهَا إِحْدَى عَشْرَةَ تَشْدِيدَةً. وَإِذَا فَرَغَ قَالَ: «آمِينَ»، يَجْهَرُ بِهَا: إِمَامٌ وَمَأْمُومٌ مَعاً فِي جَهْرِيَّةٍ. وَغَيْرُهُمَا فِيمَا يَجْهَرُ فِيهِ."]]},{"id":"ak4_4","label":"بَابُ صِفَةِ الصَّلَاةِ · ٤","segs":[["matn","وَيُسَنُّ جَهْرُ إِمَامٍ بِقِرَاءَةِ صُبْحٍ، وَجُمُعَةٍ، وَعِيدٍ، وَكُسُوفٍ، وَاسْتِسْقَاءٍ، وَأُولَيَيْ مَغْرِبٍ وَعِشَاءٍ. وَيُكْرَهُ لِمَأْمُومٍ. وَيُخَيَّرُ مُنْفَرِدٌ وَنَحْوُهُ. ثُمَّ يَقْرَأُ بَعْدَهَا سُورَةً فِي: الصُّبْحِ: مِنْ طِوَالِ الْمُفَصَّلِ. وَالْمَغْرِبِ: مِنْ قِصَارِهِ."]]},{"id":"ak4_5","label":"بَابُ صِفَةِ الصَّلَاةِ · ٥","segs":[["matn","وَالْبَاقِي: مِنْ أَوْسَاطِهِ. ثُمَّ يَرْكَعُ مُكَبِّراً رَافِعاً يَدَيْهِ. ثُمَّ يَضَعُهُمَا عَلَى رُكْبَتَيْهِ مُفَرَّجَتَيِ الْأَصَابِعِ، وَيُسَوِّي ظَهْرَهُ. وَيَقُولُ: «سُبْحَانَ رَبِّيَ الْعَظِيمِ» ثَلَاثاً، وَهُوَ أَدْنَى الْكَمَالِ."]]},{"id":"ak4_6","label":"بَابُ صِفَةِ الصَّلَاةِ · ٦","segs":[["matn","ثُمَّ يَرْفَعُ رَأْسَهُ وَيَدَيْهِ مَعاً، قَائِلاً: «سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ». وَبَعْدَ انْتِصَابِهِ: «رَبَّنَا وَلَكَ الْحَمْدُ، مِلْءَ السَّمَاءِ وَمِلْءَ الْأَرْضِ، وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ». وَمَأْمُومٌ: «رَبَّنَا وَلَكَ الْحَمْدُ» فَقَطْ."]]},{"id":"ak4_7","label":"بَابُ صِفَةِ الصَّلَاةِ · ٧","segs":[["matn","ثُمَّ يُكَبِّرُ، وَيَسْجُدُ عَلَى الْأَعْضَاءِ السَّبْعَةِ. فَيَضَعُ رُكْبَتَيْهِ، ثُمَّ يَدَيْهِ، ثُمَّ جَبْهَتَهُ وَأَنْفَهُ. وَسُنَّ: كَوْنُهُ عَلَى أَطْرَافِ أَصَابِعِهِ. وَمُجَافَاةُ عَضُدَيْهِ عَنْ جَنْبَيْهِ. وَبَطْنِهِ عَنْ فَخِذَيْهِ. وَتَفْرِقَةُ رُكْبَتَيْهِ."]]},{"id":"ak4_8","label":"بَابُ صِفَةِ الصَّلَاةِ · ٨","segs":[["matn","وَيَقُولُ: «سُبْحَانَ رَبِّيَ الْأَعْلَى» ثَلَاثاً، وَهُوَ أَدْنَى الْكَمَالِ. ثُمَّ يَرْفَعُ مُكَبِّراً. وَيَجْلِسُ مُفْتَرِشاً. وَيَقُولُ: «رَبِّي اغْفِرْ لِي» ثَلَاثاً، وَهُوَ أَكْمَلُهُ. وَيَسْجُدُ الثَّانِيَةَ كَذَلِكَ."]]},{"id":"ak4_9","label":"بَابُ صِفَةِ الصَّلَاةِ · ٩","segs":[["matn","ثُمَّ يَنْهَضُ مُكَبِّراً، مُعْتَمِداً عَلَى رُكْبَتَيْهِ بِيَدَيْهِ، فَإِنْ شَقَّ فَبِالْأَرْضِ. فَيَأْتِي بِمِثْلِهَا غَيْرَ: النِّيَّةِ. وَالتَّحْرِيمَةِ. وَالِاسْتِفْتَاحِ. وَالتَّعَوُّذِ إِنْ كَانَ تَعَوَّذَ. ثُمَّ يَجْلِسُ مُفْتَرِشاً. وَسُنَّ: وَضْعُ يَدَيْهِ عَلَى فَخِذَيْهِ."]]},{"id":"ak4_10","label":"بَابُ صِفَةِ الصَّلَاةِ · ١٠","segs":[["matn","وَقَبْضُ الْخِنْصِرِ وَالْبِنْصِرِ مِنْ يُمْنَاهُ، وَتَحْلِيقُ إِبْهَامِهَا مَعَ الْوُسْطَى. وَإِشَارَتُهُ بِسَبَّابَتِهَا فِي: تَشَهُّدٍ وَدُعَاءٍ عِنْدَ ذِكْرِ اللَّهِ، مُطْلَقاً. وَبَسْطُ الْيُسْرَى."]]},{"id":"ak4_11","label":"بَابُ صِفَةِ الصَّلَاةِ · ١١","segs":[["matn","ثُمَّ يَتَشَهَّدُ فَيَقُولُ: «التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ، السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، وَأَشْهَدُ أَنَّ مُحَمَّداً عَبْدُهُ وَرَسُولُهُ»."]]},{"id":"ak4_12","label":"بَابُ صِفَةِ الصَّلَاةِ · ١٢","segs":[["matn","ثُمَّ يَنْهَضُ فِي مَغْرِبٍ وَرُبَاعِيَّةٍ مُكَبِّراً. وَيُصَلِّي الْبَاقِيَ كَذَلِكَ، سِرًّا، مُقْتَصِراً عَلَى الْفَاتِحَةِ. ثُمَّ يَجْلِسُ مُتَوَرِّكاً."]]},{"id":"ak4_13","label":"بَابُ صِفَةِ الصَّلَاةِ · ١٣","segs":[["matn","فَيَأْتِي بِالتَّشَهُّدِ الْأَوَّلِ، ثُمَّ يَقُولُ: «اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَى آلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ، وَبَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَى آلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ»."]]},{"id":"ak4_14","label":"بَابُ صِفَةِ الصَّلَاةِ · ١٤","segs":[["matn","وَسُنَّ أَنْ يَتَعَوَّذَ فَيَقُولَ: «أَعُوذُ بِاللَّهِ مِنْ عَذَابِ جَهَنَّمَ، وَمِنْ عَذَابِ الْقَبْرِ، وَمِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ، وَمِنْ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْمَأْثَمِ وَالْمَغْرَمِ»."]]},{"id":"ak4_15","label":"بَابُ صِفَةِ الصَّلَاةِ · ١٥","segs":[["matn","وَتَبْطُلُ بِدُعَاءٍ بِأَمْرِ الدُّنْيَا. ثُمَّ يَقُولُ عَنْ يَمِينِهِ ثُمَّ عَنْ يَسَارِهِ: «السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ»، مُرَتَّباً، مُعَرَّفاً وُجُوباً. وَامْرَأَةٌ كَرَجُلٍ، لَكِنْ: تَجْمَعُ نَفْسَهَا."]]},{"id":"ak4_16","label":"بَابُ صِفَةِ الصَّلَاةِ · ١٦","segs":[["matn","وَتَجْلِسُ مُتَرَبِّعَةً، أَوْ مُسْدِلَةً رِجْلَيْهَا عَنْ يَمِينِهَا، وَهُوَ أَفْضَلُ. وَكُرِهَ فِيهَا: الْتِفَاتٌ وَنَحْوُهُ بِلَا حَاجَةٍ. وَإِقْعَاءٌ. وَافْتِرَاشُ ذِرَاعَيْهِ سَاجِداً. وَعَبَثٌ. وَتَخَصُّرٌ. وَفَرْقَعَةُ أَصَابِعَ. وَتَشْبِيكُهَا. وَكَوْنُهُ حَاقِناً وَنَحْوَهُ. وَتَائِقاً لِطَعَامٍ وَنَحْوِهِ."]]},{"id":"ak4_17","label":"بَابُ صِفَةِ الصَّلَاةِ · ١٧","segs":[["matn","وَإِذَا نَابَهُ شَيْءٌ: سَبَّحَ رَجُلٌ. وَصَفَّقَتِ امْرَأَةٌ بِبَطْنِ كَفِّهَا عَلَى ظَهْرِ الْأُخْرَى. وَيُزِيلُ بُصَاقاً وَنَحْوَهُ بِثَوْبِهِ. وَيُبَاحُ فِي غَيْرِ مَسْجِدٍ عَنْ يَسَارِهِ. وَيُكْرَهُ أَمَامَهُ، وَيَمِينَهُ."]]},{"id":"ak4_18","label":"بَابُ صِفَةِ الصَّلَاةِ · ١٨","segs":[["matn","فَصْلٌ: وَجُمْلَةُ أَرْكَانِهَا أَرْبَعَةَ عَشَرَ: الْقِيَامُ. وَالتَّحْرِيمَةُ. وَالْفَاتِحَةُ. وَالرُّكُوعُ. وَالِاعْتِدَالُ عَنْهُ. وَالسُّجُودُ. وَالِاعْتِدَالُ عَنْهُ. وَالْجُلُوسُ بَيْنَ السَّجْدَتَيْنِ. وَالطُّمَأْنِينَةُ. وَالتَّشَهُّدُ الْأَخِيرُ. وَجَلْسَتُهُ. وَالصَّلَاةُ عَلَى النَّبِيِّ عَلَيْهِ السَّلَامُ. وَالتَّسْلِيمَتَانِ. وَالتَّرْتِيبُ."]]},{"id":"ak4_19","label":"بَابُ صِفَةِ الصَّلَاةِ · ١٩","segs":[["matn","وَوَاجِبَاتُهَا ثَمَانِيَةٌ: التَّكْبِيرُ غَيْرُ التَّحْرِيمَةِ. وَالتَّسْمِيعُ. وَالتَّحْمِيدُ. وَتَسْبِيحُ رُكُوعٍ وَسُجُودٍ. وَقَوْلُ: «رَبِّ اغْفِرْ لِي» مَرَّةً مَرَّةً. وَالتَّشَهُّدُ الْأَوَّلُ. وَجَلْسَتُهُ. وَمَا عَدَا ذَلِكَ وَالشُّرُوطَ: سُنَّةٌ. فَالرُّكْنُ وَالشَّرْطُ: لَا يَسْقُطَانِ سَهْواً وَجَهْلاً. وَيَسْقُطُ الْوَاجِبُ بِهِمَا."]]},{"id":"ak4_20","label":"بَابُ صِفَةِ الصَّلَاةِ · ٢٠","segs":[["matn","فَصْلٌ: وَيُشْرَعُ سُجُودُ السَّهْوِ: لِزِيَادَةٍ. وَنَقْصٍ. وَشَكٍّ. لَا فِي عَمْدٍ. وَهُوَ: وَاجِبٌ: لِمَا تَبْطُلُ بِتَعَمُّدِهِ. وَسُنَّةٌ: لِإِتْيَانٍ بِقَوْلٍ مَشْرُوعٍ فِي غَيْرِ مَحَلِّهِ سَهْواً، وَلَا تَبْطُلُ بِتَعَمُّدِهِ. وَمُبَاحٌ: لِتَرْكِ سُنَّةٍ."]]},{"id":"ak4_21","label":"بَابُ صِفَةِ الصَّلَاةِ · ٢١","segs":[["matn","وَمَحَلُّهُ: قَبْلَ السَّلَامِ نَدْباً. إِلَّا إِذَا سَلَّمَ عَنْ نَقْصِ رَكْعَةٍ فَأَكْثَرَ: فَبَعْدَهُ نَدْباً. وَإِنْ سَلَّمَ قَبْلَ إِتْمَامِهَا: عَمْداً: بَطَلَتْ. وَسَهْواً: فَإِنْ ذَكَرَ قَرِيباً أَتَمَّهَا وَسَجَدَ."]]},{"id":"ak4_22","label":"بَابُ صِفَةِ الصَّلَاةِ · ٢٢","segs":[["matn","وَإِنْ أَحْدَثَ، أَوْ قَهْقَهَ: بَطَلَتْ؛ كَفِعْلِهِمَا فِي صُلْبِهَا. وَإِنْ: نَفَخَ. أَوِ انْتَحَبَ لَا مِنْ خَشْيَةِ اللَّهِ. أَوْ تَنَحْنَحَ بِلَا حَاجَةٍ. فَبَانَ حَرْفَانِ: بَطَلَتْ."]]},{"id":"ak4_23","label":"بَابُ صِفَةِ الصَّلَاةِ · ٢٣","segs":[["matn","وَمَنْ تَرَكَ رُكْناً غَيْرَ التَّحْرِيمَةِ، فَذَكَرَهُ: بَعْدَ شُرُوعِهِ فِي قِرَاءَةِ رَكْعَةٍ أُخْرَى: بَطَلَتِ الْمَتْرُوكُ مِنْهَا، وَصَارَتِ الَّتِي شَرَعَ فِي قِرَاءَتِهَا مَكَانَهَا. وَقَبْلَهُ: يَعُودُ فَيَأْتِي بِهِ وَبِمَا بَعْدَهُ."]]},{"id":"ak4_24","label":"بَابُ صِفَةِ الصَّلَاةِ · ٢٤","segs":[["matn","وَبَعْدَ سَلَامٍ: فَكَتَرْكِ رَكْعَةٍ. وَإِنْ نَهَضَ عَنْ تَشَهُّدٍ أَوَّلَ نَاسِياً: لَزِمَ رُجُوعُهُ. وَكُرِهَ: إِنِ اسْتَتَمَّ قَائِماً. وَحَرُمَ وَبَطَلَتْ: إِنْ شَرَعَ فِي الْقِرَاءَةِ، لَا إِنْ نَسِيَ أَوْ جَهِلَ. وَيَتْبَعُ مَأْمُومٌ."]]},{"id":"ak4_25","label":"بَابُ صِفَةِ الصَّلَاةِ · ٢٥","segs":[["matn","وَيَجِبُ السُّجُودُ لِذَلِكَ مُطْلَقاً. وَيَبْنِي عَلَى الْيَقِينِ -وَهُوَ الْأَقَلُّ-: مَنْ شَكَّ فِي رُكْنٍ، أَوْ عَدَدٍ. وَاللَّهُ أَعْلَمُ."]]},{"id":"ak4_26","label":"بَابُ صِفَةِ الصَّلَاةِ · ٢٦","segs":[["matn","فَصْلٌ: آكَدُ صَلَاةِ تَطَوُّعٍ: كُسُوفٌ. فَاسْتِسْقَاءٌ. فَتَرَاوِيحُ. فَوِتْرٌ. وَوَقْتُهُ: مِنْ صَلَاةِ الْعِشَاءِ إِلَى الْفَجْرِ. وَأَقَلُّهُ: رَكْعَةٌ. وَأَكْثَرُهُ: إِحْدَى عَشْرَةَ، مَثْنَى مَثْنَى، وَيُوتِرُ بِوَاحِدَةٍ. وَأَدْنَى الْكَمَالِ: ثَلَاثٌ بِسَلَامَيْنِ."]]},{"id":"ak4_27","label":"بَابُ صِفَةِ الصَّلَاةِ · ٢٧","segs":[["matn","وَيَقْنُتُ بَعْدَ الرُّكُوعِ نَدْباً. فَيَقُولُ: «اللَّهُمَّ اهْدِنِي فِيمَنْ هَدَيْتَ، وَعَافِنِي فِيمَنْ عَافَيْتَ، وَتَوَلَّنِي فِيمَنْ تَوَلَّيْتَ، وَبَارِكْ لِي فِيمَا أَعْطَيْتَ، وَقِنِي شَرَّ مَا قَضَيْتَ، إِنَّكَ تَقْضِي وَلَا يُقْضَى عَلَيْكَ، إِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ، وَلَا يَعِزُّ مَنْ عَادَيْتَ، تَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ»."]]},{"id":"ak4_28","label":"بَابُ صِفَةِ الصَّلَاةِ · ٢٨","segs":[["matn","«اللَّهُمَّ إِنَّا نَعُوذُ بِرِضَاكَ مِنْ سَخَطِكَ، وَبِعَفْوِكَ مِنْ عُقُوبَتِكَ، وَبِكَ مِنْكَ، لَا نُحْصِي ثَنَاءً عَلَيْكَ، أَنْتَ كَمَا أَثْنَيْتَ عَلَى نَفْسِكَ». ثُمَّ يُصَلِّي عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. وَيُؤَمِّنُ مَأْمُومٌ."]]},{"id":"ak4_29","label":"بَابُ صِفَةِ الصَّلَاةِ · ٢٩","segs":[["matn","وَيَجْمَعُ إِمَامٌ الضَّمِيرَ. وَيَمْسَحُ الدَّاعِي وَجْهَهُ بِيَدَيْهِ مُطْلَقاً. وَالتَّرَاوِيحُ: عِشْرُونَ رَكْعَةً، بِرَمَضَانَ. تُسَنُّ وَالْوِتْرُ مَعَهَا جَمَاعَةً. وَوَقْتُهَا: بَيْنَ سُنَّةِ عِشَاءٍ وَوِتْرٍ."]]},{"id":"ak4_30","label":"بَابُ صِفَةِ الصَّلَاةِ · ٣٠","segs":[["matn","ثُمَّ الرَّاتِبَةُ: رَكْعَتَانِ قَبْلَ الظُّهْرِ، وَرَكْعَتَانِ بَعْدَهَا، وَرَكْعَتَانِ بَعْدَ الْمَغْرِبِ، وَرَكْعَتَانِ بَعْدَ الْعِشَاءِ، وَرَكْعَتَانِ قَبْلَ الْفَجْرِ، وَهُمَا آكَدُهَا. وَتُسَنُّ صَلَاةُ اللَّيْلِ بِتَأَكُّدٍ. وَهِيَ أَفْضَلُ مِنْ صَلَاةِ النَّهَارِ."]]},{"id":"ak4_31","label":"بَابُ صِفَةِ الصَّلَاةِ · ٣١","segs":[["matn","وَسُجُودُ تِلَاوَةٍ لِقَارِئٍ وَمُسْتَمِعٍ. وَيُكَبِّرُ إِذَا سَجَدَ، وَإِذَا رَفَعَ، وَيَجْلِسُ، وَيُسَلِّمُ. وَكُرِهَ لِإِمَامٍ قِرَاءَتُهَا فِي سِرِّيَّةٍ، وَسُجُودُهُ لَهَا. وَعَلَى مَأْمُومٍ مُتَابَعَتُهُ فِي غَيْرِهَا. وَسُجُودُ شُكْرٍ عِنْدَ تَجَدُّدِ نِعَمٍ، وَانْدِفَاعِ نِقَمٍ."]]},{"id":"ak4_32","label":"بَابُ صِفَةِ الصَّلَاةِ · ٣٢","segs":[["matn","وَتَبْطُلُ بِهِ صَلَاةُ غَيْرِ جَاهِلٍ وَنَاسٍ. وَهُوَ كَسُجُودِ تِلَاوَةٍ. وَأَوْقَاتُ النَّهْيِ خَمْسَةٌ: مِنْ طُلُوعِ فَجْرٍ ثَانٍ إِلَى طُلُوعِ الشَّمْسِ. وَمِنْ صَلَاةِ الْعَصْرِ إِلَى الْغُرُوبِ. وَعِنْدَ طُلُوعِهَا إِلَى ارْتِفَاعِهَا قَدْرَ رُمْحٍ."]]},{"id":"ak4_33","label":"بَابُ صِفَةِ الصَّلَاةِ · ٣٣","segs":[["matn","وَعِنْدَ قِيَامِهَا حَتَّى تَزُولَ. وَعِنْدَ غُرُوبِهَا حَتَّى يَتِمَّ. فَيَحْرُمُ ابْتِدَاءُ نَفْلٍ فِيهَا مُطْلَقاً. لَا: قَضَاءُ فَرْضٍ. وَفِعْلُ رَكْعَتَيْ طَوَافٍ. وَسُنَّةُ فَجْرٍ أَدَاءً قَبْلَهَا. وَصَلَاةُ جِنَازَةٍ بَعْدَ فَجْرٍ وَعَصْرٍ."]]},{"id":"ak4_34","label":"بَابُ صِفَةِ الصَّلَاةِ · ٣٤","segs":[["matn","فَصْلٌ: تَجِبُ الْجَمَاعَةُ لِلْخَمْسِ الْمُؤَدَّاةِ عَلَى: الرِّجَالِ. الْأَحْرَارِ. الْقَادِرِينَ. وَحَرُمَ أَنْ يَؤُمَّ قَبْلَ رَاتِبٍ إِلَّا: بِإِذْنِهِ. أَوْ عُذْرِهِ. أَوْ عَدَمِ كَرَاهَتِهِ. وَمَنْ كَبَّرَ قَبْلَ تَسْلِيمَةِ الْإِمَامِ الْأُولَى: أَدْرَكَ الْجَمَاعَةَ."]]},{"id":"ak4_35","label":"بَابُ صِفَةِ الصَّلَاةِ · ٣٥","segs":[["matn","وَمَنْ أَدْرَكَهُ رَاكِعاً؛ أَدْرَكَ الرَكْعَةَ بِشَرْطِ: إِدْرَاكِهِ رَاكِعاً. وَعَدَمِ شَكِّهِ فِيهِ. وَتَحْرِيمَتِهِ قَائِماً، وَتُسَنُّ ثَانِيَةٌ لِلرُّكُوعِ. وَمَا أَدْرَكَ مَعَهُ آخِرُهَا، وَمَا يَقْضِيهِ أَوَّلُهَا. وَيَتَحَمَّلُ عَنْ مَأْمُومٍ: قِرَاءَةً. وَسُجُودَ سَهْوٍ، وَتِلَاوَةٍ."]]},{"id":"ak4_36","label":"بَابُ صِفَةِ الصَّلَاةِ · ٣٦","segs":[["matn","وَسُتْرَةً. وَدُعَاءَ قُنُوتٍ. وَتَشَهُّداً أَوَّلَ إِذَا سُبِقَ بِرَكْعَةٍ. لَكِنْ يُسَنُّ أَنْ يَقْرَأَ فِي: سَكَتَاتِهِ. وَسِرِّيَّةٍ. وَإِذَا لَمْ يَسْمَعْهُ لِبُعْدٍ، لَا طَرَشٍ. وَسُنَّ لَهُ: التَّخْفِيفُ مَعَ الْإِتْمَامِ. وَتَطْوِيلُ الْأُولَى عَلَى الثَّانِيَةِ. وَانْتِظَارُ دَاخِلٍ مَا لَمْ يَشُقَّ."]]},{"id":"ak4_37","label":"بَابُ صِفَةِ الصَّلَاةِ · ٣٧","segs":[["matn","فَصْلٌ: الْأَقْرَأُ الْعَالِمُ فِقْهَ صَلَاتِهِ: أَوْلَى مِنَ الْأَفْقَهِ. وَلَا تَصِحُّ خَلْفَ فَاسِقٍ، إِلَّا فِي جُمُعَةٍ وَعِيدٍ تَعَذَّرَا خَلْفَ غَيْرِهِ. وَلَا إِمَامَةُ: مَنْ حَدَثُهُ دَائِمٌ."]]},{"id":"ak4_38","label":"بَابُ صِفَةِ الصَّلَاةِ · ٣٨","segs":[["matn","وَأُمِّيٍّ، وَهُوَ: مَنْ لَا يُحْسِنُ الْفَاتِحَةَ، أَوْ يُدْغِمُ فِيهَا حَرْفاً لَا يُدْغَمُ، أَوْ يَلْحَنُ فِيهَا لَحْناً يُحِيلُ الْمَعْنَى. إِلَّا بِمِثْلِهِ. وَكَذَا مَنْ بِهِ سَلَسُ بَوْلٍ."]]},{"id":"ak4_39","label":"بَابُ صِفَةِ الصَّلَاةِ · ٣٩","segs":[["matn","وَعَاجِزٌ عَنْ: رُكُوعٍ وَسُجُودٍ، أَوْ عَنْ قُعُودٍ وَنَحْوِهَا، أَوِ اجْتِنَابِ نَجَاسَةٍ، أَوِ اسْتِقْبَالٍ. وَلَا عَاجِزٍ عَنْ قِيَامٍ بِقَادِرٍ، إِلَّا: رَاتِباً. رُجِيَ زَوَالُ عِلَّتِهِ. وَلَا مُمَيِّزٍ لِبَالِغٍ فِي فَرْضٍ."]]},{"id":"ak4_40","label":"بَابُ صِفَةِ الصَّلَاةِ · ٤٠","segs":[["matn","وَلَا امْرَأَةٍ لِرِجَالٍ وَخَنَاثَى. وَلَا خَلْفَ مُحْدِثٍ أَوْ نَجِسٍ، فَإِنْ جَهِلَا حَتَّى انْقَضَتْ؛ صَحَّتْ لِمَأْمُومٍ. وَتُكْرَهُ إِمَامَةُ: لَحَّانٍ. وَفَأْفَاءٍ وَنَحْوِهِ. وَسُنَّ وُقُوفُ: الْمَأْمُومِينَ: خَلْفَ الْإِمَامِ. وَالْوَاحِدُ: عَنْ يَمِينِهِ وُجُوباً."]]},{"id":"ak4_41","label":"بَابُ صِفَةِ الصَّلَاةِ · ٤١","segs":[["matn","وَالْمَرْأَةُ: خَلْفَهُ. وَمَنْ صَلَّى: عَنْ يَسَارِ الْإِمَامِ مَعَ خُلُوِّ يَمِينِهِ. أَوْ فَذًّا رَكْعَةً. لَمْ تَصِحَّ صَلَاتُهُ. وَإِذَا جَمَعَهُمَا مَسْجِدٌ: صَحَّتِ الْقُدْوَةُ مُطْلَقاً بِشَرْطِ: الْعِلْمِ بِانْتِقَالَاتِ الْإِمَامِ."]]},{"id":"ak4_42","label":"بَابُ صِفَةِ الصَّلَاةِ · ٤٢","segs":[["matn","وَإِلَّا شُرِطَ: رُؤْيَةُ الْإِمَامِ، أَوْ مَنْ وَرَاءَهُ أَيْضاً، وَلَوْ فِي بَعْضِهَا. وَكُرِهَ: عُلُوُّ إِمَامٍ عَلَى مَأْمُومٍ ذِرَاعاً فَأَكْثَرَ. وَصَلَاتُهُ فِي مِحْرَابٍ يَمْنَعُ مُشَاهَدَتَهُ. وَتَطَوُّعُهُ مَوْضِعَ الْمَكْتُوبَةِ. وَإِطَالَتُهُ الِاسْتِقْبَالَ بَعْدَ السَّلَامِ."]]},{"id":"ak4_43","label":"بَابُ صِفَةِ الصَّلَاةِ · ٤٣","segs":[["matn","وَوُقُوفُ مَأْمُومٍ بَيْنَ سَوَارٍ تَقْطَعُ الصُّفُوفَ عُرْفاً. إِلَّا لِحَاجَةٍ فِي الْكُلِّ. وَحُضُورُ مَسْجِدٍ وَجَمَاعَةٍ لِمَنْ رَائِحَتُهُ كَرِيهَةٌ مِنْ بَصَلٍ أَوْ غَيْرِهِ. وَيُعْذَرُ بِتَرْكِ جُمُعَةٍ وَجَمَاعَةٍ: مَرِيضٌ. وَمُدَافِعُ أَحَدِ الْأَخْبَثَيْنِ."]]},{"id":"ak4_44","label":"بَابُ صِفَةِ الصَّلَاةِ · ٤٤","segs":[["matn","وَمَنْ بِحَضْرَةِ طَعَامٍ يَحْتَاجُ إِلَيْهِ. وَخَائِفٌ ضَيَاعَ مَالِهِ. أَوْ مَوْتَ قَرِيبِهِ. أَوْ ضَرَراً مِنْ سُلْطَانٍ. أَوْ مَطَرٍ وَنَحْوِهِ. أَوْ مُلَازَمَةَ غَرِيمٍ وَلَا وَفَاءَ لَهُ. أَوْ فَوْتَ رُفْقَتِهِ. وَنَحْوُهُمْ."]]},{"id":"ak4_45","label":"بَابُ صِفَةِ الصَّلَاةِ · ٤٥","segs":[["matn","فَصْلٌ: يُصَلِّي الْمَرِيضُ: قَائِماً. فَإِنْ لَمْ يَسْتَطِعْ: فَقَاعِداً. فَإِنْ لَمْ يَسْتَطِعْ: فَعَلَى جَنْبٍ، وَالْأَيْمَنُ أَفْضَلُ. وَكُرِهَ مُسْتَلْقِياً مَعَ قُدْرَتِهِ عَلَى جَنْبٍ، وَإِلَّا تَعَيَّنَ. وَيُومِئُ بِرُكُوعٍ وَسُجُودٍ، وَيَجْعَلُهُ أَخْفَضَ."]]},{"id":"ak4_46","label":"بَابُ صِفَةِ الصَّلَاةِ · ٤٦","segs":[["matn","فَإِنْ عَجَزَ: أَوْمَأَ بِطَرْفِهِ وَنَوَى بِقَلْبِهِ؛ كَأَسِيرٍ خَائِفٍ. فَإِنْ عَجَزَ: فَبِقَلْبِهِ، مُسْتَحْضِراً الْقَوْلِ وَالْفِعْلِ. وَلَا يَسْقُطُ فِعْلُهَا مَا دَامَ الْعَقْلُ ثَابِتاً. فَإِنْ طَرَأَ عَجْزٌ أَوْ قُدْرَةٌ فِي أَثْنَائِهَا: انْتَقَلَ وَبَنَى."]]},{"id":"ak4_47","label":"بَابُ صِفَةِ الصَّلَاةِ · ٤٧","segs":[["matn","فَصْلٌ: وَيُسَنُّ قَصْرُ الرُّبَاعِيَّةِ فِي: سَفَرٍ طَوِيلٍ. مُبَاحٍ. وَيَقْضِي صَلَاةَ سَفَرٍ فِي حَضَرٍ، وَعَكْسُهُ: تَامَّةً. وَمَنْ نَوَى: إِقَامَةً مُطْلَقَةً بِمَوْضِعٍ. أَوْ أَكْثَرَ مِنْ أَرْبَعَةِ أَيَّامٍ. أَوِ ائْتَمَّ بِمُقِيمٍ. أَتَمَّ."]]},{"id":"ak4_48","label":"بَابُ صِفَةِ الصَّلَاةِ · ٤٨","segs":[["matn","وَإِنْ حُبِسَ ظُلْماً، أَوْ لَمْ يَنْوِ إِقَامَةً: قَصَرَ أَبَداً. وَيُبَاحُ لَهُ الْجَمْعُ: بَيْنَ الظُّهْرَيْنِ أَوِ الْعِشَاءَيْنِ بِوَقْتِ إِحْدَاهُمَا. وَلِمَرِيضٍ وَنَحْوِهِ يَلْحَقُهُ بِتَرْكِهِ مَشَقَّةٌ. وَبَيْنَ الْعِشَاءَيْنِ فَقَطْ لِمَطَرٍ وَنَحْوِهِ: يَبُلُّ الثَّوْبَ."]]},{"id":"ak4_49","label":"بَابُ صِفَةِ الصَّلَاةِ · ٤٩","segs":[["matn","وَتُوجَدُ مَعَهُ مَشَقَّةٌ. وَلِوَحَلٍ. وَرِيحٍ شَدِيدَةٍ، بَارِدَةٍ، لَا بَارِدَةٍ فَقَطْ، إِلَّا بِلَيْلَةٍ مُظْلِمَةٍ. وَالْأَفْضَلُ فِعْلُ الْأَرْفَقِ مِنْ تَقْدِيمٍ أَوْ تَأْخِيرٍ. وَكُرِهَ فِعْلُهُ فِي بَيْتِهِ وَنَحْوِهِ بِلَا ضَرُورَةٍ."]]},{"id":"ak4_50","label":"بَابُ صِفَةِ الصَّلَاةِ · ٥٠","segs":[["matn","وَيَبْطُلُ جَمْعُ تَقْدِيمٍ: بِرَاتِبَةٍ بَيْنَهُمَا. وَتَفْرِيقٍ بِأَكْثَرَ مِنْ وُضُوءٍ خَفِيفٍ وَإِقَامَةٍ. وَتَجُوزُ صَلَاةُ الْخَوْفِ بِأَيِّ صِفَةٍ صَحَّتْ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. وَصَحَّتْ مِنْ سِتَّةِ أَوْجُهٍ. وَسُنَّ فِيهَا حَمْلُ سِلَاحٍ غَيْرِ مُثْقِلٍ."]]},{"id":"ak4_51","label":"بَابُ صِفَةِ الصَّلَاةِ · ٥١","segs":[["matn","فَصْلٌ: تَلْزَمُ الْجُمُعَةُ كُلَّ: مُسْلِمٍ. مُكَلَّفٍ. ذَكَرٍ. حُرٍّ. مُسْتَوْطِنٍ بِبِنَاءٍ. وَمَنْ صَلَّى الظُّهْرَ مِمَّنْ عَلَيْهِ الْجُمُعَةُ قَبْلَ الْإِمَامِ: لَمْ تَصِحَّ، وَإِلَّا صَحَّتْ. وَالْأَفْضَلُ بَعْدَهُ. وَحَرُمَ سَفَرُ مَنْ تَلْزَمُهُ بَعْدَ الزَّوَالِ."]]},{"id":"ak4_52","label":"بَابُ صِفَةِ الصَّلَاةِ · ٥٢","segs":[["matn","وَكُرِهَ قَبْلَهُ، مَا لَمْ يَأْتِ بِهَا فِي طَرِيقِهِ، أَوْ يَخَفْ فَوْتَ رُفْقَةٍ. وَشُرِطَ لِصِحَّتِهَا: الْوَقْتُ. وَهُوَ: أَوَّلُ وَقْتِ الْعِيدِ، إِلَى آخِرِ وَقْتِ الظُّهْرِ."]]},{"id":"ak4_53","label":"بَابُ صِفَةِ الصَّلَاةِ · ٥٣","segs":[["matn","فَإِنْ خَرَجَ قَبْلَ التَّحْرِيمَةِ: صَلَّوْا ظُهْراً، وَإِلَّا جُمُعَةً. وَحُضُورُ أَرْبَعِينَ بِالْإِمَامِ مِنْ أَهْلِ وُجُوبِهَا. فَإِنْ نَقَصُوا قَبْلَ إِتْمَامِهَا: اسْتَأْنَفُوا جُمُعَةً إِنْ أَمْكَنَ، وَإِلَّا ظُهْراً."]]},{"id":"ak4_54","label":"بَابُ صِفَةِ الصَّلَاةِ · ٥٤","segs":[["matn","وَمَنْ أَدْرَكَ مَعَ الْإِمَامِ رَكْعَةً: أَتَمَّهَا جُمُعَةً. وَتَقْدِيمُ خُطْبَتَيْنِ. مِنْ شَرْطِهِمَا: الْوَقْتُ. وَحَمْدُ اللَّهِ. وَالصَّلَاةُ عَلَى رَسُولِهِ عَلَيْهِ السَّلَامُ. وَقِرَاءَةُ آيَةٍ. وَحُضُورُ الْعَدَدِ الْمُعْتَبَرِ. وَرَفْعُ الصَّوْتِ بِقَدْرِ إِسْمَاعِهِ. وَالنِّيَّةُ."]]},{"id":"ak4_55","label":"بَابُ صِفَةِ الصَّلَاةِ · ٥٥","segs":[["matn","وَالْوَصِيَّةُ بِتَقْوَى اللَّهِ، وَلَا يَتَعَيَّنُ لَفْظُهَا. وَأَنْ تَكُونَا مِمَّنْ يَصِحُّ أَنْ يَؤُمَّ فِيهَا، لَا مِمَّنْ يَتَوَلَّى الصَّلَاةَ. وَتُسَنُّ الْخُطْبَةُ: عَلَى مِنْبَرٍ، أَوْ مَوْضِعٍ عَالٍ."]]},{"id":"ak4_56","label":"بَابُ صِفَةِ الصَّلَاةِ · ٥٦","segs":[["matn","وَسَلَامُ خَطِيبٍ: إِذَا خَرَجَ، وَإِذَا أَقْبَلَ عَلَيْهِمْ. وَجُلُوسُهُ إِلَى فَرَاغِ الْأَذَانِ، وَبَيْنَهُمَا قَلِيلاً. وَالْخُطْبَةُ قَائِماً. مُعْتَمِداً عَلَى سَيْفٍ، أَوْ عَصاً. قَاصِداً تِلْقَاءَهُ. وَتَقْصِيرُهُمَا، وَالثَّانِيَةِ أَكْثَرَ. وَالدُّعَاءُ لِلْمُسْلِمِينَ، وَأُبِيحَ لِمُعَيَّنٍ؛ كَالسُّلْطَانِ."]]},{"id":"ak4_57","label":"بَابُ صِفَةِ الصَّلَاةِ · ٥٧","segs":[["matn","وَهِيَ رَكْعَتَانِ. يَقْرَأُ فِي الْأُولَى بَعْدَ الْفَاتِحَةِ: الْجُمُعَةَ، وَالثَّانِيَةِ: الْمُنَافِقِينَ. وَحَرُمَ إِقَامَتُهَا وَعِيدٍ فِي أَكْثَرَ مِنْ مَوْضِعٍ بِبَلَدٍ إِلَّا لِحَاجَةٍ. وَأَقَلُّ السُّنَّةِ بَعْدَهَا: رَكْعَتَانِ، وَأَكْثَرُهَا: سِتٌّ."]]},{"id":"ak4_58","label":"بَابُ صِفَةِ الصَّلَاةِ · ٥٨","segs":[["matn","وَسُنَّ: قَبْلَهَا أَرْبَعٌ غَيْرُ رَاتِبَةٍ. وَقِرَاءَةُ الْكَهْفِ فِي يَوْمِهَا وَلَيْلَتِهَا. وَكَثْرَةُ دُعَاءٍ، وَصَلَاةٍ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. وَغُسْلٌ. وَتَنَظُّفٌ. وَتَطَيُّبٌ. وَلُبْسُ بَيْضَاءَ. وَتَبْكِيرٌ إِلَيْهَا مَاشِياً. وَدُنُوٌّ مِنَ الْإِمَامِ."]]},{"id":"ak4_59","label":"بَابُ صِفَةِ الصَّلَاةِ · ٥٩","segs":[["matn","وَكُرِهَ: لِغَيْرِهِ: تَخَطِّي الرِّقَابِ، إِلَّا لِفُرْجَةٍ لَا يَصِلُ إِلَيْهَا إِلَّا بِهِ. وَإِيثَارٌ بِمَكَانٍ أَفْضَلَ، لَا قَبُولٌ. وَحَرُمَ: أَنْ يُقِيمَ غَيْرَ صَبِيٍّ مِنْ مَكَانِهِ فَيَجْلِسَ فِيهِ."]]},{"id":"ak4_60","label":"بَابُ صِفَةِ الصَّلَاةِ · ٦٠","segs":[["matn","وَالْكَلَامُ حَالَ الْخُطْبَةِ، عَلَى غَيْرِ: خَطِيبٍ، وَمَنْ كَلَّمَهُ لِحَاجَةٍ. وَمَنْ دَخَلَ وَالْإِمَامُ يَخْطُبُ: صَلَّى التَّحِيَّةَ فَقَطْ، خَفِيفَةً."]]},{"id":"ak4_61","label":"بَابُ صِفَةِ الصَّلَاةِ · ٦١","segs":[["matn","فَصْلٌ: وَصَلَاةُ الْعِيدَيْنِ: فَرْضُ كِفَايَةٍ. وَوَقْتُهَا: كَصَلَاةِ الضُّحَى، وَآخِرُهُ: الزَّوَالُ. فَإِنْ لَمْ يُعْلَمْ بِالْعِيدِ إِلَّا بَعْدَهُ: صَلَّوْا مِنَ الْغَدِ قَضَاءً. وَشُرِطَ لِوُجُوبِهَا: شُرُوطُ جُمُعَةٍ. وَلِصِحَّتِهَا: اسْتِيطَانٌ. وَعَدَدُ الْجُمُعَةِ."]]},{"id":"ak4_62","label":"بَابُ صِفَةِ الصَّلَاةِ · ٦٢","segs":[["matn","لَكِنْ يُسَنُّ لِمَنْ فَاتَتْهُ أَوْ بَعْضُهَا: أَنْ يَقْضِيَهَا، وَعَلَى صِفَتِهَا أَفْضَلُ. وَتُسَنُّ: فِي صَحْرَاءَ. وَتَأْخِيرُ صَلَاةِ فِطْرٍ. وَأَكْلٌ قَبْلَهَا. وَتَقْدِيمُ أَضْحَى. وَتَرْكُ أَكْلٍ قَبْلَهَا لِمُضَحٍّ. وَيُصَلِّيهَا رَكْعَتَيْنِ. قَبْلَ الْخُطْبَةِ."]]},{"id":"ak4_63","label":"بَابُ صِفَةِ الصَّلَاةِ · ٦٣","segs":[["matn","يُكَبِّرُ فِي الْأُولَى بَعْدَ الِاسْتِفْتَاحِ، وَقَبْلَ التَّعَوُّذِ وَالْقِرَاءَةِ: سِتًّا، وَفِي الثَّانِيَةِ قَبْلَ الْقِرَاءَةِ: خَمْساً. رَافِعاً يَدَيْهِ مَعَ كُلِّ تَكْبِيرَةٍ."]]},{"id":"ak4_64","label":"بَابُ صِفَةِ الصَّلَاةِ · ٦٤","segs":[["matn","وَيَقُولُ بَيْنَ كُلِّ تَكْبِيرَتَيْنِ: «اللَّهُ أَكْبَرُ كَبِيراً، وَالْحَمْدُ لِلَّهِ كَثِيراً، وَسُبْحَانَ اللَّهِ بُكْرَةً وَأَصِيلاً، وَصَلَّى اللَّهُ عَلَى مُحَمَّدٍ وَآلِهِ وَسَلَّمَ تَسْلِيماً كَثِيراً»، أَوْ غَيْرَهُ."]]},{"id":"ak4_65","label":"بَابُ صِفَةِ الصَّلَاةِ · ٦٥","segs":[["matn","ثُمَّ يَقْرَأُ بَعْدَ الْفَاتِحَةِ فِي الْأُولَى: «سَبِّحْ»، وَالثَّانِيَةِ: «الْغَاشِيَةَ». ثُمَّ يَخْطُبُ كَخُطْبَتَيِ الْجُمُعَةِ، لَكِنْ يَسْتَفْتِحُ فِي الْأُولَى: بِتِسْعِ تَكْبِيرَاتٍ، وَالثَّانِيَةَ: بِسَبْعٍ."]]},{"id":"ak4_66","label":"بَابُ صِفَةِ الصَّلَاةِ · ٦٦","segs":[["matn","وَيُبَيِّنُ لَهُمْ فِي الْفِطْرِ مَا يُخْرِجُونَ، وَفِي الْأَضْحَى مَا يُضَحُّونَ. وَسُنَّ التَّكْبِيرُ الْمُطْلَقُ: لَيْلَتَيِ الْعِيدَيْنِ، وَالْفِطْرُ آكَدُ. وَمِنْ أَوَّلِ ذِي الْحِجَّةِ إِلَى فَرَاغِ الْخُطْبَةِ."]]},{"id":"ak4_67","label":"بَابُ صِفَةِ الصَّلَاةِ · ٦٧","segs":[["matn","وَالْمُقَيَّدُ: عَقِبَ كُلِّ فَرِيضَةٍ، فِي جَمَاعَةٍ: مِنْ فَجْرِ عَرَفَةَ لِمُحِلٍّ. وَلِمُحْرِمٍ: مِنْ ظُهْرِ يَوْمِ النَّحْرِ إِلَى عَصْرِ آخِرِ أَيَّامِ التَّشْرِيقِ."]]},{"id":"ak4_68","label":"بَابُ صِفَةِ الصَّلَاةِ · ٦٨","segs":[["matn","فَصْلٌ: وَتُسَنُّ صَلَاةُ كُسُوفٍ: رَكْعَتَيْنِ، كُلُّ رَكْعَةٍ بِقِيَامَيْنِ وَرُكُوعَيْنِ. وَتَطْوِيلُ سُورَةٍ وَتَسْبِيحٍ. وَكَوْنُ أَوَّلِ كُلٍّ أَطْوَلَ. وَاسْتِسْقَاءٍ: إِذَا أَجْدَبَتِ الْأَرْضُ، وَقُحِطَ الْمَطَرُ. وَصِفَتُهَا وَأَحْكَامُهَا: كَعِيدٍ. وَهِيَ وَالَّتِي قَبْلَهَا: جَمَاعَةً أَفْضَلُ."]]},{"id":"ak4_69","label":"بَابُ صِفَةِ الصَّلَاةِ · ٦٩","segs":[["matn","وَإِذَا أَرَادَ الْإِمَامُ الْخُرُوجَ لَهَا: وَعَظَ النَّاسَ. وَأَمَرَهُمْ بِالتَّوْبَةِ. وَالْخُرُوجِ مِنَ الْمَظَالِمِ. وَتَرْكِ التَّشَاحُنِ. وَالصِّيَامِ. وَالصَّدَقَةِ. وَيَعِدُهُمْ يَوْماً يَخْرُجُونَ فِيهِ. وَيَخْرُجُ: مُتَوَاضِعاً، مُتَخَشِّعاً، مُتَذَلِّلاً، مُتَضَرِّعاً، مُتَنَظِّفاً، لَا مُطَيَّباً."]]},{"id":"ak4_70","label":"بَابُ صِفَةِ الصَّلَاةِ · ٧٠","segs":[["matn","وَمَعَهُ: أَهْلُ الدِّينِ وَالصَّلَاحِ، وَالشُّيُوخُ، وَمُمَيِّزُ الصِّبْيَانِ. فَيُصَلِّي، ثُمَّ يَخْطُبُ وَاحِدَةً. يَفْتَتِحُهَا بِالتَّكْبِيرِ كَخُطْبَةِ عِيدٍ. وَيُكْثِرُ فِيهَا: الِاسْتِغْفَارَ، وَقِرَاءَةَ الْآيَاتِ الَّتِي فِيهَا الْأَمْرُ بِهِ."]]},{"id":"ak4_71","label":"بَابُ صِفَةِ الصَّلَاةِ · ٧١","segs":[["matn","وَيَرْفَعُ يَدَيْهِ وَظُهُورُهُمَا نَحْوَ السَّمَاءِ، فَيَدْعُو بِدُعَاءِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَمِنْهُ: «اللَّهُمَّ اسْقِنَا غَيْثاً مُغِيثاً...» إِلَى آخِرِهِ."]]},{"id":"ak4_72","label":"بَابُ صِفَةِ الصَّلَاةِ · ٧٢","segs":[["matn","وَإِنْ كَثُرَ الْمَطَرُ حَتَّى خِيفَ سُنَّ قَوْلُ: «اللَّهُمَّ حَوَالَيْنَا وَلَا عَلَيْنَا، اللَّهُمَّ عَلَى الظِّرَابِ، وَالْآكَامِ، وَبُطُونِ الْأَوْدِيَةِ، وَمَنَابِتِ الشَّجَرِ»، «رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ...» الْآيَةَ."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"ak5","title":"كِتَابُ الْجَنَائِزِ","units":[{"id":"ak5_1","label":"كِتَابُ الْجَنَائِزِ · ١","segs":[["matn","تَرْكُ الدَّوَاءِ أَفْضَلُ. وَسُنَّ: اسْتِعْدَادٌ لِلْمَوْتِ. وَإِكْثَارٌ مِنْ ذِكْرِهِ. وَعِيَادَةُ مُسْلِمٍ غَيْرِ مُبْتَدِعٍ. وَتَذْكِيرُهُ التَّوْبَةَ، وَالْوَصِيَّةَ. فَإِذَا نُزِلَ بِهِ سُنَّ: تَعَاهُدُ بَلِّ حَلْقِهِ بِمَاءٍ أَوْ شَرَابٍ. وَتَنْدِيَةُ شَفَتَيْهِ."]]},{"id":"ak5_2","label":"كِتَابُ الْجَنَائِزِ · ٢","segs":[["matn","وَتَلْقِينُهُ: «لَا إِلَهَ إِلَّا اللَّهُ» مَرَّةً، وَلَا يُزَادُ عَلَى ثَلَاثٍ، إِلَّا أَنْ يَتَكَلَّمَ فَيُعَادُ بِرِفْقٍ. وَقِرَاءَةُ: الْفَاتِحَةِ، وَ«يس» عِنْدَهُ. وَتَوْجِيهُهُ إِلَى الْقِبْلَةِ. وَإِذَا مَاتَ: تَغْمِيضُ عَيْنَيْهِ. وَشَدُّ لَحْيَيْهِ. وَتَلْيِينُ مَفَاصِلِهِ."]]},{"id":"ak5_3","label":"كِتَابُ الْجَنَائِزِ · ٣","segs":[["matn","وَخَلْعُ ثِيَابِهِ. وَسَتْرُهُ بِثَوْبٍ. وَوَضْعُ حَدِيدَةٍ أَوْ نَحْوِهَا عَلَى بَطْنِهِ. وَجَعْلُهُ عَلَى سَرِيرِ غُسْلِهِ مُتَوَجِّهاً مُنْحَدِراً نَحْوَ رِجْلَيْهِ. وَإِسْرَاعُ تَجْهِيزِهِ. وَيَجِبُ فِي نَحْوِ: تَفْرِيقِ وَصِيَّتِهِ، وَقَضَاءِ دَيْنِهِ."]]},{"id":"ak5_4","label":"كِتَابُ الْجَنَائِزِ · ٤","segs":[["matn","فَصْلٌ: وَإِذَا أَخَذَ فِي غَسْلِهِ: سَتَرَ عَوْرَتَهُ. وَسُنَّ سَتْرُ كُلِّهِ عَنِ الْعُيُونِ. وَكُرِهَ حُضُورُ غَيْرِ مُعِينٍ. ثُمَّ نَوَى، وَسَمَّى، وَهُمَا كَفِي غُسْلِ حَيٍّ."]]},{"id":"ak5_5","label":"كِتَابُ الْجَنَائِزِ · ٥","segs":[["matn","ثُمَّ يَرْفَعُ رَأْسَ غَيْرِ حَامِلٍ إِلَى قُرْبِ جُلُوسٍ، وَيَعْصِرُ بَطْنَهُ بِرِفْقٍ، وَيُكْثِرُ الْمَاءَ حِينَئِذٍ. ثُمَّ يَلُفُّ عَلَى يَدِهِ خِرْقَةً فَيُنَجِّيهِ بِهَا. وَحَرُمَ مَسُّ عَوْرَةِ مَنْ لَهُ سَبْعٌ."]]},{"id":"ak5_6","label":"كِتَابُ الْجَنَائِزِ · ٦","segs":[["matn","ثُمَّ يُدْخِلُ إِصْبَعَيْهِ وَعَلَيْهَا خِرْقَةٌ مَبْلُولَةٌ فِي فَمِهِ، فَيَمْسَحُ أَسْنَانَهُ، وَفِي مَنْخِرَيْهِ فَيُنَظِّفُهُمَا بِلَا إِدْخَالِ مَاءٍ. ثُمَّ يُوَضِّئُهُ. وَيَغْسِلُ رَأْسَهُ وَلِحْيَتَهُ بِرَغْوَةِ السِّدْرِ، وَبَدَنَهُ بِثُفْلِهِ. ثُمَّ يُفِيضُ عَلَيْهِ الْمَاءَ."]]},{"id":"ak5_7","label":"كِتَابُ الْجَنَائِزِ · ٧","segs":[["matn","وَسُنَّ: تَثْلِيثٌ. وَتَيَامُنٌ. وَإِمْرَارُ يَدِهِ كُلَّ مَرَّةٍ عَلَى بَطْنِهِ. فَإِنْ لَمْ يُنْقِ: زَادَ حَتَّى يُنْقِي. وَكُرِهَ: اقْتِصَارٌ عَلَى مَرَّةٍ. وَمَاءٌ حَارٌّ، وَخِلَالٌ، وَأُشْنَانٌ بِلَا حَاجَةٍ. وَتَسْرِيحُ شَعْرِهِ."]]},{"id":"ak5_8","label":"كِتَابُ الْجَنَائِزِ · ٨","segs":[["matn","وَسُنَّ: كَافُورٌ وَسِدْرٌ فِي الْأَخِيرَةِ. وَخِضَابُ شَعْرٍ. وَقَصُّ شَارِبٍ، وَتَقْلِيمُ أَظْفَارٍ إِنْ طَالَا. وَتَنْشِيفٌ. وَيُجَنَّبُ مُحْرِمٌ مَاتَ مَا يُجَنَّبُ فِي حَيَاتِهِ. وَسِقْطٌ لِأَرْبَعَةِ أَشْهُرٍ: كَمَوْلُودٍ حَيًّا."]]},{"id":"ak5_9","label":"كِتَابُ الْجَنَائِزِ · ٩","segs":[["matn","وَإِذَا تَعَذَّرَ غَسْلُ مَيِّتٍ: يُمِّمَ. وَسُنَّ: تَكْفِينُ رَجُلٍ فِي ثَلَاثِ لَفَائِفَ بِيضٍ بَعْدَ تَبْخِيرِهَا. وَيُجْعَلُ الْحَنُوطُ: فِيمَا بَيْنَهَا. وَمِنْهُ بِقُطْنٍ بَيْنَ أَلْيَيْهِ. وَالْبَاقِي عَلَى مَنَافِذِ وَجْهِهِ. وَمَوَاضِعِ سُجُودِهِ."]]},{"id":"ak5_10","label":"كِتَابُ الْجَنَائِزِ · ١٠","segs":[["matn","ثُمَّ يَرُدُّ طَرَفَ الْعُلْيَا مِنَ الْجَانِبِ الْأَيْسَرِ عَلَى شِقِّهِ الْأَيْمَنِ، ثُمَّ الْأَيْمَنَ عَلَى الْأَيْسَرِ، ثُمَّ الثَّانِيَةَ وَالثَّالِثَةَ كَذَلِكَ. وَيَجْعَلُ أَكْثَرَ الْفَاضِلِ عِنْدَ رَأْسِهِ."]]},{"id":"ak5_11","label":"كِتَابُ الْجَنَائِزِ · ١١","segs":[["matn","وَسُنَّ لِامْرَأَةٍ خَمْسَةُ أَثْوَابٍ: إِزَارٌ، وَخِمَارٌ، وَقَمِيصٌ، وَلِفَافَتَانِ. وَلِصَغِيرَةٍ: قَمِيصٌ، وَلِفَافَتَانِ. وَالْوَاجِبُ: ثَوْبٌ يَسْتُرُ جَمِيعَ الْمَيِّتِ."]]},{"id":"ak5_12","label":"كِتَابُ الْجَنَائِزِ · ١٢","segs":[["matn","فَصْلٌ: وَتَسْقُطُ الصَّلَاةُ عَلَيْهِ بِمُكَلَّفٍ. وَتُسَنُّ جَمَاعَةً. وَقِيَامُ إِمَامٍ وَمُنْفَرِدٍ: عِنْدَ صَدْرِ رَجُلٍ. وَوَسَطِ امْرَأَةٍ. ثُمَّ يُكَبِّرُ أَرْبَعاً. يَقْرَأُ بَعْدَ الْأُولَى وَالتَّعَوُّذِ: الْفَاتِحَةَ بِلَا اسْتِفْتَاحٍ."]]},{"id":"ak5_13","label":"كِتَابُ الْجَنَائِزِ · ١٣","segs":[["matn","وَيُصَلِّي عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعْدَ الثَّانِيَةِ. وَيَدْعُو بَعْدَ الثَّالِثَةِ، وَالْأَفْضَلُ بِشَيْءٍ مِمَّا وَرَدَ، وَمِنْهُ: «اللَّهُمَّ اغْفِرْ لِحَيِّنَا وَمَيِّتِنَا، وَشَاهِدِنَا وَغَائِبِنَا، وَصَغِيرِنَا وَكَبِيرِنَا، وَذَكَرِنَا وَأُنْثَانَا»."]]},{"id":"ak5_14","label":"كِتَابُ الْجَنَائِزِ · ١٤","segs":[["matn","«إِنَّكَ تَعْلَمُ مُنْقَلَبَنَا وَمَثْوَانَا، وَأَنْتَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، اللَّهُمَّ مَنْ أَحْيَيْتَهُ مِنَّا فَأَحْيِهِ عَلَى الْإِسْلَامِ وَالسُّنَّةِ، وَمَنْ تَوَفَّيْتَهُ مِنَّا فَتَوَفَّهُ عَلَيْهِمَا»."]]},{"id":"ak5_15","label":"كِتَابُ الْجَنَائِزِ · ١٥","segs":[["matn","«اللَّهُمَّ اغْفِرْ لَهُ وَارْحَمْهُ، وَعَافِهِ وَاعْفُ عَنْهُ، وَأَكْرِمْ نُزُلَهُ، وَأَوْسِعْ مَدْخَلَهُ، وَاغْسِلْهُ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ، وَنَقِّهِ مِنَ الذُّنُوبِ وَالْخَطَايَا كَمَا يُنَقَّى الثَّوْبُ الْأَبْيَضُ مِنَ الدَّنَسِ،"]]},{"id":"ak5_16","label":"كِتَابُ الْجَنَائِزِ · ١٦","segs":[["matn","وَأَبْدِلْهُ دَاراً خَيْراً مِنْ دَارِهِ، وَزَوْجاً خَيْراً مِنْ زَوْجِهِ، وَأَدْخِلْهُ الْجَنَّةَ، وَأَعِذْهُ مِنْ عَذَابِ الْقَبْرِ، وَعَذَابِ النَّارِ». «وَافْسَحْ لَهُ فِي قَبْرِهِ، وَنَوِّرْ لَهُ فِيهِ»."]]},{"id":"ak5_17","label":"كِتَابُ الْجَنَائِزِ · ١٧","segs":[["matn","وَإِنْ كَانَ صَغِيراً أَوْ مَجْنُوناً قَالَ: «اللَّهُمَّ اجْعَلْهُ ذُخْراً لِوَالِدَيْهِ، وَفَرَطاً، وَأَجْراً، وَشَفِيعاً مُجَاباً، اللَّهُمَّ ثَقِّلْ بِهِ مَوَازِينَهُمَا، وَأَعْظِمْ بِهِ أُجُورَهُمَا، وَأَلْحِقْهُ بِصَالِحِ سَلَفِ الْمُؤْمِنِينَ، وَاجْعَلْهُ فِي كَفَالَةِ إِبْرَاهِيمَ، وَقِهِ بِرَحْمَتِكَ عَذَابَ الْجَحِيمِ»."]]},{"id":"ak5_18","label":"كِتَابُ الْجَنَائِزِ · ١٨","segs":[["matn","وَيَقِفُ بَعْدَ الرَّابِعَةِ قَلِيلاً. وَيُسَلِّمُ. وَيَرْفَعُ يَدَيْهِ مَعَ كُلِّ تَكْبِيرَةٍ. وَسُنَّ: تَرْبِيعٌ فِي حَمْلِهَا. وَإِسْرَاعٌ. وَكَوْنُ مَاشٍ: أَمَامَهَا. وَرَاكِبٍ لِحَاجَةٍ: خَلْفَهَا. وَقُرْبٌ مِنْهَا. وَكَوْنُ قَبْرٍ لَحْداً."]]},{"id":"ak5_19","label":"كِتَابُ الْجَنَائِزِ · ١٩","segs":[["matn","وَقَوْلُ مُدْخِلٍ: «بِاسْمِ اللَّهِ، عَلَى مِلَّةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ». وَلَحْدُهُ عَلَى شِقِّهِ الْأَيْمَنِ. وَيَجِبُ اسْتِقْبَالُهُ الْقِبْلَةَ. وَكُرِهَ: بِلَا حَاجَةٍ جُلُوسُ تَابِعِهَا قَبْلَ وَضْعِهَا. وَتَجْصِيصُ قَبْرٍ. وَبِنَاءٌ. وَكِتَابَةٌ."]]},{"id":"ak5_20","label":"كِتَابُ الْجَنَائِزِ · ٢٠","segs":[["matn","وَمَشْيٌ. وَجُلُوسٌ عَلَيْهِ. وَإِدْخَالُهُ شَيْئاً مَسَّتْهُ النَّارُ. وَتَبَسُّمٌ. وَحَدِيثٌ بِأَمْرِ الدُّنْيَا عِنْدَهُ. وَحَرُمَ دَفْنُ اثْنَيْنِ فِي قَبْرٍ إِلَّا لِضَرُورَةٍ. وَأَيُّ قُرْبَةٍ فُعِلَتْ وَجُعِلَ ثَوَابُهَا لِمُسْلِمٍ حَيٍّ أَوْ مَيِّتٍ: نَفَعَهُ."]]},{"id":"ak5_21","label":"كِتَابُ الْجَنَائِزِ · ٢١","segs":[["matn","وَسُنَّ: لِرِجَالٍ زِيَارَةُ قَبْرِ مُسْلِمٍ. وَالْقِرَاءَةُ عِنْدَهُ. وَمَا يُخَفِّفُ عَنْهُ، وَلَوْ بِجَعْلِ جَرِيدَةٍ رَطْبَةٍ فِي الْقَبْرِ."]]},{"id":"ak5_22","label":"كِتَابُ الْجَنَائِزِ · ٢٢","segs":[["matn","وَقَوْلُ زَائِرٍ، وَمَارٍّ بِهِ: «السَّلَامُ عَلَيْكُمْ دَارَ قَوْمٍ مُؤْمِنِينَ، وَإِنَّا إِنْ شَاءَ اللَّهُ بِكُمْ لَاحِقُونَ، يَرْحَمُ اللَّهُ الْمُسْتَقْدِمِينَ مِنْكُمْ وَالْمُسْتَأْخِرِينَ، نَسْأَلُ اللَّهَ لَنَا وَلَكُمُ الْعَافِيَةَ»."]]},{"id":"ak5_23","label":"كِتَابُ الْجَنَائِزِ · ٢٣","segs":[["matn","«اللَّهُمَّ لَا تَحْرِمْنَا أَجْرَهُمْ، وَلَا تَفْتِنَّا بَعْدَهُمْ، وَاغْفِرْ لَنَا وَلَهُمْ». وَتَعْزِيَةُ الْمُصَابِ بِالْمَيِّتِ: سُنَّةٌ. وَيَجُوزُ الْبُكَاءُ عَلَيْهِ. وَحَرُمَ: نَدْبٌ. وَنِيَاحَةٌ. وَشَقُّ ثَوْبٍ، وَلَطْمُ خَدٍّ وَنَحْوُهُ."]]}],"group":"كِتَابُ الْجَنَائِزِ"},{"id":"ak6","title":"كِتَابُ الزَّكَاةِ","units":[{"id":"ak6_1","label":"كِتَابُ الزَّكَاةِ · ١","segs":[["matn","تَجِبُ فِي خَمْسَةِ أَشْيَاءَ: بَهِيمَةِ أَنْعَامٍ، وَنَقْدٍ، وَعَرْضِ تِجَارَةٍ، وَخَارِجٍ مِنَ الْأَرْضِ، وَثِمَارٍ. بِشَرْطِ: إِسْلَامٍ. وَحُرِّيَّةٍ. وَمِلْكِ نِصَابٍ. وَاسْتِقْرَارِهِ. وَسَلَامَةٍ مِنْ دَيْنٍ يَنْقُصُ النِّصَابَ. وَمُضِيِّ حَوْلٍ، إِلَّا فِي: مُعَشَّرٍ."]]},{"id":"ak6_2","label":"كِتَابُ الزَّكَاةِ · ٢","segs":[["matn","وَنِتَاجِ سَائِمَةٍ. وَرِبْحِ تِجَارَةٍ. وَإِنْ نَقَصَ فِي بَعْضِ الْحَوْلِ بِبَيْعٍ أَوْ غَيْرِهِ -لَا فِرَاراً-: انْقَطَعَ. وَإِنْ أَبْدَلَهُ بِجِنْسِهِ: فَلَا. وَإِذَا قَبَضَ الدَّيْنَ: زَكَّاهُ لِمَا مَضَى."]]},{"id":"ak6_3","label":"كِتَابُ الزَّكَاةِ · ٣","segs":[["matn","وَشُرِطَ لَهَا فِي بَهِيمَةِ أَنْعَامٍ: سَوْمٌ أَيْضاً. وَأَقَلُّ نِصَابِ إِبِلٍ: خَمْسٌ، وَفِيهَا شَاةٌ. وَفِي عَشْرٍ: شَاتَانِ. وَفِي خَمْسَ عَشْرَةَ: ثَلَاثٌ. وَفِي عِشْرِينَ: أَرْبَعٌ."]]},{"id":"ak6_4","label":"كِتَابُ الزَّكَاةِ · ٤","segs":[["matn","وَفِي خَمْسٍ وَعِشْرِينَ: بِنْتُ مَخَاضٍ، وَهِيَ الَّتِي لَهَا سَنَةٌ. وَفِي سِتٍّ وَثَلَاثِينَ: بِنْتُ لَبُونٍ، وَهِيَ الَّتِي لَهَا سَنَتَانِ. وَفِي سِتٍّ وَأَرْبَعِينَ: حِقَّةٌ، وَهِيَ الَّتِي لَهَا ثَلَاثٌ."]]},{"id":"ak6_5","label":"كِتَابُ الزَّكَاةِ · ٥","segs":[["matn","وَفِي إِحْدَى وَسِتِّينَ: جَذَعَةٌ، وَهِيَ الَّتِي لَهَا أَرْبَعٌ. وَفِي سِتٍّ وَسَبْعِينَ: بِنْتَا لَبُونٍ. وَفِي إِحْدَى وَتِسْعِينَ: حِقَّتَانِ. وَفِي مِائَةٍ وَإِحْدَى وَعِشْرِينَ: ثَلَاثُ بَنَاتِ لَبُونٍ."]]},{"id":"ak6_6","label":"كِتَابُ الزَّكَاةِ · ٦","segs":[["matn","ثُمَّ فِي كُلِّ أَرْبَعِينَ: بِنْتُ لَبُونٍ، وَفِي كُلِّ خَمْسِينَ: حِقَّةٌ. وَأَقَلُّ نِصَابِ الْبَقَرِ: ثَلَاثُونَ، وَفِيهَا تَبِيعٌ، وَهُوَ الَّذِي لَهُ سَنَةٌ، أَوْ تَبِيعَةٌ. وَفِي أَرْبَعِينَ: مُسِنَّةٌ، وَهِيَ الَّتِي لَهَا سَنَتَانِ."]]},{"id":"ak6_7","label":"كِتَابُ الزَّكَاةِ · ٧","segs":[["matn","وَفِي سِتِّينَ: تَبِيعَتَانِ. ثُمَّ فِي كُلِّ ثَلَاثِينَ: تَبِيعٌ، وَفِي كُلِّ أَرْبَعِينَ: مُسِنَّةٌ. وَأَقَلُّ نِصَابِ الْغَنَمِ: أَرْبَعُونَ، وَفِيهَا شَاةٌ. وَفِي مِائَةٍ وَإِحْدَى وَعِشْرِينَ: شَاتَانِ. وَفِي مِائَتَيْنِ وَوَاحِدَةٍ: ثَلَاثٌ، إِلَى أَرْبَعِمِائَةٍ."]]},{"id":"ak6_8","label":"كِتَابُ الزَّكَاةِ · ٨","segs":[["matn","ثُمَّ فِي كُلِّ مِائَةٍ: شَاةٌ. وَالشَّاةُ: بِنْتُ سَنَةٍ مِنَ الْمَعْزِ، وَنِصْفِهَا مِنَ الضَّأْنِ. وَالْخُلْطَةُ فِي بَهِيمَةِ الْأَنْعَامِ بِشَرْطِهَا: تُصَيِّرُ الْمَالَيْنِ كَالْوَاحِدِ."]]},{"id":"ak6_9","label":"كِتَابُ الزَّكَاةِ · ٩","segs":[["matn","فَصْلٌ: وَتَجِبُ فِي كُلِّ: مَكِيلٍ. مُدَّخَرٍ. خَرَجَ مِنَ الْأَرْضِ. وَنِصَابُهُ: خَمْسَةُ أَوْسُقٍ، وَهِيَ ثَلَاثُمِائَةٍ وَاثْنَانِ وَأَرْبَعُونَ رِطْلاً، وَسِتَّةُ أَسْبَاعِ رِطْلٍ بِالدِّمَشْقِيِّ. وَشُرِطَ: مِلْكُهُ وَقْتَ وُجُوبٍ، وَهُوَ: اشْتِدَادُ حَبٍّ."]]},{"id":"ak6_10","label":"كِتَابُ الزَّكَاةِ · ١٠","segs":[["matn","وَبُدُوُّ صَلَاحِ ثَمَرٍ. وَلَا يَسْتَقِرُّ إِلَّا بِجَعْلِهَا فِي بَيْدَرٍ وَنَحْوِهِ. وَالْوَاجِبُ: عُشْرُ مَا سُقِيَ بِلَا مُؤْنَةٍ. وَنِصْفُهُ: فِيمَا سُقِيَ بِهَا. وَثَلَاثَةُ أَرْبَاعِهِ: فِيمَا سُقِيَ بِهِمَا. فَإِنْ تَفَاوَتَا: اعْتُبِرَ الْأَكْثَرُ."]]},{"id":"ak6_11","label":"كِتَابُ الزَّكَاةِ · ١١","segs":[["matn","وَمَعَ الْجَهْلِ: الْعُشْرُ. وَفِي الْعَسَلِ: الْعُشْرُ. سَوَاءٌ أَخَذَهُ مِنْ: مَوَاتٍ، أَوْ مِلْكِهِ. إِذَا بَلَغَ مِائَةً وَسِتِّينَ رِطْلاً عِرَاقِيَّةً. وَمَنِ اسْتَخْرَجَ مِنْ مَعْدِنٍ نِصَاباً: فَفِيهِ رُبُعُ الْعُشْرِ فِي الْحَالِ."]]},{"id":"ak6_12","label":"كِتَابُ الزَّكَاةِ · ١٢","segs":[["matn","وَفِي الرِّكَازِ: الْخُمُسُ مُطْلَقاً. وَهُوَ: مَا وُجِدَ مِنْ دِفْنِ الْجَاهِلِيَّةِ."]]},{"id":"ak6_13","label":"كِتَابُ الزَّكَاةِ · ١٣","segs":[["matn","فَصْلٌ: وَأَقَلُّ نِصَابِ ذَهَبٍ: عِشْرُونَ مِثْقَالاً. وَفِضَّةٍ: مِائَتَا دِرْهَمٍ. وَيُضَمَّانِ فِي تَكْمِيلِ النِّصَابِ، وَالْعُرُوضُ إِلَى كُلٍّ مِنْهُمَا. وَالْوَاجِبُ فِيهِمَا: رُبُعُ الْعُشْرِ. وَأُبِيحَ لِرَجُلٍ مِنَ الْفِضَّةِ: خَاتَمٌ. وَقَبِيعَةُ سَيْفٍ."]]},{"id":"ak6_14","label":"كِتَابُ الزَّكَاةِ · ١٤","segs":[["matn","وَحِلْيَةُ مِنْطَقَةٍ، وَنَحْوُهُ. وَمِنَ الذَّهَبِ: قَبِيعَةُ سَيْفٍ. وَمَا دَعَتْ إِلَيْهِ ضَرُورَةٌ؛ كَأَنْفٍ. وَلِنِسَاءٍ مِنْهُمَا: مَا جَرَتْ عَادَتُهُنَّ بِلُبْسِهِ. وَلَا زَكَاةَ فِي حُلِيٍّ مُبَاحٍ أُعِدَّ: لِاسْتِعْمَالٍ. أَوْ عَارِيَّةٍ."]]},{"id":"ak6_15","label":"كِتَابُ الزَّكَاةِ · ١٥","segs":[["matn","وَيَجِبُ تَقْوِيمُ عَرْضِ التِّجَارَةِ بِالْأَحَظِّ لِلْفُقَرَاءِ مِنْهُمَا. وَتُخْرَجُ مِنْ قِيمَتِهِ. وَإِنِ اشْتَرَى عَرْضاً بِنِصَابِ غَيْرِ سَائِمَةٍ: بَنَى عَلَى حَوْلِهِ."]]},{"id":"ak6_16","label":"كِتَابُ الزَّكَاةِ · ١٦","segs":[["matn","فَصْلٌ: وَتَجِبُ الْفِطْرَةُ: عَلَى كُلِّ مُسْلِمٍ. إِذَا كَانَتْ فَاضِلَةً عَنْ: نَفَقَةٍ وَاجِبَةٍ يَوْمَ الْعِيدِ وَلَيْلَتَهُ. وَحَوَائِجَ أَصْلِيَّةٍ. فَيُخْرِجُ عَنْ: نَفْسِهِ. وَمُسْلِمٍ يَمُونُهُ. وَتُسَنُّ عَنْ جَنِينٍ. وَتَجِبُ بِغُرُوبِ الشَّمْسِ لَيْلَةَ الْفِطْرِ."]]},{"id":"ak6_17","label":"كِتَابُ الزَّكَاةِ · ١٧","segs":[["matn","وَتَجُوزُ قَبْلَهُ بِيَوْمَيْنِ فَقَطْ. وَيَوْمَهُ قَبْلَ الصَّلَاةِ أَفْضَلُ. وَتُكْرَهُ فِي بَاقِيهِ. وَيَحْرُمُ تَأْخِيرُهَا عَنْهُ، وَتُقْضَى وُجُوباً."]]},{"id":"ak6_18","label":"كِتَابُ الزَّكَاةِ · ١٨","segs":[["matn","وَهِيَ: صَاعٌ مِنْ بُرٍّ، أَوْ شَعِيرٍ، أَوْ سَوِيقِهِمَا، أَوْ دَقِيقِهِمَا، أَوْ تَمْرٍ، أَوْ زَبِيبٍ، أَوْ أَقِطٍ. وَالْأَفْضَلُ: تَمْرٌ، فَزَبِيبٌ، فَبُرٌّ، فَأَنْفَعُ. فَإِنْ عَدِمَتْ: أَجْزَأَ كُلُّ حَبٍّ يُقْتَاتُ. وَيَجُوزُ إِعْطَاءُ جَمَاعَةٍ مَا يَلْزَمُ الْوَاحِدَ، وَعَكْسُهُ."]]},{"id":"ak6_19","label":"كِتَابُ الزَّكَاةِ · ١٩","segs":[["matn","فَصْلٌ: وَيَجِبُ إِخْرَاجُ زَكَاةٍ عَلَى الْفَوْرِ مَعَ إِمْكَانِهِ. وَيُخْرِجُ وَلِيُّ صَغِيرٍ وَمَجْنُونٍ عَنْهُمَا. وَشُرِطَ لَهُ نِيَّةٌ. وَحَرُمَ نَقْلُهَا إِلَى مَسَافَةِ قَصْرٍ إِنْ وُجِدَ أَهْلُهَا."]]},{"id":"ak6_20","label":"كِتَابُ الزَّكَاةِ · ٢٠","segs":[["matn","فَإِنْ كَانَ فِي بَلَدٍ وَمَالُهُ فِي آخَرَ؛ أَخْرَجَ: زَكَاةَ الْمَالِ فِي بَلَدِ الْمَالِ. وَفِطْرَتَهُ وَفِطْرَةً لَزِمَتْهُ فِي بَلَدِ نَفْسِهِ. وَيَجُوزُ تَعْجِيلُهَا لِحَوْلَيْنِ فَقَطْ."]]},{"id":"ak6_21","label":"كِتَابُ الزَّكَاةِ · ٢١","segs":[["matn","وَلَا تُدْفَعُ إِلَّا إِلَى الْأَصْنَافِ الثَّمَانِيَةِ، وَهُمُ: الْفُقَرَاءُ. وَالْمَسَاكِينُ. وَالْعَامِلُونَ عَلَيْهَا. وَالْمُؤَلَّفَةُ قُلُوبُهُمْ. وَفِي الرِّقَابِ. وَالْغَارِمُونَ. وَفِي سَبِيلِ اللَّهِ. وَابْنُ السَّبِيلِ. وَيَجُوزُ الِاقْتِصَارُ عَلَى وَاحِدٍ مِنْ صِنْفٍ."]]},{"id":"ak6_22","label":"كِتَابُ الزَّكَاةِ · ٢٢","segs":[["matn","وَالْأَفْضَلُ تَعْمِيمُهُمْ، وَالتَّسْوِيَةُ بَيْنَهُمْ. وَتُسَنُّ إِلَى مَنْ لَا تَلْزَمُهُ مُؤْنَتُهُ مِنْ أَقَارِبِهِ. وَلَا تُدْفَعُ: لِبَنِي هَاشِمٍ. وَمَوَالِيهِمْ. وَلَا لِأَصْلٍ. وَفَرْعٍ وَعَبْدٍ. وَكَافِرٍ."]]},{"id":"ak6_23","label":"كِتَابُ الزَّكَاةِ · ٢٣","segs":[["matn","فَإِنْ دَفَعَهَا لِمَنْ ظَنَّهُ أَهْلاً فَلَمْ يَكُنْ، أَوْ بِالْعَكْسِ: لَمْ تُجْزِئْهُ. إِلَّا لِغَنِيٍّ ظَنَّهُ فَقِيراً. وَصَدَقَةُ التَّطَوُّعِ بِالْفَاضِلِ عَنْ كِفَايَتِهِ وَكِفَايَةِ مَنْ يَمُونُهُ: سُنَّةٌ مُؤَكَّدَةٌ."]]},{"id":"ak6_24","label":"كِتَابُ الزَّكَاةِ · ٢٤","segs":[["matn","وَفِي رَمَضَانَ، وَزَمَنٍ وَمَكَانٍ فَاضِلٍ، وَوَقْتِ حَاجَةٍ: أَفْضَلُ."]]}],"group":"كِتَابُ الزَّكَاةِ"},{"id":"ak7","title":"كِتَابُ الصِّيَامِ","units":[{"id":"ak7_1","label":"كِتَابُ الصِّيَامِ · ١","segs":[["matn","يَلْزَمُ كُلَّ: مُسْلِمٍ. مُكَلَّفٍ. قَادِرٍ. بِرُؤْيَةِ الْهِلَالِ، وَلَوْ مِنْ عَدْلٍ. أَوْ بِإِكْمَالِ شَعْبَانَ. أَوْ وُجُودِ مَانِعٍ مِنْ رُؤْيَتِهِ لَيْلَةَ الثَّلَاثِينَ مِنْهُ؛ كَغَيْمٍ وَجَبَلٍ وَغَيْرِهِمَا. وَإِنْ رُئِيَ نَهَاراً: فَهُوَ لِلْمُقْبِلَةِ."]]},{"id":"ak7_2","label":"كِتَابُ الصِّيَامِ · ٢","segs":[["matn","وَإِنْ: صَارَ أَهْلًا لِوُجُوبِهِ فِي أَثْنَائِهِ. أَوْ قَدِمَ مُسَافِرٌ مُفْطِراً. أَوْ طَهَرَتْ حَائِضٌ: أَمْسَكُوا، وَقَضَوْا. وَمَنْ أَفْطَرَ لِكِبَرٍ أَوْ مَرَضٍ لَا يُرْجَى بُرْؤُهُ: أَطْعَمَ لِكُلِّ يَوْمٍ مِسْكِيناً."]]},{"id":"ak7_3","label":"كِتَابُ الصِّيَامِ · ٣","segs":[["matn","وَسُنَّ الْفِطْرُ: لِمَرِيضٍ يَشُقُّ عَلَيْهِ. وَمُسَافِرٍ يَقْصُرُ. وَإِنْ أَفْطَرَتْ حَامِلٌ أَوْ مُرْضِعٌ: خَوْفاً عَلَى أَنْفُسِهِمَا: قَضَتَا فَقَطْ. أَوْ عَلَى وَلَدَيْهِمَا: مَعَ الْإِطْعَامِ، مِمَّنْ يَمُونُ الْوَلَدَ."]]},{"id":"ak7_4","label":"كِتَابُ الصِّيَامِ · ٤","segs":[["matn","وَمَنْ أُغْمِيَ عَلَيْهِ، أَوْ جُنَّ جَمِيعَ النَّهَارِ: لَمْ يَصِحَّ صَوْمُهُ. وَيَقْضِي الْمُغْمَى عَلَيْهِ. وَلَا يَصِحُّ صَوْمُ فَرْضٍ إِلَّا بِنِيَّةٍ مُعَيَّنَةٍ بِجُزْءٍ مِنَ اللَّيْلِ."]]},{"id":"ak7_5","label":"كِتَابُ الصِّيَامِ · ٥","segs":[["matn","وَيَصِحُّ نَفْلٌ مِمَّنْ لَمْ يَفْعَلْ مُفْسِداً بِنِيَّةٍ نَهَاراً مُطْلَقاً."]]},{"id":"ak7_6","label":"كِتَابُ الصِّيَامِ · ٦","segs":[["matn","فَصْلٌ: وَمَنْ: أَدْخَلَ إِلَى جَوْفِهِ. أَوْ مُجَوَّفٍ فِي جَسَدِهِ؛ كَدِمَاغٍ وَحَلْقٍ، شَيْئاً مِنْ أَيِّ مَوْضِعٍ كَانَ، غَيْرَ إِحْلِيلِهِ. أَوِ ابْتَلَعَ نُخَامَةً بَعْدَ وُصُولِهَا إِلَى فَمِهِ. أَوِ اسْتَقَاءَ فَقَاءَ."]]},{"id":"ak7_7","label":"كِتَابُ الصِّيَامِ · ٧","segs":[["matn","أَوِ اسْتَمْنَى، أَوْ بَاشَرَ دُونَ الْفَرْجِ فَأَمْنَى، أَوْ أَمْذَى. أَوْ كَرَّرَ النَّظَرَ فَأَمْنَى. أَوْ نَوَى الْإِفْطَارَ. أَوْ حَجَمَ، أَوِ احْتَجَمَ. عَامِداً، مُخْتَاراً، ذَاكِراً لِصَوْمِهِ: أَفْطَرَ. لَا: إِنْ فَكَّرَ فَأَنْزَلَ."]]},{"id":"ak7_8","label":"كِتَابُ الصِّيَامِ · ٨","segs":[["matn","أَوْ دَخَلَ مَاءُ مَضْمَضَةٍ أَوِ اسْتِنْشَاقٍ حَلْقَهُ، وَلَوْ بَالَغَ أَوْ زَادَ عَلَى ثَلَاثٍ. وَمَنْ جَامَعَ بِرَمَضَانَ، نَهَاراً، بِلَا عُذْرِ شَبَقٍ وَنَحْوِهِ: فَعَلَيْهِ الْقَضَاءُ وَالْكَفَّارَةُ مُطْلَقاً."]]},{"id":"ak7_9","label":"كِتَابُ الصِّيَامِ · ٩","segs":[["matn","وَلَا كَفَّارَةَ عَلَيْهَا مَعَ الْعُذْرِ؛ كَنَوْمٍ، وَإِكْرَاهٍ، وَنِسْيَانٍ، وَجَهْلٍ، وَعَلَيْهَا الْقَضَاءُ. وَهِيَ: عِتْقُ رَقَبَةٍ. فَإِنْ لَمْ يَجِدْ: فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ. فَإِنْ لَمْ يَسْتَطِعْ: فَإِطْعَامُ سِتِّينَ مِسْكِيناً. فَإِنْ لَمْ يَجِدْ: سَقَطَتْ."]]},{"id":"ak7_10","label":"كِتَابُ الصِّيَامِ · ١٠","segs":[["matn","وَكُرِهَ: أَنْ يَجْمَعَ رِيقَهُ فَيَبْتَلِعَهُ. وَذَوْقُ طَعَامٍ. وَمَضْغُ عِلْكٍ لَا يَتَحَلَّلُ. وَإِنْ وَجَدَ طَعْمَهُمَا فِي حَلْقِهِ أَفْطَرَ. وَالْقُبْلَةُ وَنَحْوُهَا مِمَّنْ تُحَرِّكُ شَهْوَتَهُ. وَيَحْرُمُ: إِنْ ظَنَّ إِنْزَالاً. وَمَضْغُ عِلْكٍ يَتَحَلَّلُ."]]},{"id":"ak7_11","label":"كِتَابُ الصِّيَامِ · ١١","segs":[["matn","وَكَذِبٌ، وَغِيبَةٌ، وَنَمِيمَةٌ، وَشَتْمٌ وَنَحْوُهُ بِتَأَكُّدٍ. وَسُنَّ: تَعْجِيلُ فِطْرٍ. وَتَأْخِيرُ سُحُورٍ. وَقَوْلُ مَا وَرَدَ عِنْدَ فِطْرٍ. وَتَتَابُعُ الْقَضَاءِ فَوْراً. وَحَرُمَ تَأْخِيرُهُ إِلَى آخَرَ بِلَا عُذْرٍ."]]},{"id":"ak7_12","label":"كِتَابُ الصِّيَامِ · ١٢","segs":[["matn","فَإِنْ فَعَلَ؛ وَجَبَ مَعَ الْقَضَاءِ: إِطْعَامُ مِسْكِينٍ عَنْ كُلِّ يَوْمٍ. وَإِنْ مَاتَ الْمُفَرِّطُ -وَلَوْ قَبْلَ آخَرَ-: أُطْعِمَ عَنْهُ كَذَلِكَ، مِنْ رَأْسِ مَالِهِ، وَلَا يُصَامُ."]]},{"id":"ak7_13","label":"كِتَابُ الصِّيَامِ · ١٣","segs":[["matn","وَإِنْ كَانَ عَلَى الْمَيِّتِ نَذْرٌ مِنْ حَجٍّ، أَوْ مِنْ صَوْمٍ، أَوْ صَلَاةٍ، وَنَحْوِهَا: سُنَّ لِوَلِيِّهِ قَضَاؤُهُ. وَمَعَ تَرِكَةٍ يَجِبُ، لَا مُبَاشَرَةُ وَلِيٍّ."]]},{"id":"ak7_14","label":"كِتَابُ الصِّيَامِ · ١٤","segs":[["matn","فَصْلٌ: يُسَنُّ صَوْمُ: أَيَّامِ الْبِيضِ. وَالْخَمِيسِ. وَالِاثْنَيْنِ. وَسِتٍّ مِنْ شَوَّالٍ. وَشَهْرِ اللَّهِ الْمُحَرَّمِ. وَآكَدُهُ: الْعَاشِرُ، ثُمَّ التَّاسِعُ. وَتِسْعِ ذِي الْحِجَّةِ. وَآكَدُهُ: يَوْمُ عَرَفَةَ لِغَيْرِ حَاجٍّ بِهَا."]]},{"id":"ak7_15","label":"كِتَابُ الصِّيَامِ · ١٥","segs":[["matn","وَأَفْضَلُ الصِّيَامِ: صَوْمُ يَوْمٍ وَفِطْرُ يَوْمٍ. وَكُرِهَ: إِفْرَادُ رَجَبٍ، وَالْجُمُعَةِ، وَالسَّبْتِ. وَالشَّكِّ. وَكُلِّ عِيدٍ لِلْكُفَّارِ. وَتَقَدُّمُ رَمَضَانَ بِيَوْمٍ أَوْ بِيَوْمَيْنِ. مَا لَمْ يُوَافِقْ عَادَةً فِي الْكُلِّ. وَحَرُمَ صَوْمُ: الْعِيدَيْنِ مُطْلَقاً."]]},{"id":"ak7_16","label":"كِتَابُ الصِّيَامِ · ١٦","segs":[["matn","وَأَيَّامِ التَّشْرِيقِ، إِلَّا عَنْ دَمِ مُتْعَةٍ وَقِرَانٍ. وَمَنْ دَخَلَ: فِي فَرْضٍ مُوَسَّعٍ: حَرُمَ قَطْعُهُ بِلَا عُذْرٍ. أَوْ نَفْلٍ -غَيْرِ حَجٍّ وَعُمْرَةٍ-: كُرِهَ بِلَا عُذْرٍ. وَاللَّهُ أَعْلَمُ."]]},{"id":"ak7_17","label":"كِتَابُ الصِّيَامِ · ١٧","segs":[["matn","فَصْلٌ: وَالِاعْتِكَافُ سُنَّةٌ. وَلَا يَصِحُّ مِمَّنْ تَلْزَمُهُ الْجَمَاعَةُ إِلَّا فِي مَسْجِدٍ تُقَامُ فِيهِ، إِنْ أَتَى عَلَيْهِ صَلَاةٌ. وَشُرِطَ لَهُ: طَهَارَةٌ مِمَّا يُوجِبُ غُسْلاً."]]},{"id":"ak7_18","label":"كِتَابُ الصِّيَامِ · ١٨","segs":[["matn","وَإِنْ نَذَرَهُ أَوِ الصَّلَاةَ فِي مَسْجِدٍ: غَيْرِ الثَّلَاثَةِ: فَلَهُ فِعْلُهُ فِي غَيْرِهِ. وَفِي أَحَدِهَا: فَلَهُ فِعْلُهُ فِيهِ وَفِي الْأَفْضَلِ. وَأَفْضَلُهَا: الْمَسْجِدُ الْحَرَامُ، ثُمَّ مَسْجِدُ النَّبِيِّ عَلَيْهِ السَّلَامُ، فَالْأَقْصَى."]]},{"id":"ak7_19","label":"كِتَابُ الصِّيَامِ · ١٩","segs":[["matn","وَلَا يَخْرُجُ مَنِ اعْتَكَفَ مَنْذُوراً مُتَتَابِعاً إِلَّا لِمَا لَا بُدَّ مِنْهُ. وَلَا يَعُودُ مَرِيضاً، وَلَا يَشْهَدُ جِنَازَةً إِلَّا بِشَرْطٍ. وَوَطْءُ الْفَرْجِ يُفْسِدُهُ. وَكَذَا إِنْزَالٌ بِمُبَاشَرَةٍ. وَيَلْزَمُ لِإِفْسَادِهِ: كَفَّارَةُ يَمِينٍ. وَسُنَّ اشْتِغَالُهُ بِالْقُرَبِ. وَاجْتِنَابُ مَا لَا يَعْنِيهِ."]]}],"group":"كِتَابُ الصِّيَامِ"},{"id":"ak8","title":"كِتَابُ الْحَجِّ وَالْعُمْرَةِ","units":[{"id":"ak8_1","label":"كِتَابُ الْحَجِّ وَالْعُمْرَةِ · ١","segs":[["matn","يَجِبَانِ عَلَى: الْمُسْلِمِ. الْحُرِّ. الْمُكَلَّفِ. الْمُسْتَطِيعِ. فِي الْعُمْرِ مَرَّةً. عَلَى الْفَوْرِ. فَإِنْ زَالَ مَانِعُ حَجٍّ بِعَرَفَةَ، وَعُمْرَةٍ قَبْلَ طَوَافِهَا، وَفُعِلَا إِذَنْ: وَقَعَا فَرْضاً."]]},{"id":"ak8_2","label":"كِتَابُ الْحَجِّ وَالْعُمْرَةِ · ٢","segs":[["matn","وَإِنْ عَجَزَ لِكِبَرٍ أَوْ مَرَضٍ لَا يُرْجَى بُرْؤُهُ: لَزِمَهُ أَنْ يُقِيمَ مَنْ يَحُجُّ عَنْهُ وَيَعْتَمِرُ مِنْ حَيْثُ وَجَبَا. وَيُجْزِئَانِهِ مَا لَمْ يَبْرَأْ قَبْلَ إِحْرَامِ نَائِبٍ. وَشُرِطَ لِامْرَأَةٍ: مَحْرَمٌ أَيْضاً."]]},{"id":"ak8_3","label":"كِتَابُ الْحَجِّ وَالْعُمْرَةِ · ٣","segs":[["matn","فَإِنْ أَيِسَتْ مِنْهُ: اسْتَنَابَتْ. وَإِنْ مَاتَ مَنْ لَزِمَاهُ: أُخْرِجَا مِنْ تَرِكَتِهِ. وَسُنَّ لِمُرِيدِ إِحْرَامٍ: غُسْلٌ، أَوْ تَيَمُّمٌ لِعُذْرٍ. وَتَنَظُّفٌ. وَتَطَيُّبٌ فِي بَدَنٍ، وَكُرِهَ فِي ثَوْبٍ. وَإِحْرَامٌ بِإِزَارٍ وَرِدَاءٍ أَبْيَضَيْنِ."]]},{"id":"ak8_4","label":"كِتَابُ الْحَجِّ وَالْعُمْرَةِ · ٤","segs":[["matn","عَقِبَ فَرِيضَةٍ أَوْ رَكْعَتَيْنِ، فِي غَيْرِ وَقْتِ نَهْيٍ. وَنِيَّتُهُ: شَرْطٌ. وَالِاشْتِرَاطُ فِيهِ: سُنَّةٌ. وَأَفْضَلُ الْأَنْسَاكِ: التَّمَتُّعُ، وَهُوَ: أَنْ يُحْرِمَ بِعُمْرَةٍ، فِي أَشْهُرِ الْحَجِّ، وَيَفْرُغَ مِنْهَا، ثُمَّ بِهِ فِي عَامِهِ."]]},{"id":"ak8_5","label":"كِتَابُ الْحَجِّ وَالْعُمْرَةِ · ٥","segs":[["matn","ثُمَّ الْإِفْرَادُ، وَهُوَ: أَنْ يُحْرِمَ بِحَجٍّ، ثُمَّ بِعُمْرَةٍ بَعْدَ فَرَاغِهِ مِنْهُ. وَالْقِرَانُ: أَنْ يُحْرِمَ بِهِمَا مَعاً. أَوْ بِهَا ثُمَّ يُدْخِلَهُ عَلَيْهَا قَبْلَ الشُّرُوعِ فِي طَوَافِهَا."]]},{"id":"ak8_6","label":"كِتَابُ الْحَجِّ وَالْعُمْرَةِ · ٦","segs":[["matn","وَعَلَى كُلٍّ مِنْ مُتَمَتِّعٍ وَقَارِنٍ إِذَا كَانَ أُفُقِيًّا: دَمُ نُسُكٍ بِشَرْطِهِ. وَإِنْ حَاضَتْ مُتَمَتِّعَةٌ فَخَشِيَتْ فَوَاتَ الْحَجِّ: أَحْرَمَتْ بِهِ وَصَارَتْ قَارِنَةً. وَتُسَنُّ التَّلْبِيَةُ، وَتَتَأَكَّدُ: إِذَا عَلَا نَشَزاً. أَوْ هَبَطَ وَادِياً."]]},{"id":"ak8_7","label":"كِتَابُ الْحَجِّ وَالْعُمْرَةِ · ٧","segs":[["matn","أَوْ صَلَّى مَكْتُوبَةً. أَوْ أَقْبَلَ لَيْلٌ أَوْ نَهَارٌ. أَوِ الْتَقَتِ الرِّفَاقُ. أَوْ رَكِبَ أَوْ نَزَلَ. أَوْ سَمِعَ مُلَبِّياً. أَوْ رَأَى الْبَيْتَ. أَوْ فَعَلَ مَحْظُوراً نَاسِياً. وَكُرِهَ: إِحْرَامٌ قَبْلَ مِيقَاتٍ. وَبِحَجٍّ قَبْلَ أَشْهُرِهِ."]]},{"id":"ak8_8","label":"كِتَابُ الْحَجِّ وَالْعُمْرَةِ · ٨","segs":[["matn","فَصْلٌ: وَمِيقَاتُ: أَهْلِ الْمَدِينَةِ: الْحُلَيْفَةُ. وَالشَّامِ، وَمِصْرَ، وَالْمَغْرِبِ: الْجُحْفَةُ. وَالْيَمَنِ: يَلَمْلَمُ. وَنَجْدٍ: قَرْنٌ. وَالْمَشْرِقِ: ذَاتُ عِرْقٍ. وَيُحْرِمُ مَنْ بِمَكَّةَ: لِحَجٍّ: مِنْهَا. وَلِعُمْرَةٍ: مِنَ الْحِلِّ."]]},{"id":"ak8_9","label":"كِتَابُ الْحَجِّ وَالْعُمْرَةِ · ٩","segs":[["matn","وَأَشْهُرُ الْحَجِّ: شَوَّالٌ، وَذُو الْقَعْدَةِ، وَعَشْرٌ مِنْ ذِي الْحِجَّةِ. وَمَحْظُورَاتُ الْإِحْرَامِ تِسْعَةٌ: إِزَالَةُ شَعْرٍ. وَتَقْلِيمُ أَظْفَارٍ. وَتَغْطِيَةُ رَأْسِ ذَكَرٍ. وَلُبْسُهُ الْمَخِيطَ. إِلَّا: سَرَاوِيلَ لِعَدَمِ إِزَارٍ، وَخُفَّيْنِ لِعَدَمِ نَعْلَيْنِ. وَالطِّيبُ."]]},{"id":"ak8_10","label":"كِتَابُ الْحَجِّ وَالْعُمْرَةِ · ١٠","segs":[["matn","وَقَتْلُ صَيْدِ الْبَرِّ. وَعَقْدُ نِكَاحٍ. وَجِمَاعٌ. وَمُبَاشَرَةٌ فِيمَا دُونَ فَرْجٍ. فَفِي: أَقَلَّ مِنْ ثَلَاثِ شَعَرَاتٍ، وَثَلَاثَةِ أَظْفَارٍ: فِي كُلِّ وَاحِدٍ فَأَقَلَّ طَعَامُ مِسْكِينٍ. وَفِي الثَّلَاثِ فَأَكْثَرَ: دَمٌ."]]},{"id":"ak8_11","label":"كِتَابُ الْحَجِّ وَالْعُمْرَةِ · ١١","segs":[["matn","وَفِي تَغْطِيَةِ الرَّأْسِ بِلَاصِقٍ، وَلُبْسِ مَخِيطٍ، وَتَطَيُّبٍ فِي بَدَنٍ، أَوْ ثَوْبٍ، أَوْ شَمٍّ، أَوْ دَهْنٍ: الْفِدْيَةُ. وَإِنْ قَتَلَ: صَيْداً. مَأْكُولاً. بَرِّيًّا أَصْلاً. فَعَلَيْهِ جَزَاؤُهُ."]]},{"id":"ak8_12","label":"كِتَابُ الْحَجِّ وَالْعُمْرَةِ · ١٢","segs":[["matn","وَالْجِمَاعُ قَبْلَ التَّحَلُّلِ الْأَوَّلِ فِي حَجٍّ، وَقَبْلَ فَرَاغِ سَعْيٍ فِي عُمْرَةٍ: مُفْسِدٌ لِنُسُكِهِمَا مُطْلَقاً. وَفِيهِ لِحَجٍّ: بَدَنَةٌ، وَلِعُمْرَةٍ: شَاةٌ. وَيَمْضِيَانِ فِي فَاسِدِهِ. وَيَقْضِيَانِهِ مُطْلَقاً إِنْ كَانَا مُكَلَّفَيْنِ فَوْراً."]]},{"id":"ak8_13","label":"كِتَابُ الْحَجِّ وَالْعُمْرَةِ · ١٣","segs":[["matn","وَإِلَّا بَعْدَ التَّكْلِيفِ وَحَجَّةِ الْإِسْلَامِ فَوْراً. وَلَا يَفْسُدُ النُّسُكُ: بِمُبَاشَرَةٍ. وَيَجِبُ بِهَا: بَدَنَةٌ إِنْ أَنْزَلَ، وَإِلَّا شَاةٌ. وَلَا بِوَطْءٍ فِي حَجٍّ بَعْدَ التَّحَلُّلِ الْأَوَّلِ وَقَبْلَ الثَّانِي."]]},{"id":"ak8_14","label":"كِتَابُ الْحَجِّ وَالْعُمْرَةِ · ١٤","segs":[["matn","لَكِنْ يَفْسُدُ الْإِحْرَامُ، فَيُحْرِمُ مِنَ الْحِلِّ لِيَطُوفَ لِلزِّيَارَةِ فِي إِحْرَامٍ صَحِيحٍ، وَيَسْعَى إِنْ لَمْ يَكُنْ سَعَى. وَعَلَيْهِ شَاةٌ. وَإِحْرَامُ امْرَأَةٍ كَرَجُلٍ، إِلَّا فِي: لُبْسِ مَخِيطٍ. وَتَجْتَنِبُ الْبُرْقُعَ وَالْقُفَّازَيْنِ. وَتَغْطِيَةَ الْوَجْهِ. فَإِنْ غَطَّتْهُ بِلَا عُذْرٍ: فَدَتْ."]]},{"id":"ak8_15","label":"كِتَابُ الْحَجِّ وَالْعُمْرَةِ · ١٥","segs":[["matn","فَصْلٌ فِي الْفِدْيَةِ: يُخَيَّرُ بِفِدْيَةِ حَلْقٍ، وَتَقْلِيمٍ، وَتَغْطِيَةِ رَأْسٍ، وَطِيبٍ، بَيْنَ: صِيَامِ ثَلَاثَةِ أَيَّامٍ. أَوْ إِطْعَامِ سِتَّةِ مَسَاكِينَ. كُلِّ مِسْكِينٍ: مُدَّ بُرٍّ، أَوْ نِصْفَ صَاعِ تَمْرٍ، أَوْ زَبِيبٍ، أَوْ شَعِيرٍ."]]},{"id":"ak8_16","label":"كِتَابُ الْحَجِّ وَالْعُمْرَةِ · ١٦","segs":[["matn","أَوْ ذَبْحِ شَاةٍ. وَفِي جَزَاءِ صَيْدٍ بَيْنَ: مِثْلِ مِثْلِيٍّ. أَوْ تَقْوِيمِهِ بِدَرَاهِمَ، يَشْتَرِي بِهَا طَعَاماً يُجْزِئُ فِي فِطْرَةٍ، فَيُطْعِمُ عَنْ كُلِّ مِسْكِينٍ مُدَّ بُرٍّ، أَوْ نِصْفَ صَاعٍ مِنْ غَيْرِهِ."]]},{"id":"ak8_17","label":"كِتَابُ الْحَجِّ وَالْعُمْرَةِ · ١٧","segs":[["matn","أَوْ يَصُومُ عَنْ طَعَامِ كُلِّ مِسْكِينٍ يَوْماً. وَبَيْنَ إِطْعَامٍ أَوْ صِيَامٍ فِي غَيْرِ مِثْلِيٍّ. وَإِنْ عَدِمَ مُتَمَتِّعٌ أَوْ قَارِنٌ الْهَدْيَ: صَامَ ثَلَاثَةَ أَيَّامٍ فِي الْحَجِّ، وَالْأَفْضَلُ جَعْلُ آخِرِهَا يَوْمَ عَرَفَةَ."]]},{"id":"ak8_18","label":"كِتَابُ الْحَجِّ وَالْعُمْرَةِ · ١٨","segs":[["matn","وَسَبْعَةً إِذَا رَجَعَ لِأَهْلِهِ. وَالْمُحْصَرُ إِذَا لَمْ يَجِدْهُ: صَامَ عَشَرَةَ أَيَّامٍ، ثُمَّ حَلَّ. وَتَسْقُطُ بِنِسْيَانٍ فِي: لُبْسٍ، وَطِيبٍ، وَتَغْطِيَةِ رَأْسٍ. وَكُلُّ هَدْيٍ أَوْ طَعَامٍ: فَلِمَسَاكِينِ الْحَرَمِ."]]},{"id":"ak8_19","label":"كِتَابُ الْحَجِّ وَالْعُمْرَةِ · ١٩","segs":[["matn","إِلَّا فِدْيَةَ أَذًى وَلُبْسٍ وَنَحْوِهَا: فَحَيْثُ وُجِدَ سَبَبُهَا. وَيُجْزِئُ الصَّوْمُ بِكُلِّ مَكَانٍ. وَالدَّمُ: شَاةٌ. أَوْ سُبُعُ بَدَنَةٍ أَوْ بَقَرَةٍ. وَيُرْجَعُ فِي جَزَاءِ صَيْدٍ: إِلَى مَا قَضَتْ فِيهِ الصَّحَابَةُ."]]},{"id":"ak8_20","label":"كِتَابُ الْحَجِّ وَالْعُمْرَةِ · ٢٠","segs":[["matn","وَفِيمَا لَمْ تَقْضِ فِيهِ: إِلَى قَوْلِ عَدْلَيْنِ خَبِيرَيْنِ. وَمَا لَا مِثْلَ لَهُ: تَجِبُ قِيمَتُهُ مَكَانَهُ. وَحَرُمَ مُطْلَقاً: صَيْدُ حَرَمِ مَكَّةَ. وَقَطْعُ شَجَرِهِ وَحَشِيشِهِ، إِلَّا الْإِذْخِرَ. وَفِيهِ الْجَزَاءُ. وَصَيْدُ حَرَمِ الْمَدِينَةِ."]]},{"id":"ak8_21","label":"كِتَابُ الْحَجِّ وَالْعُمْرَةِ · ٢١","segs":[["matn","وَقَطْعُ شَجَرِهِ وَحَشِيشِهِ، لِغَيْرِ حَاجَةِ عَلَفٍ وَقَتَبٍ وَنَحْوِهِمَا. وَلَا جَزَاءَ."]]}],"group":"كِتَابُ الْحَجِّ وَالْعُمْرَةِ"},{"id":"ak9","title":"بَابُ دُخُولِ مَكَّةَ","units":[{"id":"ak9_1","label":"بَابُ دُخُولِ مَكَّةَ · ١","segs":[["matn","يُسَنُّ: نَهَاراً. مِنْ أَعْلَاهَا. وَالْمَسْجِدِ مِنْ بَابِ بَنِي شَيْبَةَ. فَإِذَا رَأَى الْبَيْتَ: رَفَعَ يَدَيْهِ، وَقَالَ مَا وَرَدَ. ثُمَّ طَافَ مُضْطَبِعاً: لِلْعُمْرَةِ الْمُعْتَمِرُ. وَلِلْقُدُومِ غَيْرُهُ."]]},{"id":"ak9_2","label":"بَابُ دُخُولِ مَكَّةَ · ٢","segs":[["matn","وَيَسْتَلِمُ الْحَجَرَ الْأَسْوَدَ وَيُقَبِّلُهُ، فَإِنْ شَقَّ: أَشَارَ إِلَيْهِ، وَيَقُولُ مَا وَرَدَ. وَيَرْمُلُ الْأُفُقِيُّ فِي هَذَا الطَّوَافِ. فَإِذَا فَرَغَ صَلَّى رَكْعَتَيْنِ خَلْفَ الْمَقَامِ. ثُمَّ يَسْتَلِمُ الْحَجَرَ الْأَسْوَدَ."]]},{"id":"ak9_3","label":"بَابُ دُخُولِ مَكَّةَ · ٣","segs":[["matn","وَيَخْرُجُ إِلَى الصَّفَا مِنْ بَابِهِ، فَيَرْقَاهُ حَتَّى يَرَى الْبَيْتَ، فَيُكَبِّرُ ثَلَاثاً، وَيَقُولُ مَا وَرَدَ. ثُمَّ يَنْزِلُ مَاشِياً إِلَى الْعَلَمِ الْأَوَّلِ، فَيَسْعَى شَدِيداً إِلَى الْآخَرِ."]]},{"id":"ak9_4","label":"بَابُ دُخُولِ مَكَّةَ · ٤","segs":[["matn","ثُمَّ يَمْشِي وَيَرْقَى الْمَرْوَةَ، وَيَقُولُ مَا قَالَهُ عَلَى الصَّفَا. ثُمَّ يَنْزِلُ فَيَمْشِي فِي مَوْضِعِ مَشْيِهِ، وَيَسْعَى فِي مَوْضِعِ سَعْيِهِ، إِلَى الصَّفَا. يَفْعَلُهُ سَبْعاً، وَيُحْسَبُ ذَهَابُهُ وَرُجُوعُهُ."]]},{"id":"ak9_5","label":"بَابُ دُخُولِ مَكَّةَ · ٥","segs":[["matn","وَيَتَحَلَّلُ مُتَمَتِّعٌ: لَا هَدْيَ مَعَهُ: بِتَقْصِيرِ شَعْرِهِ. وَمَنْ مَعَهُ هَدْيٌ: إِذَا حَجَّ. وَالْمُتَمَتِّعُ يَقْطَعُ التَّلْبِيَةَ إِذَا أَخَذَ فِي الطَّوَافِ."]]},{"id":"ak9_6","label":"بَابُ دُخُولِ مَكَّةَ · ٦","segs":[["matn","فَصْلٌ فِي صِفَةِ الْحَجِّ وَالْعُمْرَةِ: يُسَنُّ: لِمُحِلٍّ بِمَكَّةَ: الْإِحْرَامُ بِالْحَجِّ يَوْمَ التَّرْوِيَةِ. وَالْمَبِيتُ بِمِنًى. فَإِذَا طَلَعَتِ الشَّمْسُ سَارَ إِلَى عَرَفَةَ. وَكُلُّهَا مَوْقِفٌ إِلَّا بَطْنَ عُرَنَةَ. وَجَمَعَ فِيهَا بَيْنَ الظُّهْرِ وَالْعَصْرِ تَقْدِيماً."]]},{"id":"ak9_7","label":"بَابُ دُخُولِ مَكَّةَ · ٧","segs":[["matn","وَأَكْثَرَ الدُّعَاءَ، مِمَّا وَرَدَ. وَوَقْتُ الْوُقُوفِ: مِنْ فَجْرِ عَرَفَةَ إِلَى فَجْرِ النَّحْرِ. ثُمَّ يَدْفَعُ بَعْدَ الْغُرُوبِ إِلَى مُزْدَلِفَةَ بِسَكِينَةٍ. وَيَجْمَعُ فِيهَا بَيْنَ الْعِشَاءَيْنِ تَأْخِيراً. وَيَبِيتُ بِهَا."]]},{"id":"ak9_8","label":"بَابُ دُخُولِ مَكَّةَ · ٨","segs":[["matn","فَإِذَا صَلَّى الصُّبْحَ أَتَى الْمَشْعَرَ الْحَرَامَ، فَرَقَاهُ، وَوَقَفَ عِنْدَهُ، وَحَمِدَ اللَّهَ وَكَبَّرَ، وَقَرَأَ: «فَإِذَا أَفَضْتُمْ مِنْ عَرَفَاتٍ» الْآيَتَيْنِ. وَيَدْعُو حَتَّى يُسْفِرَ. ثُمَّ يَدْفَعُ إِلَى مِنًى."]]},{"id":"ak9_9","label":"بَابُ دُخُولِ مَكَّةَ · ٩","segs":[["matn","فَإِذَا بَلَغَ مُحَسِّراً أَسْرَعَ رَمْيَةَ حَجَرٍ. وَأَخَذَ حَصَى الْجِمَارِ سَبْعِينَ، أَكْبَرَ مِنَ الْحِمّصِ وَدُونَ الْبُنْدُقِ. فَيَرْمِي جَمْرَةَ الْعَقَبَةِ وَحْدَهَا بِسَبْعٍ. يَرْفَعُ يُمْنَاهُ حَتَّى يُرَى بَيَاضُ إِبْطِهِ. وَيُكَبِّرُ مَعَ كُلِّ حَصَاةٍ."]]},{"id":"ak9_10","label":"بَابُ دُخُولِ مَكَّةَ · ١٠","segs":[["matn","ثُمَّ يَنْحَرُ. وَيَحْلِقُ أَوْ يُقَصِّرُ مِنْ جَمِيعِ شَعْرِهِ. وَالْمَرْأَةُ قَدْرَ أَنْمُلَةٍ. ثُمَّ قَدْ حَلَّ لَهُ كُلُّ شَيْءٍ إِلَّا النِّسَاءَ. ثُمَّ يُفِيضُ إِلَى مَكَّةَ، فَيَطُوفُ طَوَافَ الزِّيَارَةِ الَّذِي هُوَ رُكْنٌ."]]},{"id":"ak9_11","label":"بَابُ دُخُولِ مَكَّةَ · ١١","segs":[["matn","ثُمَّ يَسْعَى إِنْ لَمْ يَكُنْ سَعَى. وَقَدْ حَلَّ لَهُ كُلُّ شَيْءٍ. وَسُنَّ أَنْ يَشْرَبَ مِنْ زَمْزَمَ لِمَا أَحَبَّ. وَيَتَضَلَّعَ مِنْهُ. وَيَدْعُوَ بِمَا وَرَدَ. ثُمَّ يَرْجِعُ فَيَبِيتُ بِمِنًى ثَلَاثَ لَيَالٍ."]]},{"id":"ak9_12","label":"بَابُ دُخُولِ مَكَّةَ · ١٢","segs":[["matn","وَيَرْمِي الْجِمَارَ فِي كُلِّ يَوْمٍ مِنْ أَيَّامٍ التَّشْرِيقِ: بَعْدَ الزَّوَالِ وَقَبْلَ الصَّلَاةِ. وَمَنْ تَعَجَّلَ فِي يَوْمَيْنِ: إِنْ لَمْ يَخْرُجْ قَبْلَ الْغُرُوبِ؛ لَزِمَهُ الْمَبِيتُ وَالرَّمْيُ مِنَ الْغَدِ. وَطَوَافُ الْوَدَاعِ: وَاجِبٌ."]]},{"id":"ak9_13","label":"بَابُ دُخُولِ مَكَّةَ · ١٣","segs":[["matn","يَفْعَلُهُ، ثُمَّ يَقِفُ فِي الْمُلْتَزَمِ دَاعِياً بِمَا وَرَدَ. وَتَدْعُو الْحَائِضُ وَالنُّفَسَاءُ عَلَى بَابِ الْمَسْجِدِ. وَسُنَّ زِيَارَةُ قَبْرِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَقَبْرَيْ صَاحِبَيْهِ."]]},{"id":"ak9_14","label":"بَابُ دُخُولِ مَكَّةَ · ١٤","segs":[["matn","وَصِفَةُ الْعُمْرَةِ: أَنْ يُحْرِمَ بِهَا: مَنْ بِالْحَرَمِ: مِنْ أَدْنَى الْحِلِّ. وَغَيْرُهُ: مِنْ دُوَيْرَةِ أَهْلِهِ، إِنْ كَانَ دُونَ مِيقَاتٍ. وَإِلَّا: فَمِنْهُ. ثُمَّ يَطُوفُ، وَيَسْعَى، وَيُقَصِّرُ."]]},{"id":"ak9_15","label":"بَابُ دُخُولِ مَكَّةَ · ١٥","segs":[["matn","فَصْلٌ: أَرْكَانُ الْحَجِّ أَرْبَعَةٌ: إِحْرَامٌ. وَوُقُوفٌ. وَطَوَافٌ. وَسَعْيٌ. وَوَاجِبَاتُهُ سَبْعَةٌ: إِحْرَامُ مَارٍّ عَلَى مِيقَاتٍ مِنْهُ. وَوُقُوفٌ إِلَى اللَّيْلِ إِنْ وَقَفَ نَهَاراً. وَمَبِيتٌ بِمُزْدَلِفَةَ إِلَى بَعْدِ نِصْفِهِ إِنْ وَافَاهَا قَبْلَهُ."]]},{"id":"ak9_16","label":"بَابُ دُخُولِ مَكَّةَ · ١٦","segs":[["matn","وَبِمِنًى لَيَالِيَهَا. وَالرَّمْيُ مُرَتَّباً. وَحَلْقٌ أَوْ تَقْصِيرٌ. وَطَوَافُ وَدَاعٍ. وَأَرْكَانُ الْعُمْرَةِ ثَلَاثَةٌ: إِحْرَامٌ. وَطَوَافٌ. وَسَعْيٌ. وَوَاجِبُهَا اثْنَانِ: الْإِحْرَامُ مِنَ الْحِلِّ. وَالْحَلْقُ أَوِ التَّقْصِيرُ. وَمَنْ فَاتَهُ الْوُقُوفُ: فَاتَهُ الْحَجُّ. وَتَحَلَّلَ بِعُمْرَةٍ."]]},{"id":"ak9_17","label":"بَابُ دُخُولِ مَكَّةَ · ١٧","segs":[["matn","وَهَدَى إِنْ لَمْ يَكُنِ اشْتَرَطَ. وَمَنْ مُنِعَ الْبَيْتَ: هَدَى، ثُمَّ حَلَّ. فَإِنْ فَقَدَهُ: صَامَ عَشَرَةَ أَيَّامٍ. وَمَنْ صُدَّ عَنْ عَرَفَةَ: تَحَلَّلَ بِعُمْرَةٍ، وَلَا دَمَ."]]},{"id":"ak9_18","label":"بَابُ دُخُولِ مَكَّةَ · ١٨","segs":[["matn","فَصْلٌ: وَالْأُضْحِيَّةُ سُنَّةٌ. يُكْرَهُ تَرْكُهَا لَقَادِرٍ. وَوَقْتُ الذَّبْحِ: بَعْدَ صَلَاةِ الْعِيدِ أَوْ قَدْرِهَا، إِلَى آخِرِ ثَانِي التَّشْرِيقِ. وَلَا يُعْطَى جَازِرٌ أُجْرَتَهُ مِنْهَا."]]},{"id":"ak9_19","label":"بَابُ دُخُولِ مَكَّةَ · ١٩","segs":[["matn","وَلَا يُبَاعُ جِلْدُهَا، وَلَا شَيْءٌ مِنْهَا، بَلْ يُنْتَفَعُ بِهِ. وَأَفْضَلُ هَدْيٍ وَأُضْحِيَّةٍ: إِبِلٌ، ثُمَّ بَقَرٌ، ثُمَّ غَنَمٌ. وَلَا يُجْزِئُ إِلَّا جَذَعُ ضَأْنٍ، أَوْ ثَنِيُّ غَيْرِهِ."]]},{"id":"ak9_20","label":"بَابُ دُخُولِ مَكَّةَ · ٢٠","segs":[["matn","فَثَنِيُّ إِبِلٍ: مَا لَهُ خَمْسُ سِنِينَ. وَبَقَرٍ: سَنَتَانِ. وَتُجْزِئُ: الشَّاةُ: عَنْ وَاحِدٍ. وَالْبَدَنَةُ وَالْبَقَرَةُ: عَنْ سَبْعَةٍ. وَلَا تُجْزِئُ: هَزِيلَةٌ. وَبَيِّنَةُ عَوَرٍ أَوْ عَرَجٍ. وَلَا ذَاهِبَةُ الثَّنَايَا."]]},{"id":"ak9_21","label":"بَابُ دُخُولِ مَكَّةَ · ٢١","segs":[["matn","أَوْ أَكْثَرِ أُذُنِهَا أَوْ قَرْنِهَا. وَالسُّنَّةُ: نَحْرُ إِبِلٍ قَائِمَةً، مَعْقُولَةً يَدُهَا الْيُسْرَى. وَذَبْحُ غَيْرِهَا. وَيَقُولُ: «بِاسْمِ اللَّهِ، اللَّهُمَّ هَذَا مِنْكَ وَلَكَ». وَسُنَّ: أَنْ يَأْكُلَ، وَيُهْدِيَ، وَيَتَصَدَّقَ؛ أَثْلَاثاً، مُطْلَقاً. وَالْحَلْقُ بَعْدَهَا."]]},{"id":"ak9_22","label":"بَابُ دُخُولِ مَكَّةَ · ٢٢","segs":[["matn","وَإِنْ أَكَلَهَا إِلَّا أُوقِيَّةً: جَازَ. وَحَرُمَ عَلَى مُرِيدِهَا أَخْذُ شَيْءٍ مِنْ شَعْرِهِ وَظُفُرِهِ وَبَشَرَتِهِ فِي الْعَشْرِ. وَتُسَنُّ الْعَقِيقَةُ. وَهِيَ: عَنِ الْغُلَامِ: شَاتَانِ، وَعَنِ الْجَارِيَةِ: شَاةٌ. تُذْبَحُ: يَوْمَ السَّابِعِ."]]},{"id":"ak9_23","label":"بَابُ دُخُولِ مَكَّةَ · ٢٣","segs":[["matn","فَإِنْ فَاتَ: فَفِي أَرْبَعَةَ عَشَرَ. فَإِنْ فَاتَ: فَفِي أَحَدٍ وَعِشْرِينَ. ثُمَّ لَا تُعْتَبَرُ الْأَسَابِيعُ. وَحُكْمُهَا كَأُضْحِيَّةٍ."]]}],"group":"كِتَابُ الْحَجِّ وَالْعُمْرَةِ"},{"id":"ak10","title":"كِتَابُ الْجِهَادِ","units":[{"id":"ak10_1","label":"كِتَابُ الْجِهَادِ · ١","segs":[["matn","هُوَ فَرْضُ كِفَايَةٍ. إِلَّا: إِذَا حَضَرَهُ. أَوْ حَصَرَهُ أَوْ بَلَدَهُ عَدُوٌّ. أَوْ كَانَ النَّفِيرُ عَامًّا. فَفَرْضُ عَيْنٍ. وَلَا يَتَطَوَّعُ بِهِ مَنْ أَحْدُ أَبَوَيْهِ حُرٌّ مُسْلِمٌ إِلَّا بِإِذْنِهِ. وَسُنَّ رِبَاطٌ."]]},{"id":"ak10_2","label":"كِتَابُ الْجِهَادِ · ٢","segs":[["matn","وَأَقَلُّهُ: سَاعَةٌ. وَتَمَامُهُ: أَرْبَعُونَ يَوْماً. وَعَلَى الْإِمَامِ: مَنْعُ مُخَذِّلٍ، وَمُرْجِفٍ. وَعَلَى الْجَيْشِ: طَاعَتُهُ وَالصَّبْرُ مَعَهُ. وَتُمْلَكُ الْغَنِيمَةُ: بِالِاسْتِيلَاءِ عَلَيْهَا فِي دَارِ حَرْبٍ. فَيُجْعَلُ خُمُسُهَا خَمْسَةَ أَسْهُمٍ: سَهْمٌ لِلَّهِ وَلِرَسُولِهِ."]]},{"id":"ak10_3","label":"كِتَابُ الْجِهَادِ · ٣","segs":[["matn","وَسَهْمٌ لِذَوِي الْقُرْبَى، وَهُمْ: بَنُو هَاشِمٍ، وَالْمُطَّلِبِ. وَسَهْمٌ لِلْيَتَامَى الْفُقَرَاءِ. وَسَهْمٌ لِلْمَسَاكِينِ. وَسَهْمٌ لِأَبْنَاءِ السَّبِيلِ. وَشُرِطَ فِيمَنْ يُسْهَمُ لَهُ: إِسْلَامٌ. ثُمَّ يُقْسَمُ الْبَاقِي بَيْنَ مَنْ شَهِدَ الْوَقْعَةَ: لِلرَّاجِلِ سَهْمٌ."]]},{"id":"ak10_4","label":"كِتَابُ الْجِهَادِ · ٤","segs":[["matn","وَلِلْفَارِسِ: عَلَى فَرَسٍ عَرَبِيٍّ: ثَلَاثَةٌ. وَعَلَى غَيْرِهِ: اثْنَانِ. وَيُقْسَمُ لِحُرٍّ. مُسْلِمٍ. وَيُرْضَخُ لِغَيْرِهِمْ. وَإِذَا فَتَحُوا أَرْضاً بِالسَّيْفِ؛ خُيِّرَ الْإِمَامُ بَيْنَ: قَسْمِهَا."]]},{"id":"ak10_5","label":"كِتَابُ الْجِهَادِ · ٥","segs":[["matn","وَوَقْفِهَا عَلَى الْمُسْلِمِينَ، ضَارِباً عَلَيْهَا خَرَاجاً مُسْتَمِرًّا، يُؤْخَذُ مِمَّنْ هُوَ فِي يَدِهِ. وَمَا أُخِذَ مِنْ مَالِ مُشْرِكٍ بِلَا قِتَالٍ؛ كَجِزْيَةٍ، وَخَرَاجٍ، وَعُشْرٍ: فَيْءٌ لِمَصَالِحِ الْمُسْلِمِينَ. وَكَذَا خُمُسُ خُمُسِ الْغَنِيمَةِ."]]},{"id":"ak10_6","label":"كِتَابُ الْجِهَادِ · ٦","segs":[["matn","فَصْلٌ: وَيَجُوزُ عَقْدُ الذِّمَّةِ لِمَنْ لَهُ كِتَابٌ أَوْ شُبْهَتُهُ. وَيُقَاتَلُ: هَؤُلَاءِ: حَتَّى يُسْلِمُوا أَوْ يُعْطُوا الْجِزْيَةَ. وَغَيْرُهُمْ: حَتَّى يُسْلِمُوا أَوْ يُقْتَلُوا. وَتُؤْخَذُ مِنْهُمْ: مُمْتَهَنِينَ، مُصَغَّرِينَ. وَلَا تُؤْخَذُ مِنْ: صَبِيٍّ. وَعَبْدٍ."]]},{"id":"ak10_7","label":"كِتَابُ الْجِهَادِ · ٧","segs":[["matn","وَامْرَأَةٍ. وَفَقِيرٍ عَاجِزٍ عَنْهَا. وَنَحْوِهِمْ. وَيَلْزَمُ أَخْذُهُمْ بِحُكْمِ الْإِسْلَامِ فِيمَا يَعْتَقِدُونَ تَحْرِيمَهُ مِنْ نَفْسٍ، وَعِرْضٍ، وَمَالٍ، وَغَيْرِهَا. وَيَلْزَمُهُمُ التَّمَيُّزُ عَنِ الْمُسْلِمِينَ. وَلَهُمْ رُكُوبُ غَيْرِ خَيْلٍ بِغَيْرِ سَرْجٍ. وَحَرُمَ: تَعْظِيمُهُمْ."]]},{"id":"ak10_8","label":"كِتَابُ الْجِهَادِ · ٨","segs":[["matn","وَبُدَاءَتُهُمْ بِالسَّلَامِ. وَإِنْ تَعَدَّى الذِّمِّيُّ عَلَى مُسْلِمٍ، أَوْ ذَكَرَ اللَّهَ، أَوْ كِتَابَهُ، أَوْ رَسُولَهُ بِسُوءٍ: انْتَقَضَ عَهْدُهُ. فَيُخَيَّرُ الْإِمَامُ فِيهِ كَأَسِيرٍ حَرْبِيٍّ."]]}],"group":"كِتَابُ الْجِهَادِ"},{"id":"ak11","title":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ","units":[{"id":"ak11_1","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ١","segs":[["matn","يَنْعَقِدُ: بِمُعَاطَاةٍ. وَبِإِيجَابٍ وَقَبُولٍ. بِسَبْعَةِ شُرُوطٍ: الرِّضَا مِنْهُمَا. وَكَوْنُ عَاقِدٍ جَائِزَ التَّصَرُّفِ. وَكَوْنُ مَبِيعٍ مَالاً. وَهُوَ: مَا فِيهِ مَنْفَعَةٌ مُبَاحَةٌ. وَكَوْنُهُ مَمْلُوكاً لِبَائِعِهِ، أَوْ مَأْذُوناً لَهُ فِيهِ."]]},{"id":"ak11_2","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٢","segs":[["matn","وَكَوْنُهُ مَقْدُوراً عَلَى تَسْلِيمِهِ. وَكَوْنُهُ مَعْلُوماً لَهُمَا: بِرُؤْيَةٍ. أَوْ صِفَةٍ تَكْفِي فِي السَّلَمِ. وَكَوْنُ ثَمَنٍ مَعْلُوماً. فَلَا يَصِحُّ بِمَا يَنْقَطِعُ بِهِ السِّعْرُ. وَإِنْ بَاعَ: مُشَاعاً بَيْنَهُ وَبَيْنَ غَيْرِهِ."]]},{"id":"ak11_3","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٣","segs":[["matn","أَوْ عَبْدَهُ وَعَبْدَ غَيْرِهِ بِغَيْرِ إِذْنٍ، أَوْ عَبْداً وَحُرًّا، أَوْ خَلًّا وَخَمْراً. صَفْقَةً وَاحِدَةً: صَحَّ فِي نَصِيبِهِ وَعَبْدِهِ وَالْخَلِّ بِقِسْطِهِ، وَلِمُشْتَرٍ الْخِيَارُ."]]},{"id":"ak11_4","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٤","segs":[["matn","وَلَا يَصِحُّ: بِلَا حَاجَةٍ بَيْعٌ وَلَا شِرَاءٌ مِمَّنْ تَلْزَمُهُ الْجُمُعَةُ بَعْدَ نِدَائِهَا الثَّانِي. وَتَصِحُّ سَائِرُ الْعُقُودِ. وَلَا بَيْعُ عَصِيرٍ أَوْ عِنَبٍ لِمُتَّخِذِهِ خَمْراً، وَلَا سِلَاحٍ فِي فِتْنَةٍ."]]},{"id":"ak11_5","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٥","segs":[["matn","وَلَا عَبْدٍ مُسْلِمٍ لِكَافِرٍ لَا يَعْتِقُ عَلَيْهِ. وَحَرُمَ وَلَمْ يَصِحَّ: بَيْعُهُ عَلَى بَيْعِ أَخِيهِ، وَشِرَاؤُهُ عَلَى شِرَائِهِ. وَسَوْمُهُ عَلَى سَوْمِهِ."]]},{"id":"ak11_6","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٦","segs":[["matn","فَصْلٌ: وَالشُّرُوطُ فِي الْبَيْعِ ضَرْبَانِ: صَحِيحٌ: كَشَرْطِ رَهْنٍ، وَضَامِنٍ، وَتَأْجِيلِ ثَمَنٍ. وَكَشَرْطِ بَائِعٍ نَفْعاً مَعْلُوماً فِي مَبِيعٍ؛ كَسُكْنَى الدَّارِ شَهْراً، أَوْ مُشْتَرٍ نَفْعَ بَائِعٍ؛ كَحَمْلِ حَطَبٍ أَوْ تَكْسِيرِهِ."]]},{"id":"ak11_7","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٧","segs":[["matn","وَإِنْ جَمَعَ بَيْنَ شَرْطَيْنِ: بَطَلَ الْبَيْعُ. وَفَاسِدٌ: يُبْطِلُهُ: كَشَرْطِ عَقْدٍ آخَرَ مِنْ قَرْضٍ وَغَيْرِهِ. أَوْ مَا يُعَلِّقُ الْبَيْعَ؛ كَبِعْتُكَ إِنْ جِئْتَنِي بِكَذَا، أَوْ رَضِيَ زَيْدٌ."]]},{"id":"ak11_8","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٨","segs":[["matn","وَفَاسِدٌ لَا يُبْطِلُهُ: كَشَرْطِ أَنْ لَا خَسَارَةَ. أَوْ مَتَى نَفَقَ وَإِلَّا رَدَّهُ، وَنَحْوِ ذَلِكَ. وَإِنْ شَرَطَ الْبَرَاءَةَ مِنْ كُلِّ عَيْبٍ مَجْهُولٍ: لَمْ يَبْرَأْ."]]},{"id":"ak11_9","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٩","segs":[["matn","فَصْلٌ: وَالْخِيَارُ سَبْعَةُ أَقْسَامٍ: خِيَارُ مَجْلِسٍ: فَالْمُتَبَايِعَانِ بِالْخِيَارِ مَا لَمْ يَتَفَرَّقَا بِأَبْدَانِهِمَا عُرْفاً. وَخِيَارُ شَرْطٍ: وَهُوَ أَنْ يَشْتَرِطَاهُ أَوْ أَحَدُهُمَا مُدَّةً مَعْلُومَةً. وَحَرُمَ حِيلَةً، وَلَمْ يَصِحَّ الْبَيْعُ."]]},{"id":"ak11_10","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ١٠","segs":[["matn","وَيَنْتَقِلُ الْمِلْكُ فِيهِمَا لِمُشْتَرٍ. لَكِنْ يَحْرُمُ وَلَا يَصِحُّ تَصَرُّفٌ فِي مَبِيعٍ وَعِوَضِهِ مُدَّتَهُمَا، إِلَّا: عِتْقَ مُشْتَرٍ مُطْلَقاً. وَإِلَّا تَصَرُّفَهُ فِي مَبِيعٍ، وَالْخِيَارُ لَهُ."]]},{"id":"ak11_11","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ١١","segs":[["matn","وَخِيَارُ غَبْنٍ يَخْرُجُ عَنِ الْعَادَةِ: لِنَجْشٍ، أَوْ غَيْرِهِ. لَا لِاسْتِعْجَالٍ. وَخِيَارُ تَدْلِيسٍ بِمَا يَزِيدُ بِهِ الثَّمَنُ؛ كَتَصْرِيَةٍ، وَتَسْوِيدِ شَعْرِ جَارِيَةٍ."]]},{"id":"ak11_12","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ١٢","segs":[["matn","وَخِيَارُ غَبْنٍ، وَعَيْبٍ، وَتَدْلِيسٍ: عَلَى التَّرَاخِي، مَا لَمْ يُوجَدْ دَلِيلُ الرِّضَا. إِلَّا فِي تَصْرِيَةٍ فَثَلَاثَةُ أَيَّامٍ. وَخِيَارُ عَيْبٍ يَنْقُصُ قِيمَةَ الْمَبِيعِ؛ كَمَرَضٍ، وَفَقْدِ عُضْوٍ، وَزِيَادَتِهِ."]]},{"id":"ak11_13","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ١٣","segs":[["matn","فَإِذَا عَلِمَ الْعَيْبَ: خُيِّرَ بَيْنَ إِمْسَاكٍ مَعَ أَرْشٍ، أَوْ رَدٍّ وَأَخْذِ ثَمَنٍ. وَإِنْ تَلِفَ مَبِيعٌ، أَوْ أُعْتِقَ وَنَحْوُهُ: تَعَيَّنَ أَرْشٌ."]]},{"id":"ak11_14","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ١٤","segs":[["matn","وَإِنْ تَعَيَّبَ أَيْضاً: خُيِّرَ فِيهِ بَيْنَ أَخْذِ أَرْشٍ، وَرَدٍّ مَعَ دَفْعِ أَرْشٍ وَيَأْخُذُ ثَمَنَهُ. وَإِنِ اخْتَلَفَا عِنْدَ مَنْ حَدَثَ: فَقَوْلُ مُشْتَرٍ بِيَمِينِهِ. وَخِيَارُ تَخْبِيرِ ثَمَنٍ: فَمَتَى بَانَ أَكْثَرَ."]]},{"id":"ak11_15","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ١٥","segs":[["matn","أَوْ أَنَّهُ اشْتَرَاهُ مُؤَجَّلاً. أَوْ مِمَّنْ لَا تُقْبَلُ شَهَادَتُةُ لَهُ. أَوْ بِأَكْثَرَ مِنْ ثَمَنِهِ حِيلَةً. أَوْ بَاعَ بَعْضَهُ بِقِسْطِهِ. وَلَمْ يُبَيِّنْ ذَلِكَ؛ فَلِمُشْتَرٍ الْخِيَارُ."]]},{"id":"ak11_16","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ١٦","segs":[["matn","وَخِيَارٌ لِاخْتِلَافِ الْمُتَبَايِعَيْنِ: فَإِذَا اخْتَلَفَا فِي قَدْرِ ثَمَنٍ، أَوْ أُجْرَةٍ، وَلَا بَيِّنَةَ، أَوْ لَهُمَا: حَلَفَ بَائِعٌ: مَا بِعْتُهُ بِكَذَا، وَإِنَّمَا بِعْتُهُ بِكَذَا. ثُمَّ مُشْتَرٍ: مَا اشْتَرَيْتُهُ بِكَذَا، وَإِنَّمَا اشْتَرَيْتُهُ بِكَذَا."]]},{"id":"ak11_17","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ١٧","segs":[["matn","وَلِكُلٍّ الْفَسْخُ إِنْ لَمْ يَرْضَ بِقَوْلِ الْآخَرِ. وَبَعْدَ تَلَفٍ: يَتَحَالَفَانِ، وَيَغْرَمُ مُشْتَرٍ قِيمَتَهُ. وَإِنِ اخْتَلَفَا فِي أَجَلٍ، أَوْ شَرْطٍ وَنَحْوِهِ: فَقَوْلُ نَافٍ. أَوْ عَيْنِ مَبِيعٍ، أَوْ قَدْرِهِ: فَقَوْلُ بَائِعٍ."]]},{"id":"ak11_18","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ١٨","segs":[["matn","وَيَثْبُتُ لِلْخُلْفِ فِي الصِّفَةِ، وَتَغَيُّرِ مَا تَقَدَّمَتْ رُؤْيَتُهُ."]]},{"id":"ak11_19","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ١٩","segs":[["matn","فَصْلٌ: وَمَنِ اشْتَرَى مَكِيلاً وَنَحْوَهُ: لَزِمَ بِالْعَقْدِ. وَلَمْ يَصِحَّ تَصَرُّفُهُ فِيهِ قَبْلَ قَبْضِهِ. وَيَحْصُلُ قَبْضُ: مَا بِيعَ بِكَيْلٍ وَنَحْوِهِ: بِذَلِكَ، مَعَ حُضُورِ مُشْتَرٍ أَوْ نَائِبِهِ، وَوِعَاؤُهُ كَيَدِهِ. وَصُبْرَةٍ وَمَنْقُولٍ: بِنَقْلٍ."]]},{"id":"ak11_20","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٢٠","segs":[["matn","وَمَا يُتَنَاوَلُ: بِتَنَاوُلِهِ. وَغَيْرِهِ: بِتَخْلِيَةٍ. وَالْإِقَالَةُ فَسْخٌ. تُسَنُّ لِلنَّادِمِ."]]},{"id":"ak11_21","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٢١","segs":[["matn","فَصْلٌ: الرِّبَا نَوْعَانِ: رِبَا فَضْلٍ. وَرِبَا نَسِيئَةٍ. فَرِبَا الْفَضْلِ: يَحْرُمُ فِي كُلِّ مَكِيلٍ وَمَوْزُونٍ بِيعَ بِجِنْسِهِ مُتَفَاضِلاً. وَلَوْ يَسِيراً لَا يَتَأَتَّى. وَيَصِحُّ: بِهِ مُتَسَاوِياً. وَبِغَيْرِهِ مُطْلَقاً، بِشَرْطِ قَبْضٍ قَبْلَ تَفَرُّقٍ."]]},{"id":"ak11_22","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٢٢","segs":[["matn","لَا مَكِيلٍ بِجِنْسِهِ وَزْناً، وَلَا عَكْسُهُ. إِلَّا إِذَا عُلِمَ تَسَاوِيهِمَا فِي الْمِعْيَارِ الشَّرْعِيِّ. وَرِبَا النَّسِيئَةِ: يَحْرُمُ فِيمَا اتَّفَقَا فِي عِلَّةِ رِبَا فَضْلٍ؛ كَمَكِيلٍ بِمَكِيلٍ، وَمَوْزُونٍ بِمَوْزُونٍ نَسَاءً."]]},{"id":"ak11_23","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٢٣","segs":[["matn","إِلَّا أَنْ يَكُونَ الثَّمَنُ أَحَدَ النَّقْدَيْنِ؛ فَيَصِحُّ. وَيَجُوزُ: بَيْعُ مَكِيلٍ بِمَوْزُونٍ وَعَكْسُهُ مُطْلَقاً. وَصَرْفُ ذَهَبٍ بِفِضَّةٍ وَعَكْسُهُ، وَإِذَا افْتَرَقَ مُتَصَارِفَانِ؛ بَطَلَ الْعَقْدُ فِيمَا لَمْ يُقْبَضْ."]]},{"id":"ak11_24","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٢٤","segs":[["matn","فَصْلٌ: وَإِذَا بَاعَ دَاراً شَمِلَ الْبَيْعُ: أَرْضَهَا. وَبِنَاءَهَا. وَسَقْفَهَا، وَبَاباً مَنْصُوباً، وَسُلَّماً وَرَفًّا مَسْمُورَيْنِ، وَخَابِيَةً مَدْفُونَةً. لَا قُفْلاً، وَمِفْتَاحاً، وَدَلْواً، وَبَكْرَةً وَنَحْوَهَا. أَوْ أَرْضاً شَمِلَ: غَرْسَهَا. وَبِنَاءَهَا."]]},{"id":"ak11_25","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٢٥","segs":[["matn","لَا زَرْعاً، وَبَذْرَهُ إِلَّا بِشَرْطٍ، وَيَصِحُّ مَعَ جَهْلِ ذَلِكَ. وَمَا يُجَزُّ أَوْ يُلْقَطُ مِرَاراً: فَأُصُولُهُ: لِمُشْتَرٍ. وَجَزَّةٌ وَلَقْطَةٌ ظَاهِرَتَانِ: لِبَائِعٍ، مَا لَمْ يَشْرِطْهُ مُشْتَرٍ."]]},{"id":"ak11_26","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٢٦","segs":[["matn","وَمَنْ بَاعَ نَخْلاً تَشَقَّقَ طَلْعُهُ: فَالثَّمَرُ لَهُ مُبَقًّى إِلَى جَدَادٍ، مَا لَمْ يَشْرِطْهُ مُشْتَرٍ."]]},{"id":"ak11_27","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٢٧","segs":[["matn","وَكَذَا حُكْمُ شَجَرٍ فِيهِ ثَمَرٌ بَادٍ، أَوْ ظَهَرَ مِنْ نَوْرِهِ؛ كَمِشْمِشٍ، أَوْ خَرَجَ مِنْ أَكْمَامِهِ؛ كَوَرْدٍ وَقُطْنٍ. وَمَا قَبْلَ ذَلِكَ، وَالْوَرَقُ مُطْلَقاً: لِمُشْتَرٍ."]]},{"id":"ak11_28","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٢٨","segs":[["matn","وَلَا يَصِحُّ بَيْعُ ثَمَرٍ قَبْلَ بُدُوِّ صَلَاحِهِ، وَلَا زَرْعٍ قَبْلَ اشْتِدَادِ حَبِّهِ، لِغَيْرِ مَالِكِ أَصْلٍ أَوْ أَرْضِهِ. إِلَّا بِشَرْطِ قَطْعٍ، إِنْ كَانَ مُنْتَفِعاً بِهِ، وَلَيْسَ مُشَاعاً."]]},{"id":"ak11_29","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٢٩","segs":[["matn","وَكَذَا بَقْلٌ وَرَطْبَةٌ، وَلَا قِثَّاءٍ وَنَحْوِهِ، إِلَّا: لَقْطَةً لَقْطَةً. أَوْ مَعَ أَصْلِهِ. وَإِنْ تُرِكَ مَا شُرِطَ قَطْعُهُ: بَطَلَ الْبَيْعُ بِزِيَادَةٍ غَيْرِ يَسِيرَةٍ. إِلَّا الْخَشَبَ فَلَا، وَيَشْتَرِكَانِ فِيهَا."]]},{"id":"ak11_30","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٣٠","segs":[["matn","وَحَصَادٌ، وَلَقَاطٌ، وَجَدَادٌ: عَلَى مُشْتَرٍ. وَعَلَى بَائِعٍ سَقْيٌ، وَلَوْ تَضَرَّرَ أَصْلٌ. وَمَا تَلِفَ -سِوَى يَسِيرٍ- بِآفَةٍ سَمَاوِيَّةٍ؛ فَعَلَى بَائِعٍ. مَا لَمْ يُبَعْ مَعَ أَصْلٍ. أَوْ يُؤَخَّرْ أَخْذٌ عَنْ عَادَتِهِ."]]},{"id":"ak11_31","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٣١","segs":[["matn","وَصَلَاحُ بَعْضِ ثَمَرَةِ شَجَرَةٍ: صَلَاحٌ لِجَمِيعِ نَوْعِهَا الَّذِي فِي الْبُسْتَانِ. فَصَلَاحُ ثَمَرِ: نَخْلٍ: أَنْ يَحْمَرَّ أَوْ يَصْفَرَّ. وَعِنَبٍ: أَنْ يَتَمَوَّهَ بِالْمَاءِ الْحُلْوِ. وَبَقِيَّةِ ثَمَرٍ: بُدُوُّ نُضْجٍ، وَطِيبُ أَكْلٍ."]]},{"id":"ak11_32","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٣٢","segs":[["matn","وَيَشْمَلُ بَيْعُ: دَابَّةٍ: عِذَارَهَا، وَمِقْوَدَهَا، وَنَعْلَهَا. وَقِنٍّ: لِبَاسَهُ لِغَيْرِ جَمَالٍ."]]},{"id":"ak11_33","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٣٣","segs":[["matn","فَصْلٌ: وَيَصِحُّ السَّلَمُ بِسَبْعَةِ شُرُوطٍ: أَنْ يَكُونَ فِيمَا يُمْكِنُ ضَبْطُ صِفَاتِهِ؛ كَمَكِيلٍ وَنَحْوِهِ. وَذِكْرُ جِنْسٍ وَنَوْعٍ، وَكُلِّ وَصْفٍ يَخْتَلِفُ بِهِ الثَّمَنُ غَالِباً، وَحَدَاثَةٍ وَقِدَمٍ. وَذِكْرُ قَدْرِهِ."]]},{"id":"ak11_34","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٣٤","segs":[["matn","وَلَا يَصِحُّ فِي مَكِيلٍ وَزْناً، وَعَكْسُهُ. وَذِكْرُ أَجَلٍ مَعْلُومٍ؛ كَشَهْرٍ. وَأَنْ يُوجَدَ غَالِباً فِي مَحِلِّهِ. فَإِنْ تَعَذَّرَ أَوْ بَعْضُهُ: صَبَرَ، أَوْ أَخَذَ رَأْسَ مَالِهِ. وَقَبْضُ الثَّمَنِ قَبْلَ التَّفَرُّقِ."]]},{"id":"ak11_35","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٣٥","segs":[["matn","وَأَنْ يُسْلِمَ فِي الذِّمَّةِ. فَلَا يَصِحُّ فِي عَيْنٍ، وَلَا ثَمَرَةِ شَجَرَةٍ مُعَيَّنَةٍ. وَيَجِبُ الْوَفَاءُ مَوْضِعَ الْعَقْدِ إِنْ لَمْ يُشْرَطْ فِي غَيْرِهِ. وَلَا يَصِحُّ: بَيْعُ مُسْلَمٍ فِيهِ قَبْلَ قَبْضِهِ."]]},{"id":"ak11_36","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٣٦","segs":[["matn","وَلَا الْحَوَالَةُ بِهِ، وَلَا عَلَيْهِ. وَلَا أَخْذُ رَهْنٍ وَكَفِيلٍ بِهِ. وَلَا أَخْذُ غَيْرِهِ عَنْهُ."]]},{"id":"ak11_37","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٣٧","segs":[["matn","فَصْلٌ: وَكُلُّ مَا صَحَّ بَيْعُهُ صَحَّ قَرْضُهُ، إِلَّا بَنِي آدَمَ. وَيَجِبُ رَدُّ مِثْلِ: فُلُوسٍ. وَمَكِيلٍ وَمَوْزُونٍ. فَإِنْ فُقِدَ: فَقِيمَتُهُ يَوْمَ فَقْدِهِ، وَقِيمَةُ غَيْرِهَا يَوْمَ قَبْضِهِ. وَيَحْرُمُ كُلُّ شَرْطٍ يَجُرُّ نَفْعاً."]]},{"id":"ak11_38","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٣٨","segs":[["matn","وَإِنْ وَفَّاهُ أَجْوَدَ، أَوْ أَهْدَى إِلَيْهِ هَدِيَّةً بَعْدَ وَفَاءٍ بِلَا شَرْطٍ: فَلَا بَأْسَ."]]},{"id":"ak11_39","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٣٩","segs":[["matn","فَصْلٌ: وَكُلُّ مَا جَازَ بَيْعُهُ جَازَ رَهْنُهُ. وَكَذَا ثَمَرٌ وَزَرْعٌ لَمْ يَبْدُ صَلَاحُهُمَا. وَقِنٌّ دُونَ وَلَدِهِ وَنَحْوِهِ. وَيَلْزَمُ فِي حَقِّ رَاهِنٍ بِقَبْضٍ. وَتَصَرُّفُ كُلٍّ مِنْهُمَا فِيهِ بِغَيْرِ إِذْنِ الْآخَرِ: بَاطِلٌ."]]},{"id":"ak11_40","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٤٠","segs":[["matn","إِلَّا عِتْقَ رَاهِنٍ، وَتُؤْخَذُ قِيمَتُهُ مِنْهُ رَهْناً. وَهُوَ أَمَانَةٌ فِي يَدِ مُرْتَهِنٍ. وَإِنْ رَهَنَ عِنْدَ اثْنَيْنِ فَوَفَّى أَحَدَهُمَا، أَوْ رَهَنَاهُ فَاسْتَوْفَى مِنْ أَحَدِهِمَا: انْفَكَّ فِي نَصِيبِهِ."]]},{"id":"ak11_41","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٤١","segs":[["matn","وَإِذَا حَلَّ الدَّيْنُ وَامْتَنَعَ مِنْ وَفَائِهِ: فَإِنْ كَانَ أَذِنَ لِمُرْتَهِنٍ فِي بَيْعِهِ: بَاعَهُ. وَإِلَّا أُجْبِرَ عَلَى الْوَفَاءِ، أَوْ بَيْعِ الرَّهْنِ. فَإِنْ أَبَى: حُبِسَ أَوْ عُزِّرَ."]]},{"id":"ak11_42","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٤٢","segs":[["matn","فَإِنْ أَصَرَّ: بَاعَهُ حَاكِمٌ، وَوَفَّى دَيْنَهُ. وَغَائِبٌ كَمُمْتَنِعٍ. وَإِنْ شَرَطَ: أَلَّا يُبَاعَ إِذَا حَلَّ الدَّيْنُ. أَوْ إِنْ جَاءَهُ بِحَقِّهِ فِي وَقْتِ كَذَا وَإِلَّا فَالرَّهْنُ لَهُ بِالدَّيْنِ. لَمْ يَصِحَّ الشَّرْطُ."]]},{"id":"ak11_43","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٤٣","segs":[["matn","وَلِمُرْتَهِنٍ أَنْ يَرْكَبَ مَا يُرْكَبُ، وَيَحْلُبَ مَا يُحْلَبُ بِقَدْرِ نَفَقَتِهِ بِلَا إِذْنٍ. وَإِنْ أَنْفَقَ عَلَيْهِ: بِلَا إِذْنِ رَاهِنٍ مَعَ إِمْكَانِهِ: لَمْ يَرْجِعْ."]]},{"id":"ak11_44","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٤٤","segs":[["matn","وَإِلَّا: رَجَعَ بِالْأَقَلِّ مِمَّا أَنْفَقَهُ وَنَفَقَةِ مِثْلِهِ إِنْ نَوَاهُ. وَمُعَارٌ، وَمُؤْجَرٌ، وَمُودَعٌ: كَرَهْنٍ. وَلَوْ خَرِبَ فَعَمَرَهُ: رَجَعَ بِآلَتِهِ فَقَطْ."]]},{"id":"ak11_45","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٤٥","segs":[["matn","فَصْلٌ: وَيَصِحُّ ضَمَانُ جَائِزِ التَّصَرُّفِ مَا وَجَبَ أَوْ سَيَجِبُ عَلَى غَيْرِهِ. لَا الْأَمَانَاتِ، بَلِ التَّعَدِّي فِيهَا. وَلَا جِزْيَةٍ. وَشُرِطَ رِضَا ضَامِنٍ فَقَطْ. وَلِرَبِّ حَقٍّ مُطَالَبَةُ مَنْ شَاءَ مِنْهُمَا."]]},{"id":"ak11_46","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٤٦","segs":[["matn","وَتَصِحُّ الْكَفَالَةُ: بِبَدَنِ مَنْ عَلَيْهِ حَقٌّ مَالِيٌّ. وَبِكُلِّ عَيْنٍ يَصِحُّ ضَمَانُهَا. وَشُرِطَ رِضَا كَفِيلٍ فَقَطْ. فَإِنْ: مَاتَ. أَوْ تَلِفَتِ الْعَيْنُ بِفِعْلِ اللَّهِ تَعَالَى قَبْلَ طَلَبٍ. بَرِئَ."]]},{"id":"ak11_47","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٤٧","segs":[["matn","وَتَجُوزُ الْحَوَالَةُ: عَلَى دَيْنٍ مُسْتَقِرٍّ. إِنِ اتَّفَقَ الدَّيْنَانِ جِنْساً، وَوَقْتاً، وَوَصْفاً، وَقَدْراً. وَتَصِحُّ بِخَمْسَةٍ عَلَى خَمْسَةٍ مِنْ عَشَرَةٍ، وَعَكْسُهُ. وَيُعْتَبَرُ رِضَا: مُحِيلٍ. وَمُحْتَالٍ عَلَى غَيْرِ مَلِيءٍ."]]},{"id":"ak11_48","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٤٨","segs":[["matn","فَصْلٌ: وَالصُّلْحُ فِي الْأَمْوَالِ قِسْمَانِ: أَحَدُهُمَا: عَلَى الْإِقْرَارِ، وَهُوَ نَوْعَانِ: الصُّلْحُ عَلَى جِنْسِ الْحَقِّ، مِثْلُ أَنْ يُقِرَّ لَهُ بِدَيْنٍ أَوْ عَيْنٍ، فَيَضَعَ أَوْ يَهَبَ لَهُ الْبَعْضَ وَيَأْخُذَ الْبَاقِيَ: فَيَصِحُّ: مِمَّنْ يَصِحُّ تَبَرُّعُهُ."]]},{"id":"ak11_49","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٤٩","segs":[["matn","بِغَيْرِ لَفْظِ صُلْحٍ. بِلَا شَرْطٍ. الثَّانِي: عَلَى غَيْرِ جِنْسِهِ: فَإِنْ كَانَ بِأَثْمَانٍ عَنْ أَثْمَانٍ: فَصَرْفٌ. وَبِعَرْضٍ عَنْ نَقْدٍ، وَعَكْسُهُ: فَبَيْعٌ."]]},{"id":"ak11_50","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٥٠","segs":[["matn","الْقِسْمُ الثَّانِي: عَلَى الْإِنْكَارِ، بِأَنْ يَدَّعِيَ عَلَيْهِ، فَيُنْكِرَ أَوْ يَسْكُتَ، ثُمَّ يُصَالِحَهُ: فَيَصِحُّ، وَيَكُونُ: إِبْرَاءً فِي حَقِّهِ. وَبَيْعاً فِي حَقِّ مُدَّعٍ. وَمَنْ عَلِمَ كَذِبَ نَفْسِهِ: فَالصُّلْحُ بَاطِلٌ فِي حَقِّهِ."]]},{"id":"ak11_51","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٥١","segs":[["matn","فَصْلٌ: وَإِذَا حَصَلَ فِي أَرْضِهِ أَوْ جِدَارِهِ أَوْ هَوَائِهِ غُصْنُ شَجَرَةِ غَيْرِهِ، أَوْ غُرْفَتُهُ؛ لَزِمَ: إِزَالَتُهُ، وَضَمِنَ مَا تَلِفَ بِهِ بَعْدَ طَلَبٍ. فَإِنْ أَبَى: لَمْ يُجْبَرْ فِي الْغُصْنِ، وَلَوَاهُ."]]},{"id":"ak11_52","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٥٢","segs":[["matn","فَإِنْ لَمْ يُمْكِنْهُ: فَلَهُ قَطْعُهُ بِلَا حُكْمٍ. وَيَجُوزُ فَتْحُ بَابٍ لِاسْتِطْرَاقٍ فِي دَرْبٍ نَافِذٍ. لَا إِخْرَاجُ جَنَاحٍ، وَسَابَاطٍ، وَمِيزَابٍ، إِلَّا: بِإِذْنِ إِمَامٍ. مَعَ أَمْنِ الضَّرَرِ."]]},{"id":"ak11_53","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٥٣","segs":[["matn","وَفِعْلُ ذَلِكَ فِي مِلْكِ جَارٍ، وَدَرْبٍ مُشْتَرَكٍ: حَرَامٌ بِلَا إِذْنِ مُسْتَحِقٍّ. وَكَذَا وَضْعُ خَشَبٍ، إِلَّا: أَلَّا يُمْكِنَ تَسْقِيفٌ إِلَّا بِهِ. وَلَا ضَرَرَ. فَيُجْبَرُ. وَمَسْجِدٌ كَدَارٍ."]]},{"id":"ak11_54","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٥٤","segs":[["matn","وَإِنْ طَلَبَ شَرِيكٌ فِي حَائِطٍ أَوْ سَقْفٍ انْهَدَمَ شَرِيكَهُ لِلْبِنَاءِ مَعَهُ: أُجْبِرَ. كَنَقْضٍ خَوْفَ سُقُوطٍ. وَإِنْ بَنَاهُ بِنِيَّةِ الرُّجُوعِ: رَجَعَ. وَكَذَا نَهْرٌ وَنَحْوُهُ."]]},{"id":"ak11_55","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٥٥","segs":[["matn","فَصْلٌ: وَمَنْ مَالُهُ لَا يَفِي بِمَا عَلَيْهِ حَالًّا: وَجَبَ الْحَجْرُ عَلَيْهِ بِطَلَبِ بَعْضِ غُرَمَائِهِ. وَسُنَّ إِظْهَارُهُ. وَلَا يَنْفُذُ تَصَرُّفُهُ فِي مَالِهِ بَعْدَ الْحَجْرِ."]]},{"id":"ak11_56","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٥٦","segs":[["matn","وَلَا إِقْرَارُهُ عَلَيْهِ، بَلْ فِي ذِمَّتِهِ، فَيُطَالَبُ بَعْدَ فَكِّ حَجْرٍ. وَمَنْ سَلَّمَهُ عَيْنَ مَالٍ جَاهِلَ الْحَجْرِ؛ أَخَذَهَا: إِنْ كَانَتْ بِحَالِهَا. وَعِوَضُهَا كُلُّهُ بَاقٍ. وَلَمْ يَتَعَلَّقْ بِهَا حَقٌّ لِلْغَيْرِ."]]},{"id":"ak11_57","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٥٧","segs":[["matn","وَيَبِيعُ حَاكِمٌ مَالَهُ، وَيَقْسِمُهُ عَلَى غُرَمَائِهِ. وَمَنْ لَمْ يَقْدِرْ عَلَى وَفَاءِ شَيْءٍ مِنْ دَيْنِهِ، أَوْ هُوَ مُؤَجَّلٌ: تَحْرُمُ مُطَالَبَتُهُ، وَحَبْسُهُ، وَكَذَا مُلَازَمَتُهُ. وَلَا يَحِلُّ مُؤَجَّلٌ: بِفَلَسٍ."]]},{"id":"ak11_58","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٥٨","segs":[["matn","وَلَا بِمَوْتٍ إِنْ وَثَّقَ الْوَرَثَةُ: بِرَهْنٍ مُحْرِزٍ. أَوْ كَفِيلٍ مَلِيءٍ. وَإِنْ ظَهَرَ غَرِيمٌ بَعْدَ الْقِسْمَةِ: رَجَعَ عَلَى الْغُرَمَاءِ بِقِسْطِهِ."]]},{"id":"ak11_59","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٥٩","segs":[["matn","فَصْلٌ: وَيُحْجَرُ عَلَى الصَّغِيرِ، وَالْمَجْنُونِ، وَالسَّفِيهِ: لِحَظِّهِمْ. وَمَنْ دَفَعَ إِلَيْهِمْ مَالَهُ بِعَقْدٍ أَوْ لَا: رَجَعَ بِمَا بَقِيَ، لَا مَا تَلِفَ. وَيَضْمَنُونَ: جِنَايَةً. وَإِتْلَافَ مَا لَمْ يُدْفَعْ إِلَيْهِمْ."]]},{"id":"ak11_60","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٦٠","segs":[["matn","وَمَنْ بَلَغَ رَشِيداً، أَوْ مَجْنُوناً ثُمَّ عَقَلَ وَرَشَدَ: انْفَكَّ الْحَجْرُ عَنْهُ بِلَا حُكْمٍ. وَأُعْطِيَ مَالَهُ. لَا قَبْلَ ذَلِكَ بِحَالٍ. وَبُلُوغُ ذَكَرٍ: بِإِمْنَاءٍ. أَوْ بِتَمَامِ خَمْسَ عَشْرَةَ سَنَةً."]]},{"id":"ak11_61","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٦١","segs":[["matn","أَوْ بِنَبَاتِ شَعْرٍ خَشِنٍ حَوْلَ قُبُلِهِ. وَأُنْثَى: بِذَلِكَ. وَبِحَيْضٍ. وَحَمْلُهَا دَلِيلُ إِمْنَاءٍ. وَلَا يُدْفَعُ إِلَيْهِ مَالُهُ حَتَّى يُخْتَبَرَ بِمَا يَلِيقُ بِهِ، وَيُؤْنَسَ رُشْدُهُ. وَمَحَلُّهُ قَبْلَ بُلُوغٍ."]]},{"id":"ak11_62","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٦٢","segs":[["matn","وَالرُّشْدُ هُنَا: إِصْلَاحُ الْمَالِ، بِأَنْ: يَبِيعَ وَيَشْتَرِيَ فَلَا يُغْبَنَ غَالِباً. وَلَا يَبْذُلَ مَالَهُ فِي حَرَامٍ، وَغَيْرِ فَائِدَةٍ. وَوَلِيُّهُمْ حَالَ الْحَجْرِ: الْأَبُ. ثُمَّ وَصِيُّهُ. ثُمَّ الْحَاكِمُ. وَلَا يَتَصَرَّفُ لَهُمْ إِلَّا بِالْأَحَظِّ."]]},{"id":"ak11_63","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٦٣","segs":[["matn","وَيُقْبَلُ قَوْلُهُ بَعْدَ فَكِّ حَجْرٍ فِي: مَنْفَعَةٍ. وَضَرُورَةٍ. وَتَلَفٍ. لَا فِي دَفْعِ مَالٍ بَعْدَ رُشْدٍ، إِلَّا مِنْ مُتَبَرِّعٍ. وَيَتَعَلَّقُ: دَيْنُ مَأْذُونٍ لَهُ: بِذِمَّةِ سَيِّدٍ."]]},{"id":"ak11_64","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٦٤","segs":[["matn","وَدَيْنُ غَيْرِهِ، وَأَرْشُ جِنَايَةِ قِنٍّ، وَقِيَمُ مُتْلَفَاتِهِ: بِرَقَبَتِهِ."]]},{"id":"ak11_65","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٦٥","segs":[["matn","فَصْلٌ: وَتَصِحُّ الْوَكَالَةُ: بِكُلِّ قَوْلٍ يَدُلُّ عَلَى إِذْنٍ. وَقَبُولُهَا: بِكُلِّ قَوْلٍ، أَوْ فِعْلٍ دَالٍّ عَلَيْهِ. وَشُرِطَ: كَوْنُهُمَا جَائِزَيِ التَّصَرُّفِ. وَمَنْ لَهُ تَصَرُّفٌ فِي شَيْءٍ فَلَهُ: تَوَكُّلٌ، وَتَوْكِيلٌ فِيهِ."]]},{"id":"ak11_66","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٦٦","segs":[["matn","وَتَصِحُّ فِي: كُلِّ حَقِّ آدَمِيٍّ. لَا ظِهَارٍ، وَلِعَانٍ، وَأَيْمَانٍ. وَفِي كُلِّ حَقٍّ لِلَّهِ تَدْخُلُهُ النِّيَابَةُ. وَهِيَ، وَشَرِكَةٌ، وَمُضَارَبَةٌ، وَمُسَاقَاةٌ، وَمُزَارَعَةٌ، وَوَدِيعَةٌ، وَجُعَالَةٌ: عُقُودٌ جَائِزَةٌ، لِكُلٍّ فَسْخُهَا."]]},{"id":"ak11_67","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٦٧","segs":[["matn","وَلَا يَصِحُّ بِلَا إِذْنٍ: بَيْعُ وَكِيلٍ لِنَفْسِهِ، وَلَا شِرَاؤُهُ مِنْهَا لِمُوَكِّلِهِ. وَوَلَدُهُ وَوَالِدُهُ وَمُكَاتَبُهُ؛ كَنَفْسِهِ. وَإِنْ بَاعَ بِدُونِ ثَمَنِ مِثْلٍ، أَوِ اشْتَرَى بِأَكْثَرَ مِنْهُ: صَحَّ، وَضَمِنَ زِيَادَةً أَوْ نَقْصاً."]]},{"id":"ak11_68","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٦٨","segs":[["matn","وَوَكِيلُ مَبِيعٍ: يُسَلِّمُهُ، وَلَا يَقْبِضُ ثَمَنَهُ إِلَّا بِقَرِينَةٍ. وَيُسَلِّمُ وَكِيلُ الشِّرَاءِ الثَّمَنَ. وَوَكِيلُ خُصُومَةٍ: لَا يَقْبِضُ. وَقَبْضٍ يُخَاصِمُ. وَالْوَكِيلُ: أَمِينٌ، لَا يَضْمَنُ إِلَّا بِتَعَدٍّ أَوْ تَفْرِيطٍ. وَيُقْبَلُ قَوْلُهُ فِي: نَفْيِهِمَا."]]},{"id":"ak11_69","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٦٩","segs":[["matn","وَهَلَاكٍ بِيَمِينِهِ. كَدَعْوَى مُتَبَرِّعٍ رَدَّ الْعَيْنِ أَوْ ثَمَنِهَا لِمُوَكِّلٍ. لَا لِوَرَثَتِهِ إِلَّا بِبَيِّنَةٍ."]]},{"id":"ak11_70","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٧٠","segs":[["matn","فَصْلٌ: وَالشَّرِكَةُ خَمْسَةُ أَضْرُبٍ: شَرِكَةُ عِنَانٍ: وَهِيَ أَنْ يُحْضِرَ كُلٌّ مِنْ عَدَدٍ جَائِزِ التَّصَرُّفِ مِنْ مَالِهِ نَقْداً مَعْلُوماً، لِيَعْمَلَ فِيهِ كُلٌّ، عَلَى أَنَّ لَهُ مِنَ الرِّبْحِ جُزْءاً مُشَاعاً مَعْلُوماً."]]},{"id":"ak11_71","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٧١","segs":[["matn","الثَّانِي: الْمُضَارَبَةُ: وَهِيَ دَفْعُ مَالٍ مُعَيَّنٍ مَعْلُومٍ لِمَنْ يَتَّجِرُ فِيهِ، بِجُزْءٍ مَعْلُومٍ مُشَاعٍ مِنْ رِبْحِهِ. وَإِنْ ضَارَبَ لِآخَرَ فَأَضَرَّ الْأَوَّلَ: حَرُمَ. وَرَدَّ حِصَّتَهُ فِي الشَّرِكَةِ."]]},{"id":"ak11_72","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٧٢","segs":[["matn","وَإِنْ تَلِفَ رَأْسُ الْمَالِ أَوْ بَعْضُهُ بَعْدَ تَصَرُّفٍ، أَوْ خَسِرَ: جُبِرَ مِنْ رِبْحٍ قَبْلَ قِسْمَةٍ. الثَّالِثُ: شَرِكَةُ الْوُجُوهِ: وَهِيَ أَنْ يَشْتَرِكَا فِي رِبْحِ مَا يَشْتَرِيَانِ فِي ذِمَمِهِمَا بِجَاهَيْهِمَا."]]},{"id":"ak11_73","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٧٣","segs":[["matn","وَكُلٌّ وَكِيلُ الْآخَرِ، وَكَفِيلُهُ بِالثَّمَنِ. الرَّابِعُ: شَرِكَةُ الْأَبْدَانِ: وَهِيَ: أَنْ يَشْتَرِكَا فِيمَا يَتَمَلَّكَانِ بِأَبْدَانِهِمَا مِنْ مُبَاحٍ؛ كَاصْطِيَادٍ وَنَحْوِهِ. أَوْ يَتَقَبَّلَانِ فِي ذِمَمِهِمَا مِنْ عَمَلٍ؛ كَخِيَاطَةٍ."]]},{"id":"ak11_74","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٧٤","segs":[["matn","فَمَا تَقَبَّلَهُ أَحَدُهُمَا: لَزِمَهُمَا عَمَلُهُ، وَطُولِبَا بِهِ. وَإِنْ تَرَكَ أَحَدُهُمَا الْعَمَلَ لِعُذْرٍ أَوْ لَا: فَالْكَسْبُ بَيْنَهُمَا. وَيَلْزَمُ مَنْ عُذِرَ أَوْ لَمْ يَعْرِفِ الْعَمَلَ: أَنْ يُقِيمَ مَقَامَهُ بِطَلَبِ شَرِيكٍ."]]},{"id":"ak11_75","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٧٥","segs":[["matn","الْخَامِسُ: شَرِكَةُ الْمُفَاوَضَةِ: وَهِيَ: أَنْ يُفَوِّضَ كُلٌّ إِلَى صَاحِبِهِ كُلَّ تَصَرُّفٍ مَالِيٍّ. وَيَشْتَرِكَا فِي كُلِّ مَا يَثْبُتُ لَهُمَا وَعَلَيْهِمَا، فَتَصِحُّ، إِنْ لَمْ يُدْخِلَا فِيهِمَا كَسْباً نَادِراً. وَكُلُّهَا جَائِزَةٌ. وَلَا ضَمَانَ فِيهَا إِلَّا بِتَعَدٍّ أَوْ تَفْرِيطٍ."]]},{"id":"ak11_76","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٧٦","segs":[["matn","فَصْلٌ: وَتَصِحُّ الْمُسَاقَاةُ عَلَى: شَجَرٍ لَهُ ثَمَرٌ يُؤْكَلُ. وَثَمَرَةٍ مَوْجُودَةٍ بِجُزْءٍ مِنْهَا. وَعَلَى شَجَرٍ يَغْرِسُهُ وَيَعْمَلُ عَلَيْهِ حَتَّى يُثْمِرَ. بِجُزْءٍ مِنَ الثَّمَرَةِ أَوِ الشَّجَرِ أَوْ مِنْهُمَا."]]},{"id":"ak11_77","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٧٧","segs":[["matn","فَإِنْ فَسَخَ: مَالِكٌ قَبْلَ ظُهُورِ ثَمَرَةٍ: فَلِعَامِلٍ أُجْرَتُهُ. أَوْ عَامِلٌ: فَلَا شَيْءَ لَهُ. وَتُمْلَكُ الثَّمَرَةُ: بِظُهُورِهَا. فَعَلَى عَامِلٍ تَمَامُ عَمَلٍ إِذَا فُسِخَتْ بَعْدَهُ."]]},{"id":"ak11_78","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٧٨","segs":[["matn","وَعَلَى عَامِلٍ: كُلُّ مَا فِيهِ نُمُوٌّ أَوْ إِصْلَاحٌ، وَحَصَادٌ وَنَحْوُهُ. وَعَلَى رَبِّ أَصْلٍ: حِفْظٌ وَنَحْوُهُ. وَعَلَيْهِمَا -بِقَدْرِ حِصَّتَيْهِمَا-: جَدَادٌ."]]},{"id":"ak11_79","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٧٩","segs":[["matn","وَتَصِحُّ الْمُزَارَعَةُ: بِجُزْءٍ مَعْلُومٍ مِمَّا يَخْرُجُ مِنَ الْأَرْضِ، بِشَرْطِ: عِلْمِ بَذْرٍ وَقَدْرِهِ. وَكَوْنِهِ مِنْ رَبِّ الْأَرْضِ. وَاللَّهُ أَعْلَمُ."]]},{"id":"ak11_80","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٨٠","segs":[["matn","فَصْلٌ: وَتَصِحُّ الْإِجَارَةُ بِثَلَاثَةِ شُرُوطٍ: مَعْرِفَةُ مَنْفَعَةٍ. وَإِبَاحَتُهَا. وَمَعْرِفَةُ أُجْرَةٍ. إِلَّا أَجِيراً وَظِئْراً بِطَعَامِهِمَا وَكِسْوَتِهِمَا. وَإِنْ دَخَلَ حَمَّاماً، أَوْ سَفِينَةً، أَوْ أَعْطَى ثَوْبَهُ خَيَّاطاً وَنَحْوَهُ: صَحَّ، وَلَهُ أُجْرَةُ مِثْلٍ."]]},{"id":"ak11_81","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٨١","segs":[["matn","وَهِيَ ضَرْبَانِ: إِجَارَةُ عَيْنٍ، وَشُرِطَ: مَعْرِفَتُهَا. وَقُدْرَةٌ عَلَى تَسْلِيمِهَا. وَعَقْدٌ -فِي غَيْرِ ظِئْرٍ- عَلَى نَفْعِهَا دُونَ أَجْزَائِهَا. وَاشْتِمَالُهَا عَلَى النَّفْعِ. وَكَوْنُهَا لِمُؤْجِرٍ، أَوْ مَأْذُونًا لَهُ فِيهَا."]]},{"id":"ak11_82","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٨٢","segs":[["matn","وَإِجَارَةُ الْعَيْنِ قِسْمَانِ: إِلَى أَمَدٍ مَعْلُومٍ، يَغْلِبُ عَلَى الظَّنِّ بَقَاؤُهَا فِيهِ. الثَّانِي: لِعَمَلٍ مَعْلُومٍ؛ كَإِجَارَةِ دَابَّةٍ لِرُكُوبٍ أَوْ حَمْلٍ إِلَى مَوْضِعٍ مُعَيَّنٍ."]]},{"id":"ak11_83","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٨٣","segs":[["matn","الضَّرْبُ الثَّانِي: عَقْدٌ عَلَى مَنْفَعَةٍ فِي الذِّمَّةِ، فِي شَيْءٍ مُعَيَّنٍ أَوْ مَوْصُوفٍ. فَيُشْتَرَطُ: تَقْدِيرُهَا بِعَمَلٍ أَوْ مُدَّةٍ؛ كَبِنَاءِ دَارٍ، وَخِيَاطَةٍ. وَشُرِطَ: مَعْرِفَةُ ذَلِكَ وَضَبْطُهُ. وَكَوْنُ أَجِيرٍ فِيهَا آدَمِيًّا، جَائِزَ التَّصَرُّفِ."]]},{"id":"ak11_84","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٨٤","segs":[["matn","وَكَوْنُ عَمَلٍ لَا يَخْتَصُّ فَاعِلُهُ أَنْ يَكُونَ مِنْ أَهْلِ الْقُرْبَةِ. وَعَلَى مُؤْجِرٍ: كُلُّ مَا جَرَتْ بِهِ عَادَةٌ وَعُرْفٌ؛ كَزِمَامِ مَرْكُوبٍ، وَشَدٍّ، وَرَفْعٍ وَحَطٍّ."]]},{"id":"ak11_85","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٨٥","segs":[["matn","وَعَلَى مُكْتَرٍ نَحْوُ: مَحْمِلٍ، وَمِظَلَّةٍ، وَتَعْزِيلُ نَحْوِ بَالُوعَةٍ إِنْ تَسَلَّمَهَا فَارِغَةً، وَعَلَى مُكْرٍ تَسْلِيمُهَا كَذَلِكَ."]]},{"id":"ak11_86","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٨٦","segs":[["matn","فَصْلٌ: وَهِيَ عَقْدٌ لَازِمٌ. فَإِنْ تَحَوَّلَ مُسْتَأْجِرٌ فِي أَثْنَاءِ الْمُدَّةِ بِلَا عُذْرٍ: فَعَلَيْهِ كُلُّ الْأُجْرَةِ. وَإِنْ حَوَّلَهُ مَالِكٌ: فَلَا شَيْءَ لَهُ. وَتَنْفَسِخُ: بِتَلَفِ مَعْقُودٍ عَلَيْهِ. وَمَوْتِ مُرْتَضِعٍ."]]},{"id":"ak11_87","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٨٧","segs":[["matn","وَانْقِلَاعِ ضِرْسٍ أَوْ بُرْئِهِ وَنَحْوِهِ. وَلَا يَضْمَنُ: أَجِيرٌ خَاصٌّ مَا جَنَتْ يَدُهُ خَطَأً. وَلَا نَحْوُ حَجَّامٍ، وَطَبِيبٍ، وَبَيْطَارٍ: عُرِفَ حِذْقُهُمْ. إِنْ أَذِنَ فِيهِ مُكَلَّفٌ أَوْ وَلِيُّ غَيْرِهِ. وَلَمْ تَجْنِ أَيْدِيهِمْ."]]},{"id":"ak11_88","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٨٨","segs":[["matn","وَلَا رَاعٍ مَا لَمْ يَتَعَدَّ أَوْ يُفَرِّطْ. وَيَضْمَنُ مُشْتَرَكٌ مَا تَلِفَ بِفِعْلِهِ. لَا مِنْ حِرْزِهِ، وَلَا أُجْرَةَ لَهُ. وَالْخَاصُّ: مَنْ قُدِّرَ نَفْعُهُ بِالزَّمَنِ. وَالْمُشْتَرَكُ: بِالْعَمَلِ."]]},{"id":"ak11_89","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٨٩","segs":[["matn","وَتَجِبُ الْأُجْرَةُ: بِالْعَقْدِ، مَا لَمْ تُؤَجَّلْ. وَلَا ضَمَانَ عَلَى مُسْتَأْجِرٍ، إِلَّا بِتَعَدٍّ أَوْ تَفْرِيطٍ. وَالْقَوْلُ قَوْلُهُ فِي نَفْيِهِمَا."]]},{"id":"ak11_90","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٩٠","segs":[["matn","فَصْلٌ: وَتَجُوزُ الْمُسَابَقَةُ عَلَى أَقْدَامٍ، وَسِهَامٍ، وَسُفُنٍ، وَمَزَارِيقَ، وَسَائِرِ حَيَوَانٍ. لَا بِعِوَضٍ، إِلَّا عَلَى إِبِلٍ، وَخَيْلٍ، وَسِهَامٍ. وَشُرِطَ: تَعْيِينُ مَرْكُوبَيْنِ. وَاتِّحَادُهُمَا. وَتَعْيِينُ رُمَاةٍ. وَتَحْدِيدُ مَسَافَةٍ. وَعِلْمُ عِوَضٍ، وَإِبَاحَتُهُ. وَخُرُوجٌ عَنْ شِبْهِ قِمَارٍ. وَاللَّهُ أَعْلَمُ."]]},{"id":"ak11_91","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٩١","segs":[["matn","فَصْلٌ: وَالْعَارِيَّةُ سُنَّةٌ. وَكُلُّ مَا يُنْتَفَعُ بِهِ مَعَ بَقَاءِ عَيْنِهِ، نَفْعاً مُبَاحاً؛ تَصِحُّ إِعَارَتُهُ، إِلَّا: الْبُضْعَ. وَعَبْداً مُسْلِماً لِكَافِرٍ. وَصَيْداً وَنَحْوَهُ لِمُحْرِمٍ. وَأَمَةً وَأَمْرَدَ لِغَيْرِ مَأْمُونٍ. وَتُضْمَنُ مُطْلَقاً: بِمِثْلِ مِثْلِيٍّ."]]},{"id":"ak11_92","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٩٢","segs":[["matn","وَقِيمَةِ غَيْرِهِ يَوْمَ تَلَفٍ. لَا: إِنْ تَلِفَتْ بِاسْتِعْمَالٍ بِمَعْرُوفٍ؛ كَخَمْلِ مِنْشَفَةٍ. وَلَا إِنْ كَانَتْ وَقْفاً؛ كَكُتُبِ عِلْمٍ، إِلَّا بِتَفْرِيطٍ. وَعَلَيْهِ مُؤْنَةُ رَدِّهَا. وَإِنْ أَرْكَبَ مُنْقَطِعاً لِلَّهِ: لَمْ يَضْمَنْ."]]},{"id":"ak11_93","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٩٣","segs":[["matn","فَصْلٌ: وَالْغَصْبُ كَبِيرَةٌ. فَمَنْ غَصَبَ كَلْباً يُقْتَنَى، أَوْ خَمْرَ ذِمِّيٍّ مُحْتَرَمَةً: رَدَّهُمَا. لَا جِلْدَ مَيْتَةٍ. وَإِتْلَافُ الثَّلَاثَةِ: هَدَرٌ. وَإِنِ اسْتَوْلَى عَلَى حُرٍّ مُسْلِمٍ: لَمْ يَضْمَنْهُ. بَلْ ثِيَابَ صَغِيرٍ وَحُلِيَّهُ."]]},{"id":"ak11_94","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٩٤","segs":[["matn","وَإِنِ اسْتَعْمَلَهُ كَرْهاً أَوْ حَبَسَهُ: فَعَلَيْهِ أُجْرَتُهُ؛ كَقِنٍّ. وَيَلْزَمُهُ رَدُّ مَغْصُوبٍ بِزِيَادَتِهِ. وَإِنْ نَقَصَ لِغَيْرِ تَغَيُّرِ سِعْرٍ: فَعَلَيْهِ أَرْشُهُ. وَإِنْ بَنَى أَوْ غَرَسَ؛ لَزِمَهُ: قَلْعٌ. وَأَرْشُ نَقْصٍ. وَتَسْوِيَةُ أَرْضٍ. وَالْأُجْرَةُ."]]},{"id":"ak11_95","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٩٥","segs":[["matn","وَلَوْ غَصَبَ مَا اتَّجَرَ، أَوْ صَادَ أَوْ حَصَدَ بِهِ: فَمَهْمَا حَصَلَ بِذَلِكَ فَلِمَالِكِهِ. وَإِنْ خَلَطَهُ بِمَا لَا يَتَمَيَّزُ، أَوْ صَبَغَ الثَّوْبَ: فَهُمَا شَرِيكَانِ بِقَدْرِ مِلْكَيْهِمَا. وَإِنْ نَقَصَتِ الْقِيمَةُ: ضَمِنَ."]]},{"id":"ak11_96","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٩٦","segs":[["matn","فَصْلٌ: وَمَنِ اشْتَرَى أَرْضاً فَغَرَسَ، أَوْ بَنَى، ثُمَّ اسْتُحِقَّتْ، وَقُلِعَ ذَلِكَ: رَجَعَ عَلَى بَائِعٍ بِمَا غَرِمَهُ. وَإِنْ أَطْعَمَهُ لِعَالِمٍ بِغَصْبِهِ: ضَمِنَ آكِلٌ. وَيُضْمَنُ مِثْلِيٌّ: بِمِثْلِهِ، وَغَيْرُهُ: بِقِيمَتِهِ."]]},{"id":"ak11_97","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٩٧","segs":[["matn","وَحَرُمَ تَصَرُّفُ غَاصِبٍ بِمَغْصُوبٍ. وَلَا يَصِحُّ عَقْدٌ. وَلَا عِبَادَةٌ. وَالْقَوْلُ فِي تَالِفٍ، وَقَدْرِهِ، وَصِفَتِهِ: قَوْلُهُ. وَفِي رَدِّهِ، وَعَيْبٍ فِيهِ: قَوْلُ رَبِّهِ."]]},{"id":"ak11_98","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٩٨","segs":[["matn","وَمَنْ بِيَدِهِ غَصْبٌ، أَوْ غَيْرُهُ، وَجَهِلَ رَبَّهُ: فَلَهُ الصَّدَقَةُ بِهِ عَنْهُ بِنِيَّةِ الضَّمَانِ. وَيَسْقُطُ إِثْمُ غَصْبٍ. وَمَنْ أَتْلَفَ -وَلَوْ سَهْواً- مُحْتَرَماً: ضَمِنَهُ."]]},{"id":"ak11_99","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ٩٩","segs":[["matn","وَإِنْ رَبَطَ دَابَّةً بِطَرِيقٍ ضَيِّقٍ: ضَمِنَ مَا أَتْلَفَتْهُ مُطْلَقاً. وَإِنْ كَانَتْ بِيَدِ رَاكِبٍ، أَوْ قَائِدٍ، أَوْ سَائِقٍ: ضَمِنَ جِنَايَةَ مُقَدَّمِهَا، وَوَطْأَهَا بِرِجْلِهَا."]]},{"id":"ak11_100","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ١٠٠","segs":[["matn","فَصْلٌ: وَتَثْبُتُ الشُّفْعَةُ: فَوْراً، لِمُسْلِمٍ، تَامِّ الْمِلْكِ. فِي حِصَّةِ شَرِيكِهِ الْمُنْتَقِلَةِ لِغَيْرِهِ بِعِوَضٍ مَالِيٍّ. بِمَا اسْتَقَرَّ عَلَيْهِ الْعَقْدُ. وَشُرِطَ: تَقَدُّمُ مِلْكِ شَفِيعٍ. وَكَوْنُ شِقْصٍ مُشَاعاً مِنْ أَرْضٍ تَجِبُ قِسْمَتُهَا."]]},{"id":"ak11_101","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ١٠١","segs":[["matn","وَيَدْخُلُ غِرَاسٌ وَبِنَاءٌ تَبَعاً، لَا ثَمَرَةٌ وَزَرْعٌ. وَأَخْذُ جَمِيعِ مَبِيعٍ. فَإِنْ أَرَادَ أَخْذَ الْبَعْضِ. أَوْ عَجَزَ عَنْ بَعْضِ الثَّمَنِ بَعْدَ إِنْظَارِهِ ثَلَاثاً. أَوْ قَالَ لِمُشْتَرٍ: بِعْنِي، أَوْ صَالِحْنِي."]]},{"id":"ak11_102","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ١٠٢","segs":[["matn","أَوْ أَخْبَرَهُ عَدْلٌ، فَكَذَّبَهُ وَنَحْوُهُ. سَقَطَتْ. فَإِنْ عَفَا بَعْضُهُمْ: أَخَذَ بَاقِيهِمُ الْكُلَّ، أَوْ تَرَكَهُ. وَإِنْ مَاتَ شَفِيعٌ قَبْلَ طَلَبٍ: بَطَلَتْ. وَإِنْ كَانَ الثَّمَنُ مُؤَجَّلاً: أَخَذَ مَلِيءٌ بِهِ. وَغَيْرُهُ: بِكَفِيلٍ مَلِيءٍ. وَلَوْ أَقَرَّ بَائِعٌ بِالْبَيْعِ وَأَنْكَرَ مُشْتَرٍ: ثَبَتَتْ."]]},{"id":"ak11_103","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ١٠٣","segs":[["matn","فَصْلٌ: وَيُسَنُّ قَبُولُ وَدِيعَةٍ: لِمَنْ يَعْلَمُ مِنْ نَفْسِهِ الْأَمَانَةَ. وَيَلْزَمُ حِفْظُهَا فِي حِرْزِ مِثْلِهَا."]]},{"id":"ak11_104","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ١٠٤","segs":[["matn","وَإِنْ عَيَّنَهُ رَبُّهَا فَأَحْرَزَ بِدُونِهِ، أَوْ تَعَدَّى أَوْ فَرَّطَ، أَوْ قَطَعَ عَلَفَ دَابَّةٍ عَنْهَا بِغَيْرِ قَوْلٍ: ضَمِنَ. وَيُقْبَلُ قَوْلُ مُودَعٍ فِي: رَدِّهَا إِلَى رَبِّهَا، أَوْ غَيْرِهِ بِإِذْنِهِ، لَا وَارِثِهِ."]]},{"id":"ak11_105","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ١٠٥","segs":[["matn","وَفِي تَلَفِهَا. وَعَدَمِ تَفْرِيطٍ وَتَعَدٍّ. وَفِي الْإِذْنِ. وَإِنْ أَوْدَعَ اثْنَانِ مَكِيلاً أَوْ مَوْزُوناً يُقْسَمُ، فَطَلَبَ أَحَدُهُمَا نَصِيبَهُ لِغَيْبَةِ شَرِيكٍ، أَوِ امْتِنَاعِهِ: سُلِّمَ إِلَيْهِ."]]},{"id":"ak11_106","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ١٠٦","segs":[["matn","وَلِمُودَعٍ، وَمُضَارَبٍ، وَمُرْتَهِنٍ، وَمُسْتَأْجِرٍ إِنْ غُصِبَتِ الْعَيْنُ: الْمُطَالَبَةُ بِهَا."]]},{"id":"ak11_107","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ١٠٧","segs":[["matn","فَصْلٌ: وَمَنْ أَحْيَا أَرْضاً مُنْفَكَّةً عَنِ الِاخْتِصَاصَاتِ، وَمِلْكِ مَعْصُومٍ: مَلَكَهَا. وَيَحْصُلُ: بِحَوْزِهَا بِحَائِطٍ مَنِيعٍ. أَوْ إِجْرَاءِ مَاءٍ لَا تُزْرَعُ إِلَّا بِهِ. أَوْ قَطْعِ مَاءٍ لَا تُزْرَعَ مَعَهُ. أَوْ حَفْرِ بِئْرٍ."]]},{"id":"ak11_108","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ١٠٨","segs":[["matn","أَوْ غَرْسِ شَجَرٍ فِيهَا. وَمَنْ سَبَقَ إِلَى طَرِيقٍ وَاسِعٍ؛ فَهُوَ أَحَقُّ بِالْجُلُوسِ فِيهِ: مَا بَقِيَ مَتَاعُهُ. مَا لَمْ يَضُرَّ."]]},{"id":"ak11_109","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ١٠٩","segs":[["matn","فَصْلٌ: وَيَجُوزُ جَعْلُ شَيْءٍ مَعْلُومٍ، لِمَنْ يَعْمَلُ عَمَلاً وَلَوْ مَجْهُولاً؛ كَرَدِّ عَبْدٍ، وَلُقَطَةٍ، وَبِنَاءِ حَائِطٍ. فَمَنْ فَعَلَهُ بَعْدَ عِلْمِهِ: اسْتَحَقَّهُ. وَلِكُلٍّ فَسْخُهَا: فَمِنْ عَامِلٍ: لَا شَيْءَ لَهُ."]]},{"id":"ak11_110","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ١١٠","segs":[["matn","وَمِنْ جَاعِلٍ: لِعَامِلٍ أُجْرَةُ عَمَلِهِ. وَإِنْ عَمِلَ غَيْرُ مُعَدٍّ لِأَخْذِ أُجْرَةٍ لِغَيْرِهِ عَمَلاً بِلَا جُعْلٍ، أَوْ مُعَدٌّ بِلَا إِذْنٍ: فَلَا شَيْءَ لَهُ."]]},{"id":"ak11_111","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ١١١","segs":[["matn","إِلَّا: فِي تَحْصِيلِ مَتَاعٍ مِنْ بَحْرٍ أَوْ فَلَاةٍ: فَلَهُ أَجْرُ مِثْلِهِ. وَفِي رَقِيقٍ: دِينَارٌ، أَوِ اثْنَا عَشَرَ دِرْهَماً."]]},{"id":"ak11_112","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ١١٢","segs":[["matn","فَصْلٌ: وَاللُّقَطَةُ ثَلَاثَةُ أَقْسَامٍ: مَا لَا تَتْبَعُهُ هِمَّةُ أَوْسَاطِ النَّاسِ؛ كَرَغِيفٍ، وَشِسْعٍ: فَيُمْلَكُ بِلَا تَعْرِيفٍ. الثَّانِي: الضَّوَالُّ الَّتِي تَمْتَنِعُ مِنْ صِغَارِ السِّبَاعِ؛ كَخَيْلٍ، وَإِبِلٍ، وَبَقَرٍ: فَيَحْرُمُ التِقَاطُهَا. وَلَا تُمْلَكُ بِتَعْرِيفِهَا."]]},{"id":"ak11_113","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ١١٣","segs":[["matn","الثَّالِثُ: بَاقِي الْأَمْوَالِ؛ كَثَمَنٍ، وَمَتَاعٍ، وَغَنَمٍ، وَفُصْلَانٍ، وَعَجَاجِيلَ: فَلِمَنْ أَمِنَ نَفْسَهُ عَلَيْهَا: أَخْذُهَا. وَيَجِبُ حِفْظُهَا. وَتَعْرِيفُهَا فِي مَجَامِعِ النَّاسِ، غَيْرِ الْمَسَاجِدِ حَوْلاً كَامِلاً. وَتُمْلَكُ بَعْدَهُ حُكْماً."]]},{"id":"ak11_114","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ١١٤","segs":[["matn","وَيَحْرُمُ تَصَرُّفُهُ فِيهَا قَبْلَ مَعْرِفَةِ وِعَائِهَا، وَوِكَائِهَا، وَعِفَاصِهَا، وَقَدْرِهَا، وَجِنْسِهَا، وَصِفَتِهَا. وَمَتَى جَاءَ رَبُّهَا فَوَصَفَهَا: لَزِمَ دَفْعُهَا إِلَيْهِ. وَمَنْ أُخِذَ نَعْلُهُ وَنَحْوُهُ، وَوَجَدَ غَيْرَهُ مَكَانَهُ: فَلُقَطَةٌ."]]},{"id":"ak11_115","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ١١٥","segs":[["matn","وَاللَّقِيطُ: طِفْلٌ لَا يُعْرَفُ نَسَبُهُ، وَلَا رِقُّهُ؛ نُبِذَ أَوْ ضَلَّ، إِلَى التَّمْيِيزِ. وَالتِقَاطُهُ: فَرْضُ كِفَايَةٍ. فَإِنْ لَمْ يَكُنْ مَعَهُ شَيْءٌ، وَتَعَذَّرَ بَيْتُ الْمَالِ: أَنْفَقَ عَلَيْهِ عَالِمٌ بِلَا رُجُوعٍ."]]},{"id":"ak11_116","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ١١٦","segs":[["matn","وَهُوَ مُسْلِمٌ إِنْ وُجِدَ فِي بَلَدٍ يَكْثُرُ فِيهِ الْمُسْلِمُونَ. وَإِنْ أَقَرَّ بِهِ مَنْ يُمْكِنُ كَوْنُهُ مِنْهُ: أُلْحِقَ بِهِ. وَاللَّهُ أَعْلَمُ."]]},{"id":"ak11_117","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ١١٧","segs":[["matn","فَصْلٌ: وَالْوَقْفُ سُنَّةٌ. وَيَصِحُّ: بِقَوْلٍ. وَفِعْلٍ دَالٍّ عَلَيْهِ عُرْفاً؛ كَمَنْ بَنَى أَرْضَهُ مَسْجِداً أَوْ مَقْبَرَةً، وَأَذِنَ لِلنَّاسِ أَنْ يُصَلُّوا فِيهَا وَيَدْفِنُوا فِيهَا. وَصَرِيحُهُ: وَقَفْتُ، وَحَبَّسْتُ، وَسَبَّلْتُ. وَكِنَايَتُهُ: تَصَدَّقْتُ، وَحَرَّمْتُ، وَأَبَّدْتُ."]]},{"id":"ak11_118","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ١١٨","segs":[["matn","وَشُرُوطُهُ خَمْسَةٌ: كَوْنُهُ فِي عَيْنٍ، مَعْلُومَةٍ، يَصِحُّ بَيْعُهَا -غَيْرَ مُصْحَفٍ-، وَيُنْتَفَعُ بِهَا مَعَ بَقَائِهَا. وَكَوْنُهُ عَلَى بِرٍّ. وَيَصِحُّ مِنْ مُسْلِمٍ عَلَى ذِمِّيٍّ، وَعَكْسُهُ."]]},{"id":"ak11_119","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ١١٩","segs":[["matn","وَكَوْنُهُ فِي غَيْرِ مَسْجِدٍ وَنَحْوِهِ: عَلَى مُعَيَّنٍ يَمْلِكُ. وَكَوْنُ وَاقِفٍ نَافِذَ التَّصَرُّفِ. وَوَقْفُهُ نَاجِزاً. وَيَجِبُ الْعَمَلُ بِشَرْطِ وَاقِفٍ إِنْ وَافَقَ الشَّرْعَ. وَمَعَ إِطْلَاقٍ: يَسْتَوِي غَنِيٌّ وَفَقِيرٌ، وَذَكَرٌ وَأُنْثَى."]]},{"id":"ak11_120","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ١٢٠","segs":[["matn","وَالنَّظَرُ عِنْدَ عَدَمِ الشَّرْطِ: لِمَوْقُوفٍ عَلَيْهِ إِنْ كَانَ مَحْصُوراً. وَإِلَّا فَلِحَاكِمٍ، كَمَا لَوْ كَانَ عَلَى مَسْجِدٍ وَنَحْوِهِ."]]},{"id":"ak11_121","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ١٢١","segs":[["matn","وَإِنْ وَقَفَ عَلَى وَلَدِهِ، أَوْ وَلَدِ غَيْرِهِ: فَهُوَ لِذَكَرٍ وَأُنْثَى بِالسَّوِيَّةِ، ثُمَّ لِوَلَدِ بَنِيهِ. وَعَلَى بَنِيهِ، أَوْ بَنِي فُلَانٍ: فَلِذُكُورٍ فَقَطْ. وَإِنْ كَانُوا قَبِيلَةً: دَخَلَ النِّسَاءُ، دُونَ أَوْلَادِهِنَّ مِنْ غَيْرِهِمْ."]]},{"id":"ak11_122","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ١٢٢","segs":[["matn","وَعَلَى قَرَابَتِهِ، أَوْ أَهْلِ بَيْتِهِ، أَوْ قَوْمِهِ: دَخَلَ ذَكَرٌ وَأُنْثَى مِنْ أَوْلَادِهِ، وَأَوْلَادِ أَبِيهِ وَجَدِّهِ وَجَدِّ أَبِيهِ. لَا مُخَالِفُ دِينِهِ. وَإِنْ وَقَفَ عَلَى جَمَاعَةٍ: يُمْكِنُ حَصْرُهُمْ: وَجَبَ تَعْمِيمُهُمْ وَالتَّسْوِيَةُ بَيْنَهُمْ. وَإِلَّا: جَازَ التَّفْضِيلُ، وَالِاقْتِصَارُ عَلَى وَاحِدٍ."]]},{"id":"ak11_123","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ١٢٣","segs":[["matn","فَصْلٌ: وَالْهِبَةُ مُسْتَحَبَّةٌ. وَتَصِحُّ هِبَةُ: مُصْحَفٍ. وَكُلِّ مَا يَصِحُّ بَيْعُهُ. وَتَنْعَقِدُ: بِمَا يَدُلُّ عَلَيْهَا عُرْفاً. وَتَلْزَمُ: بِقَبْضٍ، بِإِذْنِ وَاهِبٍ. وَمَنْ أَبْرَأَ غَرِيمَهُ: بَرِئَ، وَلَوْ لَمْ يَقْبَلْ."]]},{"id":"ak11_124","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ١٢٤","segs":[["matn","وَيَجِبُ تَعْدِيلٌ فِي عَطِيَّةِ وَارِثٍ؛ بِأَنْ يُعْطِيَ كُلًّا بِقَدْرِ إِرْثِهِ. فَإِنْ فَضَّلَ: سَوَّى بِرُجُوعٍ. وَإِنْ مَاتَ قَبْلَهُ: ثَبَتَ تَفْضِيلُهُ. وَيَحْرُمُ عَلَى وَاهِبٍ أَنْ يَرْجِعَ فِي هِبَتِهِ بَعْدَ قَبْضٍ، وَكُرِهَ قَبْلَهُ."]]},{"id":"ak11_125","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ١٢٥","segs":[["matn","إِلَّا الْأَبَ. وَلَهُ أَنْ يَتَمَلَّكَ بِقَبْضٍ، مَعَ قَوْلٍ أَوْ نِيَّةٍ، مِنْ مَالِ وَلَدِهِ -غَيْرِ سُرِّيَّةٍ- مَا شَاءَ: مَا لَمْ يَضُرَّهُ. أَوْ لِيُعْطِيَهُ لِوَلَدٍ آخَرَ. أَوْ يَكُنْ بِمَرَضِ مَوْتِ أَحَدِهِمَا."]]},{"id":"ak11_126","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ١٢٦","segs":[["matn","أَوْ يَكُنْ كَافِراً وَالِابْنُ مُسْلِماً. وَلَيْسَ لِوَلَدٍ وَلَا لِوَرَثَتِهِ مُطَالَبَةُ أَبِيهِ بِدَيْنٍ وَنَحْوِهِ. بَلْ بِنَفَقَةٍ وَاجِبَةٍ. وَمَنْ مَرَضُهُ: غَيْرُ مَخُوفٍ: تَصَرُّفُهُ كَصَحِيحٍ."]]},{"id":"ak11_127","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ١٢٧","segs":[["matn","أَوْ مَخُوفٌ؛ كَبِرْسَامٍ، أَوْ إِسْهَالٍ مُتَدَارِكٍ، وَمَا قَالَ طَبِيبَانِ مُسْلِمَانِ عَدْلَانِ عِنْدَ إِشْكَالِهِ: إِنَّهُ مَخُوفٌ: لَا يَلْزَمُ تَبَرُّعُهُ لِوَارِثٍ بِشَيْءٍ. وَلَا بِمَا فَوْقَ الثُّلُثِ لِغَيْرِهِ، إِلَّا بِإِجَازَةِ الْوَرَثَةِ."]]},{"id":"ak11_128","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ١٢٨","segs":[["matn","وَمَنِ امْتَدَّ مَرَضُهُ بِجُذَامٍ وَنَحْوِهِ، وَلَمْ يَقْطَعْهُ بِفِرَاشٍ: فَكَصَحِيحٍ. وَيُعْتَبَرُ عِنْدَ الْمَوْتِ كَوْنُهُ وَارِثاً أَوْ لَا. وَيُبْدَأُ بِالْأَوَّلِ فَالْأَوَّلِ بِالْعَطِيَّةِ. وَلَا يَصِحُّ الرُّجُوعُ فِيهَا. وَيُعْتَبَرُ قَبُولُهَا عِنْدَ وُجُودِهَا."]]},{"id":"ak11_129","label":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ · ١٢٩","segs":[["matn","وَيَثْبُتُ الْمِلْكُ فِيهَا مِنْ حِينِهَا. وَالْوَصِيَّةُ بِخِلَافِ ذَلِكَ كُلِّهِ."]]}],"group":"كِتَابُ الْبَيْعِ وَسَائِرِ الْمُعَامَلَاتِ"},{"id":"ak12","title":"كِتَابُ الْوَصَايَا","units":[{"id":"ak12_1","label":"كِتَابُ الْوَصَايَا · ١","segs":[["matn","يُسَنُّ لِمَنْ تَرَكَ مَالاً كَثِيراً عُرْفاً: الْوَصِيَّةُ بِخُمُسِهِ. وَتَحْرُمُ: مِمَّنْ يَرِثُهُ غَيْرُ أَحَدِ الزَّوْجَيْنِ، بِأَكْثَرَ مِنَ الثُّلُثِ لِأَجْنَبِيٍّ. أَوْ لِوَارِثٍ بِشَيْءٍ. وَتَصِحُّ مَوْقُوفَةً عَلَى الْإِجَازَةِ. وَتُكْرَهُ: مِنْ فَقِيرٍ وَارِثُهُ مُحْتَاجٌ."]]},{"id":"ak12_2","label":"كِتَابُ الْوَصَايَا · ٢","segs":[["matn","فَإِنْ لَمْ يَفِ الثُّلُثُ بِالْوَصَايَا: تَحَاصُّوا فِيهِ؛ كَمَسَائِلِ الْعَوْلِ. وَتُخْرَجُ الْوَاجِبَاتُ؛ مِنْ دَيْنٍ، وَحَجٍّ، وَزَكَاةٍ: مِنْ رَأْسِ الْمَالِ مُطْلَقاً. وَتَصِحُّ: لِعَبْدِهِ بِمُشَاعٍ؛ كَثُلُثٍ، وَيَعْتِقُ مِنْهُ بِقَدْرِهِ، فَإِنْ فَضَلَ شَيْءٌ أَخَذَهُ."]]},{"id":"ak12_3","label":"كِتَابُ الْوَصَايَا · ٣","segs":[["matn","وَبِحَمْلٍ تُحُقِّقَ وُجُودُهُ. لَا لِكَنِيسَةٍ، وَبَيْتِ نَارٍ، وَكَتْبِ التَّوْرَاةِ وَالْإِنْجِيلِ، وَنَحْوِهِمَا. وَتَصِحُّ: بِمَجْهُولٍ. وَمَعْدُومٍ. وَبِمَا لَا يَقْدِرُ عَلَى تَسْلِيمِهِ. وَمَا حَدَثَ بَعْدَ الْوَصِيَّةِ: يَدْخُلُ فِيهَا. وَتَبْطُلُ: بِتَلَفِ مُعَيَّنٍ وُصِّيَ بِهِ."]]},{"id":"ak12_4","label":"كِتَابُ الْوَصَايَا · ٤","segs":[["matn","وَإِنْ وَصَّى: بِمِثْلِ نَصِيبِ وَارِثٍ مُعَيَّنٍ: فَلَهُ مِثْلُهُ مَضْمُوماً إِلَى الْمَسْأَلَةِ. وَبِمِثْلِ نَصِيبِ أَحَدِ وَرَثَتِهِ: لَهُ مِثْلُ مَا لِأَقَلِّهِمْ. وَبِسَهْمٍ مِنْ مَالِهِ: لَهُ سُدُسٌ."]]},{"id":"ak12_5","label":"كِتَابُ الْوَصَايَا · ٥","segs":[["matn","وَبِشَيْءٍ، أَوْ حَظٍّ، أَوْ جُزْءٍ: يُعْطِيهِ الْوَارِثُ مَا شَاءَ."]]},{"id":"ak12_6","label":"كِتَابُ الْوَصَايَا · ٦","segs":[["matn","فَصْلٌ: وَيَصِحُّ الْإِيصَاءُ إِلَى كُلِّ: مُسْلِمٍ. مُكَلَّفٍ. رَشِيدٍ. عَدْلٍ، وَلَوْ ظَاهِراً. وَمِنْ كَافِرٍ إِلَى: مُسْلِمٍ. وَعَدْلٍ فِي دِينِهِ. وَلَا يَصِحُّ إِلَّا: فِي مَعْلُومٍ. يَمْلِكُ الْمُوصِي فِعْلَهُ."]]},{"id":"ak12_7","label":"كِتَابُ الْوَصَايَا · ٧","segs":[["matn","وَمَنْ مَاتَ بِمَحَلٍّ لَا حَاكِمَ فِيهِ، وَلَا وَصِيَّ؛ فَلِمُسْلِمٍ: حَوْزُ تَرِكَتِهِ. وَفِعْلُ الْأَصْلَحِ فِيهَا مِنْ بَيْعٍ وَغَيْرِهِ. وَتَجْهِيزُهُ مِنْهَا، وَمَعَ عَدَمِهَا مِنْهُ."]]},{"id":"ak12_8","label":"كِتَابُ الْوَصَايَا · ٨","segs":[["matn","وَيَرْجِعُ عَلَيْهَا وَعَلَى مَنْ تَلْزَمُهُ نَفَقَتُهُ: إِنْ نَوَاهُ، أَوِ اسْتَأْذَنَ حَاكِماً."]]}],"group":"كِتَابُ الْوَصَايَا"},{"id":"ak13","title":"كِتَابُ الْفَرَائِضِ","units":[{"id":"ak13_1","label":"كِتَابُ الْفَرَائِضِ · ١","segs":[["matn","أَسْبَابُ الْإِرْثِ: رَحِمٌ. وَنِكَاحٌ. وَوَلَاءٌ. وَمَوَانِعُهُ: قَتْلٌ. وَرِقٌّ. وَاخْتِلَافُ دِينٍ. وَأَرْكَانُهُ: وَارِثٌ. وَمُوَرِّثٌ. وَمَالٌ مَوْرُوثٌ. وَشُرُوطُهُ: تَحَقُّقُ مَوْتِ مُوَرِّثٍ. وَتَحَقُّقُ وُجُودِ وَارِثٍ. وَالْعِلْمُ بِالْجِهَةِ الْمُقْتَضِيَةِ لِلْإِرْثِ. وَالْوَرَثَةُ: ذُو فَرْضٍ. وَعَصَبَةٌ."]]},{"id":"ak13_2","label":"كِتَابُ الْفَرَائِضِ · ٢","segs":[["matn","وَذُو رَحِمٍ. فَذَوُو الْفَرْضِ عَشَرَةٌ: الزَّوْجَانِ، وَالْأَبَوَانِ، وَالْجَدُّ، وَالْجَدَّةُ، وَالْبِنْتُ، وَبِنْتُ الِابْنِ، وَالْأُخْتُ، وَوَلَدُ الْأُمِّ. وَالْفُرُوضُ الْمُقَدَّرَةُ فِي كِتَابِ اللَّهِ سِتَّةٌ: النِّصْفُ، وَالرُّبُعُ، وَالثُّمُنُ، وَالثُّلُثَانِ، وَالثُّلُثُ، وَالسُّدُسُ."]]},{"id":"ak13_3","label":"كِتَابُ الْفَرَائِضِ · ٣","segs":[["matn","فَالنِّصْفُ فَرْضُ خَمْسَةٍ: الزَّوْجِ، إِنْ لَمْ يَكُنْ لِلزَّوْجَةِ وَلَدٌ، وَلَا وَلَدُ ابْنٍ. وَالْبِنْتِ. وَبِنْتِ الِابْنِ، مَعَ عَدَمِ وَلَدِ الصُّلْبِ. وَالْأُخْتِ لِأَبَوَيْنِ، عِنْدَ عَدَمِ الْوَلَدِ وَوَلَدِ الِابْنِ."]]},{"id":"ak13_4","label":"كِتَابُ الْفَرَائِضِ · ٤","segs":[["matn","وَالْأُخْتِ لِلْأَبِ عِنْدَ عَدَمِ الْأَشِقَّاءِ. وَالرُّبُعُ فَرْضُ اثْنَيْنِ: الزَّوْجِ، مَعَ الْوَلَدِ أَوْ وَلَدِ الِابْنِ. وَالزَّوْجَةِ فَأَكْثَرَ مَعَ عَدَمِهِمَا. وَالثُّمُنُ فَرْضُ وَاحِدٍ: وَهُوَ الزَّوْجَةُ فَأَكْثَرُ، مَعَ الْوَلَدِ أَوْ وَلَدِ الِابْنِ."]]},{"id":"ak13_5","label":"كِتَابُ الْفَرَائِضِ · ٥","segs":[["matn","وَالثُّلُثَانِ فَرْضُ أَرْبَعَةٍ: الْبِنْتَيْنِ فَأَكْثَرَ. وَبِنْتَيِ الِابْنِ فَأَكْثَرَ. وَالْأُخْتَيْنِ لِأَبَوَيْنِ فَأَكْثَرَ. وَالْأُخْتَيْنِ لِأَبٍ فَأَكْثَرَ. وَالثُّلُثُ فَرْضُ اثْنَيْنِ: وَلَدَيِ الْأُمِّ فَأَكْثَرَ. يَسْتَوِي فِيهِ ذَكَرُهُمْ وَأُنْثَاهُمْ."]]},{"id":"ak13_6","label":"كِتَابُ الْفَرَائِضِ · ٦","segs":[["matn","وَالْأُمِّ حَيْثُ: لَا وَلَدَ وَلَا وَلَدَ ابْنٍ، وَلَا عَدَدَ مِنَ الْإِخْوَةِ وَالْأَخَوَاتِ. لَكِنْ لَهَا ثُلُثُ الْبَاقِي فِي الْعُمَرِيَّتَيْنِ، وَهُمَا: أَبَوَانِ، وَزَوْجٌ أَوْ زَوْجَةٌ."]]},{"id":"ak13_7","label":"كِتَابُ الْفَرَائِضِ · ٧","segs":[["matn","وَالسُّدُسُ فَرْضُ سَبْعَةٍ: الْأُمِّ، مَعَ الْوَلَدِ أَوْ وَلَدِ الِابْنِ، أَوْ عَدَدٍ مِنَ الْإِخْوَةِ وَالْأَخَوَاتِ. وَالْجَدَّةِ فَأَكْثَرَ مَعَ تَحَاذٍ. وَبِنْتِ الِابْنِ فَأَكْثَرَ مَعَ بِنْتِ الصُّلْبِ. وَأُخْتٍ فَأَكْثَرَ لِأَبٍ مَعَ أُخْتٍ لِأَبَوَيْنِ."]]},{"id":"ak13_8","label":"كِتَابُ الْفَرَائِضِ · ٨","segs":[["matn","وَالْوَاحِدِ مِنْ وَلَدِ الْأُمِّ. وَالْأَبِ مَعَ الْوَلَدِ أَوْ وَلَدِ الِابْنِ. وَالْجَدِّ كَذَلِكَ. وَاللَّهُ أَعْلَمُ."]]},{"id":"ak13_9","label":"كِتَابُ الْفَرَائِضِ · ٩","segs":[["matn","فَصْلٌ: وَالْجَدُّ مَعَ الْإِخْوَةِ وَالْأَخَوَاتِ لِأَبَوَيْنِ أَوْ لِأَبٍ: كَأَحَدِهِمْ. فَإِنْ لَمْ يَكُنْ مَعَهُ صَاحِبُ فَرْضٍ: فَلَهُ خَيْرُ أَمْرَيْنِ: الْمُقَاسَمَةُ. أَوْ ثُلُثُ جَمِيعِ الْمَالِ. وَإِنْ كَانَ: فَلَهُ خَيْرُ ثَلَاثَةِ أُمُورٍ: الْمُقَاسَمَةُ."]]},{"id":"ak13_10","label":"كِتَابُ الْفَرَائِضِ · ١٠","segs":[["matn","أَوْ ثُلُثُ الْبَاقِي بَعْدَ صَاحِبِ الْفَرْضِ. أَوْ سُدُسُ جَمِيعِ الْمَالِ. فَإِنْ لَمْ يَبْقَ غَيْرُهُ: أَخَذَهُ، وَسَقَطُوا."]]},{"id":"ak13_11","label":"كِتَابُ الْفَرَائِضِ · ١١","segs":[["matn","إِلَّا فِي الْأَكْدَرِيَّةِ، وَهِيَ: زَوْجٌ وَأُمٌّ وَجَدٌّ وَأُخْتٌ لِأَبَوَيْنِ أَوْ لِأَبٍ، فَلِلزَّوْجِ نِصْفٌ، وَلِلْأُمِّ ثُلُثٌ، وَلِلْجَدِّ سُدُسٌ، وَلِلْأُخْتِ نِصْفٌ، فَتَعُولُ إِلَى تِسْعَةٍ، ثُمَّ يُقْسَمُ نَصِيبُ الْجَدِّ وَالْأُخْتِ بَيْنَهُمَا، وَهُوَ أَرْبَعَةٌ عَلَى ثَلَاثَةٍ، فَتَصِحُّ مِنْ سَبْعَةٍ وَعِشْرِينَ."]]},{"id":"ak13_12","label":"كِتَابُ الْفَرَائِضِ · ١٢","segs":[["matn","وَلَا يَعُولُ فِي مَسَائِلِ الْجَدِّ، وَلَا يُفْرَضُ لِأُخْتٍ مَعَهُ ابْتِدَاءً إِلَّا فِيهَا. وَإِذَا كَانَ مَعَ الشَّقِيقِ وَلَدُ أَبٍ: عَدَّهُ عَلَى الْجَدِّ، ثُمَّ أَخَذَ مَا حَصَلَ لَهُ."]]},{"id":"ak13_13","label":"كِتَابُ الْفَرَائِضِ · ١٣","segs":[["matn","وَتَأْخُذُ أُنْثَى لِأَبَوَيْنِ تَمَامَ فَرْضِهَا، وَالْبَقِيَّةُ لِوَلَدِ الْأَبِ."]]},{"id":"ak13_14","label":"كِتَابُ الْفَرَائِضِ · ١٤","segs":[["matn","فَصْلٌ: حَجْبُ الْحِرْمَانِ لَا يَدْخُلُ عَلَى: الزَّوْجَيْنِ، وَالْأَبَوَيْنِ، وَالْوَلَدِ. وَيَسْقُطُ: الْجَدُّ بِالْأَبِ. وَكُلُّ جَدٍّ وَابْنٍ أَبْعَدَ بِأَقْرَبَ. وَكُلُّ جَدَّةٍ بِأُمٍّ، وَالْقُرْبَى مِنْهُنَّ تَحْجُبُ الْبُعْدَى مُطْلَقاً."]]},{"id":"ak13_15","label":"كِتَابُ الْفَرَائِضِ · ١٥","segs":[["matn","لَا أَبٌ أُمَّهُ، أَوْ أُمَّ أَبِيهِ. وَلَا يَرِثُ إِلَّا ثَلَاثٌ: أُمُّ أُمٍّ. وَأُمُّ أَبٍ. وَأُمُّ أَبِي أَبٍ. وَإِنْ عَلَوْنَ أُمُومَةً. وَلِذَاتِ قَرَابَتَيْنِ مَعَ ذَاتِ قَرَابَةٍ: ثُلُثَا السُّدُسِ."]]},{"id":"ak13_16","label":"كِتَابُ الْفَرَائِضِ · ١٦","segs":[["matn","وَيَسْقُطُ: وَلَدُ الْأَبَوَيْنِ: بِابْنٍ، وَإِنْ نَزَلَ، وَأَبٍ. وَوَلَدُ الْأَبِ: بِهَؤُلَاءِ، وَأَخٍ لِأَبَوَيْنِ. وَابْنُ أَخٍ: بِهَؤُلَاءِ، وَجَدٍّ. وَوَلَدُ الْأُمِّ: بِوَلَدٍ، وَوَلَدِ ابْنٍ وَإِنْ نَزَلَ، وَأَبٍ، وَأَبِيهِ وَإِنْ عَلَا. وَمَنْ لَا يَرِثُ لِمَانِعٍ فِيهِ: لَا يَحْجُبُ."]]},{"id":"ak13_17","label":"كِتَابُ الْفَرَائِضِ · ١٧","segs":[["matn","فَصْلٌ: وَالْعَصَبَةُ: يَأْخُذُ مَا أَبْقَتِ الْفُرُوضُ. وَإِنْ لَمْ يَبْقَ شَيْءٌ: سَقَطَ مُطْلَقاً. وَإِنِ انْفَرَدَ أَخَذَ جَمِيعَ الْمَالِ. لَكِنْ لِلْجَدِّ وَالْأَبِ ثَلَاثُ حَالَاتٍ: فَيَرِثَانِ بِالتَّعْصِيبِ فَقَطْ: مَعَ عَدَمِ الْوَلَدِ وَوَلَدِ الِابْنِ."]]},{"id":"ak13_18","label":"كِتَابُ الْفَرَائِضِ · ١٨","segs":[["matn","وَبِالْفَرْضِ فَقَطْ: مَعَ ذُكُورِيَّتِهِ. وَبِالْفَرْضِ وَالتَّعْصِيبِ: مَعَ أُنُوثِيَّتِهِ. وَأُخْتٌ فَأَكْثَرُ، مَعَ بِنْتٍ أَوْ بِنْتِ ابْنٍ فَأَكْثَرَ: يَرِثْنَ مَا فَضَلَ. وَالِابْنُ. وَابْنُهُ. وَالْأَخُ لِأَبَوَيْنِ. أَوْ لِأَبٍ."]]},{"id":"ak13_19","label":"كِتَابُ الْفَرَائِضِ · ١٩","segs":[["matn","يُعَصِّبُونَ أَخَوَاتِهِمْ، فَلِذَكَرٍ مِثْلَا مَا لِأُنْثَى. وَمَتَى كَانَ الْعَاصِبُ عَمًّا، أَوِ ابْنَهُ، أَوِ ابْنَ أَخٍ: انْفَرَدَ بِالْإِرْثِ دُونَ أَخَوَاتِهِ."]]},{"id":"ak13_20","label":"كِتَابُ الْفَرَائِضِ · ٢٠","segs":[["matn","وَإِنْ عَدِمَتْ عَصَبَةُ النَّسَبِ: وَرِثَ الْمَوْلَى الْمُعْتِقُ مُطْلَقاً، ثُمَّ عَصَبَتُهُ الذُّكُورُ؛ الْأَقْرَبُ فَالْأَقْرَبُ؛ كَالنَّسَبِ."]]},{"id":"ak13_21","label":"كِتَابُ الْفَرَائِضِ · ٢١","segs":[["matn","فَصْلٌ: أُصُولُ الْمَسَائِلِ سَبْعَةٌ: أَرْبَعَةٌ لَا تَعُولُ: وَهِيَ مَا فِيهَا فَرْضٌ، أَوْ فَرْضَانِ مِنْ نَوْعٍ. فَنِصْفَانِ، أَوْ نِصْفٌ وَالْبَقِيَّةُ: مِنِ اثْنَيْنِ. وَثُلُثَانِ، أَوْ ثُلُثٌ وَالْبَقِيَّةُ: مِنْ ثَلَاثَةٍ."]]},{"id":"ak13_22","label":"كِتَابُ الْفَرَائِضِ · ٢٢","segs":[["matn","وَرُبُعٌ وَالْبَقِيَّةُ أَوْ مَعَ النِّصْفِ: مِنْ أَرْبَعَةٍ. وَثُمُنٌ وَالْبَقِيَّةُ أَوْ مَعَ النِّصْفِ: مِنْ ثَمَانِيَةٍ. وَثَلَاثَةٌ تَعُولُ: وَهِيَ مَا فَرْضُهَا نَوْعَانِ فَأَكْثَرُ."]]},{"id":"ak13_23","label":"كِتَابُ الْفَرَائِضِ · ٢٣","segs":[["matn","فَنِصْفٌ مَعَ ثُلُثَيْنِ، أَوْ ثُلُثٍ، أَوْ سُدُسٍ: مِنْ سِتَّةٍ، وَتَعُولُ إِلَى عَشَرَةٍ، شَفْعاً وَوِتْراً. وَرُبُعٌ مَعَ ثُلُثَيْنِ، أَوْ ثُلُثٍ، أَوْ سُدُسٍ: مِنِ اثْنَيْ عَشَرَ، وَتَعُولُ إِلَى سَبْعَةَ عَشَرَ وِتْراً."]]},{"id":"ak13_24","label":"كِتَابُ الْفَرَائِضِ · ٢٤","segs":[["matn","وَثُمُنٌ مَعَ سُدُسٍ، أَوْ ثُلُثَيْنِ، أَوْ هُمَا: مِنْ أَرْبَعَةٍ وَعِشْرِينَ، وَتَعُولُ مَرَّةً وَاحِدَةً إِلَى سَبْعَةٍ وَعِشْرِينَ. وَإِنْ فَضَلَ عَنِ الْفَرْضِ شَيْءٌ، وَلَا عَصَبَةَ: رُدَّ عَلَى كُلٍّ بِقَدْرِ فَرْضِهِ."]]},{"id":"ak13_25","label":"كِتَابُ الْفَرَائِضِ · ٢٥","segs":[["matn","مَا عَدَا الزَّوْجَيْنِ. وَإِذَا كَانَتِ التَّرِكَةُ مَعْلُومَةً: وَأَمْكَنَ نِسْبَةُ سَهْمِ كُلِّ وَارِثٍ مِنَ الْمَسْأَلَةِ: فَلَهُ مِنَ التَّرِكَةِ مِثْلُ نِسْبَتِهِ."]]},{"id":"ak13_26","label":"كِتَابُ الْفَرَائِضِ · ٢٦","segs":[["matn","وَإِنْ شِئْتَ ضَرَبْتَ سِهَامَهُ فِي التَّرِكَةِ، وَقَسَمْتَ الْحَاصِلَ عَلَى الْمَسْأَلَةِ، فَمَا خَرَجَ فَنَصِيبُهُ. وَإِنْ شِئْتَ قَسَمْتَهُ عَلَى غَيْرِ ذَلِكَ مِنَ الطُّرُقِ."]]},{"id":"ak13_27","label":"كِتَابُ الْفَرَائِضِ · ٢٧","segs":[["matn","فَصْلٌ: فِي ذَوِي الْأَرْحَامِ، وَهُمْ أَحَدَ عَشَرَ صِنْفاً: وَلَدُ الْبَنَاتِ لِصُلْبٍ أَوْ لِابْنٍ. وَوَلَدُ الْأَخَوَاتِ. وَبَنَاتُ الْإِخْوَةِ. وَبَنَاتُ الْأَعْمَامِ. وَوَلَدُ وَلَدِ الْأُمِّ. وَالْعَمُّ لِأُمٍّ. وَالْأَخْوَالُ، وَالْخَالَاتُ. وَأَبُو الْأُمِّ."]]},{"id":"ak13_28","label":"كِتَابُ الْفَرَائِضِ · ٢٨","segs":[["matn","وَكُلُّ جَدَّةٍ أَدْلَتْ بِأَبٍ بَيْنَ أُمَّيْنِ، أَوْ أَبٍ أَعْلَى مِنَ الْجَدِّ. وَمَنْ أَدْلَى بِهِمْ. وَإِنَّمَا يَرِثُونَ: إِذَا لَمْ يَكُنْ صَاحِبُ فَرْضٍ. وَلَا عَصَبَةٌ. بِتَنْزِيلِهِمْ مَنْزِلَةَ مَنْ أَدْلَوْا بِهِ. وَذَكَرُهُمْ كَأُنْثَاهُمْ."]]},{"id":"ak13_29","label":"كِتَابُ الْفَرَائِضِ · ٢٩","segs":[["matn","وَلِزَوْجٍ أَوْ زَوْجَةٍ مَعَهُمْ: فَرْضُهُ بِلَا حَجْبٍ وَلَا عَوْلٍ، وَالْبَاقِي لَهُمْ. وَاللَّهُ أَعْلَمُ."]]},{"id":"ak13_30","label":"كِتَابُ الْفَرَائِضِ · ٣٠","segs":[["matn","فَصْلٌ: وَالْحَمْلُ يَرِثُ وَيُورَثُ. إِنِ اسْتَهَلَّ صَارِخاً، أَوْ وُجِدَ دَلِيلُ حَيَاتِهِ، سِوَى حَرَكَةٍ أَوْ تَنَفُّسٍ يَسِيرَيْنِ، أَوِ اخْتِلَاجٍ. وَإِنْ طَلَبَ وَرَثَةٌ الْقِسْمَةَ: وُقِفَ لَهُ الْأَكْثَرُ مِنْ إِرْثِ ذَكَرَيْنِ أَوْ أُنْثَيَيْنِ."]]},{"id":"ak13_31","label":"كِتَابُ الْفَرَائِضِ · ٣١","segs":[["matn","وَيُدْفَعُ لِمَنْ لَا يَحْجُبُهُ إِرْثُهُ كَامِلاً. وَلِمَنْ يَنْقُصُهُ الْيَقِينُ. فَإِذَا وُلِدَ: أَخَذَ نَصِيبَهُ، وَرُدَّ مَا بَقِيَ. وَإِنْ أَعْوَزَ شَيْئاً: رَجَعَ."]]},{"id":"ak13_32","label":"كِتَابُ الْفَرَائِضِ · ٣٢","segs":[["matn","وَمَنْ قَتَلَ مُوَرِّثَهُ، وَلَوْ بِمُشَارَكَةٍ، أَوْ سَبَبٍ: لَمْ يَرِثْهُ إِنْ لَزِمَهُ قَوَدٌ، أَوْ دِيَةٌ، أَوْ كَفَّارَةٌ. وَلَا يَرِثُ رَقِيقٌ، وَلَا يُورَثُ. وَيَرِثُ مُبَعَّضٌ، وَيُورَثُ، وَيَحْجُبُ: بِقَدْرِ حُرِّيَّتِهِ."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"ak14","title":"كِتَابُ الْعِتْقِ","units":[{"id":"ak14_1","label":"كِتَابُ الْعِتْقِ · ١","segs":[["matn","يُسَنُّ: عِتْقُ مَنْ لَهُ كَسْبٌ. وَيُكْرَهُ: لِمَنْ لَا قُوَّةَ لَهُ وَلَا كَسْبَ. وَلَا تَصِحُّ الْوَصِيَّةُ بِهِ، بَلْ تَعْلِيقُهُ بِالْمَوْتِ ، وَهُوَ التَّدْبِيرُ. وَيُعْتَبَرُ مِنَ الثُّلُثِ."]]},{"id":"ak14_2","label":"كِتَابُ الْعِتْقِ · ٢","segs":[["matn","وَتُسَنُّ كِتَابَةُ: مَنْ عَلِمَ فِيهِ خَيْراً، وَهُوَ الْكَسْبُ وَالْأَمَانَةُ. وَتُكْرَهُ: لِمَنْ لَا كَسْبَ لَهُ. وَيَجُوزُ بَيْعُ الْمُكَاتَبِ. وَمُشْتَرِيهِ يَقُومُ مَقَامَ مُكَاتِبِهِ. فَإِنْ أَدَّى: عَتَقَ، وَوَلَاؤُهُ لِمُنْتَقَلٍ إِلَيْهِ."]]},{"id":"ak14_3","label":"كِتَابُ الْعِتْقِ · ٣","segs":[["matn","وَأُمُّ الْوَلَدِ: تَعْتِقُ بِمَوْتِ سَيِّدِهَا مِنْ كُلِّ مَالِهِ."]]},{"id":"ak14_4","label":"كِتَابُ الْعِتْقِ · ٤","segs":[["matn","وَهِيَ: مَنْ وَلَدَتْ مَا فِيهِ صُورَةٌ وَلَوْ خَفِيَّةً، مِنْ مَالِكٍ وَلَوْ بَعْضَهَا، أَوْ مُحَرَّمَةً عَلَيْهِ، أَوْ مِنْ أَبِيهِ، إِنْ لَمْ يَكُنْ وَطِئَهَا الِابْنُ. وَأَحْكَامُهَا: كَأَمَةٍ."]]},{"id":"ak14_5","label":"كِتَابُ الْعِتْقِ · ٥","segs":[["matn","إِلَّا فِيمَا يَنْقُلُ الْمِلْكَ فِي رَقَبَتِهَا، أَوْ يُرَادُ لَهُ. وَمَنْ أَعْتَقَ رَقَبَةً، أَوْ عَتَقَتْ عَلَيْهِ: فَلَهُ عَلَيْهَا الْوَلَاءُ. وَهُوَ: أَنَّهُ يَصِيرُ عَصَبَةً لَهَا مُطْلَقاً عِنْدَ عَدَمِ عَصَبَةِ النَّسَبِ."]]}],"group":"كِتَابُ الْعِتْقِ"},{"id":"ak15","title":"كِتَابُ النِّكَاحِ","units":[{"id":"ak15_1","label":"كِتَابُ النِّكَاحِ · ١","segs":[["matn","يُسَنُّ: مَعَ شَهْوَةٍ لِمَنْ لَمْ يَخَفِ الزِّنَى. وَيَجِبُ: عَلَى مَنْ يَخَافُهُ. وَيُسَنُّ نِكَاحُ: وَاحِدَةٍ. حَسِيبَةٍ. دَيِّنَةٍ. أَجْنَبِيَّةٍ. بِكْرٍ. وَلُودٍ."]]},{"id":"ak15_2","label":"كِتَابُ النِّكَاحِ · ٢","segs":[["matn","وَلِمُرِيدِ خِطْبَةِ امْرَأَةٍ مَعَ ظَنِّ إِجَابَةٍ: نَظَرٌ إِلَى مَا يَظْهَرُ مِنْهَا غَالِباً. بِلَا خَلْوَةٍ. إِنْ أَمِنَ الشَّهْوَةَ. وَلَهُ نَظَرُ ذَلِكَ، وَرَأْسٍ، وَسَاقٍ، مِنْ: ذَوَاتِ مَحَارِمِهِ. وَمِنْ أَمَةٍ."]]},{"id":"ak15_3","label":"كِتَابُ النِّكَاحِ · ٣","segs":[["matn","وَحَرُمَ: تَصْرِيحٌ بِخِطْبَةِ مُعْتَدَّةٍ عَلَى غَيْرِ زَوْجٍ تَحِلُّ لَهُ. وَتَعْرِيضٌ بِخِطْبَةِ رَجْعِيَّةٍ. وَخِطْبَةٌ عَلَى خِطْبَةِ مُسْلِمٍ أُجِيبَ. وَسُنَّ عَقْدُهُ: يَوْمَ الْجُمُعَةِ. مَسَاءً. بَعْدَ خُطْبَةِ ابْنِ مَسْعُودٍ."]]},{"id":"ak15_4","label":"كِتَابُ النِّكَاحِ · ٤","segs":[["matn","فَصْلٌ: أَرْكَانُهُ: الزَّوْجَانِ الْخَالِيَانِ عَنِ الْمَوَانِعِ. وَإِيجَابٌ بِلَفْظِ: \"أَنَكَحْتُ\"، أَوْ \"زَوَّجْتُ\"، وَقَبُولٌ بِلَفْظِ: \"قَبِلْتُ\"، أَوْ \"رَضِيتُ\" فَقَطْ، أَوْ مَعَ \"هَذَا النِّكَاحِ\"، أَوْ \"تَزَوَّجْتُهَا\"."]]},{"id":"ak15_5","label":"كِتَابُ النِّكَاحِ · ٥","segs":[["matn","وَمَنْ جَهِلَهَا: لَمْ يَلْزَمْهُ تَعَلُّمٌ، وَكَفَاهُ مَعْنَاهَا الْخَاصُّ بِكُلِّ لِسَانٍ. وَشُرُوطُهُ أَرْبَعَةٌ: تَعْيِينُ الزَّوْجَيْنِ. وَرِضَاهُمَا. لَكِنْ لِأَبٍ وَوَصِيِّهِ فِي نِكَاحٍ تَزْوِيجُ: صَغِيرٍ. وَبَالِغٍ مَعْتُوهٍ. وَمَجْنُونَةٍ. وَثَيِّبٍ لَهَا دُونَ تِسْعٍ."]]},{"id":"ak15_6","label":"كِتَابُ النِّكَاحِ · ٦","segs":[["matn","وَبِكْرٍ مُطْلَقاً. كَسَيِّدٍ مَعَ إِمَائِهِ وَعَبْدِهِ الصَّغِيرِ. فَلَا يُزَوِّجُ بَاقِي الْأَوْلِيَاءِ: صَغِيرَةً بِحَالٍ. وَلَا بِنْتَ تِسْعٍ إِلَّا بِإِذْنِهَا. وَهُوَ: صُمَاتُ بِكْرٍ، وَنُطْقُ ثَيِّبٍ. وَالْوَلِيُّ. وَشُرُوطُهُ: تَكْلِيفٌ. وَذُكُورَةٌ. وَحُرِّيَّةٌ. وَرُشْدٌ."]]},{"id":"ak15_7","label":"كِتَابُ النِّكَاحِ · ٧","segs":[["matn","وَاتِّفَاقُ دِينٍ. وَعَدَالَةٌ وَلَوْ ظَاهِراً. إِلَّا فِي سُلْطَانٍ، وَسَيِّدٍ. وَيُقَدَّمُ وُجُوباً: أَبٌ. ثُمَّ وَصِيُّهُ فِيهِ. ثُمَّ جَدٌّ لِأَبٍ وَإِنْ عَلَا. ثُمَّ ابْنٌ وَإِنْ نَزَلَ. وَهَكَذَا عَلَى تَرْتِيبِ الْمِيرَاثِ."]]},{"id":"ak15_8","label":"كِتَابُ النِّكَاحِ · ٨","segs":[["matn","ثُمَّ الْمَوْلَى الْمُنْعِمُ. ثُمَّ أَقْرَبُ عَصَبَتِهِ نَسَباً. ثُمَّ وَلَاءً. ثُمَّ السُّلْطَانُ. فَإِنْ: عَضَلَ الْأَقْرَبُ. أَوْ لَمْ يَكُنْ أَهْلاً. أَوْ كَانَ مُسَافِراً فَوْقَ مَسَافَةِ قَصْرٍ. زَوَّجَ حُرَّةً: أَبْعَدُ، وَأَمَةً: حَاكِمٌ."]]},{"id":"ak15_9","label":"كِتَابُ النِّكَاحِ · ٩","segs":[["matn","وَشَهَادَةُ: رَجُلَيْنِ. مُكَلَّفَيْنِ. عَدْلَيْنِ، وَلَوْ ظَاهِراً. سَمِيعَيْنِ. نَاطِقَيْنِ. وَالْكَفَاءَةُ شَرْطٌ لِلُزُومِهِ، فَيَحْرُمُ تَزْوِيجُهَا بِغَيْرِهِ إِلَّا بِرِضَاهَا."]]},{"id":"ak15_10","label":"كِتَابُ النِّكَاحِ · ١٠","segs":[["matn","فَصْلٌ: وَيَحْرُمُ أَبَداً: أُمٌّ، وَجَدَّةٌ وَإِنْ عَلَتْ. وَبِنْتٌ، وَبِنْتُ وَلَدٍ وَإِنْ سَفَلَتْ. وَأُخْتٌ مُطْلَقاً. وَبِنْتُهَا، وَبِنْتُ وَلَدِهَا وَإِنْ سَفَلَتْ. وَبِنْتُ كُلِّ أَخٍ، وَبِنْتُهَا، وَبِنْتُ وَلَدِهَا وَإِنْ سَفَلَتْ. وَعَمَّةٌ، وَخَالَةٌ مُطْلَقاً."]]},{"id":"ak15_11","label":"كِتَابُ النِّكَاحِ · ١١","segs":[["matn","وَيَحْرُمُ بِرَضَاعٍ مَا يَحْرُمُ بِنَسَبٍ. وَيَحْرُمُ: بِعَقْدٍ: حَلَائِلُ عَمُودَيْ نَسَبِهِ. وَأُمَّهَاتُ زَوْجَتِهِ وَإِنْ عَلَوْنَ. وَبِدُخُولٍ: رَبِيبَةٌ، وَبِنْتُهَا، وَبِنْتُ وَلَدِهَا وَإِنْ سَفَلَتْ. وَإِلَى أَمَدٍ: أُخْتُ مُعْتَدَّتِهِ أَوْ زَوْجَتِهِ."]]},{"id":"ak15_12","label":"كِتَابُ النِّكَاحِ · ١٢","segs":[["matn","وَزَانِيَةٌ حَتَّى تَتُوبَ وَتَنْقَضِيَ عِدَّتُهَا. وَمُطَلَّقَتُهُ ثَلَاثاً حَتَّى يَطَأَهَا زَوْجٌ غَيْرُهُ، بِشَرْطِهِ. وَمُسْلِمَةٌ عَلَى كَافِرٍ. وَكَافِرَةٌ عَلَى مُسْلِمٍ، إِلَّا حُرَّةً كِتَابِيَّةً."]]},{"id":"ak15_13","label":"كِتَابُ النِّكَاحِ · ١٣","segs":[["matn","وَعَلَى حُرٍّ مُسْلِمٍ: أَمَةٌ مُسْلِمَةٌ، مَا لَمْ: يَخَفْ عَنَتَ عُزُوبَةٍ لِحَاجَةِ مُتْعَةٍ أَوْ خِدْمَةٍ. وَيَعْجِزْ عَنْ طَوْلِ حُرَّةٍ، أَوْ ثَمَنِ أَمَةٍ. وَعَلَى عَبْدٍ: سَيِّدَتُهُ. وَعَلَى سَيِّدٍ: أَمَتُهُ، وَأَمَةُ وَلَدِهِ."]]},{"id":"ak15_14","label":"كِتَابُ النِّكَاحِ · ١٤","segs":[["matn","وَعَلَى حُرَّةٍ: قِنُّ وَلَدِهَا. وَمَنْ حَرُمَ وَطْؤُهَا بِعَقْدٍ؛ حَرُمَ بِمِلْكِ يَمِينٍ، إِلَّا أَمَةً كِتَابِيَّةً."]]},{"id":"ak15_15","label":"كِتَابُ النِّكَاحِ · ١٥","segs":[["matn","فَصْلٌ: وَالشُّرُوطُ فِي النِّكَاحِ نَوْعَانِ: صَحِيحٌ: كَشَرْطِ زِيَادَةٍ فِي مَهْرِهَا. فَإِنْ لَمْ يَفِ بِذَلِكَ: فَلَهَا الْفَسْخُ. وَفَاسِدٌ: يُبْطِلُ الْعَقْدَ، وَهُوَ أَرْبَعَةُ أَشْيَاءَ: نِكَاحُ الشِّغَارِ. وَالْمُحَلِّلِ. وَالْمُتْعَةِ."]]},{"id":"ak15_16","label":"كِتَابُ النِّكَاحِ · ١٦","segs":[["matn","وَالْمُعَلَّقُ عَلَى شَرْطٍ غَيْرِ مَشِيئَةِ اللَّهِ تَعَالَى. وَفَاسِدٌ لَا يُبْطِلُهُ؛ كَشَرْطِ: أَنْ لَا مَهْرَ. أَوْ لَا نَفَقَةَ. أَوْ أَنْ يُقِيمَ عِنْدَهَا أَكْثَرَ مِنْ ضَرَّتِهَا، أَوْ أَقَلَّ."]]},{"id":"ak15_17","label":"كِتَابُ النِّكَاحِ · ١٧","segs":[["matn","وَإِنْ شُرِطَ نَفْيُ عَيْبٍ لَا يُفْسَخُ بِهِ النِّكَاحُ، فَوُجِدَ بِهَا: فَلَهُ الْفَسْخُ."]]},{"id":"ak15_18","label":"كِتَابُ النِّكَاحِ · ١٨","segs":[["matn","فَصْلٌ: وَعَيْبُ نِكَاحٍ ثَلَاثَةُ أَنْوَاعٍ: نَوْعٌ مُخْتَصٌّ بِالرَّجُلِ؛ كَجَبٍّ، وَعُنَّةٍ. وَنَوْعٌ مُخْتَصٌّ بِالْمَرْأَةِ؛ كَسَدِّ فَرْجٍ، وَرَتَقٍ. وَنَوْعٌ مُشْتَرَكٌ بَيْنَهُمَا؛ كَجُنُونٍ، وَجُذَامٍ. فَيُفْسَخُ بِكُلٍّ مِنْ ذَلِكَ، وَلَوْ حَدَثَ بَعْدَ دُخُولٍ."]]},{"id":"ak15_19","label":"كِتَابُ النِّكَاحِ · ١٩","segs":[["matn","لَا بِنَحْوِ عَمًى، أَوْ طَرَشٍ، وَقَطْعِ يَدٍ أَوْ رِجْلٍ، إِلَّا بِشَرْطٍ. وَمَنْ ثَبَتَتْ عُنَّتُهُ: أُجِّلَ سَنَةً مِنْ حِينِ تَرْفَعُهُ إِلَى الْحَاكِمِ. فَإِنْ لَمْ يَطَأْ فِيهَا: فَلَهَا الْفَسْخُ."]]},{"id":"ak15_20","label":"كِتَابُ النِّكَاحِ · ٢٠","segs":[["matn","وَخِيَارُ عَيْبٍ عَلَى التَّرَاخِي، لَكِنْ يَسْقُطُ بِمَا يَدُلُّ عَلَى الرِّضَا. لَا فِي عُنَّةٍ إِلَّا بِقَوْلٍ. وَلَا فَسْخَ إِلَّا بِحَاكِمٍ. فَإِنْ فُسِخَ: قَبْلَ دُخُولٍ: فَلَا مَهْرَ."]]},{"id":"ak15_21","label":"كِتَابُ النِّكَاحِ · ٢١","segs":[["matn","وَبَعْدَهُ: لَهَا الْمُسَمَّى، يَرْجِعُ بِهِ عَلَى مُغِرٍّ. وَيُقَرُّ الْكُفَّارُ عَلَى نِكَاحٍ فَاسِدٍ إِنِ اعْتَقَدُوا صِحَّتَهُ. وَإِنْ أَسْلَمَ الزَّوْجَانِ وَالْمَرْأَةُ تُبَاحُ إِذاً: أُقِرَّا."]]}],"group":"كِتَابُ النِّكَاحِ"},{"id":"ak16","title":"بَابُ الصَّدَاقِ","units":[{"id":"ak16_1","label":"بَابُ الصَّدَاقِ · ١","segs":[["matn","يُسَنُّ: تَسْمِيَتُهُ فِي الْعَقْدِ. وَتَخْفِيفُهُ. وَكُلُّ مَا صَحَّ ثَمَناً أَوْ أُجْرَةً: صَحَّ مَهْراً. فَإِنْ لَمْ يُسَمَّ، أَوْ بَطَلَتِ التَّسْمِيَةُ: وَجَبَ مَهْرُ مِثْلٍ بِعَقْدٍ."]]},{"id":"ak16_2","label":"بَابُ الصَّدَاقِ · ٢","segs":[["matn","وَإِنْ تَزَوَّجَهَا عَلَى أَلْفٍ لَهَا وَأَلْفٍ لِأَبِيهَا: صَحَّ. فَلَوْ طَلَّقَ قَبْلَ دُخُولٍ: رَجَعَ بِأَلْفِهَا، وَلَا شَيْءَ عَلَى الْأَبِ لَهُمَا. وَإِنْ شُرِطَ لِغَيْرِ الْأَبِ شَيْءٌ: فَالْكُلُّ لَهَا. وَيَصِحُّ تَأْجِيلُهُ."]]},{"id":"ak16_3","label":"بَابُ الصَّدَاقِ · ٣","segs":[["matn","وَإِنْ أُطْلِقَ الْأَجَلُ: فَمَحَلُّهُ الْفُرْقَةُ. وَتَمْلِكُهُ بِعَقْدٍ. وَيَصِحُّ تَفْوِيضُ بُضْعٍ: بِأَنْ يُزَوِّجَ أَبٌ ابْنَتَهُ الْمُجْبَرَةَ، أَوْ وَلِيُّ غَيْرِهَا بِإِذْنِهَا بِلَا مَهْرٍ؛ كَعَلَى مَا شَاءَتْ، أَوْ شَاءَ فُلَانٌ."]]},{"id":"ak16_4","label":"بَابُ الصَّدَاقِ · ٤","segs":[["matn","وَيَجِبُ لَهَا بِعَقْدٍ: مَهْرُ مِثْلٍ. وَيَسْتَقِرُّ بِدُخُولٍ. وَإِنْ مَاتَ أَحَدُهُمَا قَبْلَ دُخُولٍ وَفَرْضٍ: وَرِثَهُ الْآخَرُ. وَلَهَا مَهْرُ نِسَائِهَا؛ كَأُمِّهَا، وَعَمَّتِهَا، وَخَالَتِهَا. وَإِنْ طُلِّقَتْ قَبْلَهُمَا: لَمْ يَكُنْ لَهَا عَلَيْهِ إِلَّا الْمُتْعَةُ."]]},{"id":"ak16_5","label":"بَابُ الصَّدَاقِ · ٥","segs":[["matn","وَهِيَ: بِقَدْرِ يُسْرِهِ وَعُسْرِهِ. وَيَجِبُ مَهْرُ مِثْلٍ لِمَنْ وُطِئَتْ بِشُبْهَةٍ، أَوْ زِنىً كُرْهاً. لَا أَرْشُ بَكَارَةٍ مَعَهُ. وَلَهَا مَنْعُ نَفْسِهَا حَتَّى تَقْبِضَ مَهْراً حَالًّا. لَا: إِذَا حَلَّ قَبْلَ تَسْلِيمٍ."]]},{"id":"ak16_6","label":"بَابُ الصَّدَاقِ · ٦","segs":[["matn","أَوْ تَبَرَّعَتْ بِتَسْلِيمِ نَفْسِهَا. وَإِنْ أَعْسَرَ بِحَالٍّ: فَلَهَا الْفَسْخُ بِحَاكِمٍ. وَيُقَرِّرُ الْمُسَمَّى كُلَّهُ: مَوْتٌ. وَقَتْلٌ. وَوَطْءٌ فِي فَرْجٍ، وَلَوْ دُبُراً. وَخَلْوَةٌ: عَنْ مُمَيِّزٍ. مِمَّنْ يَطَأُ مِثْلُهُ. مَعَ عِلْمِهِ."]]},{"id":"ak16_7","label":"بَابُ الصَّدَاقِ · ٧","segs":[["matn","إِنْ لَمْ تَمْنَعْهُ. وَطَلَاقٌ فِي مَرَضِ مَوْتِ أَحَدِهِمَا. وَلَمْسٌ أَوْ نَظَرٌ إِلَى فَرْجِهَا بِشَهْوَةٍ فِيهِمَا، وَتَقْبِيلُهَا. وَيُنَصِّفُهُ: كُلُّ فُرْقَةٍ مِنْ قِبَلِهِ قَبْلَ دُخُولٍ. وَمِنْ قِبَلِهَا قَبْلَهُ: تُسْقِطُهُ."]]},{"id":"ak16_8","label":"بَابُ الصَّدَاقِ · ٨","segs":[["matn","فَصْلٌ: وَتُسَنُّ الْوَلِيمَةُ لِلْعُرْسِ، وَلَوْ بِشَاةٍ فَأَقَلَّ. وَتَجِبُ الْإِجَابَةُ إِلَيْهَا بِشَرْطِهِ. وَتُسَنُّ: لِكُلِّ دَعْوَةٍ مُبَاحَةٍ. وَتُكْرَهُ: لِمَنْ فِي مَالِهِ حَرَامٌ؛ كَأَكْلٍ مِنْهُ، وَمُعَامَلَتِهِ، وَقَبُولِ هَدِيَّتِهِ، وَهِبَتِهِ. وَيُسَنُّ الْأَكْلُ."]]},{"id":"ak16_9","label":"بَابُ الصَّدَاقِ · ٩","segs":[["matn","وَإِبَاحَتُهُ تَتَوَقَّفُ عَلَى: صَرِيحِ إِذْنٍ، أَوْ قَرِينَةٍ مُطْلَقاً. وَالصَّائِمُ: فَرْضاً: يَدْعُو. وَنَفْلاً: يُسَنُّ أَكْلُهُ مَعَ جَبْرِ خَاطِرٍ. وَسُنَّ: إِعْلَانُ نِكَاحٍ. وَضَرْبٌ بِدُفٍّ مُبَاحٍ: فِيهِ، وَفِي خِتَانٍ، وَنَحْوِهِ."]]},{"id":"ak16_10","label":"بَابُ الصَّدَاقِ · ١٠","segs":[["matn","فَصْلٌ: وَيَلْزَمُ كُلًّا مِنَ الزَّوْجَيْنِ: مُعَاشَرَةُ الْآخَرِ بِالْمَعْرُوفِ. وَأَلَّا يَمْطُلَهُ بِمَا يَلْزَمُهُ. وَلَا يَتَكَرَّهَ لِبَذْلِهِ. وَيَجِبُ بِعَقْدٍ تَسْلِيمُ حُرَّةٍ: يُوطَأُ مِثْلُهَا. فِي بَيْتِ زَوْجٍ، إِنْ طَلَبَهَا، وَلَمْ تَكُنْ شَرَطَتْ دَارَهَا."]]},{"id":"ak16_11","label":"بَابُ الصَّدَاقِ · ١١","segs":[["matn","وَمَنِ اسْتَمْهَلَ: أُمْهِلَ الْيَوْمَيْنِ وَالثَّلَاثَةَ. لَا لِعَمَلِ جَهَازٍ. وَتَسْلِيمُ أَمَةٍ: لَيْلاً فَقَطْ. وَلِزَوْجٍ: اسْتِمْتَاعٌ بِزَوْجَةٍ، كُلَّ وَقْتٍ، مَا لَمْ يَضُرَّهَا، أَوْ يَشْغَلْهَا عَنْ فَرْضٍ."]]},{"id":"ak16_12","label":"بَابُ الصَّدَاقِ · ١٢","segs":[["matn","وَالسَّفَرُ بِحُرَّةٍ، مَا لَمْ تَكُنْ شَرَطَتْ بَلَدَهَا. وَلَهُ إِجْبَارُهَا عَلَى: غُسْلِ حَيْضٍ. وَجَنَابَةٍ. وَنَجَاسَةٍ. وَأَخْذِ مَا تَعَافُهُ النَّفْسُ مِنْ شَعَرٍ وَغَيْرِهِ. وَيَلْزَمُهُ: الْوَطْءُ فِي كُلِّ أَرْبَعَةِ أَشْهُرٍ مَرَّةً إِنْ قَدَرَ."]]},{"id":"ak16_13","label":"بَابُ الصَّدَاقِ · ١٣","segs":[["matn","وَمَبِيتٌ بِطَلَبٍ عِنْدَ حُرَّةٍ: لَيْلَةً مِنْ كُلِّ أَرْبَعٍ، وَأَمَةٍ: مِنْ كُلِّ سَبْعٍ. وَإِنْ سَافَرَ فَوْقَ نِصْفِ سَنَةٍ وَطَلَبَتْ قُدُومَهُ: رَاسَلَهُ حَاكِمٌ. فَإِنْ أَبَى بِلَا عُذْرٍ: فُرِّقَ بَيْنَهُمَا بِطَلَبِهَا."]]},{"id":"ak16_14","label":"بَابُ الصَّدَاقِ · ١٤","segs":[["matn","وَإِنْ لَمْ يُعْلَمْ خَبَرُهُ: فَلَا فَسْخَ لِذَلِكَ بِحَالٍ. وَحَرُمَ جَمْعُ زَوْجَتَيْهِ بِمَسْكَنٍ وَاحِدٍ مَا لَمْ يَرْضَيَا. وَلَهُ مَنْعُهَا مِنَ الْخُرُوجِ. وَعَلَى غَيْرِ طِفْلٍ: التَّسْوِيَةُ بَيْنَ زَوْجَاتٍ فِي الْقَسْمِ."]]},{"id":"ak16_15","label":"بَابُ الصَّدَاقِ · ١٥","segs":[["matn","لَا فِي وَطْءٍ، وَكِسْوَةٍ، وَنَحْوِهِمَا إِذَا قَامَ بِالْوَاجِبِ. وَعِمَادُهُ: اللَّيْلُ، إِلَّا فِي حَارِسٍ وَنَحْوِهِ: فَالنَّهَارُ. وَزَوْجَةٌ أَمَةٌ عَلَى النِّصْفِ مِنْ حُرَّةٍ. وَمُبَعَّضَةٌ بِالْحِسَابِ. وَإِنْ: أَبَتِ الْمَبِيتَ مَعَهُ. أَوِ السَّفَرَ."]]},{"id":"ak16_16","label":"بَابُ الصَّدَاقِ · ١٦","segs":[["matn","أَوْ سَافَرَتْ فِي حَاجَتِهَا. سَقَطَ قَسْمُهَا وَنَفَقَتُهَا. وَإِنْ تَزَوَّجَ بِكْرًا: أَقَامَ عِنْدَهَا سَبْعًا، أَوْ ثَيِّبًا: أَقَامَ ثَلَاثًا، ثُمَّ دَارَ. وَالنُّشُوزُ حَرَامٌ. وَهُوَ: مَعْصِيَتُهَا إِيَّاهُ فِيمَا يَجِبُ عَلَيْهَا."]]},{"id":"ak16_17","label":"بَابُ الصَّدَاقِ · ١٧","segs":[["matn","فَمَتَى ظَهَرَتْ أَمَارَتُهُ: وَعَظَهَا. فَإِنْ أَصَرَّتْ: هَجَرَهَا فِي الْمَضْجَعِ مَا شَاءَ، وَفِي الْكَلَامِ ثَلَاثاً. فَإِنْ أَصَرَّتْ: ضَرَبَهَا غَيْرَ شَدِيدٍ. وَلَهُ ضَرْبُهَا عَلَى تَرْكِ فَرَائِضِ اللَّهِ تَعَالَى."]]}],"group":"كِتَابُ النِّكَاحِ"},{"id":"ak17","title":"بَابُ الْخُلْعِ","units":[{"id":"ak17_1","label":"بَابُ الْخُلْعِ · ١","segs":[["matn","يُبَاحُ: لِسُوءِ عِشْرَةٍ، وَبُغْضَةٍ، وَكِبَرٍ، وَقِلَّةِ دِينٍ. وَيُكْرَهُ: مَعَ اسْتِقَامَةٍ. وَهُوَ بِلَفْظِ خُلْعٍ، أَوْ فَسْخٍ، أَوْ مُفَادَاةٍ: فَسْخٌ. وَبِلَفْظِ طَلَاقٍ، أَوْ نِيَّتِهِ، أَوْ كِنَايَتِهِ: طَلْقَةٌ بَائِنَةٌ. وَلَا يَصِحُّ إِلَّا بِعِوَضٍ."]]},{"id":"ak17_2","label":"بَابُ الْخُلْعِ · ٢","segs":[["matn","وَيُكْرَهُ بِأَكْثَرَ مِمَّا أَعْطَاهَا. وَيَصِحُّ بَذْلُهُ مِمَّنْ يَصِحُّ تَبَرُّعُهُ، مِنْ زَوْجَةٍ وَأَجْنَبِيٍّ. وَيَصِحُّ بِمَجْهُولٍ، وَمَعْدُومٍ. لَا بِلَا عِوَضٍ. وَلَا بِمُحَرَّمٍ. وَلَا حِيلَةً لِإِسْقَاطِ طَلَاقٍ."]]},{"id":"ak17_3","label":"بَابُ الْخُلْعِ · ٣","segs":[["matn","وَإِذَا قَالَ: مَتَى، أَوْ: إِذَا أَعْطَيْتِنِي أَلْفاً فَأَنْتِ طَالِقٌ؛ طَلُقَتْ بِعَطِيَّتِهِ، وَلَوْ تَرَاخَتْ. وَإِنْ قَالَتِ: اخْلَعْنِي بِأَلْفٍ، أَوْ: عَلَى أَلْفٍ، فَفَعَلَ؛ بَانَتْ وَاسْتَحَقَّهَا."]]},{"id":"ak17_4","label":"بَابُ الْخُلْعِ · ٤","segs":[["matn","وَلَيْسَ لَهُ خَلْعُ: زَوْجَةِ ابْنِهِ الصَّغِيرِ، وَلَا طَلَاقُهَا. وَلَا ابْنَتِهِ الصَّغِيرَةِ بِشَيْءٍ مِنْ مَالِهَا. وَإِنْ عَلَّقَ طَلَاقَهَا عَلَى صِفَةٍ، ثُمَّ أَبَانَهَا فَوُجِدَتْ أَوْ لَا، ثُمَّ نَكَحَهَا فَوُجِدَتْ: طَلُقَتْ. وَكَذَا عِتْقٌ."]]}],"group":"كِتَابُ النِّكَاحِ"},{"id":"ak18","title":"كِتَابُ الطَّلَاقِ","units":[{"id":"ak18_1","label":"كِتَابُ الطَّلَاقِ · ١","segs":[["matn","يُكْرَهُ: بِلَا حَاجَةٍ. وَيُبَاحُ: لَهَا. وَيُسَنُّ: لِتَضَرُّرِهَا بِالْوَطْءِ. وَتَرْكِهَا صَلَاةً، وَعِفَّةً، وَنَحْوَهُمَا. وَلَا يَصِحُّ إِلَّا مِنْ زَوْجٍ، وَلَوْ مُمَيِّزًا يَعْقِلُهُ. وَمَنْ: عُذِرَ بِزَوَالِ عَقْلِهِ. أَوْ أُكْرِهَ. أَوْ هُدِّدَ مِنْ قَادِرٍ."]]},{"id":"ak18_2","label":"كِتَابُ الطَّلَاقِ · ٢","segs":[["matn","فَطَلَّقَ لِذَلِكَ: لَمْ يَقَعْ. وَمَنْ صَحَّ طَلَاقُهُ: صَحَّ تَوْكِيلُهُ فِيهِ، وَتَوَكُّلُهُ. وَيَصِحُّ تَوْكِيلُ امْرَأَةٍ فِي طَلَاقِ نَفْسِهَا، وَغَيْرِهَا. وَالسُّنَّةُ: أَنْ يُطَلِّقَهَا وَاحِدَةً، فِي طُهْرٍ لَمْ يُجَامِعْ فِيهِ."]]},{"id":"ak18_3","label":"كِتَابُ الطَّلَاقِ · ٣","segs":[["matn","وَإِنْ طَلَّقَ مَدْخُولاً بِهَا فِي: حَيْضٍ. أَوْ طُهْرٍ جَامَعَ فِيهِ. فَبِدْعَةٌ، مُحَرَّمٌ، وَيَقَعُ. لَكِنْ تُسَنُّ رَجْعَتُهَا. وَلَا سُنَّةَ وَلَا بِدْعَةَ: لِمُسْتَبِينٍ حَمْلُهَا. أَوْ صَغِيرَةٍ. وَآيِسَةٍ. وَغَيْرِ مَدْخُولٍ بِهَا."]]},{"id":"ak18_4","label":"كِتَابُ الطَّلَاقِ · ٤","segs":[["matn","وَيَقَعُ: بِصَرِيحِهِ مُطْلَقاً. وَبِكِنَايَتِهِ مَعَ النِّيَّةِ. وَصَرِيحُهُ: لَفْظُ طَلَاقٍ، وَمَا تَصَرَّفَ مِنْهُ، غَيْرَ: أَمْرٍ. وَمُضَارِعٍ. وَمُطَلِّقَةٍ، بِكَسْرِ اللَّامِ. وَإِنْ قَالَ: أَنْتِ عَلَيَّ حَرَامٌ. أَوْ: كَظَهْرِ أُمِّي."]]},{"id":"ak18_5","label":"كِتَابُ الطَّلَاقِ · ٥","segs":[["matn","وَمَا أَحَلَّ اللَّهُ عَلَيَّ حَرَامٌ. فَهُوَ ظِهَارٌ، وَلَوْ نَوَى طَلَاقاً. وَإِنْ قَالَ: كَالْمَيْتَةِ أَوِ الدَّمِ: وَقَعَ مَا نَوَاهُ. وَمَعَ عَدَمِ نِيَّةٍ: ظِهَارٌ. وَإِنْ قَالَ: حَلَفْتُ بِالطَّلَاقِ، وَكَذَبَ: دُيِّنَ، وَلَزِمَهُ حُكْماً."]]},{"id":"ak18_6","label":"كِتَابُ الطَّلَاقِ · ٦","segs":[["matn","وَيَمْلِكُ: حُرٌّ وَمُبَعَّضٌ: ثَلَاثَ تَطْلِيقَاتٍ. وَعَبْدٌ: اثْنَتَيْنِ. وَيَصِحُّ اسْتِثْنَاءُ النِّصْفِ فَأَقَلَّ مِنْ طَلَقَاتٍ، وَمُطَلَّقَاتٍ. وَشُرِطَ: تَلَفُّظٌ. وَاتِّصَالٌ مُعْتَادٌ. وَنِيَّتُهُ قَبْلَ تَمَامِ مُسْتَثْنًى مِنْهُ. وَيَصِحُّ بِقَلْبٍ مِنْ مُطَلَّقَاتٍ لَا طَلَقَاتٍ."]]},{"id":"ak18_7","label":"كِتَابُ الطَّلَاقِ · ٧","segs":[["matn","وَأَنْتِ طَالِقٌ: قَبْلَ مَوْتِي: تَطْلُقُ فِي الْحَالِ. وَبَعْدَهُ أَوْ مَعَهُ: لَا تَطْلُقُ. وَفِي هَذَا الشَّهْرِ، أَوِ الْيَوْمِ، أَوِ السَّنَةِ: تَطْلُقُ فِي الْحَالِ، فَإِنْ قَالَ: أَرَدْتُ آخِرَ الْكُلِّ: قُبِلَ حُكْماً."]]},{"id":"ak18_8","label":"كِتَابُ الطَّلَاقِ · ٨","segs":[["matn","وَغَداً، أَوْ يَوْمَ السَّبْتِ وَنَحْوَهُ: تَطْلُقُ بِأَوَّلِهِ، فَلَوْ قَالَ: أَرَدْتُ الْآخِرَ؛ لَمْ يُقْبَلْ. وَإِذَا مَضَتْ سَنَةٌ فَأَنْتِ طَالِقٌ: تَطَلُقُ بِمُضِيِّ اثْنَيْ عَشَرَ شَهْراً. وَإِنْ قَالَ: السَّنَةُ؛ فَبِانْسِلَاخِ ذِي الْحِجَّةِ. وَاللَّهُ أَعْلَمُ."]]},{"id":"ak18_9","label":"كِتَابُ الطَّلَاقِ · ٩","segs":[["matn","فَصْلٌ: وَمَنْ عَلَّقَ طَلَاقاً وَنَحْوَهُ بِشَرْطٍ: لَمْ يَقَعْ حَتَّى يُوجَدَ. فَلَوْ لَمْ يَلْفِظْ بِهِ، وَادَّعَاهُ: لَمْ يُقْبَلْ حُكْماً. وَلَا يَصِحُّ إِلَّا مِنْ زَوْجٍ. بِصَرِيحٍ، وَكِنَايَةٍ مَعَ قَصْدٍ."]]},{"id":"ak18_10","label":"كِتَابُ الطَّلَاقِ · ١٠","segs":[["matn","وَيَقْطَعُهُ: فَصْلٌ بِتَسْبِيحٍ، وَسُكُوتٍ. لَا كَلَامٍ مُنْتَظِمٍ؛ كَأَنْتِ طَالِقٌ يَا زَانِيَةُ إِنْ قُمْتِ. وَأَدَوَاتُ الشَّرْطِ نَحْوُ: إِنْ، وَمَتَى، وَإِذَا. وَإِنْ كَلَّمْتُكِ فَأَنْتِ طَالِقٌ فَتَحَقَّقِي، أَوْ تَنَحَّيْ، وَنَحْوُهُ: تَطْلُقُ."]]},{"id":"ak18_11","label":"كِتَابُ الطَّلَاقِ · ١١","segs":[["matn","وَإِنْ بَدَأْتُكِ بِالْكَلَامِ فَأَنْتِ طَالِقٌ، فَقَالَتْ: إِنْ بَدَأْتُكَ بِهِ فَعَبْدِي حُرٌّ؛ انْحَلَّتْ يَمِينُهُ، وَتَبْقَى يَمِينُهَا."]]},{"id":"ak18_12","label":"كِتَابُ الطَّلَاقِ · ١٢","segs":[["matn","وَإِنْ خَرَجْتِ بِغَيْرِ إِذْنِي وَنَحْوُهُ فَأَنْتِ طَالِقٌ، ثُمَّ أَذِنَ لَهَا فَخَرَجَتْ، ثُمَّ خَرَجَتْ بِغَيْرِ إِذْنٍ، أَوْ أَذِنَ لَهَا وَلَمْ تَعْلَمْ: طَلُقَتْ. وَإِنْ عَلَّقَهُ عَلَى مَشِيئَتِهَا: تَطْلُقُ بِمَشِيئَتِهَا غَيْرَ مُكْرَهَةٍ."]]},{"id":"ak18_13","label":"كِتَابُ الطَّلَاقِ · ١٣","segs":[["matn","أَوْ بِمَشِيئَةِ اثْنَيْنِ: فَبِمَشِيئَتِهِمَا كَذَلِكَ. وَإِنْ عَلَّقَهُ عَلَى مَشِيئَةِ اللَّهِ تَعَالَى: تَطْلُقُ فِي الْحَالِ. وَكَذَا عِتْقٌ."]]},{"id":"ak18_14","label":"كِتَابُ الطَّلَاقِ · ١٤","segs":[["matn","وَإِنْ حَلَفَ: لَا يَدْخُلُ دَاراً، أَوْ لَا يَخْرُجُ مِنْهَا، فَأَدْخَلَ أَوْ أَخْرَجَ بَعْضَ جَسَدِهِ، أَوْ دَخَلَ طَاقَ الْبَابِ. أَوْ: لَا يَلْبَسُ ثَوْباً مِنْ غَزْلِهَا، فَلَبِسَ ثَوْباً فِيهِ مِنْهُ."]]},{"id":"ak18_15","label":"كِتَابُ الطَّلَاقِ · ١٥","segs":[["matn","أَوْ: لَا يَشْرَبُ مَاءَ هَذَا الْإِنَاءِ، فَشَرِبَ بَعْضَهُ. لَمْ يَحْنَثْ. وَلَيَفْعَلَنَّ شَيْئاً: لَا يَبَرُّ إِلَّا بِفِعْلِهِ كُلِّهِ، مَا لَمْ يَكُنْ لَهُ نِيَّةٌ."]]},{"id":"ak18_16","label":"كِتَابُ الطَّلَاقِ · ١٦","segs":[["matn","وَإِنْ فَعَلَ الْمَحْلُوفَ عَلَيْهِ نَاسِياً أَوْ جَاهِلاً: حَنِثَ فِي طَلَاقٍ وَعَتَاقٍ. وَيَنْفَعُ غَيْرَ ظَالِمٍ تَأَوُّلٌ بِيَمِينِهِ. وَمَنْ شَكَّ: فِي طَلَاقٍ أَوْ مَا عُلِّقَ عَلَيْهِ: لَمْ يَلْزَمْهُ."]]},{"id":"ak18_17","label":"كِتَابُ الطَّلَاقِ · ١٧","segs":[["matn","أَوْ فِي عَدَدِهِ: رَجَعَ إِلَى الْيَقِينِ. وَإِنْ قَالَ لِمَنْ ظَنَّهَا زَوْجَتَهُ: أَنْتِ طَالِقٌ؛ طَلُقَتْ زَوْجَتُهُ. لَا عَكْسُهَا. وَمَنْ أَوْقَعَ بِزَوْجَتِهِ كَلِمَةً، وَشَكَّ هَلْ هِيَ طَلَاقٌ أَوْ ظِهَارٌ: لَمْ يَلْزَمْهُ شَيْءٌ."]]},{"id":"ak18_18","label":"كِتَابُ الطَّلَاقِ · ١٨","segs":[["matn","فَصْلٌ: وَإِذَا طَلَّقَ حُرٌّ مَنْ دَخَلَ، أَوْ خَلَا بِهَا أَقَلَّ مِنْ ثَلَاثٍ، أَوْ عَبْدٌ وَاحِدَةً، لَا عِوَضَ فِيهِمَا: فَلَهُ، وَلِوَلِيِّ مَجْنُونٍ رَجْعَتُهَا فِي عِدَّتِهَا مُطْلَقاً. وَسُنَّ لَهَا إِشْهَادٌ."]]},{"id":"ak18_19","label":"كِتَابُ الطَّلَاقِ · ١٩","segs":[["matn","وَتَحْصُلُ بِوَطْئِهَا مُطْلَقاً. وَالرَّجْعِيَّةُ زَوْجَةٌ فِي غَيْرِ قَسْمٍ. وَتَصِحُّ بَعْدَ طُهْرٍ مِنْ حَيْضَةٍ ثَالِثَةٍ قَبْلَ غُسْلٍ. وَتَعُودُ بَعْدَ عِدَّةٍ بِعَقْدٍ جَدِيدٍ عَلَى مَا بَقِيَ مِنْ طَلَاقِهَا."]]},{"id":"ak18_20","label":"كِتَابُ الطَّلَاقِ · ٢٠","segs":[["matn","وَمَنِ ادَّعَتِ انْقِضَاءَ عِدَّتِهَا، وَأَمْكَنَ: قُبِلَ. لَا فِي شَهْرٍ بِحَيْضٍ إِلَّا بِبَيِّنَةٍ. وَإِنْ طَلَّقَ حُرٌّ ثَلَاثاً، أَوْ عَبْدٌ اثْنَتَيْنِ: لَمْ تَحِلَّ لَهُ حَتَّى يَطَأَهَا زَوْجٌ غَيْرُهُ: فِي قُبُلٍ. بِنِكَاحٍ صَحِيحٍ."]]},{"id":"ak18_21","label":"كِتَابُ الطَّلَاقِ · ٢١","segs":[["matn","مَعَ انْتِشَارٍ، وَيَكْفِي تَغْيِيبُ حَشَفَةٍ، وَلَوْ لَمْ يُنْزِلْ، أَوْ يَبْلُغْ عَشْراً. لَا فِي حَيْضٍ، أَوْ نِفَاسٍ، أَوْ إِحْرَامٍ، أَوْ صَوْمِ فَرْضٍ، أَوْ رِدَّةٍ."]]},{"id":"ak18_22","label":"كِتَابُ الطَّلَاقِ · ٢٢","segs":[["matn","فَصْلٌ: وَالْإِيلَاءُ حَرَامٌ. وَهُوَ: حَلِفُ: زَوْجٍ. عَاقِلٍ. يُمْكِنُهُ الْوَطْءُ. بِاللَّهِ أَوْ صِفَةٍ مِنْ صِفَاتِهِ. عَلَى تَرْكِ وَطْءِ زَوْجَتِهِ الْمُمْكِنِ، فِي قُبُلٍ. أَبَداً، أَوْ مُطْلَقاً، أَوْ فَوْقَ أَرْبَعَةِ أَشْهُرٍ."]]},{"id":"ak18_23","label":"كِتَابُ الطَّلَاقِ · ٢٣","segs":[["matn","فَمَتَى مَضَى أَرْبَعَةُ أَشْهُرٍ مِنْ يَمِينِهِ وَلَمْ يُجَامِعْ فِيهَا بِلَا عُذْرٍ: أُمِرَ بِهِ. فَإِنْ أَبَى: أُمِرَ بِالطَّلَاقِ. فَإِنِ امْتَنَعَ: طَلَّقَ عَلَيْهِ حَاكِمٌ. وَيَجِبُ بِوَطْئِهِ: كَفَّارَةُ يَمِينٍ. وَتَارِكُ الْوَطْءِ ضِرَاراً بِلَا عُذْرٍ: كَمُولٍ."]]},{"id":"ak18_24","label":"كِتَابُ الطَّلَاقِ · ٢٤","segs":[["matn","فَصْلٌ: وَالظِّهَارُ مُحَرَّمٌ. وَهُوَ: أَنْ يُشَبِّهَ زَوْجَتَهُ أَوْ بَعْضَهَا، بِمَنْ تَحْرُمُ عَلَيْهِ، أَوْ بَعْضِهَا، أَوْ بِرَجُلٍ مُطْلَقاً. لَا بِشَعْرٍ، وَسِنٍّ، وَظُفُرٍ، وَرِيقٍ وَنَحْوِهَا. وَإِنْ قَالَتْهُ لِزَوْجِهَا: فَلَيْسَ بِظِهَارٍ."]]},{"id":"ak18_25","label":"كِتَابُ الطَّلَاقِ · ٢٥","segs":[["matn","وَعَلَيْهَا كَفَّارَتُهُ بِوَطْئِهَا مُطَاوِعَةً. وَيَصِحُّ مِمَّنْ يَصِحُّ طَلَاقُهُ. وَيَحْرُمُ عَلَيْهِمَا وَطْءٌ وَدَوَاعِيهِ قَبْلَ كَفَّارَتِهِ. وَهِيَ: عِتْقُ رَقَبَةٍ. فَإِنْ لَمْ يَجِدْ: فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ. فَإِنْ لَمْ يَسْتَطِعْ: فَإِطْعَامُ سِتِّينَ مِسْكِيناً."]]},{"id":"ak18_26","label":"كِتَابُ الطَّلَاقِ · ٢٦","segs":[["matn","وَيُكَفِّرُ: كَافِرٌ بِمَالٍ. وَعَبْدٌ بِالصَّوْمِ. وَشُرِطَ فِي رَقَبَةِ كَفَّارَةٍ، وَنَذْرِ عِتْقٍ مُطْلَقٍ: إِسْلَامٌ. وَسَلَامَةٌ مِنْ عَيْبٍ مُضِرٍّ بِالْعَمَلِ ضَرَراً بَيِّناً. وَلَا يُجْزِئُ التَّكْفِيرُ إِلَّا بِمَا يُجْزِئُ فِطْرَةً."]]},{"id":"ak18_27","label":"كِتَابُ الطَّلَاقِ · ٢٧","segs":[["matn","وَيُجْزِئُ مِنَ الْبُرِّ: مُدٌّ لِكُلِّ مِسْكِينٍ، وَمِنْ غَيْرِهِ: مُدَّانِ."]]},{"id":"ak18_28","label":"كِتَابُ الطَّلَاقِ · ٢٨","segs":[["matn","فَصْلٌ: وَيَجُوزُ اللِّعَانُ بَيْنَ: زَوْجَيْنِ. بَالِغَيْنِ. عَاقِلَيْنِ. لِإِسْقَاطِ الْحَدِّ. فَمَنْ قَذَفَ زَوْجَتَهُ لَفْظاً وَكَذَّبَتْهُ: فَلَهُ لِعَانُهَا."]]},{"id":"ak18_29","label":"كِتَابُ الطَّلَاقِ · ٢٩","segs":[["matn","بِأَنْ يَقُولَ أَرْبَعاً: أَشْهَدُ بِاللَّهِ إِنِّي لَصَادِقٌ فِيمَا رَمَيْتُهَا بِهِ مِنَ الزِّنَى، وَفِي الْخَامِسَةِ: وَإِنَّ لَعْنَةَ اللَّهِ عَلَيْهِ إِنْ كَانَ مِنَ الْكَاذِبِينَ."]]},{"id":"ak18_30","label":"كِتَابُ الطَّلَاقِ · ٣٠","segs":[["matn","ثُمَّ تَقُولَ هِيَ أَرْبَعاً: أَشْهَدُ بِاللَّهِ إِنَّهُ لَكَاذِبٌ فِيمَا رَمَانِي بِهِ مِنَ الزِّنَى، وَفِي الْخَامِسَةِ: وَإِنَّ غَضَبَ اللَّهِ عَلَيْهَا إِنْ كَانَ مِنَ الصَّادِقِينَ. فَإِذَا تَمَّ: سَقَطَ الْحَدُّ. وَثَبَتَتِ الْفُرْقَةُ الْمُؤَبَّدَةُ."]]},{"id":"ak18_31","label":"كِتَابُ الطَّلَاقِ · ٣١","segs":[["matn","وَيَنْتَفِي الْوَلَدُ بِنَفْيِهِ. وَمَنْ أَتَتْ زَوْجَتُهُ بِوَلَدٍ: بَعْدَ نِصْفِ سَنَةٍ مُنْذُ أَمْكَنَ اجْتِمَاعُهُ بِهَا. أَوْ لِدُونِ أَرْبَعِ سِنِينَ مُنْذُ أَبَانَهَا. وَلَوِ ابْنَ عَشْرٍ: لَحِقَهُ نَسَبُهُ."]]},{"id":"ak18_32","label":"كِتَابُ الطَّلَاقِ · ٣٢","segs":[["matn","وَلَا يُحْكَمُ بِبُلُوغِهِ مَعَ شَكٍّ فِيهِ. وَمَنْ أَعْتَقَ، أَوْ بَاعَ مَنْ أَقَرَّ بِوَطْئِهَا، فَوَلَدَتْ لِدُونِ نِصْفِ سَنَةٍ: لَحِقَهُ. وَالْبَيْعُ بَاطِلٌ."]]}],"group":"كِتَابُ الطَّلَاقِ"},{"id":"ak19","title":"بَابُ الْعِدَدِ","units":[{"id":"ak19_1","label":"بَابُ الْعِدَدِ · ١","segs":[["matn","لَا عِدَّةَ فِي فُرْقَةِ حَيٍّ قَبْلَ وَطْءٍ وَخَلْوَةٍ. وَشُرِطَ لِوَطْءٍ: كَوْنُهَا يُوطَأُ مِثْلُهَا. وَكَوْنُهُ يَلْحَقُ بِهِ الْوَلَدُ. وَلِخَلْوَةٍ: مُطَاوَعَتُهُ. وَعِلْمُهُ بِهَا، وَلَوْ مَعَ مَانِعٍ. وَتَلْزَمُ لِوَفَاةٍ مُطْلَقاً."]]},{"id":"ak19_2","label":"بَابُ الْعِدَدِ · ٢","segs":[["matn","وَالْمُعْتَدَّاتُ سِتٌّ: الْحَامِلُ: وَعِدَّتُهَا إِلَى وَضْعِ كُلِّ حَمْلٍ تَصِيرُ بِهِ أَمَةٌ أُمَّ وَلَدٍ. وَشُرِطَ: لُحُوقُهُ لِلزَّوْجِ. وَأَقَلُّ مُدَّتِهِ: سِتَّةُ أَشْهُرٍ، وَغَالِبُهَا: تِسْعَةٌ، وَأَكْثَرُهَا: أَرْبَعُ سِنِينَ."]]},{"id":"ak19_3","label":"بَابُ الْعِدَدِ · ٣","segs":[["matn","وَيُبَاحُ إِلْقَاءُ نُطْفَةٍ قَبْلَ أَرْبَعِينَ يَوْماً بِدَوَاءٍ مُبَاحٍ. الثَّانِيَةُ: الْمُتَوَفَّى عَنْهَا بِلَا حَمْلٍ؛ فَتَعْتَدُّ: حُرَّةٌ: أَرْبَعَةَ أَشْهُرٍ وَعَشْرَ لَيَالٍ بِعَشَرَةِ أَيَّامٍ. وَأَمَةٌ: نِصْفَهَا. وَمُبَعَّضَةٌ: بِالْحِسَابِ."]]},{"id":"ak19_4","label":"بَابُ الْعِدَدِ · ٤","segs":[["matn","وَتَعْتَدُّ مَنْ أَبَانَهَا فِي مَرَضِ مَوْتِهِ: الْأَطْوَلَ مِنْ عِدَّةِ وَفَاةٍ أَوْ طَلَاقٍ إِنْ وَرِثَتْ. وَإِلَّا عِدَّةَ طَلَاقٍ. الثَّالِثَةُ: ذَاتُ الْحَيْضِ الْمُفَارَقَةُ فِي الْحَيَاةِ: فَتَعْتَدُّ حُرَّةٌ وَمُبَعَّضَةٌ: بِثَلَاثِ حَيْضَاتٍ. وَأَمَةٌ: بِحَيْضَتَيْنِ."]]},{"id":"ak19_5","label":"بَابُ الْعِدَدِ · ٥","segs":[["matn","الرَّابِعَةُ: الْمُفَارَقَةُ فِي الْحَيَاةِ، وَلَمْ تَحِضْ لِصِغَرٍ أَوْ إِيَاسٍ: فَتَعْتَدُّ حُرَّةٌ: بِثَلَاثَةِ أَشْهُرٍ. وَأَمَةٌ: بِشَهْرَيْنِ. وَمُبَعَّضَةٌ: بِالْحِسَابِ."]]},{"id":"ak19_6","label":"بَابُ الْعِدَدِ · ٦","segs":[["matn","الْخَامِسَةُ: مَنِ ارْتَفَعَ حَيْضُهَا: وَلَمْ تَعْلَمْ مَا رَفَعَهُ: فَتَعْتَدُّ لِلْحَمْلِ غَالِبَ مُدَّتِهِ، ثُمَّ تَعْتَدُّ كَآيِسَةٍ. وَإِنْ عَلِمَتْ مَا رَفَعَهُ: فَلَا تَزَالُ حَتَّى يَعُودَ فَتَعْتَدَّ بِهِ، أَوْ تَصِيرَ آيِسَةً فَتَعْتَدَّ عِدَّتَهَا."]]},{"id":"ak19_7","label":"بَابُ الْعِدَدِ · ٧","segs":[["matn","وَعِدَّةُ: بَالِغَةٍ لَمْ تَحِضْ. وَمُسْتَحَاضَةٍ مُبْتَدَأَةٍ أَوْ نَاسِيَةٍ. كَآيِسَةٍ. السَّادِسَةُ: امْرَأَةُ الْمَفْقُودِ تَتَرَبَّصُ -وَلَوْ أَمَةً-: أَرْبَعَ سِنِينَ: إِنِ انْقَطَعَ خَبَرُهُ لِغَيْبَةٍ ظَاهِرُهَا الْهَلَاكُ. وَتِسْعِينَ مُنْذُ وُلِدَ: إِنْ كَانَ ظَاهِرُهَا السَّلَامَةَ."]]},{"id":"ak19_8","label":"بَابُ الْعِدَدِ · ٨","segs":[["matn","ثُمَّ تَعْتَدُّ لِلْوَفَاةِ. وَإِنْ طَلَّقَ غَائِبٌ أَوْ مَاتَ: فَابْتِدَاءُ الْعِدَّةِ مِنَ الْفُرْقَةِ. وَعِدَّةُ مَنْ وُطِئَتْ بِشُبْهَةٍ أَوْ زِنًى: كَمُطَلَّقَةٍ. إِلَّا أَمَةً غَيْرَ مُزَوَّجَةٍ: فَتُسْتَبْرَأُ بِحَيْضَةٍ."]]},{"id":"ak19_9","label":"بَابُ الْعِدَدِ · ٩","segs":[["matn","وَإِنْ وُطِئَتْ مُعْتَدَّةٌ بِشُبْهَةٍ، أَوْ زِنًى، أَوْ نِكَاحٍ فَاسِدٍ: أَتَمَّتْ عِدَّةَ الْأَوَّلِ، وَلَا يُحْتَسَبُ مِنْهَا مُقَامُهَا عِنْدَ ثَانٍ، ثُمَّ اعْتَدَّتْ لِثَانٍ. وَيَحْرُمُ إِحْدَادٌ عَلَى مَيِّتٍ غَيْرِ زَوْجٍ: فَوْقَ ثَلَاثٍ."]]},{"id":"ak19_10","label":"بَابُ الْعِدَدِ · ١٠","segs":[["matn","وَيَجِبُ: عَلَى زَوْجَةِ مَيِّتٍ. وَيُبَاحُ: لِبَائِنٍ. وَهُوَ: تَرْكُ زِينَةٍ، وَطِيبٍ، وَكُلِّ مَا يَدْعُو إِلَى جِمَاعِهَا وَيُرَغِّبُ فِي النَّظَرِ إِلَيْهَا. وَيَحْرُمُ -بِلَا حَاجَةٍ-: تَحَوُّلُهَا مِنْ مَسْكَنٍ وَجَبَتْ فِيهِ."]]},{"id":"ak19_11","label":"بَابُ الْعِدَدِ · ١١","segs":[["matn","وَلَهَا الْخُرُوجُ لِحَاجَتِهَا: نَهَاراً. وَمَنْ مَلَكَ أَمَةً يُوطَأُ مِثْلُهَا مِنْ أَيِّ شَخْصٍ كَانَ؛ حَرُمَ عَلَيْهِ وَطْءٌ وَمُقَدِّمَاتُهُ قَبْلَ اسْتِبْرَاءِ: حَامِلٍ: بِوَضْعٍ. وَمَنْ تَحِيضُ: بِحَيْضَةٍ. وَآيِسَةٍ وَصَغِيرَةٍ: بِشَهْرٍ."]]},{"id":"ak19_12","label":"بَابُ الْعِدَدِ · ١٢","segs":[["matn","فَصْلٌ: وَيَحْرُمُ مِنَ الرَّضَاعِ مَا يَحْرُمُ مِنَ النَّسَبِ. عَلَى رَضِيعٍ، وَفَرْعِهِ وَإِنْ نَزَلَ فَقَطْ. وَلَا حُرْمَةَ إِلَّا: بِخَمْسِ رَضَعَاتٍ. فِي الْحَوْلَيْنِ. وَتَثْبُتُ: بِسَعُوطٍ، وَوَجُورٍ. وَلَبَنِ مَيْتَةٍ، وَمَوْطُوءَةٍ بِشُبْهَةٍ. وَمَشُوبٍ."]]},{"id":"ak19_13","label":"بَابُ الْعِدَدِ · ١٣","segs":[["matn","وَكُلُّ امْرَأَةٍ تَحْرُمُ عَلَيْهِ بِنْتُهَا؛ كَأُمِّهِ، وَجَدَّتِهِ، وَرَبِيبَتِهِ، إِذَا أَرْضَعَتْ طِفْلَةً: حَرَّمَتْهَا عَلَيْهِ. وَكُلُّ رَجُلٍ تَحْرُمُ عَلَيْهِ بِنْتُهُ؛ كَأَخِيهِ، وَأَبِيهِ، وَرَبِيبِهِ، إِذَا أَرْضَعَتِ امْرَأَتُهُ بِلَبَنِهِ طِفْلَةً حَرَّمَتْهَا عَلَيْهِ."]]},{"id":"ak19_14","label":"بَابُ الْعِدَدِ · ١٤","segs":[["matn","وَمَنْ قَالَ: إِنَّ زَوْجَتَهُ أُخْتُهُ مِنَ الرَّضَاعِ؛ بَطَلَ نِكَاحُهُ. وَلَا مَهْرَ قَبْلَ دُخُولٍ إِنْ صَدَّقَتْهُ. وَيَجِبُ نِصْفُهُ إِنْ كَذَّبَتْهُ. وَكُلُّهُ بَعْدَ دُخُولٍ مُطْلَقاً."]]},{"id":"ak19_15","label":"بَابُ الْعِدَدِ · ١٥","segs":[["matn","وَإِنْ قَالَتْ هِيَ ذَلِكَ، وَكَذَّبَهَا: فَهِيَ زَوْجَتُهُ حُكْماً. وَمَنْ شَكَّ فِي رَضَاعٍ، أَوْ عَدَدِهِ: بَنَى عَلَى الْيَقِينِ. وَيَثْبُتُ: بِإِخْبَارِ مُرْضِعَةٍ. وَبِشَهَادَةِ عَدْلٍ مُطْلَقاً."]]}],"group":"كِتَابُ الطَّلَاقِ"},{"id":"ak20","title":"بَابُ النَّفَقَاتِ","units":[{"id":"ak20_1","label":"بَابُ النَّفَقَاتِ · ١","segs":[["matn","وَعَلَى زَوْجٍ نَفَقَةُ زَوْجَتِهِ؛ مِنْ مَأْكُولٍ، وَمَشْرُوبٍ، وَكِسْوَةٍ، وَسُكْنَى: بِالْمَعْرُوفِ. فَيُفْرَضُ: لِمُوسِرَةٍ مَعَ مُوسِرٍ عِنْدَ تَنَازُعٍ: مِنْ أَرْفَعِ خُبْزِ الْبَلَدِ وَأُدْمِهِ عَادَةَ الْمُوسِرِينَ، وَمَا يَلْبَسُ مِثْلُهَا، وَيَنَامُ عَلَيْهِ."]]},{"id":"ak20_2","label":"بَابُ النَّفَقَاتِ · ٢","segs":[["matn","وَلِفَقِيرَةٍ مَعَ فَقِيرٍ: كِفَايَتُهَا مِنْ أَدْنَى خُبْزِ الْبَلَدِ وَأُدْمِهِ، وَمَا يَلْبَسُ مِثْلُهَا، وَيَنَامُ وَيُجْلَسُ عَلَيْهِ. وَلِمُتَوَسِّطَةٍ مَعَ مُتَوَسِّطٍ، وَمُوسِرَةٍ مَعَ فَقِيرٍ، وَعَكْسِهَا: مَا بَيْنَ ذَلِكَ. لَا الْقِيمَةَ إِلَّا بِرِضَاهُمَا."]]},{"id":"ak20_3","label":"بَابُ النَّفَقَاتِ · ٣","segs":[["matn","وَعَلَيْهِ مُؤْنَةُ نَظَافَتِهَا. لَا دَوَاءٌ، وَأُجْرَةُ طَبِيبٍ، وَثَمَنُ طِيبٍ. وَتَجِبُ: لِرَجْعِيَّةٍ، وَبَائِنٍ حَامِلٍ. لَا لِمُتَوَفًّى عَنْهَا. وَمَنْ: حُبِسَتْ. أَوْ نَشَزَتْ. أَوْ صَامَتْ نَفْلاً، أَوْ لِكَفَّارَةٍ، أَوْ قَضَاءِ رَمَضَانَ وَوَقْتُهُ مُتَّسِعٌ."]]},{"id":"ak20_4","label":"بَابُ النَّفَقَاتِ · ٤","segs":[["matn","أَوْ حَجَّتْ نَفْلاً بِلَا إِذْنِهِ. أَوْ سَافَرَتْ لِحَاجَتِهَا بِإِذْنِهِ. سَقَطَتْ. وَلَهَا الْكِسْوَةُ: كُلَّ عَامٍ مَرَّةً، فِي أَوَّلِهِ. وَمَتَى لَمْ يُنْفِقْ: تَبْقَى فِي ذِمَّتِهِ."]]},{"id":"ak20_5","label":"بَابُ النَّفَقَاتِ · ٥","segs":[["matn","وَإِنْ أَنْفَقَتْ مِنْ مَالِهِ فِي غَيْبَتِهِ، فَبَانَ مَيِّتاً: رَجَعَ عَلَيْهَا وَارِثٌ. وَمَنْ تَسَلَّمَ مَنْ يَلْزَمُهُ تَسْلِيمُهَا، أَوْ بَذَلَتْهُ هِيَ أَوْ وَلِيُّهَا: وَجَبَتْ نَفَقَتُهَا. وَلَوْ مَعَ صِغَرِهِ، وَمَرَضِهِ، وَعُنَّتِهِ، وَجَبِّهِ."]]},{"id":"ak20_6","label":"بَابُ النَّفَقَاتِ · ٦","segs":[["matn","وَلَهَا مَنْعُ نَفْسِهَا قَبْلَ دُخُولٍ لِقَبْضِ مَهْرٍ حَالٍّ، وَلَهَا النَّفَقَةُ. وَإِنْ: أَعْسَرَ بِنَفَقَةِ مُعْسِرٍ أَوْ بَعْضِهَا، لَا بِمَا فِي ذِمَّتِهِ. أَوْ غَابَ، وَتَعَذَّرَتْ بِاسْتِدَانَةٍ أَوْ نَحْوِهَا. فَلَهَا الْفَسْخُ بِحَاكِمٍ."]]},{"id":"ak20_7","label":"بَابُ النَّفَقَاتِ · ٧","segs":[["matn","وَتَرْجِعُ بِمَا اسْتَدَانَتْهُ لَهَا أَوْ لِوَلَدِهَا الصَّغِيرِ مُطْلَقاً."]]},{"id":"ak20_8","label":"بَابُ النَّفَقَاتِ · ٨","segs":[["matn","فَصْلٌ: وَتَجِبُ عَلَيْهِ بِمَعْرُوفٍ لِكُلٍّ مِنْ: أَبَوَيْهِ وَإِنْ عَلَوْا، وَوَلَدِهِ وَإِنْ سَفَلَ، وَلَوْ حَجَبَهُ مُعْسِرٌ."]]},{"id":"ak20_9","label":"بَابُ النَّفَقَاتِ · ٩","segs":[["matn","وَلِكُلِّ مَنْ يَرِثُهُ بِفَرْضٍ أَوْ تَعْصِيبٍ، لَا بِرَحِمٍ سِوَى عَمُودَيْ نَسَبِهِ: مَعَ فَقْرِ مَنْ تَجِبُ لَهُ، وَعَجْزِهِ عَنْ كَسْبٍ. إِذَا كَانَتْ فَاضِلَةً عَنْ قُوتِ نَفْسِهِ، وَزَوْجَتِهِ، وَرَقِيقِهِ يَوْمَهُ وَلَيْلَتَهُ؛ كَفِطْرَةٍ."]]},{"id":"ak20_10","label":"بَابُ النَّفَقَاتِ · ١٠","segs":[["matn","لَا مِنْ رَأْسِ مَالٍ، وَثَمَنِ مِلْكٍ، وَآلَةِ صَنْعَةٍ. وَتَسْقُطُ بِمُضِيِّ زَمَنٍ، مَا لَمْ: يَفْرِضْهَا حَاكِمٌ. أَوْ تُسْتَدَنْ بِإِذْنِهِ. وَإِنِ امْتَنَعَ مَنْ وَجَبَتْ عَلَيْهِ: رَجَعَ عَلَيْهِ مُنْفِقٌ بِنِيَّةِ الرُّجُوعِ."]]},{"id":"ak20_11","label":"بَابُ النَّفَقَاتِ · ١١","segs":[["matn","وَهِيَ عَلَى كُلٍّ بِقَدْرِ إِرْثِهِ. وَإِنْ كَانَ أَبٌ: انْفَرَدَ بِهَا. وَتَجِبُ عَلَيْهِ لِرَقِيقِهِ، وَلَوْ آبِقاً، وَنَاشِزاً. وَلَا يُكَلِّفُهُ مُشِقًّا كَثِيراً، وَيُرِيحُهُ وَقْتَ قَائِلَةٍ، وَنَوْمٍ، وَلِصَلَاةِ فَرْضٍ. وَعَلَيْهِ عَلَفُ بَهَائِمِهِ وَسَقْيُهَا."]]},{"id":"ak20_12","label":"بَابُ النَّفَقَاتِ · ١٢","segs":[["matn","وَإِنْ عَجَزَ: أُجْبِرَ عَلَى بَيْعٍ، أَوْ إِجَارَةٍ، أَوْ ذَبْحِ مَأْكُولٍ. وَحَرُمَ: تَحْمِيلُهَا مُشِقًّا. وَلَعْنُهَا. وَحَلْبُهَا مَا يَضُرُّ بِوَلَدِهَا. وَضَرْبُ وَجْهٍ. وَوَسْمٌ فِيهِ، وَيَجُوزُ فِي غَيْرِهِ لِغَرَضٍ صَحِيحٍ."]]},{"id":"ak20_13","label":"بَابُ النَّفَقَاتِ · ١٣","segs":[["matn","فَصْلٌ: وَتَجِبُ الْحَضَانَةُ لِحِفْظِ: صَغِيرٍ، وَمَجْنُونٍ، وَمَعْتُوهٍ. وَالْأَحَقُّ بِهَا: أُمٌّ. ثُمَّ أُمَّهَاتُهَا، الْقُرْبَى فَالْقُرْبَى. ثُمَّ أَبٌ. ثُمَّ أُمَّهَاتُهُ كَذَلِكَ. ثُمَّ جَدٌّ. ثُمَّ أُمَّهَاتُهُ كَذَلِكَ."]]},{"id":"ak20_14","label":"بَابُ النَّفَقَاتِ · ١٤","segs":[["matn","ثُمَّ أُخْتٌ لِأَبَوَيْنِ، ثُمَّ لِأُمٍّ، ثُمَّ لِأَبٍ. ثُمَّ خَالَةٌ. ثُمَّ عَمَّةٌ. ثُمَّ بِنْتُ أَخٍ وَأُخْتٍ. ثُمَّ بِنْتُ عَمٍّ وَعَمَّةٍ. ثُمَّ بِنْتُ عَمِّ أَبٍ وَعَمَّتِهِ عَلَى مَا فُصِّلَ."]]},{"id":"ak20_15","label":"بَابُ النَّفَقَاتِ · ١٥","segs":[["matn","ثُمَّ لِبَاقِي الْعَصَبَةِ الْأَقْرَبِ فَالْأَقْرَبِ. وَشُرِطَ كَوْنُهُ مَحْرَماً لِأُنْثَى. ثُمَّ لِذِي رَحِمٍ. ثُمَّ لِحَاكِمٍ. وَلَا تَثْبُتُ: لِمَنْ فِيهِ رِقٌّ. وَلَا لِكَافِرٍ عَلَى مُسْلِمٍ. وَلَا لِفَاسِقٍ."]]},{"id":"ak20_16","label":"بَابُ النَّفَقَاتِ · ١٦","segs":[["matn","وَلَا لِمُزَوَّجَةٍ بِأَجْنَبِيٍّ مِنْ مَحْضُونٍ مِنْ حِينِ عَقْدٍ. وَإِنْ أَرَادَ أَحَدُ أَبَوَيْهِ نُقْلَةً إِلَى بَلَدٍ آمِنٍ: وَطَرِيقُهُ مَسَافَةُ قَصْرٍ فَأَكْثَرُ، لِيَسْكُنَهُ: فَأَبٌ أَحَقُّ. أَوْ إِلَى قَرِيبٍ لِلسُّكْنَى: فَأُمٌّ."]]},{"id":"ak20_17","label":"بَابُ النَّفَقَاتِ · ١٧","segs":[["matn","وَلِحَاجَةٍ مَعَ بُعْدٍ أَوْ لَا: فَمُقِيمٌ. وَإِذَا بَلَغَ صَبِيٌّ سَبْعَ سِنِينَ عَاقِلاً: خُيِّرَ بَيْنَ أَبَوَيْهِ. وَلَا يُقَرُّ مَحْضُونٌ بِيَدِ مَنْ لَا يَصُونُهُ وَيُصْلِحُهُ."]]},{"id":"ak20_18","label":"بَابُ النَّفَقَاتِ · ١٨","segs":[["matn","وَتَكُونُ بِنْتُ سَبْعٍ عِنْدَ أَبٍ، أَوْ مَنْ يَقُومُ مَقَامَهُ إِلَى زِفَافٍ."]]}],"group":"كِتَابُ الطَّلَاقِ"},{"id":"ak21","title":"كِتَابُ الْجِنَايَاتِ","units":[{"id":"ak21_1","label":"كِتَابُ الْجِنَايَاتِ · ١","segs":[["matn","الْقَتْلُ: عَمْدٌ، وَشِبْهُ عَمْدٍ، وَخَطَأٌ. فَالْعَمْدُ: يَخْتَصُّ الْقَوَدُ بِهِ، وَهُوَ أَنْ يَقْصِدَ مَنْ يَعْلَمُهُ آدَمِيًّا مَعْصُوماً، فَيَقْتُلَهُ بِمَا يَغْلِبُ عَلَى الظَّنِّ مَوْتُهُ بِهِ؛ كَجَرْحِهِ بِمَا لَهُ نُفُوذٌ فِي الْبَدَنِ، وَضَرْبِهِ بِحَجَرٍ كَبِيرٍ."]]},{"id":"ak21_2","label":"كِتَابُ الْجِنَايَاتِ · ٢","segs":[["matn","وَشِبْهُ الْعَمْدِ: أَنْ يَقْصِدَ جِنَايَةً لَا تَقْتُلُ غَالِباً، وَلَمْ يَجْرَحْهُ بِهَا؛ كَضَرْبٍ بِسَوْطٍ أَوْ عَصاً. وَالْخَطَأُ: أَنْ يَفْعَلَ مَا لَهُ فِعْلُهُ؛ كَرَمْيِ صَيْدٍ وَنَحْوِهِ، فَيُصِيبَ آدَمِيًّا. وَعَمْدُ صَبِيٍّ وَمَجْنُونٍ: خَطَأٌ."]]},{"id":"ak21_3","label":"كِتَابُ الْجِنَايَاتِ · ٣","segs":[["matn","وَيُقْتَلُ عَدَدٌ بِوَاحِدٍ، وَمَعَ عَفْوٍ يَجِبُ دِيَةٌ وَاحِدَةٌ. وَمَنْ: أَكْرَهَ مُكَلَّفاً عَلَى قَتْلِ مُعَيَّنٍ. أَوْ عَلَى أَنْ يُكْرِهَ عَلَيْهِ. فَفَعَلَ؛ فَعَلَى كُلٍّ: الْقَوَدُ أَوِ الدِّيَةُ. وَإِنْ أَمَرَ بِهِ: غَيْرَ مُكَلَّفٍ."]]},{"id":"ak21_4","label":"كِتَابُ الْجِنَايَاتِ · ٤","segs":[["matn","أَوْ مَنْ يَجْهَلُ تَحْرِيمَهُ. أَوْ سُلْطَانٌ ظُلْماً مَنْ جَهِلَ ظُلْمَهُ فِيهِ. لَزِمَ الْآمِرَ."]]},{"id":"ak21_5","label":"كِتَابُ الْجِنَايَاتِ · ٥","segs":[["matn","فَصْلٌ: وَلِلْقِصَاصِ أَرْبَعَةُ شُرُوطٍ: تَكْلِيفُ قَاتِلٍ. وَعِصْمَةُ مَقْتُولٍ. وَمُكَافَأَتُهُ لِقَاتِلٍ: بِدِينٍ. وَحُرِّيَّةٍ. وَعَدَمُ الْوِلَادَةِ. وَلِاسْتِيفَائِهِ ثَلَاثَةٌ: تَكْلِيفُ مُسْتَحِقٍّ لَهُ. وَاتِّفَاقُهُمْ عَلَيْهِ. وَأَنْ يُؤْمَنَ فِي اسْتِيفَائِهِ تَعَدِّيهِ إِلَى غَيْرِ جَانٍ."]]},{"id":"ak21_6","label":"كِتَابُ الْجِنَايَاتِ · ٦","segs":[["matn","وَيُحْبَسُ لِقُدُومِ غَائِبٍ، وَبُلُوغٍ، وَإِفَاقَةٍ. وَيَجِبُ اسْتِيفَاؤُهُ: بِحَضْرَةِ سُلْطَانٍ أَوْ نَائِبِهِ. وَبِآلَةٍ مَاضِيَةٍ. وَفِي النَّفْسِ: بِضَرْبِ الْعُنُقِ بِسَيْفٍ."]]},{"id":"ak21_7","label":"كِتَابُ الْجِنَايَاتِ · ٧","segs":[["matn","فَصْلٌ: وَيَجِبُ بِعَمْدٍ: الْقَوَدُ أَوِ الدِّيَةُ، فَيُخَيَّرُ وَلِيٌّ. وَالْعَفْوُ مَجَّاناً أَفْضَلُ. وَمَتَى: اخْتَارَ الدِّيَةَ. أَوْ عَفَا مُطْلَقاً. أَوْ هَلَكَ جَانٍ. تَعَيَّنَتِ الدِّيَةُ."]]},{"id":"ak21_8","label":"كِتَابُ الْجِنَايَاتِ · ٨","segs":[["matn","وَمَنْ وَكَّلَ، ثُمَّ عَفَا، وَلَمْ يَعْلَمْ وَكِيلٌ حَتَّى اقْتَصَّ: فَلَا شَيْءَ عَلَيْهِمَا. وَإِنْ وَجَبَ لِقِنٍّ قَوَدٌ، أَوْ تَعْزِيرُ قَذْفٍ: فَطَلَبُهُ وَإِسْقَاطُهُ لَهُ. وَإِنْ مَاتَ فَلِسَيِّدِهِ."]]},{"id":"ak21_9","label":"كِتَابُ الْجِنَايَاتِ · ٩","segs":[["matn","وَالْقَوَدُ فِيمَا دُونَ النَّفْسِ؛ كَالْقَوَدِ فِيهَا، وَهُوَ نَوْعَانِ: أَحَدُهُمَا: فِي الطَّرَفِ. فَيُؤْخَذُ كُلٌّ مِنْ عَيْنٍ، وَأَنْفٍ، وَأُذُنٍ، وَسِنٍّ، وَنَحْوِهَا: بِمِثْلِهِ، بِشَرْطِ: مُمَاثَلَةٍ. وَأَمْنٍ مِنْ حَيْفٍ. وَاسْتِوَاءٍ فِي صِحَّةٍ وَكَمَالٍ."]]},{"id":"ak21_10","label":"كِتَابُ الْجِنَايَاتِ · ١٠","segs":[["matn","الثَّانِي: فِي الْجُرُوحِ. بِشَرْطِ: انْتِهَائِهَا إِلَى عَظْمٍ؛ كَمُوضِحَةٍ، وَجُرْحِ عَضُدٍ، وَسَاقٍ، وَنَحْوِهِمَا. وَتُضْمَنُ سِرَايَةُ جِنَايَةٍ، لَا قَوَدٍ. وَلَا يُقْتَصُّ عَنْ طَرَفٍ وَجُرْحٍ، وَلَا يُطْلَبُ لَهُمَا دِيَةٌ قَبْلَ الْبُرْءِ."]]},{"id":"ak21_11","label":"كِتَابُ الْجِنَايَاتِ · ١١","segs":[["matn","فَصْلٌ: وَدِيَةُ: الْعَمْدِ: عَلَى الْجَانِي. وَغَيْرُهَا: عَلَى عَاقِلَتِهِ. وَمَنْ قَيَّدَ حُرًّا مُكَلَّفاً، أَوْ غَلَّهُ، أَوْ غَصَبَ صَغِيراً فَتَلِفَ بِحَيَّةٍ أَوْ صَاعِقَةٍ: فَالدِّيَةُ. لَا إِنْ مَاتَ بِمَرَضٍ، أَوْ فُجَاءَةً."]]},{"id":"ak21_12","label":"كِتَابُ الْجِنَايَاتِ · ١٢","segs":[["matn","وَإِنْ أَدَّبَ امْرَأَتَهُ بِنُشُوزٍ، أَوْ مُعَلِّمٌ صَبِيَّهُ، أَوْ سُلْطَانٌ رَعِيَّتَهُ بِلَا إِسْرَافٍ: فَلَا ضَمَانَ بِتَلَفٍ مِنْ ذَلِكَ. وَمَنْ أَمَرَ مُكَلَّفاً أَنْ يَنْزِلَ بِئْراً، أَوْ يَصْعَدَ شَجَرَةً؛ فَهَلَكَ بِهِ: لَمْ يَضْمَنْ."]]},{"id":"ak21_13","label":"كِتَابُ الْجِنَايَاتِ · ١٣","segs":[["matn","وَلَوْ مَاتَتْ أَوْ حَمْلُهَا مِنْ رِيحِ طَعَامٍ وَنَحْوِهِ: ضَمِنَ رَبُّهُ إِنْ عُلِمَ ذَلِكَ عَادَةً."]]},{"id":"ak21_14","label":"كِتَابُ الْجِنَايَاتِ · ١٤","segs":[["matn","فَصْلٌ: وَدِيَةُ الْحُرِّ الْمُسْلِمِ: مِائَةُ بَعِيرٍ، أَوْ أَلْفُ مِثْقَالٍ ذَهَباً، أَوِ اثْنَا عَشَرَ أَلْفَ دِرْهَمٍ فِضَّةً، أَوْ مِائَتَا بَقَرَةٍ، أَوْ أَلْفَا شَاةٍ، فَيُخَيَّرُ مَنْ عَلَيْهِ دِيَةٌ بَيْنَهَا."]]},{"id":"ak21_15","label":"كِتَابُ الْجِنَايَاتِ · ١٥","segs":[["matn","وَيَجِبُ فِي عَمْدٍ وَشِبْهِهِ مِنْ إِبِلٍ: رُبُعٌ بِنْتُ مَخَاضٍ، وَرُبُعٌ بِنْتُ لَبُونٍ، وَرُبُعٌ حِقَّةٌ، وَرُبُعٌ جَذَعَةٌ. وَفِي خَطَأٍ أَخْمَاساً: ثَمَانُونَ مِنَ الْمَذْكُورَةِ، وَعِشْرُونَ ابْنُ مَخَاضٍ."]]},{"id":"ak21_16","label":"كِتَابُ الْجِنَايَاتِ · ١٦","segs":[["matn","وَمِنْ بَقَرٍ: نِصْفٌ مُسِنَّاتٌ، وَنِصْفٌ أَتْبِعَةٌ. وَمِنْ غَنَمٍ: نِصْفٌ ثَنَايَا، وَنِصْفٌ أَجْذِعَةٌ. وَتُعْتَبَرُ السَّلَامَةُ، لَا الْقِيمَةُ. وَدِيَةُ أُنْثَى: نِصْفُ دِيَةِ رَجُلٍ مِنْ أَهْلِ دِيَتِهَا."]]},{"id":"ak21_17","label":"كِتَابُ الْجِنَايَاتِ · ١٧","segs":[["matn","وَجِرَاحُهَا: تُسَاوِي جِرَاحَهُ فِيمَا دُونَ ثُلُثِ دِيَتِهِ. وَدِيَةُ كِتَابِيٍّ حُرٍّ: نِصْفُ دِيَةِ مُسْلِمٍ. وَمَجُوسِيٍّ وَوَثَنِيٍّ: ثَمَانُمِائَةِ دِرْهَمٍ. وَدِيَةُ رَقِيقٍ: قِيمَتُهُ."]]},{"id":"ak21_18","label":"كِتَابُ الْجِنَايَاتِ · ١٨","segs":[["matn","وَجُرْحُهُ: إِنْ كَانَ مُقَدَّراً مِنَ الْحُرِّ: فَهُوَ مُقَدَّرٌ مِنْهُ مَنْسُوباً إِلَى قِيمَتِهِ. وَإِلَّا: فَمَا نَقَصَهُ بَعْدَ بُرْءٍ. وَدِيَةُ جَنِينٍ: حُرٍّ: غُرَّةٌ مَوْرُوثَةٌ عَنْهُ، قِيمَتُهَا: عُشْرُ دِيَةِ أُمِّهِ."]]},{"id":"ak21_19","label":"كِتَابُ الْجِنَايَاتِ · ١٩","segs":[["matn","وَقِنٍّ: عُشْرُ قِيمَتِهَا، وَتُقَدَّرُ حُرَّةٌ أَمَةً. وَإِنْ جَنَى رَقِيقٌ خَطَأً أَوْ عَمْداً، وَاخْتِيرَ الْمَالُ، أَوْ أَتْلَفَ مَالاً بِغَيْرِ إِذْنِ سَيِّدِهِ؛ خُيِّرَ بَيْنَ: فِدَائِهِ بِأَرْشِ الْجِنَايَةِ. أَوْ تَسْلِيمِهِ لِوَلِيِّهَا."]]},{"id":"ak21_20","label":"كِتَابُ الْجِنَايَاتِ · ٢٠","segs":[["matn","فَصْلٌ: وَمَنْ أَتْلَفَ مَا فِي الْإِنْسَانِ: مِنْهُ وَاحِدٌ؛ كَأَنْفٍ: فَفِيهِ دِيَةُ نَفْسِهِ. أَوِ اثْنَانِ أَوْ أَكْثَرُ: فَكَذَلِكَ. وَفِي أَحَدِ ذَلِكَ: نِسْبَتُهُ مِنْهَا. وَفِي الظُّفُرِ: بَعِيرَانِ. وَتَجِبُ كَامِلَةً فِي كُلِّ حَاسَّةٍ."]]},{"id":"ak21_21","label":"كِتَابُ الْجِنَايَاتِ · ٢١","segs":[["matn","وَكَذَا: كَلَامٌ، وَعَقْلٌ، وَمَنْفَعَةُ أَكْلٍ، وَمَشْيٍ، وَنِكَاحٍ. وَمَنْ وَطِئَ زَوْجَةً يُوطَأُ مِثْلُهَا لِمِثْلِهِ، فَخَرَقَ مَا بَيْنَ مَخْرَجِ بَوْلٍ وَمَنِيٍّ، أَوْ مَا بَيْنَ السَّبِيلَيْنِ: فَهَدَرٌ."]]},{"id":"ak21_22","label":"كِتَابُ الْجِنَايَاتِ · ٢٢","segs":[["matn","وَإِلَّا: فَجَائِفَةٌ إِنِ اسْتَمْسَكَ بَوْلٌ، وَإِلَّا فَالدِّيَةُ. وَفِي: كُلٍّ مِنْ شَعْرِ رَأْسٍ، وَحَاجِبَيْنِ، وَأَهْدَابِ عَيْنَيْنِ، وَلِحْيَةٍ: الدِّيَةُ. وَحَاجِبٍ: نِصْفُهَا. وَهُدْبٍ: رُبُعُهَا. وَشَارِبٍ: حُكُومَةٌ. وَمَا عَادَ: سَقَطَ مَا فِيهِ."]]},{"id":"ak21_23","label":"كِتَابُ الْجِنَايَاتِ · ٢٣","segs":[["matn","وَفِي عَيْنِ الْأَعْوَرِ: دِيَةٌ كَامِلَةٌ. وَإِنْ قَلَعَهَا صَحِيحٌ: أُقِيدَ بِشَرْطِهِ، وَعَلَيْهِ أَيْضاً: نِصْفُ الدِّيَةِ. وَإِنْ قَلَعَ مَا يُمَاثِلُ صَحِيحَتَهُ مِنْ صَحِيحٍ عَمْداً: فَدِيَةٌ كَامِلَةٌ. وَالْأَقْطَعُ كَغَيْرِهِ."]]},{"id":"ak21_24","label":"كِتَابُ الْجِنَايَاتِ · ٢٤","segs":[["matn","وَفِي: الْمُوضِحَةِ: خَمْسٌ مِنَ الْإِبِلِ. وَالْهَاشِمَةِ: عَشْرٌ. وَالْمُنَقِّلَةِ: خَمْسَةَ عَشَرَ. وَالْمَأْمُومَةِ: ثُلُثُ الدِّيَةِ؛ كَالْجَائِفَةِ، وَالدَّامِغَةِ. وَفِي الْحَارِصَةِ، وَالْبَازِلَةِ، وَالْبَاضِعَةِ، وَالْمُتَلَاحِمَةِ، وَالسِّمْحَاقِ: حُكُومَةٌ."]]},{"id":"ak21_25","label":"كِتَابُ الْجِنَايَاتِ · ٢٥","segs":[["matn","فَصْلٌ: وَعَاقِلَةُ جَانٍ: ذُكُورُ عَصَبَتِهِ نَسَباً وَوَلَاءً. وَلَا عَقْلَ عَلَى: فَقِيرٍ. وَغَيْرِ مُكَلَّفٍ. وَمُخَالِفٍ دِينَ جَانٍ. وَلَا تَحْمِلُ: عَمْداً. وَلَا عَبْداً. وَلَا صُلْحاً. وَلَا اعْتِرَافاً. وَلَا مَا دُونَ ثُلُثِ الدِّيَةِ."]]},{"id":"ak21_26","label":"كِتَابُ الْجِنَايَاتِ · ٢٦","segs":[["matn","وَمَنْ قَتَلَ نَفْساً مُحَرَّمَةً غَيْرَ عَمْدٍ، أَوْ شَارَكَ فِيهِ: فَعَلَيْهِ الْكَفَّارَةُ. وَهِيَ: كَكَفَّارَةِ ظِهَارٍ، إِلَّا أَنَّهَا لَا إِطْعَامَ فِيهَا. وَيُكَفِّرُ عَبْدٌ بِالصَّوْمِ. وَالْقَسَامَةُ: أَيْمَانٌ مُكَرَّرَةٌ فِي دَعْوَى قَتْلِ مَعْصُومٍ."]]},{"id":"ak21_27","label":"كِتَابُ الْجِنَايَاتِ · ٢٧","segs":[["matn","وَإِذَا تَمَّتْ شُرُوطُهَا: بُدِئَ بِأَيْمَانِ ذُكُورِ عَصَبَتِهِ الْوَارِثِينَ. فَيَحْلِفُونَ خَمْسِينَ يَمِيناً، كُلٌّ بِقَدْرِ إِرْثِهِ، وَيُجْبَرُ كَسْرٌ. فَإِنْ نَكَلُوا، أَوْ كَانَ الْكُلُّ نِسَاءً: حَلَفَهَا مُدَّعًى عَلَيْهِ، وَبَرِئَ."]]}],"group":"كِتَابُ الْجِنَايَاتِ"},{"id":"ak22","title":"كِتَابُ الْحُدُودِ","units":[{"id":"ak22_1","label":"كِتَابُ الْحُدُودِ · ١","segs":[["matn","لَا تَجِبُ إِلَّا عَلَى: مُكَلَّفٍ. مُلْتَزِمٍ. عَالِمٍ بِالتَّحْرِيمِ. وَعَلَى إِمَامٍ أَوْ نَائِبِهِ إِقَامَتُهَا. وَيُضْرَبُ رَجُلٌ: قَائِماً. بِسَوْطٍ لَا خَلَقٍ وَلَا جَدِيدٍ. وَيَكُونُ عَلَيْهِ قَمِيصٌ وَقَمِيصَانِ. وَلَا يُبْدِي ضَارِبٌ إِبْطَهُ."]]},{"id":"ak22_2","label":"كِتَابُ الْحُدُودِ · ٢","segs":[["matn","وَيُسَنُّ تَفْرِيقُهُ عَلَى الْأَعْضَاءِ. وَيَجِبُ اتِّقَاءُ وَجْهٍ، وَرَأْسٍ، وَفَرْجٍ، وَمَقْتَلٍ. وَامْرَأَةٌ كَرَجُلٍ، لَكِنْ: تُضْرَبُ جَالِسَةً. وَتُشَدُّ عَلَيْهَا ثِيَابُهَا، وَتُمْسَكُ يَدَاهَا. وَلَا يُحْفَرُ لِمَرْجُومٍ. وَمَنْ مَاتَ وَعَلَيْهِ حَدٌّ: سَقَطَ."]]},{"id":"ak22_3","label":"كِتَابُ الْحُدُودِ · ٣","segs":[["matn","فَيُرْجَمُ زَانٍ مُحْصَنٌ حَتَّى يَمُوتَ. وَغَيْرُهُ: يُجْلَدُ مِائَةً، وَيُغَرَّبُ عَاماً. وَرَقِيقٌ: خَمْسِينَ، وَلَا يُغَرَّبُ. وَمُبَعَّضٌ: بِحِسَابِهِ فِيهِمَا. وَالْمُحْصَنُ: مَنْ وَطِئَ زَوْجَتَهُ، بِنِكَاحٍ صَحِيحٍ، فِي قُبُلِهَا، وَلَوْ مَرَّةً."]]},{"id":"ak22_4","label":"كِتَابُ الْحُدُودِ · ٤","segs":[["matn","وَشُرُوطُهُ ثَلَاثَةٌ: تَغْيِيبُ حَشَفَةٍ أَصْلِيَّةٍ فِي فَرْجٍ أَصْلِيٍّ لِآدَمِيٍّ، وَلَوْ دُبُراً. وَانْتِفَاءُ الشُّبْهَةِ. وَثُبُوتُهُ: بِشَهَادَةِ: أَرْبَعَةِ. رِجَالٍ. عُدُولٍ. فِي مَجْلِسٍ وَاحِدٍ. بِزِنًى وَاحِدٍ. مَعَ وَصْفِهِ. أَوْ إِقْرَارِهِ: أَرْبَعَ مَرَّاتٍ."]]},{"id":"ak22_5","label":"كِتَابُ الْحُدُودِ · ٥","segs":[["matn","مَعَ ذِكْرِ حَقِيقَةِ الْوَطْءِ. بِلَا رُجُوعٍ. وَالْقَاذِفُ مُحْصَنًا: يُجْلَدُ. حُرٌّ: ثَمَانِينَ. وَرَقِيقٌ: نِصْفَهَا. وَمُبَعَّضٌ: بِحِسَابِهِ. وَالْمُحْصَنُ هُنَا: الْحُرُّ. الْمُسْلِمُ. الْعَاقِلُ. الْعَفِيفُ. وَشُرِطَ: كَوْنُ مِثْلِهِ يَطَأُ، أَوْ يُوطَأُ. لَا بُلُوغُهُ."]]},{"id":"ak22_6","label":"كِتَابُ الْحُدُودِ · ٦","segs":[["matn","وَيُعَزَّرُ بِنَحْوِ: يَا كَافِرُ، يَا مَلْعُونُ، يَا أَعْوَرُ، يَا أَعْرَجُ. وَيَجِبُ التَّعْزِيرُ فِي كُلِّ مَعْصِيَةٍ لَا حَدَّ فِيهَا وَلَا كَفَّارَةَ. وَمَرْجِعُهُ: إِلَى اجْتِهَادِ الْإِمَامِ."]]},{"id":"ak22_7","label":"كِتَابُ الْحُدُودِ · ٧","segs":[["matn","فَصْلٌ: وَكُلُّ شَرَابٍ مُسْكِرٍ: يَحْرُمُ مُطْلَقاً. إِلَّا لِدَفْعِ لُقْمَةٍ غُصَّ بِهَا، مَعَ خَوْفِ تَلَفٍ، وَيُقَدَّمُ عَلَيْهِ بَوْلٌ."]]},{"id":"ak22_8","label":"كِتَابُ الْحُدُودِ · ٨","segs":[["matn","فَإِذَا شَرِبَهُ، أَوِ احْتَقَنَ بِهِ مُسْلِمٌ، مُكَلَّفٌ، مُخْتَاراً، عَالِماً أَنَّ كَثِيرَهُ يُسْكِرُ: حُدَّ حُرٌّ: ثَمَانِينَ. وَقِنٌّ: نِصْفَهَا. وَيَثْبُتُ: بِإِقْرَارِهِ مَرَّةً؛ كَقَذْفٍ. أَوْ شَهَادَةِ عَدْلَيْنِ. وَحَرُمَ عَصِيرٌ وَنَحْوُهُ: إِذَا غَلَى. أَوْ أَتَى عَلَيْهِ ثَلَاثَةُ أَيَّامٍ."]]},{"id":"ak22_9","label":"كِتَابُ الْحُدُودِ · ٩","segs":[["matn","فَصْلٌ: وَيُقْطَعُ السَّارِقُ بِثَمَانِيَةِ شُرُوطٍ: السَّرِقَةُ، وَهِيَ: أَخْذُ مَالِ مَعْصُومٍ خُفْيَةً. وَكَوْنُ سَارِقٍ مُكَلَّفاً، مُخْتَاراً، عَالِماً بِمَسْرُوقٍ وَتَحْرِيمِهِ. وَكَوْنُ مَسْرُوقٍ مَالاً مُحْتَرَماً. وَكَوْنُهُ نِصَاباً."]]},{"id":"ak22_10","label":"كِتَابُ الْحُدُودِ · ١٠","segs":[["matn","وَهُوَ: ثَلَاثَةُ دَرَاهِمَ فِضَّةً، أَوْ رُبُعُ مِثْقَالٍ ذَهَباً، أَوْ مَا قِيمَتُهُ أَحَدُهُمَا. وَإِخْرَاجُهُ مِنْ حِرْزِ مِثْلِهِ. وَحِرْزُ كُلِّ مَالٍ: مَا حُفِظَ بِهِ عَادَةً. وَانْتِفَاءُ الشُّبْهَةِ. وَثُبُوتُهَا: بِشَهَادَةِ عَدْلَيْنِ يَصِفَانِهَا."]]},{"id":"ak22_11","label":"كِتَابُ الْحُدُودِ · ١١","segs":[["matn","أَوْ إِقْرَارٍ مَرَّتَيْنِ، مَعَ وَصْفٍ، وَدَوَامٍ عَلَيْهِ. وَمُطَالَبَةُ مَسْرُوقٍ مِنْهُ، أَوْ وَكِيلِهِ، أَوْ وَلِيِّهِ. فَإِذَا وَجَبَ: قُطِعَتْ يَدُهُ الْيُمْنَى مِنْ مَفْصِلِ كَفِّهِ، وَحُسِمَتْ."]]},{"id":"ak22_12","label":"كِتَابُ الْحُدُودِ · ١٢","segs":[["matn","فَإِنْ عَادَ: قُطِعَتْ رِجْلُهُ الْيُسْرَى مِنْ مَفْصِلِ كَعْبِهِ، وَحُسِمَتْ. فَإِنْ عَادَ: حُبِسَ حَتَّى يَتُوبَ. وَمَنْ سَرَقَ تَمْراً، أَوْ مَاشِيَةً مِنْ غَيْرِ حِرْزٍ: غُرِّمَ قِيمَتَهُ مَرَّتَيْنِ، وَلَا قَطْعَ."]]},{"id":"ak22_13","label":"كِتَابُ الْحُدُودِ · ١٣","segs":[["matn","وَمَنْ لَمْ يَجِدْ مَا يَشْتَرِيهِ، أَوْ يُشْتَرَى بِهِ زَمَنَ مَجَاعَةِ غَلَاءٍ: لَمْ يُقْطَعْ بِسَرِقَةٍ."]]},{"id":"ak22_14","label":"كِتَابُ الْحُدُودِ · ١٤","segs":[["matn","فَصْلٌ: وَقُطَّاعُ الطَّرِيقِ أَنْوَاعٌ: فَمَنْ مِنْهُمْ قَتَلَ مُكَافِئاً أَوْ غَيْرَهُ؛ كَوَلَدٍ، وَأَخَذَ الْمَالَ: قُتِلَ. ثُمَّ صُلِبَ مُكَافِئٌ حَتَّى يَشْتَهِرَ. وَمَنْ قَتَلَ فَقَطْ: قُتِلَ حَتْماً. وَلَا صَلْبَ."]]},{"id":"ak22_15","label":"كِتَابُ الْحُدُودِ · ١٥","segs":[["matn","وَمَنْ أَخَذَ الْمَالَ فَقَطْ: قُطِعَتْ يَدُهُ الْيُمْنَى، ثُمَّ رِجْلُهُ الْيُسْرَى، فِي مَقَامٍ وَاحِدٍ، وَحُسِمَتَا، وَخُلِّيَ. وَإِنْ أَخَافَ السَّبِيلَ فَقَطْ: نُفِيَ وَشُرِّدَ. وَشُرِطَ: ثُبُوتُ ذَلِكَ: بِبَيِّنَةٍ، أَوْ إِقْرَارٍ مَرَّتَيْنِ. وَحِرْزٌ. وَنِصَابٌ."]]},{"id":"ak22_16","label":"كِتَابُ الْحُدُودِ · ١٦","segs":[["matn","وَمَنْ تَابَ مِنْهُمْ قَبْلَ الْقُدْرَةِ عَلَيْهِ: سَقَطَ عَنْهُ حَقُّ اللَّهِ تَعَالَى. وَأُخِذَ بِحَقِّ آدَمِيٍّ. وَمَنْ وَجَبَ عَلَيْهِ حَدٌّ لِلَّهِ، فَتَابَ قَبْلَ ثُبُوتِهِ: سَقَطَ."]]},{"id":"ak22_17","label":"كِتَابُ الْحُدُودِ · ١٧","segs":[["matn","وَمَنْ أُرِيدَ مَالُهُ أَوْ نَفْسُهُ أَوْ حُرْمَتُهُ، وَلَمْ يَنْدَفِعِ الْمُرِيدُ إِلَّا بِالْقَتْلِ: أُبِيحَ، وَلَا ضَمَانَ. وَالْبُغَاةُ: ذُو شَوْكَةٍ، يَخْرُجُونَ عَلَى الْإِمَامِ، بِتَأْوِيلٍ سَائِغٍ. فَيَلْزَمُهُ: مُرَاسَلَتُهُمْ."]]},{"id":"ak22_18","label":"كِتَابُ الْحُدُودِ · ١٨","segs":[["matn","وَإِزَالَةُ مَا يَدَّعُونَهُ مِنْ شُبْهَةٍ وَمَظْلَمَةٍ. فَإِنْ فَاؤُوا، وَإِلَّا قَاتَلَهُمْ قَادِرٌ."]]},{"id":"ak22_19","label":"كِتَابُ الْحُدُودِ · ١٩","segs":[["matn","فَصْلٌ: وَالْمُرْتَدُّ: مَنْ كَفَرَ طَوْعاً -وَلَوْ مُمَيِّزاً- بَعْدَ إِسْلَامِهِ."]]},{"id":"ak22_20","label":"كِتَابُ الْحُدُودِ · ٢٠","segs":[["matn","فَمَتَى ادَّعَى النُّبُوَّةَ، أَوْ سَبَّ اللَّهَ أَوْ رَسُولَهُ، أَوْ جَحَدَهُ، أَوْ صِفَةً مِنْ صِفَاتِهِ، أَوْ كِتَاباً، أَوْ رَسُولاً، أَوْ مَلَكاً، أَوْ إِحْدَى الْعِبَادَاتِ الْخَمْسِ، أَوْ حُكْماً ظَاهِراً مُجْمَعاً عَلَيْهِ: كَفَرَ."]]},{"id":"ak22_21","label":"كِتَابُ الْحُدُودِ · ٢١","segs":[["matn","فَيُسْتَتَابُ ثَلَاثَةَ أَيَّامٍ، فَإِنْ لَمْ يَتُبْ قُتِلَ. وَلَا تُقْبَلُ ظَاهِراً مِمَّنْ: سَبَّ اللَّهَ أَوْ رَسُولَهُ. أَوْ تَكَرَّرَتْ رِدَّتُهُ. وَلَا مِنْ مُنَافِقٍ. وَسَاحِرٍ. وَتَجِبُ التَّوْبَةُ مِنْ كُلِّ ذَنْبٍ."]]},{"id":"ak22_22","label":"كِتَابُ الْحُدُودِ · ٢٢","segs":[["matn","وَهِيَ: إِقْلَاعٌ، وَنَدَمٌ، وَعَزْمٌ أَلَّا يَعُودَ، مَعَ رَدِّ مَظْلَمَةٍ. لَا اسْتِحْلَالٌ مِنْ نَحْوِ غِيبَةٍ وَقَذْفٍ."]]},{"id":"ak22_23","label":"كِتَابُ الْحُدُودِ · ٢٣","segs":[["matn","فَصْلٌ: وَكُلُّ طَعَامٍ طَاهِرٍ لَا مَضَرَّةَ فِيهِ: حَلَالٌ، وَأَصْلُهُ الْحِلُّ. وَحَرُمَ: نَجِسٌ؛ كَدَمٍ، وَمَيْتَةٍ. وَمُضِرٌّ؛ كَسُمٍّ. وَمِنْ حَيَوَانِ بَرٍّ: مَا يَفْتَرِسُ بِنَابِهِ؛ كَأَسَدٍ، وَنَمِرٍ، وَفَهْدٍ، وَثَعْلَبٍ، وَابْنِ آوَى، لَا ضَبُعٌ."]]},{"id":"ak22_24","label":"كِتَابُ الْحُدُودِ · ٢٤","segs":[["matn","وَمِنْ طَيْرٍ: مَا يَصِيدُ بِمِخْلَبٍ؛ كَعُقَابٍ، وَصَقْرٍ. وَمَا يَأْكُلُ الْجِيَفَ؛ كَنَسْرٍ، وَرَخَمٍ. وَمَا تَسْتَخْبِثُهُ الْعَرَبُ ذُو الْيَسَارِ؛ كَوَطْوَاطٍ، وَقُنْفُذٍ، وَنِيصٍ. وَمَا تَوَلَّدَ مِنْ مَأْكُولٍ وَغَيْرِهِ؛ كَبَغْلٍ."]]},{"id":"ak22_25","label":"كِتَابُ الْحُدُودِ · ٢٥","segs":[["matn","وَيُبَاحُ حَيَوَانُ بَحْرٍ كُلُّهُ، سِوَى: ضِفْدَعٍ. وَتِمْسَاحٍ. وَحَيَّةٍ. وَمَنِ اضْطُرَّ: أَكَلَ وُجُوباً مِنْ مُحَرَّمٍ -غَيْرِ سُمٍّ- مَا يَسُدُّ رَمَقَهُ. وَيَلْزَمُ مُسْلِماً ضِيَافَةُ: مُسْلِمٍ. مُسَافِرٍ. فِي قَرْيَةٍ لَا مِصْرٍ. يَوْماً وَلَيْلَةً قَدْرَ كِفَايَتِهِ. وَتُسَنُّ ثَلَاثَةَ أَيَّامٍ."]]},{"id":"ak22_26","label":"كِتَابُ الْحُدُودِ · ٢٦","segs":[["matn","فَصْلٌ: لَا يُبَاحُ حَيَوَانٌ يَعِيشُ فِي الْبَرِّ -غَيْرَ جَرَادٍ وَنَحْوِهِ- إِلَّا بِذَكَاتِهِ. وَشُرُوطُهَا أَرْبَعَةٌ: كَوْنُ ذَابِحٍ عَاقِلاً، مُمَيِّزاً، وَلَوْ كِتَابِيًّا. وَالْآلَةُ، وَهِيَ: كُلُّ مُحَدَّدٍ. غَيْرَ سِنٍّ وَظُفُرٍ. وَقَطْعُ حُلْقُومٍ وَمَرِيءٍ."]]},{"id":"ak22_27","label":"كِتَابُ الْحُدُودِ · ٢٧","segs":[["matn","وَسُنَّ قَطْعُ الْوَدَجَيْنِ. وَمَا عُجِزَ عَنْهُ؛ كَوَاقِعٍ فِي بِئْرٍ، وَمُتَوَحِّشٍ، وَمُتَرَدٍّ: يَكْفِي جَرْحُهُ حَيْثُ كَانَ. فَإِنْ أَعَانَهُ غَيْرُهُ؛ كَكَوْنِ رَأْسِهِ فِي الْمَاءِ وَنَحْوِهِ: لَمْ يَحِلَّ."]]},{"id":"ak22_28","label":"كِتَابُ الْحُدُودِ · ٢٨","segs":[["matn","وَقَوْلُ بِاسْمِ اللَّهِ عِنْدَ تَحْرِيكِ يَدِهِ. وَتَسْقُطُ سَهْواً، لَا جَهْلاً. وَذَكَاةُ جَنِينٍ خَرَجَ مَيِّتاً وَنَحْوَهُ: بِذَكَاةِ أُمِّهِ. وَكُرِهَتْ: بِآلَةٍ كَالَّةٍ. وَحَدُّهَا بِحَضْرَةِ مُذَكًّى. وَسَلْخٌ وَكَسْرُ عُنُقٍ قَبْلَ زُهُوقٍ."]]},{"id":"ak22_29","label":"كِتَابُ الْحُدُودِ · ٢٩","segs":[["matn","وَنَفْخُ لَحْمٍ لِبَيْعٍ. وَسُنَّ: تَوْجِيهُهُ إِلَى الْقِبْلَةِ، عَلَى شِقِّهِ الْأَيْسَرِ. وَرِفْقٌ بِهِ. وَتَكْبِيرٌ."]]},{"id":"ak22_30","label":"كِتَابُ الْحُدُودِ · ٣٠","segs":[["matn","فَصْلٌ: الصَّيْدُ مُبَاحٌ. وَشُرُوطُهُ أَرْبَعَةٌ: كَوْنُ صَائِدٍ مِنْ أَهْلِ ذَكَاةٍ. وَالْآلَةُ، وَهِيَ: آلَةُ ذَكَاةٍ. أَوْ جَارِحٌ مُعَلَّمٌ. وَهُوَ: أَنْ يَسْتَرْسِلَ إِذَا أُرْسِلَ، وَيَنْزَجِرَ إِذَا زُجِرَ، وَإِذَا أَمْسَكَ لَمْ يَأْكُلْ."]]},{"id":"ak22_31","label":"كِتَابُ الْحُدُودِ · ٣١","segs":[["matn","وَإِرْسَالُهَا قَاصِداً، فَلَوِ اسْتَرْسَلَ جَارِحٌ بِنَفْسِهِ، فَقَتَلَ صَيْداً: لَمْ يَحِلَّ. وَالتَّسْمِيَةُ عِنْدَ رَمْيٍ أَوْ إِرْسَالٍ. وَلَا تَسْقُطُ بِحَالٍ. وَسُنَّ تَكْبِيرٌ مَعَهَا."]]},{"id":"ak22_32","label":"كِتَابُ الْحُدُودِ · ٣٢","segs":[["matn","وَمَنْ أَعْتَقَ صَيْداً، أَوْ أَرْسَلَ بَعِيراً أَوْ غَيْرَهُ: لَمْ يَزُلْ مِلْكُهُ عَنْهُ."]]}],"group":"كِتَابُ الْحُدُودِ"},{"id":"ak23","title":"بَابُ الْأَيْمَانِ","units":[{"id":"ak23_1","label":"بَابُ الْأَيْمَانِ · ١","segs":[["matn","تَحْرُمُ بِغَيْرِ: اللَّهِ، أَوْ صِفَةٍ مِنْ صِفَاتِهِ، أَوِ الْقُرْآنِ. فَمَنْ حَلَفَ وَحَنِثَ: وَجَبَتْ عَلَيْهِ الْكَفَّارَةُ. وَلِوُجُوبِهَا أَرْبَعَةُ شُرُوطٍ: قَصْدُ عَقْدِ الْيَمِينِ. وَكَوْنُهَا عَلَى مُسْتَقْبَلٍ."]]},{"id":"ak23_2","label":"بَابُ الْأَيْمَانِ · ٢","segs":[["matn","فَلَا تَنْعَقِدُ عَلَى مَاضٍ كَاذِباً عَالِماً بِهِ، وَهِيَ الْغَمُوسُ. وَلَا ظَانًّا صِدْقَ نَفْسِهِ فَيَبِينُ بِخِلَافِهِ. وَلَا عَلَى فِعْلِ مُسْتَحِيلٍ. وَكَوْنُ حَالِفٍ مُخْتَاراً."]]},{"id":"ak23_3","label":"بَابُ الْأَيْمَانِ · ٣","segs":[["matn","وَحِنْثُهُ؛ بِفِعْلِ مَا حَلَفَ عَلَى تَرْكِهِ، أَوْ تَرْكِ مَا حَلَفَ عَلَى فِعْلِهِ. غَيْرَ: مُكْرَهٍ، أَوْ جَاهِلٍ، أَوْ نَاسٍ. وَيُسَنُّ حِنْثٌ وَيُكْرَهُ بِرٌّ: إِذَا كَانَتْ عَلَى فِعْلِ مَكْرُوهٍ، أَوْ تَرْكِ مَنْدُوبٍ."]]},{"id":"ak23_4","label":"بَابُ الْأَيْمَانِ · ٤","segs":[["matn","وَعَكْسُهُ بِعَكْسِهِ. وَيَجِبُ: إِنْ كَانَتْ عَلَى فِعْلِ مُحَرَّمٍ، أَوْ تَرْكِ وَاجِبٍ. وَعَكْسُهُ بِعَكْسِهِ."]]},{"id":"ak23_5","label":"بَابُ الْأَيْمَانِ · ٥","segs":[["matn","فَصْلٌ: وَإِنْ حَرَّمَ أَمَتَهُ، أَوْ حَلَالاً غَيْرَ زَوْجَةٍ: لَمْ يَحْرُمْ. وَعَلَيْهِ كَفَّارَةُ يَمِينٍ إِنْ فَعَلَهُ. وَتَجِبُ فَوْراً بِحِنْثٍ. وَيُخَيَّرُ فِيهَا بَيْنَ: إِطْعَامِ عَشَرَةِ مَسَاكِينَ."]]},{"id":"ak23_6","label":"بَابُ الْأَيْمَانِ · ٦","segs":[["matn","أَوْ كِسْوَتِهِمْ كِسْوَةً تَصِحُّ بِهَا صَلَاةُ الْفَرْضِ. أَوْ عِتْقِ رَقَبَةٍ مُؤْمِنَةٍ. فَإِنْ عَجَزَ كَفِطْرَةٍ: صَامَ ثَلَاثَةَ أَيَّامٍ مُتَتَابِعَةً. وَمَبْنَى يَمِينٍ: عَلَى الْعُرْفِ."]]},{"id":"ak23_7","label":"بَابُ الْأَيْمَانِ · ٧","segs":[["matn","وَيُرْجَعُ فِيهَا إِلَى نِيَّةِ حَالِفٍ لَيْسَ ظَالِماً، إِنِ احْتَمَلَهَا لَفْظُهُ؛ كَنِيَّتِهِ بِبِنَاءٍ وَسَقْفٍ: السَّمَاءَ."]]},{"id":"ak23_8","label":"بَابُ الْأَيْمَانِ · ٨","segs":[["matn","فَصْلٌ: النَّذْرُ مَكْرُوهٌ. وَلَا يَصِحُّ إِلَّا مِنْ مُكَلَّفٍ. وَالْمُنْعَقِدُ سِتَّةُ أَنْوَاعٍ: الْمُطْلَقُ؛ كَلِلَّهِ عَلِيَّ نَذْرٌ إِنْ فَعَلْتُ كَذَا، وَلَا نِيَّةَ: فَكَفَّارَةُ يَمِينٍ إِنْ فَعَلَهُ."]]},{"id":"ak23_9","label":"بَابُ الْأَيْمَانِ · ٩","segs":[["matn","الثَّانِي: نَذْرُ لَجَاجٍ وَغَضَبٍ، وَهُوَ تَعْلِيقُهُ بِشَرْطٍ يَقْصِدُ الْمَنْعَ مِنْهُ أَوِ الْحَمْلَ عَلَيْهِ، كَإِنْ كَلَّمْتُكَ فَعَلَيَّ كَذَا: فَيُخَيَّرُ بَيْنَ فِعْلِهِ، وَكَفَّارَةِ يَمِينٍ."]]},{"id":"ak23_10","label":"بَابُ الْأَيْمَانِ · ١٠","segs":[["matn","الثَّالِثُ: نَذْرُ مُبَاحٍ، كَلِلَّهِ عَلَيَّ أَنْ أَلْبَسَ ثَوْبِي: فَيُخَيَّرُ أَيْضاً. الرَّابِعُ: نَذْرُ مَكْرُوهٍ؛ كَطَلَاقٍ وَنَحْوِهِ: فَالتَّكْفِيرُ أَوْلَى. الْخَامِسُ: نَذْرُ مَعْصِيَةٍ؛ كَشُرْبِ خَمْرٍ: فَيَحْرُمُ الْوَفَاءُ، وَيَجِبُ التَّكْفِيرُ."]]},{"id":"ak23_11","label":"بَابُ الْأَيْمَانِ · ١١","segs":[["matn","السَّادِسُ: نَذْرُ تَبَرُّرٍ؛ كَصَلَاةٍ، وَصِيَامٍ، وَاعْتِكَافٍ: بِقَصْدِ التَّقَرُّبِ مُطْلَقاً. أَوْ مُعَلَّقاً بِشَرْطٍ؛ كَإِنْ شَفَى اللَّهُ مَرِيضِي فَلِلَّهِ عَلَيَّ كَذَا. فَيَلْزَمُ الْوَفَاءُ بِهِ. وَمَنْ نَذَرَ: الصَّدَقَةَ بِكُلِّ مَالِهِ: أَجْزَأَهُ ثُلُثُهُ."]]},{"id":"ak23_12","label":"بَابُ الْأَيْمَانِ · ١٢","segs":[["matn","أَوْ صَوْمَ شَهْرٍ وَنَحْوِهِ: لَزِمَهُ التَّتَابُعُ. لَا إِنْ نَذَرَ أَيَّاماً مَعْدُودَةً. وَسُنَّ الْوَفَاءُ بِالْوَعْدِ. وَحَرُمَ بِلَا اسْتِثْنَاءٍ."]]}],"group":"كِتَابُ الْحُدُودِ"},{"id":"ak24","title":"كِتَابُ الْقَضَاءِ","units":[{"id":"ak24_1","label":"كِتَابُ الْقَضَاءِ · ١","segs":[["matn","وَهُوَ فَرْضُ كِفَايَةٍ؛ كَالْإِمَامَةِ. فَيَنْصِبُ الْإِمَامُ بِكُلِّ إِقْلِيمٍ قَاضِياً. وَيَخْتَارُ أَفْضَلَ مَنْ يَجِدُ عِلْماً وَوَرَعاً، وَيَأْمُرُهُ بِالتَّقْوَى وَتَحَرِّي الْعَدْلِ. وَتُفِيدُ وِلَايَةُ حُكْمٍ عَامَّةٌ: فَصْلَ الْحُكُومَةِ. وَأَخْذَ الْحَقِّ وَدَفْعَهُ إِلَى رَبِّهِ."]]},{"id":"ak24_2","label":"كِتَابُ الْقَضَاءِ · ٢","segs":[["matn","وَالنَّظَرَ فِي مَالِ يَتِيمٍ، وَمَجْنُونٍ، وَسَفِيهٍ، وَغَائِبٍ. وَوَقْفِ عَمَلِهِ لِيُجْرَى عَلَى شَرْطِهِ، وَغَيْرِ ذَلِكَ. وَيَجُوزُ أَنْ يُوَلِّيَهُ عُمُومَ النَّظَرِ فِي عُمُومِ الْعَمَلِ، وَخَاصًّا فِي أَحَدِهِمَا أَوْ فِيهِمَا."]]},{"id":"ak24_3","label":"كِتَابُ الْقَضَاءِ · ٣","segs":[["matn","وَشُرِطَ كَوْنُ قَاضٍ: بَالِغاً. عَاقِلاً. ذَكَراً. حُرًّا. مُسْلِماً. عَدْلاً. سَمِيعاً. بَصِيراً. مُتَكَلِّماً. مُجْتَهِداً، وَلَوْ فِي مَذْهَبِ إِمَامِهِ."]]},{"id":"ak24_4","label":"كِتَابُ الْقَضَاءِ · ٤","segs":[["matn","وَإِنْ حَكَّمَ اثْنَانِ بَيْنَهُمَا رَجُلاً يَصْلُحُ لِلْقَضَاءِ: نَفَذَ حُكْمُهُ فِي كُلِّ مَا يَنْفُذُ فِيهِ حُكْمُ مَنْ وَلَّاهُ إِمَامٌ أَوْ نَائِبُهُ. وَسُنَّ كَوْنُهُ: قَوِيًّا بِلَا عُنْفٍ. لَيِّنًا بِلَا ضَعْفٍ. حَلِيماً. مُتَأَنِّياً."]]},{"id":"ak24_5","label":"كِتَابُ الْقَضَاءِ · ٥","segs":[["matn","فَطِناً. عَفِيفاً. وَعَلَيْهِ الْعَدْلُ بَيْنَ مُتَحَاكِمَيْنِ فِي لَفْظِهِ، وَلَحْظِهِ، وَمَجْلِسِهِ، وَدُخُولٍ عَلَيْهِ."]]},{"id":"ak24_6","label":"كِتَابُ الْقَضَاءِ · ٦","segs":[["matn","وَحَرُمَ: الْقَضَاءُ وَهُوَ غَضْبَانُ كَثِيراً، أَوْ حَاقِنٌ، أَوْ فِي شِدَّةِ جُوعٍ، أَوْ عَطَشٍ، أَوْ هَمٍّ، أَوْ مَلَلٍ، أَوْ كَسَلٍ، أَوْ نُعَاسٍ، أَوْ بَرْدٍ مُؤْلِمٍ، أَوْ حَرٍّ مُزْعِجٍ. وَقَبُولُ رِشْوَةٍ."]]},{"id":"ak24_7","label":"كِتَابُ الْقَضَاءِ · ٧","segs":[["matn","وَهَدِيَّةٍ مِنْ غَيْرِ مَنْ كَانَ يُهَادِيهِ قَبْلَ وِلَايَتِهِ، وَلَا حُكُومَةَ لَهُ. وَلَا يَنْفُذُ حُكْمُهُ عَلَى: عَدُوِّهِ. وَلَا لِنَفْسِهِ. وَلَا لِمَنْ لَا تُقْبَلُ شَهَادَتُهُ لَهُ."]]},{"id":"ak24_8","label":"كِتَابُ الْقَضَاءِ · ٨","segs":[["matn","وَمَنِ اسْتَعْدَاهُ عَلَى خَصْمٍ فِي الْبَلَدِ بِمَا تَتْبَعُهُ الْهِمَّةُ: لَزِمَهُ إِحْضَارُهُ. إِلَّا غَيْرَ بَرْزَةٍ، فَتُوَكِّلُ؛ كَمَرِيضٍ وَنَحْوِهِ. وَإِنْ وَجَبَ يَمِينٌ: أَرْسَلَ مَنْ يُحَلِّفُهُمَا."]]},{"id":"ak24_9","label":"كِتَابُ الْقَضَاءِ · ٩","segs":[["matn","فَصْلٌ: وَشُرِطَ: كَوْنُ مُدَّعٍ وَمُنْكِرٍ جَائِزَيِ التَّصَرُّفِ. وَتَحْرِيرُ الدَّعْوَى. وَعِلْمُ مُدَّعًى بِهِ، إِلَّا فِيمَا نُصَحِّحُهُ مَجْهُولاً؛ كَوَصِيَّةٍ. فَإِنِ ادَّعَى: عَقْداً: ذَكَرَ شُرُوطَهُ. أَوْ إِرْثاً: ذَكَرَ سَبَبَهُ."]]},{"id":"ak24_10","label":"كِتَابُ الْقَضَاءِ · ١٠","segs":[["matn","أَوْ مُحَلًّى بِأَحَدِ النَّقْدَيْنِ: قَوَّمَهُ بِالْآخَرِ، أَوْ بِهِمَا: فَبِأَيِّهِمَا شَاءَ. وَإِذَا حَرَّرَهَا: فَإِنْ أَقَرَّ الْخَصْمُ: حُكِمَ عَلَيْهِ بِسُؤَالِ مُدَّعٍ. وَإِنْ أَنْكَرَ وَلَا بَيِّنَةَ: فَقَوْلُهُ بِيَمِينِهِ."]]},{"id":"ak24_11","label":"كِتَابُ الْقَضَاءِ · ١١","segs":[["matn","فَإِنْ نَكَلَ: حُكِمَ عَلَيْهِ بِسُؤَالِ مُدَّعٍ، فِي مَالٍ وَمَا يُقْصَدُ بِهِ. وَيُسْتَحْلَفُ فِي كُلِّ حَقِّ آدَمِيٍّ سِوَى: نِكَاحٍ. وَرَجْعَةٍ. وَنَسَبٍ، وَنَحْوِهَا. لَا فِي حَقِّ اللَّهِ؛ كَحَدٍّ، وَعِبَادَةٍ."]]},{"id":"ak24_12","label":"كِتَابُ الْقَضَاءِ · ١٢","segs":[["matn","وَالْيَمِينُ الْمَشْرُوعَةُ: بِاللَّهِ وَحْدَهُ أَوْ بِصِفَتِهِ. وَيُحْكَمُ بِالْبَيِّنَةِ بَعْدَ التَّحْلِيفِ. وَشُرِطَ: فِي بَيِّنَةٍ: عَدَالَةٌ ظَاهِراً، وَفِي غَيْرِ عَقْدِ نِكَاحٍ: بَاطِناً أَيْضاً. وَفِي مُزَكٍّ: مَعْرِفَةُ جَرْحٍ وَتَعْدِيلٍ، وَمَعْرِفَةُ حَاكِمٍ خِبْرَتَهُ الْبَاطِنَةَ."]]},{"id":"ak24_13","label":"كِتَابُ الْقَضَاءِ · ١٣","segs":[["matn","وَتُقَدَّمُ بَيِّنَةُ جَرْحٍ. فَمَتَى جَهِلَ حَاكِمٌ حَالَ بَيِّنَةٍ: طَلَبَ التَّزْكِيَةَ مُطْلَقاً. وَلَا يُقْبَلُ فِيهَا، وَفِي جَرْحٍ، وَنَحْوِهِمَا: إِلَّا رَجُلَانِ."]]},{"id":"ak24_14","label":"كِتَابُ الْقَضَاءِ · ١٤","segs":[["matn","وَمَنِ ادَّعَى عَلَى غَائِبٍ مَسَافَةَ قَصْرٍ، أَوْ مُسْتَتِرٍ فِي الْبَلَدِ، أَوْ مَيِّتٍ، أَوْ غَيْرِ مُكَلَّفٍ وَلَهُ بَيِّنَةٌ: سُمِعَتْ، وَحُكِمَ بِهَا، فِي غَيْرِ حَقِّ اللَّهِ تَعَالَى."]]},{"id":"ak24_15","label":"كِتَابُ الْقَضَاءِ · ١٥","segs":[["matn","وَلَا تُسْمَعُ عَلَى غَيْرِهِمْ حَتَّى يَحْضُرَ أَوْ يَمْتَنِعَ. وَلَوْ رُفِعَ إِلَيْهِ حُكْمٌ لَا يَلْزَمُهُ نَقْضُهُ لِيُنَفِّذَهُ: لَزِمَهُ تَنْفِيذُهُ. وَيُقْبَلُ كِتَابُ قَاضٍ إِلَى قَاضٍ: فِي كُلِّ حَقِّ آدَمِيٍّ."]]},{"id":"ak24_16","label":"كِتَابُ الْقَضَاءِ · ١٦","segs":[["matn","وَفِيمَا حَكَمَ بِهِ لِيُنَفِّذَهُ. لَا فِيمَا ثَبَتَ عِنْدَهُ لِيَحْكُمَ بِهِ، إِلَّا فِي مَسَافَةِ قَصْرٍ."]]},{"id":"ak24_17","label":"كِتَابُ الْقَضَاءِ · ١٧","segs":[["matn","فَصْلٌ: وَالْقِسْمَةُ نَوْعَانِ: قِسْمَةُ تَرَاضٍ: وَهِيَ فِيمَا لَا يَنْقَسِمُ إِلَّا بِضَرَرٍ أَوْ رَدِّ عِوَضٍ؛ كَحَمَّامٍ، وَدُورٍ صِغَارٍ. وَشُرِطَ لَهَا: رِضَا كُلِّ الشُّرَكَاءِ. وَحُكْمُهَا كَبَيْعٍ."]]},{"id":"ak24_18","label":"كِتَابُ الْقَضَاءِ · ١٨","segs":[["matn","وَمَنْ دَعَا شَرِيكَهُ فِيهَا، وَفِي شَرِكَةِ نَحْوِ عَبْدٍ، وَسَيْفٍ، وَفَرَسٍ، إِلَى بَيْعٍ أَوْ إِجَارَةٍ: أُجْبِرَ. فَإِنْ أَبَى: بِيعَ أَوْ أُوجِرَ عَلَيْهِمَا، وَقُسِمَ ثَمَنٌ أَوْ أُجْرَةٌ."]]},{"id":"ak24_19","label":"كِتَابُ الْقَضَاءِ · ١٩","segs":[["matn","الثَّانِي: قِسْمَةُ إِجْبَارٍ: وَهِيَ مَا لَا ضَرَرَ فِيهَا وَلَا رَدَّ عِوَضٍ؛ كَمَكِيلٍ، وَمَوْزُونٍ مِنْ جِنْسٍ وَاحِدٍ، وَدُورٍ كِبَارٍ: فَيُجْبَرُ شَرِيكٌ أَوْ وَلِيُّهُ عَلَيْهَا."]]},{"id":"ak24_20","label":"كِتَابُ الْقَضَاءِ · ٢٠","segs":[["matn","وَيَقْسِمُ حَاكِمٌ عَلَى غَائِبٍ بِطَلَبِ شَرِيكٍ أَوْ وَلِيِّهِ، وَهَذِهِ إِفْرَازٌ. وَشُرِطَ كَوْنُ قَاسِمٍ: مُسْلِماً. عَدْلاً. عَارِفاً بِالْقِسْمَةِ. مَا لَمْ يَرْضَوْا بِغَيْرِهِ. وَيَكْفِي: وَاحِدٌ. وَمَعَ تَقْوِيمٍ: اثْنَانِ."]]},{"id":"ak24_21","label":"كِتَابُ الْقَضَاءِ · ٢١","segs":[["matn","وَتُعَدَّلُ السِّهَامُ: بِالْأَجْزَاءِ إِنْ تَسَاوَتْ. وَإِلَّا بِالْقِيمَةِ. أَوِ الرَّدِّ إِنِ اقْتَضَتْهُ. ثُمَّ يُقْرَعُ، وَتَلْزَمُ الْقِسْمَةُ بِهَا. وَإِنْ خَيَّرَ أَحَدُهُمَا الْآخَرَ: صَحَّتْ، وَلَزِمَتْ بِرِضَاهُمَا وَتَفَرُّقِهِمَا."]]}],"group":"كِتَابُ الْقَضَاءِ"},{"id":"ak25","title":"كِتَابُ الشَّهَادَاتِ","units":[{"id":"ak25_1","label":"كِتَابُ الشَّهَادَاتِ · ١","segs":[["matn","تَحَمُّلُهَا فِي غَيْرِ حَقِّ اللَّهِ: فَرْضُ كِفَايَةٍ. وَأَدَاؤُهَا: فَرْضُ عَيْنٍ، مَعَ الْقُدْرَةِ، بِلَا ضَرَرٍ. وَحَرُمَ: أَخْذُ أُجْرَةٍ وَجُعْلٍ عَلَيْهَا، لَا أُجْرَةُ مَرْكُوبٍ لِمُتَأَذٍّ بِمَشْيٍ. وَأَنْ يَشْهَدَ إِلَّا بِمَا يَعْلَمُهُ: بِرُؤْيَةٍ."]]},{"id":"ak25_2","label":"كِتَابُ الشَّهَادَاتِ · ٢","segs":[["matn","أَوْ سَمَاعٍ. أَوِ اسْتِفَاضَةٍ عَنْ عَدَدٍ يَقَعُ بِهِ الْعِلْمُ فِيمَا يَتَعَذَّرُ عِلْمُهُ غَالِباً بِغَيْرِهَا؛ كَنَسَبٍ، وَمَوْتٍ، وَنِكَاحٍ، وَطَلَاقٍ، وَوَقْفٍ، وَمَصْرِفِهِ. وَاعْتُبِرَ ذِكْرُ شُرُوطِ مَشْهُودٍ بِهِ. وَيَجِبُ إِشْهَادٌ فِي نِكَاحٍ."]]},{"id":"ak25_3","label":"كِتَابُ الشَّهَادَاتِ · ٣","segs":[["matn","وَيُسَنُّ فِي غَيْرِهِ. وَشُرِطَ فِي شَاهِدٍ: إِسْلَامٌ. وَبُلُوغٌ. وَعَقْلٌ. وَنُطْقٌ. لَكِنْ تُقْبَلُ مِنْ أَخْرَسَ بِخَطِّهِ، وَمِمَّنْ يُفِيقُ حَالَ إِفَاقَتِهِ."]]},{"id":"ak25_4","label":"كِتَابُ الشَّهَادَاتِ · ٤","segs":[["matn","وَعَدَالَةٌ، وَيُعْتَبَرُ لَهَا شَيْئَانِ: الْأَوَّلُ: الصَّلَاحُ فِي الدِّينِ، وَهُوَ: أَدَاءُ الْفَرَائِضِ بِرَوَاتِبِهَا. وَاجْتِنَابُ الْمَحَارِمِ؛ بِأَلَّا يَأْتِيَ كَبِيرَةً، وَلَا يُدْمِنَ عَلَى صَغِيرَةٍ."]]},{"id":"ak25_5","label":"كِتَابُ الشَّهَادَاتِ · ٥","segs":[["matn","الثَّانِي: اسْتِعْمَالُ الْمُرُوءَةِ بِفِعْلِ مَا يُزَيِّنُهُ وَيُجَمِّلُهُ، وَتَرْكِ مَا يُدَنِّسُهُ وَيَشِينُهُ. وَلَا تُقْبَلُ: شَهَادَةُ بَعْضِ عَمُودَيْ نَسَبِهِ لِبَعْضٍ. وَلَا أَحَدِ الزَّوْجَيْنِ لِلْآخَرِ. وَلَا مَنْ يَجُرُّ بِهَا إِلَى نَفْسِهِ نَفْعاً."]]},{"id":"ak25_6","label":"كِتَابُ الشَّهَادَاتِ · ٦","segs":[["matn","أَوْ يَدْفَعُ بِهَا عَنْهَا ضَرَراً. وَلَا عَدُوٍّ عَلَى عَدُوِّهِ فِي غَيْرِ نِكَاحٍ. وَمَنْ سَرَّهُ مَسَاءَةُ أَحَدٍ، أَوْ غَمَّهُ فَرَحُهُ: فَهُوَ عَدُوُّهُ. وَمَنْ لَا تُقْبَلُ لَهُ؛ تُقْبَلُ عَلَيْهِ."]]},{"id":"ak25_7","label":"كِتَابُ الشَّهَادَاتِ · ٧","segs":[["matn","فَصْلٌ: وَشُرِطَ: فِي الزِّنَى: أَرْبَعَةُ رِجَالٍ يَشْهَدُونَ بِهِ، أَوْ أَنَّهُ أَقَرَّ بِهِ أَرْبَعاً. وَفِي دَعْوَى فَقْرٍ مِمَّنْ عُرِفَ بِغِنًى: ثَلَاثَةٌ."]]},{"id":"ak25_8","label":"كِتَابُ الشَّهَادَاتِ · ٨","segs":[["matn","وَفِي قَوَدٍ، وَإِعْسَارٍ، وَمُوجِبِ تَعْزِيرٍ، أَوْ حَدٍّ، وَنِكَاحٍ، وَنَحْوِهِ وَمِمَّا لَيْسَ مَالاً، وَلَا يُقْصَدُ بِهِ الْمَالُ أَوْ يَطَّلِعُ عَلَيْهِ الرِّجَالُ غَالِباً: رَجُلَانِ. وَفِي مَالٍ، وَمَا يُقْصَدُ بِهِ: رَجُلَانِ."]]},{"id":"ak25_9","label":"كِتَابُ الشَّهَادَاتِ · ٩","segs":[["matn","أَوْ رَجُلٌ وَامْرَأَتَانِ. أَوْ رَجُلٌ وَيَمِينُ الْمُدَّعِي. وَفِي دَاءِ دَابَّةٍ، وَمُوضِحَةٍ، وَنَحْوِهِمَا: قَوْلُ اثْنَيْنِ، وَمَعَ عُذْرٍ وَاحِدٌ."]]},{"id":"ak25_10","label":"كِتَابُ الشَّهَادَاتِ · ١٠","segs":[["matn","وَمَا لَا يَطَّلِعُ عَلَيْهِ الرِّجَالُ؛ كَعُيُوبِ نِسَاءٍ تَحْتَ ثِيَابٍ، وَرَضَاعٍ، وَاسْتِهْلَالٍ، وَجِرَاحَةٍ وَنَحْوِهَا فِي حَمَّامٍ، وَعُرْسٍ: امْرَأَةٌ عَدْلٌ. أَوْ رَجُلٌ عَدْلٌ."]]},{"id":"ak25_11","label":"كِتَابُ الشَّهَادَاتِ · ١١","segs":[["matn","فَصْلٌ: وَتُقْبَلُ الشَّهَادَةُ عَلَى الشَّهَادَةِ فِي كُلِّ مَا يُقْبَلُ فِيهِ كِتَابُ الْقَاضِي إِلَى الْقَاضِي."]]},{"id":"ak25_12","label":"كِتَابُ الشَّهَادَاتِ · ١٢","segs":[["matn","وَشُرِطَ: تَعَذُّرُ شُهُودِ أَصْلٍ بِمَوْتٍ، أَوْ مَرَضٍ، أَوْ غَيْبَةٍ مَسَافَةَ قَصْرٍ، أَوْ خَوْفٍ مِنْ سُلْطَانٍ أَوْ غَيْرِهِ. وَدَوَامُ عَدَالَتِهِمَا. وَاسْتِرْعَاءُ أَصْلٍ لِفَرْعٍ أَوْ لِغَيْرِهِ وَهُوَ يَسْمَعُ."]]},{"id":"ak25_13","label":"كِتَابُ الشَّهَادَاتِ · ١٣","segs":[["matn","فَيَقُولُ: اشْهَدْ أَنِّي أَشْهَدُ أَنَّ فُلَانَ بْنَ فُلَانٍ أَشْهَدَنِي عَلَى نَفْسِهِ، أَوْ أَقَرَّ عِنْدِي بِكَذَا، وَنَحْوَهُ. أَوْ يَسْمَعُهُ يَشْهَدُ عِنْدَ حَاكِمٍ. أَوْ يَعْزُوهَا إِلَى سَبَبٍ؛ كَبَيْعٍ وَقَرْضٍ."]]},{"id":"ak25_14","label":"كِتَابُ الشَّهَادَاتِ · ١٤","segs":[["matn","وَتَأْدِيَةُ فَرْعٍ بِصِفَةِ تَحَمُّلِهِ. وَتَعْيِينُهُ لِأَصْلٍ. وَثُبُوتُ عَدَالَةِ الْجَمِيعِ. وَإِنْ رَجَعَ شُهُودُ مَالٍ: قَبْلَ حُكْمٍ: لَمْ يُحْكَمْ. وَبَعْدَهُ: لَمْ يُنْقَضْ، وَضَمِنُوا."]]},{"id":"ak25_15","label":"كِتَابُ الشَّهَادَاتِ · ١٥","segs":[["matn","وَإِنْ بَانَ خَطَأُ مُفْتٍ أَوْ قَاضٍ فِي إِتْلَافٍ لِمُخَالَفَةِ قَاطِعٍ: ضَمِنَا."]]}],"group":"كِتَابُ الشَّهَادَاتِ"},{"id":"ak26","title":"كِتَابُ الْإِقْرَارِ","units":[{"id":"ak26_1","label":"كِتَابُ الْإِقْرَارِ · ١","segs":[["matn","يَصِحُّ مِنْ: مُكَلَّفٍ. مُخْتَارٍ. بِلَفْظٍ، أَوْ كِتَابَةٍ، أَوْ إِشَارَةٍ مِنْ أَخْرَسَ. لَا عَلَى الْغَيْرِ، إِلَّا مِنْ: وَكِيلٍ. وَوَلِيٍّ. وَوَارِثٍ. وَيَصِحُّ مِنْ مَرِيضٍ مَرَضَ الْمَوْتِ."]]},{"id":"ak26_2","label":"كِتَابُ الْإِقْرَارِ · ٢","segs":[["matn","لَا لِوَارِثٍ إِلَّا بِبَيِّنَةٍ أَوْ إِجَازَةٍ، وَلَوْ صَارَ عِنْدَ الْمَوْتِ أَجْنَبِيًّا. وَيَصِحُّ لِأَجْنَبِيٍّ، وَلَوْ صَارَ عِنْدَ الْمَوْتِ وَارِثاً. وَإِعْطَاءٌ كَإِقْرَارٍ. وَإِنْ أَقَرَّتْ أَوْ وَلِيُّهَا بِنِكَاحٍ لَمْ يَدَّعِهِ اثْنَانِ: قُبِلَ."]]},{"id":"ak26_3","label":"كِتَابُ الْإِقْرَارِ · ٣","segs":[["matn","وَيُقْبَلُ إِقْرَارُ صَبِيٍّ لَهُ عَشْرٌ: أَنَّهُ بَلَغَ بِاحْتِلَامٍ. وَمَنِ ادُّعِيَ عَلَيْهِ بِشَيْءٍ، فَقَالَ: نَعَمْ، أَوْ: بَلَى، وَنَحْوَهُمَا، أَوِ: اتَّزِنْهُ، أَوْ: خُذْهُ؛ فَقَدْ أَقَرَّ. لَا: خُذْ، أَوِ: اتَّزِنْ، وَنَحْوُهُ."]]},{"id":"ak26_4","label":"كِتَابُ الْإِقْرَارِ · ٤","segs":[["matn","وَلَا يَضُرُّ الْإِنْشَاءُ فِيهِ. وَلَهُ عَلَيَّ أَلْفٌ لَا يَلْزَمُنِي، أَوْ: مِنْ ثَمَنِ خَمْرٍ وَنَحْوِهِ: يَلْزَمُهُ الْأَلْفُ. وَلَهُ أَوْ كَانَ عَلَيَّ أَلْفٌ قَضَيْتُهُ، أَوْ بَرِئْتُ مِنْهُ: فَقَوْلُهُ."]]},{"id":"ak26_5","label":"كِتَابُ الْإِقْرَارِ · ٥","segs":[["matn","وَإِنْ ثَبَتَ بِبَيِّنَةٍ، أَوْ عَزَاهُ لِسَبَبٍ: فَلَا. وَإِنْ أَنْكَرَ سَبَبَ الْحَقِّ، ثُمَّ ادَّعَى الدَّفْعَ بِبَيِّنَةٍ: لَمْ يُقْبَلْ."]]},{"id":"ak26_6","label":"كِتَابُ الْإِقْرَارِ · ٦","segs":[["matn","وَمَنْ أَقَرَّ بِقَبْضٍ، أَوْ إِقْبَاضٍ، أَوْ هِبَةٍ، وَنَحْوِهِنَّ، ثُمَّ أَنْكَرَ وَلَمْ يَجْحَدْ إِقْرَارَهُ وَلَا بَيِّنَةَ، وَسَأَلَ إِحْلَافَ خَصْمِهِ: لَزِمَهُ."]]},{"id":"ak26_7","label":"كِتَابُ الْإِقْرَارِ · ٧","segs":[["matn","وَمَنْ بَاعَ، أَوْ وَهَبَ، أَوْ أَعْتَقَ، ثُمَّ أَقَرَّ بِذَلِكَ لِغَيْرِهِ: لَمْ يُقْبَلْ، وَيَغْرَمُهُ لِمُقَرٍّ لَهُ. وَإِنْ قَالَ: لَمْ يَكُنْ مِلْكِي ثُمَّ مَلَكْتُهُ بَعْدُ: قُبِلَ بِبَيِّنَةٍ."]]},{"id":"ak26_8","label":"كِتَابُ الْإِقْرَارِ · ٨","segs":[["matn","مَا لَمْ يُكَذِّبْهَا بِنَحْوِ: قَبَضْتُ ثَمَنَ مِلْكِي. وَلَا يُقْبَلُ رُجُوعُ مُقِرٍّ إِلَّا فِي حَدٍّ لِلَّهِ."]]},{"id":"ak26_9","label":"كِتَابُ الْإِقْرَارِ · ٩","segs":[["matn","وَإِنْ قَالَ: لَهُ عَلَيَّ شَيْءٌ، أَوْ كَذَا، أَوْ مَالٌ عَظِيمٌ وَنَحْوُهُ، وَأَبَى تَفْسِيرَهُ: حُبِسَ حَتَّى يُفَسِّرَهُ. وَيُقْبَلُ بِأَقَلِّ مَالٍ، وَبِكَلْبٍ مُبَاحٍ. لَا بِمَيْتَةٍ، أَوْ خَمْرٍ، أَوْ قِشْرِ جَوْزَةٍ، وَنَحْوِهِ."]]},{"id":"ak26_10","label":"كِتَابُ الْإِقْرَارِ · ١٠","segs":[["matn","وَلَهُ تَمْرٌ فِي جِرَابٍ، أَوْ سِكِّينٌ فِي قِرَابٍ، أَوْ فَصٌّ فِي خَاتَمٍ، وَنَحْوُ ذَلِكَ: يَلْزَمُهُ الْأَوَّلُ. وَإِقْرَارٌ بِشَجَرٍ لَيْسَ إِقْرَاراً بِأَرْضِهِ. وَبِأَمَةٍ لَيْسَ إِقْرَاراً بِحَمْلِهَا. وَبِبُسْتَانٍ يَشْمَلُ أَشْجَارَهُ."]]},{"id":"ak26_11","label":"كِتَابُ الْإِقْرَارِ · ١١","segs":[["matn","وَإِنِ ادَّعَى أَحَدُهُمَا صِحَّةَ الْعَقْدِ وَالْآخَرُ فَسَادَهُ: فَقَوْلُ مُدَّعِي الصِّحَّةِ. وَاللَّهُ سُبْحَانَهُ وَتَعَالَى أَعْلَمُ بِالصَّوَابِ."]]}],"group":"كِتَابُ الْإِقْرَارِ"}],"basmala":"بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ","sharh":false};
